window.KSAJU_FRAGMENTS = {"version":"v4-2026-09-30","labels":{"dm":{"甲":{"en":"Oak","ko":"甲 Oak(갑목)"},"乙":{"en":"Ivy","ko":"乙 Ivy(을목)"},"丙":{"en":"Sunshine","ko":"丙 Sunshine(병화)"},"丁":{"en":"Firefly","ko":"丁 Firefly(정화)"},"戊":{"en":"Rock","ko":"戊 Rock(무토)"},"己":{"en":"Meadow","ko":"己 Meadow(기토)"},"庚":{"en":"Blade","ko":"庚 Blade(경금)"},"辛":{"en":"Gem","ko":"辛 Gem(신금)"},"壬":{"en":"Ocean","ko":"壬 Ocean(임수)"},"癸":{"en":"Rain","ko":"癸 Rain(계수)"}},"el":{"wood":{"en":"Wood","ko":"나무(木)"},"fire":{"en":"Fire","ko":"불(火)"},"earth":{"en":"Earth","ko":"흙(土)"},"metal":{"en":"Metal","ko":"쇠(金)"},"water":{"en":"Water","ko":"물(水)"}},"god":{"bigyeon":{"en":"Peer","ko":"비견(比肩)"},"geopjae":{"en":"Rival","ko":"겁재(劫財)"},"siksin":{"en":"Ease","ko":"식신(食神)"},"sanggwan":{"en":"Rebel","ko":"상관(傷官)"},"pyeonjae":{"en":"Hustle","ko":"편재(偏財)"},"jeongjae":{"en":"Wage","ko":"정재(正財)"},"pyeongwan":{"en":"Challenge","ko":"편관(偏官)"},"jeonggwan":{"en":"Duty","ko":"정관(正官)"},"pyeonin":{"en":"Insight","ko":"편인(偏印)"},"jeongin":{"en":"Nurture","ko":"정인(正印)"}},"cat":{"bigyeop":{"en":"independence and peers","ko":"독립과 동료"},"siksang":{"en":"expression and making things","ko":"표현과 만들어 내기"},"jaeseong":{"en":"wealth and practical results","ko":"재물과 실제 결과"},"gwanseong":{"en":"responsibility and structure","ko":"책임과 틀"},"inseong":{"en":"learning and nurture","ko":"배움과 보살핌"}},"season":{"spring":{"en":"spring","ko":"봄"},"summer":{"en":"summer","ko":"여름"},"autumn":{"en":"autumn","ko":"가을"},"winter":{"en":"winter","ko":"겨울"}},"pillar":{"year":{"en":"year","ko":"연주"},"month":{"en":"month","ko":"월주"},"day":{"en":"day","ko":"일주"},"hour":{"en":"hour","ko":"시주"}},"stageGroup":{"rising":{"en":"an outward, rising phase","ko":"밖으로 드러나는 오름 구간"},"forming":{"en":"a forming, renewing phase","ko":"새로 자라나는 구간"},"settling":{"en":"a settling, ripening phase","ko":"거두고 익어 가는 구간"}},"strength":{"strong":{"en":"leans strong","ko":"신강 쪽"},"balanced":{"en":"near the middle","ko":"중화(가운데)"},"weak":{"en":"leans gentle","ko":"신약 쪽"}},"yearName":{"2026":{"en":"Fire Horse","ko":"병오(丙午, 붉은 말)"},"2027":{"en":"Fire Sheep","ko":"정미(丁未, 붉은 양)"}},"areaB":{"year":{"en":"your wider circle and community","ko":"넓은 인간관계와 모임"},"month":{"en":"work, colleagues, and daily routine","ko":"일과 동료, 일상의 흐름"},"day":{"en":"close relationships and home life","ko":"가까운 관계와 집안 생활"},"hour":{"en":"long-term plans and personal projects","ko":"먼 계획과 개인적인 일"}},"areaS":{"year":{"en":"how you show up in your wider circle","ko":"넓은 관계 속에서의 내 모습"},"month":{"en":"work and daily decisions","ko":"일과 일상의 결정"},"day":{"en":"how you decide things for yourself","ko":"스스로 결정하는 방식"},"hour":{"en":"long-term plans","ko":"먼 계획"}},"pillarKo":{"year":"연주","month":"월주","day":"일주","hour":"시주"},"stage12":{"jangsaeng":{"en":"Birth, the stage of fresh growth","ko":"장생(長生), 새로 자라나는 단계"},"mokyok":{"en":"Bathing, an unsettled, exploring stage","ko":"목욕(沐浴), 들뜨고 탐색하는 단계"},"gwandae":{"en":"Coming of Age, the stage of stepping out into the world","ko":"관대(冠帶), 세상에 나설 채비를 하는 단계"},"geonrok":{"en":"Prime, a self-supporting, working stage","ko":"건록(建祿), 스스로 서서 일하는 단계"},"jewang":{"en":"Peak, the fullest stage","ko":"제왕(帝旺), 가장 힘이 찬 단계"},"soe":{"en":"Waning, just past the peak, calmer and more experienced","ko":"쇠(衰), 정점을 지나 차분하고 노련해진 단계"},"byeong":{"en":"Slowing, a quieter, gathering phase","ko":"병(病), 조용히 거두어들이는 단계"},"sa":{"en":"Resting, a quieter, gathering phase","ko":"사(死), 조용히 거두어들이는 단계"},"myo":{"en":"Gathering In, a quieter phase of storing away what a cycle produced","ko":"묘(墓), 조용히 거두어들이는 단계"},"jeol":{"en":"Clean Break, where the old cycle ends and clears the way for the next","ko":"절(絶), 조용히 거두어들이는 단계"},"tae":{"en":"Seed, where new plans form quietly","ko":"태(胎), 새 계획이 조용히 생기는 단계"},"yang":{"en":"Taking Shape, a stage of being looked after and growing inside","ko":"양(養), 보살핌 속에 안에서 자라는 단계"}},"stageNote":{"soft":{"en":", which describes how strong your core element is at that point, not events in your life","ko":". 이는 그 자리에서 일간의 힘을 말할 뿐 삶의 사건을 뜻하지 않아요"},"none":{"en":"","ko":""}},"stageName":{"jangsaeng":{"en":"Birth","ko":"장생(長生)"},"mokyok":{"en":"Bathing","ko":"목욕(沐浴)"},"gwandae":{"en":"Coming of Age","ko":"관대(冠帶)"},"geonrok":{"en":"Prime","ko":"건록(建祿)"},"jewang":{"en":"Peak","ko":"제왕(帝旺)"},"soe":{"en":"Waning","ko":"쇠(衰)"},"byeong":{"en":"Slowing","ko":"병(病)"},"sa":{"en":"Resting","ko":"사(死)"},"myo":{"en":"Gathering In","ko":"묘(墓)"},"jeol":{"en":"Clean Break","ko":"절(絶)"},"tae":{"en":"Seed","ko":"태(胎)"},"yang":{"en":"Taking Shape","ko":"양(養)"}}},"bundles":{"OV_FEEL_甲":{"tags":["dm:甲"],"v":[{"en":"You may have noticed that your life moves in long, straight lines: slow to start, hard to stop.","ko":"삶이 길고 곧은 선처럼 나아간다는 걸 느낀 적이 있을지도 몰라요. 시작은 느리지만, 한번 움직이면 잘 멈추지 않죠."},{"en":"You may have found that you grow best when nobody is rushing you.","ko":"아무도 재촉하지 않을 때 가장 잘 자란다는 걸 느꼈을지도 몰라요."}],"card":"overview"},"OV_MEAN_甲":{"tags":["dm:甲"],"v":[{"en":"Your core element, set by the day you were born, is Oak, the strong side of Wood: the tall tree. A tree's story is told in its rings, so your chart rewards years of steady growth more than quick wins.","ko":"태어난 날이 정해 주는 나의 중심 기운은 큰 나무, 곧 나무 기운의 굳센 쪽이에요. 나무의 이야기는 나이테에 새겨져요. 그래서 이 사주는 빨리 얻는 것보다 여러 해 꾸준히 자라는 쪽에 힘을 실어 줘요."},{"en":"The day you were born gives you Oak as your core element: the tall tree, the strong side of Wood. Oak grows toward the light on a straight trunk, so your chart rewards patience, a clear direction, and roots that deepen year by year.","ko":"태어난 날이 준 나의 중심 기운은 큰 나무, 나무 기운의 굳센 쪽이에요. 큰 나무는 곧은 줄기로 빛을 향해 자라요. 그래서 이 사주는 인내와 분명한 방향, 해마다 깊어지는 뿌리에 보답하는 편이에요."}],"card":"overview"},"OV_FEEL_乙":{"tags":["dm:乙"],"v":[{"en":"Looking back, some of your turning points may have come through people rather than plans.","ko":"돌아보면 인생의 전환점 몇몇은 계획보다 사람을 통해 왔을지도 몰라요."},{"en":"One good introduction may have changed your path more than any plan did.","ko":"좋은 소개 한 번이 어떤 계획보다 길을 더 크게 바꿨을지도 몰라요."}],"card":"overview"},"OV_MEAN_乙":{"tags":["dm:乙"],"v":[{"en":"Your core element, set by the day you were born, is Ivy, the gentle side of Wood: the climbing vine. Ivy climbs by finding supports, so across your life the right connections may open doors that effort alone wouldn't.","ko":"태어난 날로 정해지는 나의 중심 기운은 나무의 부드러운 쪽인 덩굴(Ivy), 곧 타고 오르는 넝쿨이에요. 덩굴은 기댈 곳을 찾아 올라가요. 그래서 살아가는 동안 노력만으로 안 열리던 문이 좋은 인연을 통해 열릴 수 있어요."},{"en":"The day you were born gives you Ivy as your core element: the climbing vine, the gentle side of Wood. Ivy reaches the top by leaning on good supports, so your chart opens up most through the people and places you choose to grow beside.","ko":"태어난 날이 정해 준 나의 중심 기운은 덩굴(Ivy)이에요. 타고 오르는 넝쿨, 나무의 부드러운 쪽이죠. 덩굴은 좋은 받침에 기대어 꼭대기에 닿아요. 그래서 이 사주는 어떤 사람, 어떤 자리 곁에서 자라기로 하느냐에 따라 가장 크게 열려요."}],"card":"overview"},"OV_FEEL_丙":{"tags":["dm:丙"],"v":[{"en":"You may have heard more than once that a room feels warmer when you walk in.","ko":"\"네가 오면 방이 환해진다\"는 말을 한 번 넘게 들어 봤을지도 몰라요."},{"en":"You may have noticed that people open up faster when you're around, even people you have just met.","ko":"당신이 곁에 있으면 처음 만난 사람도 금세 마음을 여는 걸 느낀 적이 있을지도 몰라요."}],"card":"overview"},"OV_MEAN_丙":{"tags":["dm:丙"],"v":[{"en":"Your core element, the element of the day you were born, is Sunshine (yang Fire): the sun. Sunshine lives by giving light, and your chart's long story is about learning when to shine fully and when to set and rest.","ko":"태어난 날의 기운인 나의 중심 기운은 햇빛(Sunshine), 양의 불, 곧 해예요. 햇빛은 빛을 주며 살아가고, 당신 사주의 긴 이야기는 언제 한껏 비추고 언제 저물어 쉴지를 배우는 과정이에요."},{"en":"Your core element, the element of the day you were born, is Sunshine (yang Fire): the sun. Sunshine warms whatever it reaches, so your chart is about generosity and visibility, and about remembering that even the sun rests at night.","ko":"태어난 날의 기운인 나의 중심 기운은 햇빛(Sunshine), 양의 불, 곧 해예요. 햇빛은 닿는 곳마다 따뜻하게 데워요. 그래서 이 사주는 베풂과 드러남에 관한 이야기이고, 해도 밤에는 쉰다는 걸 기억하는 이야기예요."}],"card":"overview"},"OV_FEEL_丁":{"tags":["dm:丁"],"v":[{"en":"Your life may look quieter from the outside than it feels from the inside.","ko":"밖에서 보이는 당신의 삶은 안에서 느끼는 것보다 조용해 보일지도 몰라요."},{"en":"The things you care about most may be the ones you rarely talk about.","ko":"가장 아끼는 것일수록 입 밖에 잘 꺼내지 않을지도 몰라요."}],"card":"overview"},"OV_MEAN_丁":{"tags":["dm:丁"],"v":[{"en":"Your core element, the element of the day you were born, is Firefly (yin Fire): a small light that keeps going, like a firefly's steady glow. A small light lasts by being protected and focused, so your chart grows through depth: a few people and a few crafts, tended well over many years.","ko":"당신의 중심 기운, 곧 태어난 날의 기운은 반딧불(음의 불)이에요. 반딧불이의 꾸준한 빛처럼 작게 이어지는 빛이죠. 작은 빛은 잘 지켜지고 한곳에 모일 때 오래가요. 그래서 이 사주는 넓이보다 깊이로 자라요. 몇 사람, 몇 가지 솜씨를 오랜 세월 잘 돌보는 방식이죠."},{"en":"Your core element, the element of the day you were born, is Firefly (yin Fire): a small light that keeps going. A small flame lights a whole room when it's sheltered, so your chart does best with a few close bonds and something you can give your full attention.","ko":"당신의 중심 기운, 곧 태어난 날의 기운은 반딧불(음의 불), 작게 이어지는 빛이에요. 작은 불꽃도 바람을 막아 주면 방 하나를 환하게 밝혀요. 그래서 이 사주는 가까운 몇 사람, 온 마음을 쏟을 수 있는 일 하나와 함께할 때 가장 잘 맞아요."}],"card":"overview"},"OV_FEEL_戊":{"tags":["dm:戊"],"v":[{"en":"People may have leaned on you since you were young, sometimes more than you asked for.","ko":"어릴 때부터 사람들이 당신에게 기대 왔을지도 몰라요. 가끔은 원한 것보다 더 많이요."},{"en":"You may have felt that others expect you to be the steady one, even on days you feel unsure.","ko":"마음이 흔들리는 날에도 사람들이 당신에게 든든한 쪽이기를 기대한다고 느꼈을지도 몰라요."}],"card":"overview"},"OV_MEAN_戊":{"tags":["dm:戊"],"v":[{"en":"Your core element, the element of the day you were born, is Rock (yang Earth): the great mountain. Rock changes slowly and holds a lot, so your life story is shaped by what you carry and protect, and by learning what you can set down.","ko":"태어난 날의 기운인 나의 중심 기운은 바위산, 곧 흙 기운의 굳센 쪽이에요. 바위는 천천히 변하고 많은 것을 품어요. 그래서 당신의 인생 이야기는 무엇을 지고 지키는지, 그리고 무엇을 내려놓아도 되는지 배우는 과정으로 그려져요."},{"en":"Your core element, the element of the day you were born, is Rock (yang Earth): the great mountain. A mountain gives others a place to stand and shelter from the weather, so your chart is about steadiness, and about learning that the weight can be shared.","ko":"태어난 날의 기운인 나의 중심 기운은 바위산, 흙 기운의 굳센 쪽이에요. 산은 사람들에게 딛고 설 자리와 비바람을 피할 곳을 내줘요. 그래서 이 사주는 든든함에 관한 이야기이고, 짐은 나누어 질 수 있다는 걸 배우는 이야기예요."}],"card":"overview"},"OV_FEEL_己":{"tags":["dm:己"],"v":[{"en":"You may find that your best years were the ones when something you planted finally came up.","ko":"심어 둔 무언가가 마침내 싹을 틔운 해가 가장 좋은 해였다고 느낄지도 몰라요."},{"en":"You may notice that the things that matter most to you grew slowly, then seemed to bloom all at once.","ko":"당신에게 가장 소중한 것들은 천천히 자라다가 어느 순간 한꺼번에 피어난 것처럼 느껴질지도 몰라요."}],"card":"overview"},"OV_MEAN_己":{"tags":["dm:己"],"v":[{"en":"Your core element, the element of the day you were born, is Meadow (yin Earth): fertile soil, the meadow, and the field. A meadow works in seasons of sowing, tending, and harvest, and your chart reads best as a series of patient seasons rather than one big leap.","ko":"태어난 날의 기운인 나의 중심 기운은 들판(Meadow), 부드러운 흙이에요. 기름진 땅, 풀밭, 밭이죠. 들판은 씨 뿌리고 가꾸고 거두는 계절로 움직여요. 이 사주는 한 번의 큰 도약보다 참을성 있는 계절들이 이어지는 이야기로 읽을 때 가장 잘 맞아요."},{"en":"Your core element, set by the day you were born, is Meadow (yin Earth): rich soil, open meadow, and working field. Soil gives back what's planted in it, so your chart favors patient care, good timing, and small steps that add up over the seasons.","ko":"태어난 날로 정해지는 나의 중심 기운은 들판(Meadow), 부드러운 흙이에요. 기름진 흙, 탁 트인 풀밭, 일구는 밭이죠. 흙은 심은 것을 길러 돌려줘요. 그래서 이 사주는 차분한 돌봄과 알맞은 때, 계절마다 쌓이는 작은 걸음과 잘 맞아요."}],"card":"overview"},"OV_FEEL_庚":{"tags":["dm:庚"],"v":[{"en":"Some of your clearest growth may have come right after a hard moment.","ko":"가장 뚜렷하게 성장한 때는 힘든 순간 바로 뒤였을지도 몰라요."},{"en":"One clear, honest talk may have done more for you than months of hinting.","ko":"돌려 말하며 보낸 몇 달보다 솔직하고 분명한 대화 한 번이 더 도움이 되었을지도 몰라요."}],"card":"overview"},"OV_MEAN_庚":{"tags":["dm:庚"],"v":[{"en":"Your core element, the element of the day you were born, is Blade (yang Metal): raw ore and the unpolished blade. Traditionally this metal is sharpened by fire, so your life may grow through challenge, and your strength often shows most when something real is at stake.","ko":"태어난 날의 기운인 나의 중심 기운은 칼(Blade), 양의 쇠, 곧 원석과 아직 다듬지 않은 칼이에요. 전통적으로 이 쇠는 불을 만나 날이 서요. 그래서 당신의 삶은 도전을 거치며 자랄 수 있고, 무언가 진짜로 걸려 있을 때 힘이 가장 잘 드러나는 편이에요."},{"en":"Your core element, the element of the day you were born, is Blade (yang Metal): raw ore and the unpolished blade. Raw metal gets its edge in the forge, so your chart sharpens through real tests, and your clarity shows when something truly matters.","ko":"태어난 날의 기운인 나의 중심 기운은 칼(Blade), 양의 쇠, 곧 원석과 아직 다듬지 않은 칼이에요. 날것의 쇠는 대장간 불에서 날이 서요. 그래서 이 사주는 실제 시험을 거치며 다듬어지고, 정말 중요한 순간에 분명함이 드러나요."}],"card":"overview"},"OV_FEEL_辛":{"tags":["dm:辛"],"v":[{"en":"You may keep a long memory for both kindness and small slights.","ko":"친절도, 작은 서운함도 오래 기억하는 편일지 몰라요."},{"en":"A small detail, done well, may matter a lot to you.","ko":"작은 부분이라도 제대로 해 놓았는지가 당신에게 꽤 중요할지도 몰라요."}],"card":"overview"},"OV_MEAN_辛":{"tags":["dm:辛"],"v":[{"en":"Your core element, the element of the day you were born, is Gem (yin Metal): the polished gem. A gem gains value through care and the right setting, so your chart's long story is about finding places and people that recognize quality, including your own.","ko":"당신의 중심 기운, 곧 태어난 날의 기운은 보석(음의 쇠), 잘 다듬어진 보석이에요. 보석은 정성스러운 손길과 알맞은 자리에서 값어치가 올라가요. 그래서 이 사주의 긴 이야기는 좋은 것을 알아보는 곳과 사람을 찾아가는 과정이에요. 당신 자신의 가치도 포함해서요."},{"en":"Your core element, set by the day you were born, is Gem (yin Metal), a finely polished stone. A gem shines most under the right light, so your chart is about finding the setting where your high standards and care for detail are welcomed.","ko":"태어난 날로 정해지는 당신의 중심 기운은 보석(음의 쇠), 곱게 다듬어진 돌이에요. 보석은 알맞은 빛 아래에서 가장 빛나요. 그래서 이 사주는 높은 기준과 섬세함을 반겨 주는 자리를 찾아가는 이야기예요."}],"card":"overview"},"OV_FEEL_壬":{"tags":["dm:壬"],"v":[{"en":"Your life may have taken more turns than you once expected: changes of direction and new chapters.","ko":"생각했던 것보다 인생의 굽이가 많았을지도 몰라요. 방향 전환과 새로운 장들이요."},{"en":"You may have learned the most in places you didn't plan to be.","ko":"계획하지 않았던 곳에서 가장 많이 배웠을지도 몰라요."}],"card":"overview"},"OV_MEAN_壬":{"tags":["dm:壬"],"v":[{"en":"Your core element, the element of the day you were born, is Ocean (yang Water): the great river that runs to the open sea. Big water doesn't move in straight lines; it finds the way through. Your chart suggests a life of movement. Breadth of experience may become your wisdom.","ko":"태어난 날의 기운인 나의 중심 기운은 큰 물, 곧 물 기운의 굳센 쪽으로, 넓은 바다로 흘러가는 큰 강이에요. 큰 물은 곧게 흐르지 않고 길을 찾아 흘러가요. 이 사주는 움직임이 많은 삶을 보여 줘요. 넓은 경험이 곧 지혜가 될 수 있어요."},{"en":"Your core element, the element of the day you were born, is Ocean (yang Water): the great river that runs to the open sea. A big river gathers many streams into one. Your chart is about range, about connecting far-apart people and ideas, and about trusting your own current.","ko":"태어난 날의 기운인 나의 중심 기운은 큰 물, 물 기운의 굳센 쪽으로, 넓은 바다로 흘러가는 큰 강이에요. 큰 강은 여러 갈래의 물을 하나로 모아요. 이 사주는 폭넓음, 멀리 떨어진 사람과 생각을 잇는 일, 내 물길을 믿는 일에 관한 이야기예요."}],"card":"overview"},"OV_FEEL_癸":{"tags":["dm:癸"],"v":[{"en":"You may sense changes in people and places before anyone says a word.","ko":"누가 말하기 전에 사람과 공간의 변화를 먼저 알아차리곤 할지도 몰라요."},{"en":"A quiet moment alone may be what sets your mood right again.","ko":"혼자 있는 조용한 시간이 마음을 다시 제자리로 돌려놓을지도 몰라요."}],"card":"overview"},"OV_MEAN_癸":{"tags":["dm:癸"],"v":[{"en":"Your core element, the element of the day you were born, is Rain (yin Water): rain and dew. Rain works quietly and reaches everywhere, so your chart's long story is about influence that's felt more than seen, and about protecting your own calm.","ko":"태어난 날의 기운인 나의 중심 기운은 비(Rain), 부드러운 물이에요. 비와 이슬이죠. 비는 조용히 모든 곳에 닿아요. 그래서 이 사주의 긴 이야기는 눈에 보이기보다 느껴지는 영향력, 그리고 내 마음의 고요를 지키는 일에 관한 것이에요."},{"en":"Your core element, the element of the day you were born, is Rain (yin Water): rain and dew. Rain reaches roots that nothing else can, so your chart is about quiet care and deep listening, and about keeping some calm that's only yours.","ko":"태어난 날의 기운인 나의 중심 기운은 비(Rain), 부드러운 물이에요. 비와 이슬이죠. 비는 다른 무엇도 닿지 못하는 뿌리까지 스며들어요. 그래서 이 사주는 조용한 보살핌과 깊이 귀 기울이기, 오직 나만의 고요를 지키는 일에 관한 이야기예요."}],"card":"overview"},"OV_STR_strong":{"tags":["strength:strong"],"v":[{"en":"Your chart is well stocked: many of its elements support your core element. Traditionally that reads as plenty of drive, and these days it helps to give that energy somewhere useful to go.","ko":"당신의 사주는 기운이 넉넉하게 채워져 있어요. 사주 안의 많은 기운이 나의 중심 기운을 받쳐 줘요. 전통적으로는 추진력이 넉넉한 모습으로 읽고, 요즘은 그 힘을 쓸모 있는 곳으로 흘려보내 보면 좋아요."},{"en":"Your chart leans strong: many of its elements back up your core element. Traditionally that's read as a lot of drive, so these days it may help to point that drive at something that matters to you.","ko":"당신의 사주는 힘이 센 쪽으로 기울어 있어요. 많은 기운이 나의 중심 기운을 뒷받침해요. 전통적으로는 추진력이 큰 모습으로 읽으니, 요즘은 그 힘을 내게 의미 있는 일로 향하게 해 보면 좋아요."},{"en":"Many of the elements in your chart support your core element, which we call a strong chart. Tradition reads this as energy to spare, so these days it helps to ask where you want to spend it.","ko":"사주 안의 많은 기운이 나의 중심 기운을 도와서, 우리는 이것을 힘이 센 사주라 불러요. 전통에서는 쓰고도 남는 힘으로 읽으니, 요즘은 그 힘을 어디에 쓰고 싶은지 스스로 물어보면 좋아요."},{"en":"Your chart runs on a full tank: a good share of its elements feed and back up your core element. Traditionally that's read as a steady supply of drive, so these days it helps to decide what's worth that energy.","ko":"당신의 사주는 연료가 가득 찬 상태로 달려요. 사주 안의 기운 가운데 상당 부분이 나의 중심 기운을 채우고 받쳐 줘요. 전통적으로는 추진력이 꾸준히 나오는 모습으로 읽으니, 요즘은 그 힘을 들일 만한 일이 무엇인지 정해 보면 좋아요."}],"card":"overview"},"OV_STR_weak":{"tags":["strength:weak"],"v":[{"en":"Your chart leans on support: more of the elements in your chart draw on your core element than refill it, so outside support matters more for you. This can be read as sensitivity and a gift for teamwork, and these days it helps to build steady sources of care around you.","ko":"당신의 사주는 곁의 도움에 기대는 쪽이에요. 나의 중심 기운을 채워 주는 기운보다 그 힘을 가져다 쓰는 기운이 더 많아서, 바깥의 도움이 더 중요해요. 섬세함과 협력의 재능으로 풀어 볼 수 있고, 요즘은 곁에 꾸준히 기댈 곳을 만들어 두면 좋아요."},{"en":"Your chart leans on support: more of its elements use up your core element's strength than add to it. This pattern can be read as attentiveness and care for people, so these days it helps to arrange steady places to recharge.","ko":"당신의 사주는 곁의 도움에 기대는 쪽이에요. 나의 중심 기운에 힘을 보태는 기운보다 그 힘을 써 버리는 기운이 더 많아요. 세심함과 사람을 살피는 마음으로 풀어 볼 수 있으니, 요즘은 꾸준히 기운을 채울 자리를 마련해 두면 좋아요."},{"en":"More of the elements in your chart draw on your core element than feed it, which we call leaning on support. That can be read as care for others, so these days it helps to protect your own reserves.","ko":"사주 안에 나의 중심 기운을 채우는 기운보다 그 힘을 가져다 쓰는 기운이 더 많아요. 이런 모습을 '곁의 도움에 기대는 쪽'이라 불러요. 남을 살피는 마음으로 풀어 볼 수 있고, 요즘은 내 기운의 여유분을 지켜 두면 좋아요."},{"en":"Your chart leans on support: more of the elements around your core element take from it than give back. That can be read as a caring nature, so these days it helps to line up people and routines that give back to you.","ko":"당신의 사주는 곁의 도움에 기대는 쪽이에요. 나의 중심 기운 둘레의 기운들이 돌려주기보다 가져가는 쪽이 많다는 뜻이에요. 마음 씀씀이가 깊은 모습으로 풀어 볼 수 있으니, 요즘은 나에게 되돌려 주는 사람과 습관을 곁에 두면 좋아요."},{"en":"Your chart leans on support, which means your core element gets drawn on more than it gets refilled. This can be read as a chart that does well with good company, so these days it helps to choose your support on purpose.","ko":"당신의 사주는 곁의 도움에 기대는 쪽이에요. 나의 중심 기운이 채워지는 것보다 쓰이는 일이 더 많다는 뜻이에요. 좋은 사람들과 함께할 때 잘 풀리는 사주로 읽을 수 있으니, 요즘은 곁에 둘 도움을 일부러 골라 보면 좋아요."},{"en":"Your chart has more elements that use your core element's energy than ones that restore it, so having a few dependable people and places for rest close by helps.","ko":"사주에 나의 중심 기운을 되살리는 기운보다 그 힘을 쓰는 기운이 더 많아서, 믿을 만한 사람 몇과 쉴 곳을 가까이 두면 도움이 돼요."}],"card":"overview"},"OV_STR_balanced":{"tags":["strength:balanced"],"v":[{"en":"Your chart is balanced (our middle range): what feeds your core element and what draws on it are fairly even. That leaves room to adapt, and these days it helps to choose a direction rather than wait for one.","ko":"당신의 사주는 균형 잡힌 편(우리 기준의 중간 구간)이에요. 나의 중심 기운을 채워 주는 힘과 가져다 쓰는 힘이 비교적 고르다는 뜻이에요. 적응할 여지가 넓으니, 요즘은 방향이 정해지길 기다리기보다 직접 골라 보면 좋아요."},{"en":"Your chart sits in our middle range: the forces feeding your core element and the forces drawing on it are close to even. That gives you flexibility, and these days it helps to decide where to lean instead of waiting to be pushed.","ko":"당신의 사주는 우리 기준의 중간 구간에 있어요. 나의 중심 기운을 채우는 힘과 끌어다 쓰는 힘이 거의 비슷해요. 그만큼 유연하니, 요즘은 떠밀리길 기다리기보다 어느 쪽에 힘을 실을지 정해 보면 좋아요."},{"en":"Your chart is nicely even: support for your core element and demands on it are close to equal. It leaves many roads open, so these days it helps to pick a road on purpose.","ko":"당신의 사주는 보기 좋게 고른 편이에요. 나의 중심 기운을 돕는 힘과 요구하는 힘이 거의 같아요. 열린 길이 많으니, 요즘은 그중 한 길을 일부러 골라 보면 좋아요."},{"en":"Your chart is balanced (our middle range): the elements that feed your core element and the ones that draw on it come out about level. That keeps your options open, so these days it helps to say out loud which way you want to go.","ko":"당신의 사주는 균형 잡힌 편(우리 기준의 중간 구간)이에요. 나의 중심 기운을 채우는 기운과 가져다 쓰는 기운이 비슷한 높이로 나와요. 선택지가 열려 있으니, 요즘은 어느 쪽으로 가고 싶은지 소리 내어 말해 보면 좋아요."}],"card":"overview"},"OV_ACT_strong":{"tags":["strength:strong"],"v":[{"en":"This month, pick one project where your energy serves someone besides you, and put one hour into it.","ko":"이번 달, 내 힘이 나 아닌 누군가에게도 쓰이는 일 하나를 골라 한 시간을 써 보세요."},{"en":"This month, hand one task you usually grab to someone else, and use the freed hour on something bigger.","ko":"이번 달, 늘 내가 먼저 잡던 일 하나를 다른 사람에게 넘기고, 남은 한 시간을 더 큰 일에 써 보세요."},{"en":"This month, ask one person what they need that your energy could help with, and give it one hour.","ko":"이번 달, 내 힘이 도움이 될 만한 일이 있는지 한 사람에게 물어보고 한 시간을 내어 보세요."},{"en":"This month, slow one thing down on purpose and notice what you see when you aren't rushing.","ko":"이번 달, 한 가지 일을 일부러 천천히 해 보고 서두르지 않을 때 보이는 것을 살펴보세요."},{"en":"This month, finish one thing that's almost done instead of starting something new.","ko":"이번 달, 새로운 일을 시작하기보다 거의 끝나 가는 일 하나를 마무리해 보세요."}],"card":"overview"},"OV_ACT_weak":{"tags":["strength:weak"],"v":[{"en":"This month, name two people or places that reliably recharge you, and put one of them on your calendar.","ko":"이번 달, 힘이 잘 채워지는 사람이나 장소 두 곳을 적고, 그중 하나를 달력에 넣어 보세요."},{"en":"This month, say \"let me think about it\" before one new commitment, and check your energy before you answer.","ko":"이번 달, 새 약속 하나 앞에서 \"생각해 볼게요\"라고 먼저 말하고, 내 기운을 살핀 뒤에 답해 보세요."},{"en":"This month, pick one small routine that restores you, such as a walk or a quiet cup of tea, and do it three times.","ko":"이번 달, 산책이나 조용한 차 한 잔처럼 나를 회복시키는 작은 습관 하나를 골라 세 번 해 보세요."},{"en":"This month, ask one trusted person for one small piece of help, and notice how it feels to receive it.","ko":"이번 달, 믿는 사람 한 명에게 작은 도움 하나를 부탁하고, 받을 때 어떤 기분인지 살펴보세요."},{"en":"This month, plan one rest day or half-day in advance, and treat it as non-negotiable.","ko":"이번 달, 쉬는 날이나 반나절을 미리 하나 잡아 두고, 바꿀 수 없는 약속처럼 지켜 보세요."},{"en":"This month, write down three things that leave you feeling full afterward, and do one of them this week.","ko":"이번 달, 하고 나면 마음이 채워지는 일 세 가지를 적고 이번 주에 그중 하나를 해 보세요."}],"card":"overview"},"OV_ACT_balanced":{"tags":["strength:balanced"],"v":[{"en":"This month, write one sentence about where you want to be in ten years, and keep it where you'll see it.","ko":"이번 달, 10년 뒤 어디에 있고 싶은지 한 문장으로 적어 눈에 보이는 곳에 두세요."},{"en":"This month, choose one direction you keep circling and take the smallest possible first step on it.","ko":"이번 달, 계속 맴돌기만 하던 방향 하나를 골라 가장 작은 첫걸음을 떼어 보세요."},{"en":"This month, list two directions you could take and write one honest reason for each, then pick the one you can start this week.","ko":"이번 달, 선택할 수 있는 방향 두 가지를 적고 각각 솔직한 이유를 하나씩 쓴 뒤, 이번 주에 시작할 수 있는 쪽을 골라 보세요."},{"en":"This month, say yes to one small experiment in a direction you have only been thinking about.","ko":"이번 달, 생각만 해 오던 방향에서 작은 시도 하나를 해 보겠다고 정해 보세요."}],"card":"overview"},"OV_SEASON_spring":{"tags":["season:spring"],"v":[{"en":"You were born in the spring months of the traditional seasonal calendar, when Wood energy is rising, a season linked with beginnings and growth.","ko":"당신은 전통 계절 달력의 봄, 나무 기운이 올라오는 달에 태어났어요. 시작과 성장의 계절이에요."},{"en":"Your birthday fell in the spring part of the traditional seasonal calendar, when Wood energy is climbing. It's a season linked with new starts and steady growth.","ko":"당신의 생일은 전통 계절 달력의 봄, 나무 기운이 차오르는 때에 있어요. 새 출발과 꾸준한 성장과 이어진 계절이에요."},{"en":"You arrived in the spring stretch of the traditional seasonal calendar, when Wood energy is waking up. This season is tied to first steps and things taking root.","ko":"당신은 전통 계절 달력의 봄 무렵, 나무 기운이 깨어나는 때에 태어났어요. 첫걸음과 뿌리내림에 이어진 계절이에요."}],"card":"overview"},"OV_SEASON_summer":{"tags":["season:summer"],"v":[{"en":"You were born in the summer months of the traditional seasonal calendar, when Fire energy is at its height, a season linked with warmth and full expression.","ko":"당신은 전통 계절 달력의 여름, 불 기운이 가장 높은 달에 태어났어요. 따뜻함과 활짝 드러냄의 계절이에요."},{"en":"Your birth fell in the summer part of the traditional seasonal calendar, when Fire energy runs highest. It's a season linked with brightness and showing what you have.","ko":"당신의 생일은 전통 계절 달력의 여름, 불 기운이 가장 높이 오르는 때에 있어요. 밝음과 가진 것을 드러냄에 이어진 계절이에요."},{"en":"You arrived in the summer stretch of the traditional seasonal calendar, when Fire energy is strongest. This season is tied to energy, visibility, and full effort.","ko":"당신은 전통 계절 달력의 여름 무렵, 불 기운이 가장 센 때에 태어났어요. 활기와 드러남, 온 힘을 다함에 이어진 계절이에요."}],"card":"overview"},"OV_SEASON_autumn":{"tags":["season:autumn"],"v":[{"en":"You were born in the autumn months of the traditional seasonal calendar, when Metal energy gathers, a season linked with harvest, sorting, and clarity.","ko":"당신은 계절 흐름을 따르는 전통 달력의 가을, 쇠 기운이 모이는 달에 태어났어요. 거두고 가려내고 맑아지는 계절이에요."},{"en":"Your birth fell in the autumn part of the traditional seasonal calendar, when Metal energy is drawing in. It's a season linked with gathering results and seeing things clearly.","ko":"당신의 생일은 계절 흐름을 따르는 전통 달력의 가을, 쇠 기운이 모여드는 때에 있어요. 결과를 거두고 또렷이 보는 일과 이어진 계절이에요."},{"en":"You arrived in the autumn stretch of the traditional seasonal calendar, when Metal energy is sharpening. This season is tied to editing, choosing, and letting go of extras.","ko":"당신은 전통 계절 달력의 가을 무렵, 쇠 기운이 날카로워지는 때에 태어났어요. 다듬고 고르고 덜어 내는 일에 이어진 계절이에요."}],"card":"overview"},"OV_SEASON_winter":{"tags":["season:winter"],"v":[{"en":"You were born in the winter months of the traditional seasonal calendar, when Water energy settles, a season linked with rest, storing, and reflection.","ko":"당신은 전통 계절 달력의 겨울, 물 기운이 가라앉는 달에 태어났어요. 쉬고 저장하고 돌아보는 일과 이어진 계절이에요."},{"en":"Your birthday falls in winter on the traditional seasonal calendar, when Water energy runs deep. It's a season tied to quiet, saving your strength, and looking inward.","ko":"당신의 생일은 전통 계절 달력으로 겨울, 물 기운이 깊어지는 때에 있어요. 고요함과 힘을 아껴 두기, 안을 들여다보기와 이어진 계절이에요."},{"en":"You arrived in the winter stretch of the traditional seasonal calendar, when Water is still and deep. This season is linked with patience, preparation, and a rich inner life.","ko":"당신은 전통 계절 달력의 겨울 무렵, 물이 고요하고 깊은 때에 태어났어요. 인내와 준비, 풍성한 속마음과 이어진 계절이에요."}],"card":"overview"},"OV_DECADE_best":{"tags":["dy:single"],"v":[{"en":"By our own scoring, the most active decade among your current and coming cycles is {bestList}.","ko":"우리 자체 채점으로, 지금과 앞으로의 대운 가운데 힘이 가장 큰 10년은 {bestList}(이)에요."},{"en":"On our own scoring, {bestList} is the most active decade among your current and coming cycles.","ko":"우리 자체 채점으로는 {bestList}이(가) 지금과 앞으로의 대운 가운데 힘이 가장 큰 10년이에요."}],"card":"overview"},"OV_DECADE_even":{"tags":["dy:single","decade:even"],"v":[{"en":"Your current and coming 10-year cycles look fairly even on our measure, so no single decade stands far above the others.","ko":"우리 기준으로 보면 지금과 앞으로의 10년 대운이 비교적 고르게 나와서, 어느 한 시기가 크게 두드러지지 않아요."},{"en":"On our scoring, your current and coming 10-year cycles come out close to even, so none stands out as the most active.","ko":"우리 채점으로는 지금과 앞으로의 10년 대운이 거의 고르게 나와서, 유난히 힘이 큰 시기가 따로 보이지 않아요."}],"card":"overview"},"OV_DECADE_both":{"tags":["dy:both"],"v":[{"en":"Traditionally, the direction of your 10-year cycles depends on whether you are male or female, so the Life Timeline below shows both.","ko":"전통적으로 10년 대운의 방향은 남자냐 여자냐에 따라 정해지기 때문에, 아래 인생 흐름 칸에 두 방향을 모두 보여 드려요."},{"en":"The Life Timeline below shows two versions of your 10-year cycles, because the traditional method sets their direction by whether you are male or female.","ko":"전통 방식은 남자냐 여자냐로 대운 방향을 정하기 때문에, 아래 인생 흐름 칸에 10년 대운을 두 가지로 보여 드려요."},{"en":"Because the traditional method sets the direction by whether you are male or female, the Life Timeline below shows your 10-year cycles both ways.","ko":"전통 방식은 남자냐 여자냐로 방향을 정하기 때문에, 아래 인생 흐름 칸에는 10년 대운을 두 방향으로 모두 보여 드려요."},{"en":"Your 10-year cycles are shown both ways below, since in the traditional method their direction depends on whether you are male or female.","ko":"10년 대운의 방향은 전통 방식에서 남자냐 여자냐에 달려 있어서, 아래에 두 방향을 모두 보여 드려요."}],"card":"overview"},"WHO_FEEL_甲":{"tags":["dm:甲"],"v":[{"en":"You may care more about doing something right than doing it fast.","ko":"무언가를 빨리 하기보다 제대로 하는 걸 더 중요하게 여기는 편일지도 몰라요."},{"en":"You may find it hard to start something until you know where it's heading.","ko":"어디로 가는 일인지 알기 전에는 시작하기가 어려울 수 있어요."}],"card":"personality"},"WHO_MEAN_甲":{"tags":["dm:甲"],"v":[{"en":"As Oak, you may carry the tree's instinct for direction: picking a line, growing along it, and keeping your word.","ko":"큰 나무(Oak)로서 당신은 나무의 방향 감각을 지닌 모습으로 읽어요. 한 줄기를 정하고, 그 길로 자라며, 약속을 지키는 모습이죠."},{"en":"With Oak as your core element, you may bring a steady backbone to the people around you: choosing a direction, staying with it, and becoming someone others can count on.","ko":"큰 나무(Oak)가 나의 중심 기운인 당신은 주변 사람들에게 곧은 줄기가 되어 줄 수 있어요. 방향을 정하면 끝까지 가고, 사람들이 믿고 기대는 사람이 되기도 해요."}],"card":"personality"},"WHO_FEEL_乙":{"tags":["dm:乙"],"v":[{"en":"You may read a room within minutes of walking in.","ko":"어떤 자리에 들어서면 몇 분 안에 분위기를 읽어 내는 편일지도 몰라요."},{"en":"You may adjust your tone to the person in front of you, sometimes without noticing.","ko":"눈앞의 사람에게 맞춰 말투를 바꾸고 있다는 걸 스스로도 모를 때가 있을 수 있어요."}],"card":"personality"},"WHO_MEAN_乙":{"tags":["dm:乙"],"v":[{"en":"As Ivy, you may carry the vine's instinct for connection: bending where needed, linking people, and climbing quietly.","ko":"담쟁이로서 당신은 덩굴의 연결 감각을 지닌 모습으로 읽어요. 필요한 곳에서 굽히고, 사람을 잇고, 조용히 계속 올라가는 모습이죠."},{"en":"With Ivy as your core element, you may be flexible and well connected: adapting to the setting, bringing people together, and rising without making noise.","ko":"담쟁이가 나의 중심 기운인 당신은 유연하고 사람을 잘 잇는 편일 수 있어요. 상황에 맞춰 적응하고, 사람들을 모아 주고, 소란 없이 올라가요."}],"card":"personality"},"WHO_FEEL_丙":{"tags":["dm:丙"],"v":[{"en":"You may say what you feel as soon as you feel it.","ko":"느낀 것을 느끼는 즉시 말하는 편일지도 몰라요."},{"en":"You may find it hard to hide that you're happy, or that you aren't.","ko":"기쁜 마음도, 그렇지 않은 마음도 숨기기 어려울 수 있어요."}],"card":"personality"},"WHO_MEAN_丙":{"tags":["dm:丙"],"v":[{"en":"As Sunshine, you may carry the sun's instinct for openness: warming the room, including everyone, and speaking plainly.","ko":"햇빛으로서 당신은 햇살의 열린 감각을 지닌 모습으로 읽어요. 공간을 데우고, 모두를 챙기고, 솔직하게 말하는 모습이죠."},{"en":"With Sunshine as your core element, you may bring openness to a room: making space for everyone and saying things plainly and warmly.","ko":"햇빛을 나의 중심 기운으로 지닌 당신은 어느 자리에서든 열린 분위기를 만들 수 있어요. 모두에게 자리를 내어 주고, 솔직하고 따뜻하게 말하는 편이에요."}],"card":"personality"},"WHO_FEEL_丁":{"tags":["dm:丁"],"v":[{"en":"You may notice the tired voice or the unsaid worry before anyone else does.","ko":"지친 목소리나 말하지 못한 걱정을 누구보다 먼저 알아차리는 편일지도 몰라요."},{"en":"You may prefer one deep conversation to an evening of small talk.","ko":"가벼운 수다로 보내는 저녁보다 깊은 대화 하나를 더 좋아할 수 있어요."}],"card":"personality"},"WHO_MEAN_丁":{"tags":["dm:丁"],"v":[{"en":"As Firefly, you often carry the small light's instinct for focus: lighting one space well and keeping your people close.","ko":"반딧불(Firefly)인 당신은 작은 빛의 집중 감각을 지닌 경우가 많아요. 한 공간을 잘 밝히고 내 사람들을 가까이 두는 모습이죠."},{"en":"With Firefly as your core element, you may bring focus and quiet loyalty: giving your full attention to a few people and a few things.","ko":"나의 중심 기운이 반딧불(Firefly)인 당신은 집중과 조용한 의리를 지녔을 수 있어요. 몇 사람, 몇 가지 일에 온 마음을 쏟는 모습이에요."}],"card":"personality"},"WHO_FEEL_戊":{"tags":["dm:戊"],"v":[{"en":"You may stay calm when others are rushing around you.","ko":"주변이 허둥댈 때도 차분함을 유지하는 편일지도 몰라요."},{"en":"You may keep your worries to yourself so that others can feel safe.","ko":"다른 사람들이 마음을 놓을 수 있도록 걱정을 혼자 삼킬 때가 있을 수 있어요."}],"card":"personality"},"WHO_MEAN_戊":{"tags":["dm:戊"],"v":[{"en":"As Rock, you may carry the rock's instinct for holding steady: keeping promises and giving people something solid to stand on.","ko":"바위(Rock)로서 당신은 바위의 버티는 감각을 지닌 모습으로 읽어요. 약속을 지키고, 사람들이 딛고 설 단단한 자리를 내주는 모습이죠."},{"en":"With Rock as your core element, you may bring solidity: keeping your word and making sure the people around you have firm ground to stand on.","ko":"바위(Rock)가 나의 중심 기운인 당신은 단단함을 가져다줄 수 있어요. 약속을 지키고, 주변 사람들이 딛고 설 단단한 땅을 챙겨 주는 편이에요."}],"card":"personality"},"WHO_FEEL_己":{"tags":["dm:己"],"v":[{"en":"You may remember the small practical things others forget.","ko":"남들이 잊는 작고 실용적인 것들을 기억하는 편일지도 몰라요."},{"en":"You may be the one who quietly makes sure everyone has what they need.","ko":"모두에게 필요한 것이 있는지 조용히 챙기는 사람일 수 있어요."}],"card":"personality"},"WHO_MEAN_己":{"tags":["dm:己"],"v":[{"en":"As Meadow, you may carry the meadow's instinct for caring: making room, feeding growth, and tidying the details.","ko":"들판으로서 당신은 들판의 돌보는 감각을 지녔을지도 몰라요. 자리를 내어 주고, 자라게 하고, 세세한 것을 정리하는 모습이죠."},{"en":"With Meadow as your core element, you often bring care and practicality: noticing what's needed, making room for it, and keeping the details in order.","ko":"들판이 나의 중심 기운인 당신은 돌봄과 현실 감각을 자주 가져와요. 무엇이 필요한지 알아채고, 그 자리를 마련하고, 세세한 것을 가지런히 해 두죠."}],"card":"personality"},"WHO_FEEL_庚":{"tags":["dm:庚"],"v":[{"en":"You may get impatient when a decision keeps being put off.","ko":"결정이 자꾸 미뤄지면 답답해지는 편일지도 몰라요."},{"en":"You may value a straight answer more than a polite one.","ko":"정중한 대답보다 곧은 대답을 더 값지게 여길 수 있어요."}],"card":"personality"},"WHO_MEAN_庚":{"tags":["dm:庚"],"v":[{"en":"As Blade, you often carry raw metal's instinct for clarity: cutting to the point, protecting your people, and keeping things fair.","ko":"칼날로서 당신은 날것의 쇠처럼 분명함을 찾는 감각을 자주 보여 줘요. 요점으로 바로 가고, 내 사람을 지키고, 공정하게 하려는 모습이죠."},{"en":"With Blade as your core element, you may bring a clean edge: going to the point, standing up for your people, and wanting things done fairly.","ko":"칼날을 나의 중심 기운으로 지닌 당신은 깔끔한 날을 가져다줄 수 있어요. 요점으로 바로 가고, 내 사람 편에 서고, 일이 공정하게 되기를 바라는 편이에요."}],"card":"personality"},"WHO_FEEL_辛":{"tags":["dm:辛"],"v":[{"en":"You may notice when something is almost right but not quite.","ko":"무언가가 거의 맞는데 살짝 어긋났을 때 그걸 알아채는 편일지도 몰라요."},{"en":"You may be quietly hard on yourself when your effort isn't at its best.","ko":"내 결과물이 최선이 아니라고 느끼면 조용히 스스로에게 엄격해질 수 있어요."}],"card":"personality"},"WHO_MEAN_辛":{"tags":["dm:辛"],"v":[{"en":"As Gem, you may carry the gem's instinct for quality: refining, choosing carefully, and valuing what lasts.","ko":"보석(Gem)으로서 당신은 보석의 품질 감각을 지닌 모습으로 읽어요. 다듬고, 신중히 고르고, 오래가는 것을 소중히 여기는 모습이죠."},{"en":"With Gem as your core element, you often bring refinement: choosing carefully, polishing what matters, and preferring lasting quality over quick results.","ko":"나의 중심 기운이 보석(Gem)인 당신은 다듬어진 멋을 지닌 경우가 많아요. 신중히 고르고, 중요한 것을 갈고닦고, 빠른 결과보다 오래가는 품질을 좋아하는 편이에요."}],"card":"personality"},"WHO_FEEL_壬":{"tags":["dm:壬"],"v":[{"en":"You may feel restless when life stands still for too long.","ko":"삶이 너무 오래 멈춰 있으면 답답해지는 편일지도 몰라요."},{"en":"You may enjoy a change of scene more than a long stay in one place.","ko":"한곳에 오래 머무는 것보다 장소가 바뀌는 쪽을 더 즐길 수 있어요."}],"card":"personality"},"WHO_MEAN_壬":{"tags":["dm:壬"],"v":[{"en":"As Ocean, you may carry big water's instinct for movement: exploring, connecting far-apart ideas, and staying flexible.","ko":"바다(Ocean)로서 당신은 큰 물의 흐르는 감각을 지닌 모습으로 읽어요. 탐험하고, 멀리 떨어진 생각을 잇고, 유연하게 움직이는 모습이죠."},{"en":"With Ocean as your core element, you may bring movement and range: exploring, linking ideas that seem far apart, and adapting as things change.","ko":"바다(Ocean)가 나의 중심 기운인 당신은 움직임과 폭넓음을 가져다줄 수 있어요. 탐험하고, 멀어 보이는 생각을 잇고, 상황이 바뀌면 유연하게 맞춰 가는 편이에요."}],"card":"personality"},"WHO_FEEL_癸":{"tags":["dm:癸"],"v":[{"en":"You may pick up on moods before anyone names them.","ko":"누가 말하기 전에 분위기를 먼저 알아채는 편일지도 몰라요."},{"en":"You may need a little time alone after a busy day to feel like yourself again.","ko":"바쁜 하루를 보낸 뒤에는 혼자만의 시간이 조금 있어야 나다운 기분이 돌아올 수 있어요."}],"card":"personality"},"WHO_MEAN_癸":{"tags":["dm:癸"],"v":[{"en":"As Rain, you may carry the rain's instinct for quiet reach: listening closely, imagining freely, and restoring what has gone dry.","ko":"비로서 당신은 비의 조용히 스며드는 감각을 지닌 모습으로 읽어요. 귀 기울여 듣고, 자유롭게 상상하고, 메마른 것을 되살리는 모습이죠."},{"en":"With Rain as your core element, you may bring a quiet reach: listening closely, imagining freely, and helping dry places come back to life.","ko":"비가 나의 중심 기운인 당신은 조용히 스며드는 힘을 가져올 수 있어요. 귀 기울여 듣고, 자유롭게 상상하고, 메마른 곳이 되살아나도록 돕는 모습이죠."}],"card":"personality"},"WHO_TOP_bigyeon":{"tags":["top:bigyeon"],"v":[{"en":"Counting every position in your chart, hidden ones included, the energy that shows up most is standing on your own feet. You may trust what you have tested yourself, and you often work best alongside equals rather than under close direction. Treat this as a tendency, not a rule.","ko":"숨어 있는 자리까지 사주의 모든 자리를 세었을 때 가장 많이 나오는 기운은 내 발로 서는 기운이에요. 직접 확인한 것을 믿는 편이고, 가까이서 지시받기보다 대등한 사람들과 나란히 일할 때 잘하는 경우가 많아요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every position is counted, hidden ones included, self-reliance is the strongest energy in your chart. It points to someone who likes to test things personally and grows best next to equals. Treat this as a tendency, not a rule.","ko":"숨은 자리까지 모두 세면, 사주에서 가장 센 기운은 스스로 서는 힘이에요. 직접 해 보며 확인하고, 대등한 사람 곁에서 가장 잘 자라는 사람의 모습이에요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_geopjae":{"tags":["top:geopjae"],"v":[{"en":"Counting every part of your chart, hidden layers included, the trait that shows up most is competitive drive. Someone doing well near you may wake up your own effort, and you move fastest when there's a clear target to catch. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 부분을 세었을 때 가장 두드러지는 기질은 경쟁심과 승부욕이에요. 가까운 누군가가 잘하면 내 노력에 불이 붙을 수 있고, 따라잡을 목표가 분명할 때 가장 빨리 움직여요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every part is counted, hidden layers included, competitive drive shows up most in your chart. It points to someone who gets sharper when a worthy match is nearby. Treat this as a tendency, not a rule.","ko":"숨은 층까지 모든 부분을 세면 사주에서 경쟁심과 승부욕이 가장 두드러져요. 좋은 맞수가 곁에 있을 때 더 예리해지는 사람이라는 뜻이에요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_siksin":{"tags":["top:siksin"],"v":[{"en":"Counting every spot in your chart, hidden ones included, the energy that shows up most is making and enjoying things. You may do your best work when you like what you're doing, and people relax around how easily you create. Treat this as a tendency, not a rule.","ko":"숨어 있는 자리까지 모두 세었을 때 가장 두드러지는 기운은 만들고 즐기는 기운이에요. 좋아하는 일을 할 때 가장 잘하는 편이고, 편안하게 무언가를 만들어 내는 모습에 사람들이 마음을 놓아요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every spot is counted, hidden ones too, the making-and-enjoying energy leads in your chart. It points to someone who does best when the work is fun and the pace is comfortable. Treat this as a tendency, not a rule.","ko":"숨은 자리까지 모두 세면 사주에서 앞서는 기운은 만들고 즐기는 힘이에요. 하는 일이 재미있고 속도가 편안할 때 가장 잘하는 모습으로 읽어요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_sanggwan":{"tags":["top:sanggwan"],"v":[{"en":"Counting every part of your chart, hidden layers included, the energy that shows up most is sharp, questioning expression. You notice what could be better and you say it, and your ideas may come from questioning the usual way. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 자리를 세었을 때 가장 많이 보이는 기운은 날카롭게 묻고 표현하는 기운이에요. 더 나아질 점이 보이면 말하는 편이고, 아이디어가 늘 하던 방식에 질문을 던지는 데서 나올 수 있어요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every part of your chart is counted, hidden layers included, the energy of sharp, questioning expression shows up most. It points to a quick eye for what could be better and the nerve to say so. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 자리를 세면, 날카롭게 묻고 표현하는 기운이 가장 많이 보여요. 더 나아질 점을 빨리 알아보고, 그것을 말할 배짱이 있는 모습을 가리켜요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_pyeonjae":{"tags":["top:pyeonjae"],"v":[{"en":"Counting every spot in your chart, hidden layers included, the energy that shows up most is seizing opportunity. You may spot openings, handle many things at once, and build through people and movement. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 자리를 세었을 때 가장 많이 나오는 기운은 기회를 잡는 기운이에요. 틈을 잘 발견하고, 여러 일을 한꺼번에 굴리며, 사람과 움직임을 통해 쌓아 갈 수 있어요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every spot is counted, hidden layers included, the energy of seizing opportunity shows up most in your chart. It points to someone who moves fast on an opening and enjoys keeping many things in motion. Treat this as a tendency, not a rule.","ko":"숨은 층까지 모든 자리를 세면, 사주에서 가장 두드러지는 건 기회를 붙잡는 기운이에요. 열린 틈에 빠르게 움직이고 여러 일이 돌아가는 걸 즐기는 사람의 모습이에요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_jeongjae":{"tags":["top:jeongjae"],"v":[{"en":"Counting every spot in your chart, hidden ones included, the energy that shows up most is steady earnings and results. You may like knowing what your effort will bring and building security one reliable step at a time. Treat this as a tendency, not a rule.","ko":"숨은 자리까지 사주의 모든 자리를 세었을 때 가장 두드러지는 기운은 꾸준한 벌이와 결과의 기운이에요. 노력이 무엇으로 돌아올지 아는 것을 좋아하고, 믿을 만한 한 걸음씩 안정을 쌓아 가는 편일 수 있어요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every spot is counted, hidden ones too, the steady-earnings energy leads in your chart. It points to someone who builds security patiently and likes to see effort pay off in clear ways. Treat this as a tendency, not a rule.","ko":"숨은 자리까지 모두 세면 사주에서는 꾸준한 벌이의 기운이 앞서요. 차분히 안정을 쌓고, 노력이 분명한 결과로 돌아오는 것을 좋아하는 사람이라는 뜻이에요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_pyeongwan":{"tags":["top:pyeongwan"],"v":[{"en":"Counting every position in your chart, hidden ones included, the energy that shows up most is rising to a challenge. You often perform well when the stakes are real, and you may take on responsibility before anyone asks. Taking on a lot is a strength, and setting some of it down to rest is allowed too. Treat this as a tendency, not a rule.","ko":"숨어 있는 자리까지 모두 세었을 때 가장 두드러지는 기운은 도전에 맞서는 기운이에요. 진짜 무언가 걸려 있을 때 실력이 잘 나오는 편이고, 누가 부탁하기 전에 책임을 먼저 떠안기도 해요. 많이 짊어지는 것도 강점이고, 그중 일부를 내려놓고 쉬어도 괜찮아요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every position is counted, hidden ones included, rising to a challenge is the strongest energy in your chart. It points to someone who steps up when it counts and may carry more than their share, so setting some of it down is allowed, too. Treat this as a tendency, not a rule.","ko":"숨은 자리까지 모두 세면 사주에서 가장 강한 기운은 도전에 맞서는 힘이에요. 중요한 순간에 나서고 자기 몫보다 더 짊어질 수 있는 모습으로 읽어요. 그러니 그중 일부를 내려놓아도 괜찮아요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_jeonggwan":{"tags":["top:jeonggwan"],"v":[{"en":"Counting every spot in your chart, hidden layers included, the energy that shows up most is responsibility and order. You care about doing things properly, and people tend to trust you with roles that need a steady, honest hand. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 자리를 세었을 때 가장 많이 보이는 기운은 책임과 질서예요. 일을 제대로 하는 것을 중요하게 여기고, 사람들은 흔들림 없고 정직한 손이 필요한 역할을 당신에게 맡기는 편이에요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every spot is counted, hidden layers included, the energy of responsibility and order shows up most in your chart. It points to someone who takes promises seriously and likes to keep things fair. Treat this as a tendency, not a rule.","ko":"숨은 층까지 모든 자리를 세면, 사주에서 책임과 질서의 기운이 가장 많이 보여요. 약속을 진지하게 여기고 일을 공정하게 하고 싶어 하는 사람을 가리켜요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_pyeonin":{"tags":["top:pyeonin"],"v":[{"en":"Counting every part of your chart, hidden layers included, the trait that shows up most is an unusual, independent way of understanding. You learn in your own way, notice patterns others skip, and need time alone to think things through. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 부분을 세었을 때 가장 많이 나오는 특징은 남다르고 독립적으로 이해하는 방식이에요. 나만의 방식으로 배우고, 남들이 지나치는 패턴을 알아채며, 생각을 정리할 혼자만의 시간이 필요해요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every part is counted, hidden layers included, an offbeat, original way of understanding shows up most in your chart. It points to someone who learns in an unusual way and needs quiet time to think things through. Treat this as a tendency, not a rule.","ko":"숨은 층까지 모든 부분을 세면, 사주에서 가장 두드러지는 건 엉뚱하고 독창적으로 이해하는 방식이에요. 남다른 방식으로 배우고, 생각을 정리할 조용한 시간이 필요한 사람의 모습이에요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_jeongin":{"tags":["top:jeongin"],"v":[{"en":"Counting every part of your chart, hidden layers included, the energy that shows up most is learning and receiving care. You grow through study and mentors, and you may give others the same patient support you value. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 부분을 세었을 때 가장 두드러지는 기운은 배움과 보살핌을 받는 기운이에요. 공부와 좋은 스승을 통해 자라고, 내가 소중히 여기는 그 끈기 있는 도움을 남에게도 건넬 수 있어요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every part of your chart is counted, hidden layers included, the energy of learning and receiving care shows up most. It points to someone who grows through study and good teachers, and passes that care on. Treat this as a tendency, not a rule.","ko":"숨은 층까지 사주의 모든 부분을 세면 배우고 보살핌받는 기운이 가장 두드러져요. 공부와 좋은 선생님을 통해 자라고, 그 보살핌을 다시 남에게 이어 주는 사람이라는 뜻이에요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_TOP_even":{"tags":["top:even"],"v":[{"en":"Counting every position in your chart, hidden ones included, no single energy stands out; the ten types are spread out. That can show up as range: you may switch roles with ease. Treat this as a tendency, not a rule.","ko":"숨어 있는 글자까지 모든 자리를 세어 보면 어느 한 기운도 두드러지지 않고 고르게 퍼져 있어요. 폭넓음으로 나타날 수 있어서, 역할을 쉽게 바꿔 가며 해낼 수 있어요. 규칙이라기보다 경향으로 봐 주세요."},{"en":"When every position is counted, hidden ones included, no single energy leads in your chart; all ten types are spread out fairly evenly. That can look like range, so moving between roles may feel natural. Treat this as a tendency, not a rule.","ko":"숨어 있는 글자까지 모든 자리를 세어도 어느 한 기운이 앞서지 않고 열 가지가 고르게 퍼져 있어요. 폭넓음처럼 보일 수 있어서, 역할을 오가는 일이 자연스럽게 느껴질 수 있어요. 규칙이라기보다 경향으로 봐 주세요."}],"card":"personality"},"WHO_MONTH_bigyeop":{"tags":["monthcat:bigyeop"],"v":[{"en":"Your birth-month animal shows how you meet the wider world, and it carries the theme of {monthGod}. Colleagues and acquaintances may see you as independent and self-driven.","ko":"태어난 달의 동물은 넓은 세상을 만나는 모습을 보여 주고, {monthGod}의 주제를 품고 있어요. 동료나 아는 사람들은 당신을 독립적이고 스스로 움직이는 사람으로 볼 수 있어요."},{"en":"The animal of the month you were born shows how the wider world meets you, and it carries the theme of {monthGod}. People around you may notice how self-reliant and steady you are.","ko":"태어난 달의 동물은 세상이 당신을 만나는 모습을 보여 주고, 거기에 {monthGod}이(가) 깃들어 있어요. 주변에서는 당신이 스스로 서는 모습과 꿋꿋함을 눈여겨보기도 해요."},{"en":"Your birth-month animal is the side of you others meet first, and yours carries the theme of {monthGod}. Colleagues may read you as someone who makes up their own mind.","ko":"태어난 달의 동물은 남들이 먼저 만나는 당신의 모습이고, 당신의 것에는 {monthGod}의 주제가 담겨 있어요. 동료들은 당신을 스스로 마음을 정하는 사람으로 읽을 수 있어요."}],"card":"personality"},"WHO_MONTH_siksang":{"tags":["monthcat:siksang"],"v":[{"en":"The animal of your birth month shows how you meet the wider world, and yours carries the theme of {monthGod}. Colleagues and acquaintances may see you as the one with ideas and a way with words.","ko":"태어난 달의 동물은 당신이 넓은 세상을 만나는 모습을 보여 주고, 당신의 경우 {monthGod}(이)라는 주제를 품고 있어요. 동료나 아는 사람들은 당신을 아이디어가 많고 말을 잘 풀어내는 사람으로 볼 수 있어요."},{"en":"The animal of your birth month shapes how the wider world sees you, and it points to {monthGod}. People around you often notice your ideas and how well you put things into words.","ko":"태어난 달의 동물은 세상이 당신을 보는 모습을 빚어요. 당신의 경우 {monthGod}을(를) 가리켜요. 주변 사람들은 당신의 아이디어와 말로 잘 풀어내는 솜씨를 자주 알아봐요."},{"en":"The animal of your birth month is the side of you others meet first, and yours carries the theme of {monthGod}. Colleagues may come to you when something needs a fresh idea or a clear explanation.","ko":"태어난 달의 동물은 남들이 먼저 만나는 당신의 모습이에요. 당신에게는 {monthGod}이(가) 담겨 있어요. 새 아이디어나 또렷한 설명이 필요할 때 동료들이 당신을 찾을 수 있어요."}],"card":"personality"},"WHO_MONTH_jaeseong":{"tags":["monthcat:jaeseong"],"v":[{"en":"Your birth-month animal shows how you meet the wider world, and yours carries a theme of {monthGod}. Colleagues and acquaintances may see you as practical and results-minded.","ko":"태어난 달의 동물은 당신이 바깥 세상을 만나는 모습을 보여 주는데, 당신의 경우 {monthGod}의 주제를 담고 있어요. 동료와 아는 사람들은 당신을 현실적이고 결과를 챙기는 사람으로 볼 수 있어요."},{"en":"The animal of your birth month shows how the wider world meets you, and yours points to {monthGod}. People around you may notice how practical you are about turning plans into results.","ko":"태어난 달의 동물은 세상이 당신을 만나는 모습을 보여 주고, 당신의 동물은 {monthGod}을(를) 가리켜요. 주변에서는 계획을 결과로 바꾸는 당신의 현실감을 눈여겨볼 수 있어요."},{"en":"Your birth-month animal is the side of you that others meet first, and yours leans toward {monthGod}. Colleagues may count on you to keep an eye on what's realistic.","ko":"태어난 달의 동물은 남들이 먼저 만나는 당신의 모습이고, 당신은 {monthGod} 쪽으로 기울어 있어요. 동료들은 무엇이 현실적인지 살펴 주는 사람으로 당신을 믿을 수 있어요."}],"card":"personality"},"WHO_MONTH_gwanseong":{"tags":["monthcat:gwanseong"],"v":[{"en":"The animal of your birth month shows how you meet the wider world, and it's linked with {monthGod}. Colleagues and acquaintances may see you as responsible and dependable.","ko":"태어난 달의 동물은 세상과 만나는 모습을 보여 주는데, {monthGod}와(과) 이어져 있어요. 동료나 아는 사람들은 당신을 책임감 있고 믿음직한 사람으로 볼 수 있어요."},{"en":"Your birth-month animal shows how the wider world meets you, and yours carries a theme of {monthGod}. People around you may notice how much they can rely on you.","ko":"태어난 달의 동물은 세상이 당신을 만나는 모습을 보여 주고, 당신의 동물에는 {monthGod}의 주제가 담겨 있어요. 주변 사람들은 당신에게 얼마나 기댈 수 있는지 알아챌 거예요."},{"en":"Your birth-month animal is the side of you that others meet first, and it points to {monthGod}. Colleagues may see a person who keeps promises and takes roles seriously.","ko":"태어난 달의 동물은 남들이 먼저 만나는 당신의 모습이고, {monthGod}을(를) 가리켜요. 동료들은 약속을 지키고 맡은 역할을 진지하게 대하는 사람으로 볼 수 있어요."}],"card":"personality"},"WHO_MONTH_inseong":{"tags":["monthcat:inseong"],"v":[{"en":"Your birth-month animal shows how you meet the wider world, and it points to {monthGod}. Colleagues and acquaintances may see you as thoughtful and good at explaining things.","ko":"태어난 달의 동물은 넓은 세상을 만나는 모습을 보여 주고, {monthGod}을(를) 가리켜요. 동료나 아는 사람들은 당신을 생각이 깊고 설명을 잘하는 사람으로 볼 수 있어요."},{"en":"The animal of your birth month shows how the wider world meets you, and yours points to {monthGod}. People around you often notice your thoughtfulness and how patiently you explain things.","ko":"태어난 달의 동물은 세상이 당신을 만나는 모습을 보여 주는데, 당신의 것은 {monthGod}을(를) 가리켜요. 주변 사람들은 당신의 사려 깊음과 차근차근 설명하는 모습을 자주 알아봐요."},{"en":"Your birth-month animal is the side of you that others meet first, and yours leans toward {monthGod}. Colleagues may see someone who thinks before speaking and likes to understand why.","ko":"태어난 달의 동물은 남들이 먼저 만나는 당신의 모습이고, 당신의 것은 {monthGod} 쪽으로 기울어 있어요. 동료들은 말하기 전에 생각하고 이유를 알고 싶어 하는 사람으로 볼 수 있어요."}],"card":"personality"},"WHO_ACT_bigyeop":{"tags":["topcat:bigyeop"],"v":[{"en":"This week, invite one person to join something you would normally do alone.","ko":"이번 주, 평소 혼자 하던 일에 한 사람을 초대해 보세요."},{"en":"This week, ask one peer for honest feedback on something you're proud of.","ko":"이번 주, 스스로 자랑스러운 일 하나에 대해 동료에게 솔직한 의견을 물어보세요."},{"en":"This week, share one plan you usually keep to yourself with someone you trust.","ko":"이번 주, 평소 혼자 간직하던 계획 하나를 믿는 사람에게 말해 보세요."}],"card":"personality"},"WHO_ACT_siksang":{"tags":["topcat:siksang"],"v":[{"en":"This week, finish one small thing you started just because you enjoyed it, and show it to someone.","ko":"이번 주, 좋아서 시작한 작은 일 하나를 끝내고 누군가에게 보여 주세요."},{"en":"This week, turn one idea from your notes into something someone else can see or use.","ko":"이번 주, 메모 속 아이디어 하나를 다른 사람이 보거나 쓸 수 있는 형태로 만들어 보세요."},{"en":"This week, spend fifteen minutes making something just for the joy of it, and keep it, share it, or toss it.","ko":"이번 주, 즐거움만을 위해 무언가를 만드는 데 15분을 써 보고, 간직하든 나누든 버리든 해 보세요."}],"card":"personality"},"WHO_ACT_jaeseong":{"tags":["topcat:jaeseong"],"v":[{"en":"This week, pick one result you want by the end of the month and take the first step toward it.","ko":"이번 주, 이달 말까지 얻고 싶은 결과 하나를 골라 첫 단계를 밟아 보세요."},{"en":"This week, pick one opportunity you have been juggling and give it a clear yes or no.","ko":"이번 주, 이리저리 굴리던 기회 하나에 분명하게 예 또는 아니오로 답해 보세요."},{"en":"This week, check one number or deadline you have been avoiding, and write down the next step.","ko":"이번 주, 피해 오던 숫자나 마감 하나를 확인하고 다음 단계를 적어 보세요."}],"card":"personality"},"WHO_ACT_gwanseong":{"tags":["topcat:gwanseong"],"v":[{"en":"This week, drop one duty that isn't really yours, and say so kindly.","ko":"이번 주, 사실 내 몫이 아닌 책임 하나를 부드럽게 말하고 내려놓아 보세요."},{"en":"This week, ask your manager, a teacher, or a mentor what \"done well\" looks like for one task.","ko":"이번 주, 일 하나에 대해 상사나 스승에게 \"잘한 것\"의 기준이 무엇인지 물어보세요."},{"en":"This week, name one standard you hold yourself to, and ask whether it's still serving you.","ko":"이번 주, 스스로에게 들이대는 기준 하나를 말로 적고 아직도 나에게 도움이 되는지 물어보세요."}],"card":"personality"},"WHO_ACT_inseong":{"tags":["topcat:inseong"],"v":[{"en":"This week, take twenty minutes to learn something just because you're curious.","ko":"이번 주, 그냥 궁금해서 배우는 시간을 20분 가져 보세요."},{"en":"This week, teach one thing you know well to someone who asked about it.","ko":"이번 주, 잘 아는 것 하나를 궁금해하던 사람에게 가르쳐 주세요."},{"en":"This week, write down one question you have been carrying, and ask one person how they would think about it.","ko":"이번 주, 품고 있던 질문 하나를 적고, 한 사람에게 어떻게 생각하는지 물어보세요."}],"card":"personality"},"WHO_ACT_even":{"tags":["topcat:even"],"v":[{"en":"This week, notice which role you slipped into most easily, and write it down.","ko":"이번 주, 어떤 역할에 가장 자연스럽게 들어갔는지 적어 보세요."},{"en":"This week, try a role you rarely take: lead if you usually follow, or follow if you usually lead.","ko":"이번 주, 평소 잘 안 맡는 역할을 해 보세요. 늘 따라가던 쪽이면 이끌어 보고, 늘 이끌던 쪽이면 따라가 보세요."},{"en":"This week, ask a friend which of your strengths they notice most, and compare it with your own guess.","ko":"이번 주, 친구에게 내 강점 중 무엇이 가장 눈에 띄는지 묻고 내가 짐작한 것과 견주어 보세요."}],"card":"personality"},"YR_BOUNDARY":{"tags":[],"v":[{"en":"Each traditional year runs from one Start of Spring to the next, around February 4: the Fire Horse year from around February 4, 2026 until around February 4, 2027, and the Fire Sheep year from then until around February 4, 2028.","ko":"전통에서 한 해는 2월 4일 무렵인 입춘부터 다음 입춘까지예요. 불의 말 해는 2026년 2월 4일 무렵부터 2027년 2월 4일 무렵까지, 불의 양 해는 그때부터 2028년 2월 4일 무렵까지예요."}],"card":"this_year"},"YR_FEEL_bigyeop":{"tags":["yrcat:bigyeop"],"v":[{"en":"You may feel a stronger urge in {year} to do things your own way.","ko":"{year}년에는 내 방식대로 하고 싶은 마음이 더 강해질 수 있어요."},{"en":"{year} may bring more people into your orbit who remind you of yourself.","ko":"{year}년에는 나와 닮은 사람들이 주변에 더 많이 들어올 수 있어요."},{"en":"In {year}, you may find yourself craving more independence in how you work and live.","ko":"{year}년에는 일하고 사는 방식에서 더 큰 자율을 바라게 될 수 있어요."}],"card":"this_year"},"YR_FEEL_siksang":{"tags":["yrcat:siksang"],"v":[{"en":"You may catch yourself with more ideas than time in {year}.","ko":"{year}년에는 시간보다 아이디어가 더 많은 자신을 발견할 수 있어요."},{"en":"{year} may feel like a year when you want to say more and make more.","ko":"{year}년은 더 말하고 더 만들고 싶은 해로 느껴질 수 있어요."},{"en":"In {year}, you may feel a strong urge to express yourself and create.","ko":"{year}년에는 표현하고 만들고 싶은 마음이 크게 올라올 수 있어요."}],"card":"this_year"},"YR_FEEL_jaeseong":{"tags":["yrcat:jaeseong"],"v":[{"en":"You may feel more alert to money, deals, and practical chances in {year}.","ko":"{year}년에는 돈, 거래, 현실적인 기회에 더 예민해질 수 있어요."},{"en":"{year} may make you keenly aware of what's working and what's paying off.","ko":"{year}년에는 무엇이 잘 굴러가고 무엇이 결실을 내는지 또렷이 보일 수 있어요."},{"en":"Money, deals, and practical possibilities may catch your attention more in {year}.","ko":"{year}년에는 돈과 거래, 현실적인 가능성이 눈에 더 잘 들어올 수 있어요."}],"card":"this_year"},"YR_FEEL_gwanseong":{"tags":["yrcat:gwanseong"],"v":[{"en":"You may feel more is expected of you in {year}, at work or at home.","ko":"{year}년에는 일터나 집에서 나에게 거는 기대가 커졌다고 느낄 수 있어요."},{"en":"{year} may feel like a year of stepping into a bigger role, ready or not.","ko":"{year}년은 준비가 됐든 안 됐든 더 큰 역할로 들어서는 해로 느껴질 수 있어요."},{"en":"Expectations from work or family could feel heavier in {year}.","ko":"{year}년에는 직장이나 가족이 건네는 기대가 한층 무겁게 느껴질 수 있어요."}],"card":"this_year"},"YR_FEEL_inseong":{"tags":["yrcat:inseong"],"v":[{"en":"You may feel a pull to slow down and learn in {year}.","ko":"{year}년에는 속도를 늦추고 배우고 싶은 마음이 들 수 있어요."},{"en":"{year} may make you want to read, study, or ask someone wiser.","ko":"{year}년에는 읽고, 공부하고, 더 지혜로운 사람에게 묻고 싶어질 수 있어요."}],"card":"this_year"},"YR_TG_bigyeon":{"tags":["yrgod:bigyeon"],"v":[{"en":"In {year}, the year's element, {ys}, meets your core element as {yrGod}: a year that tends to bring people who are like you, such as partners, competitors, and teammates, and asks you to stand on your own terms.","ko":"{year}년에는 그해의 기운 {ys}이(가) 나의 중심 기운과 {yrGod}(으)로 만나요. 동업자, 경쟁자, 팀원처럼 나와 닮은 사람들이 곁에 오기 쉽고, 내 기준으로 서 보라고 하는 해예요."},{"en":"{year} brings {ys} energy, which meets your core element as {yrGod}. It can bring people who resemble you, such as partners, competitors, and teammates, and invites you to stand on your own terms.","ko":"{year}년에는 {ys} 기운이 들어와 나의 중심 기운과 {yrGod}(으)로 만나요. 동업자와 경쟁자, 팀원처럼 당신과 닮은 사람들이 올 수 있고, 내 기준으로 서 보라고 청하는 해예요."},{"en":"The {ys} element of {year} reaches your core element as {yrGod}: a year when people like you, whether partners, competitors, or teammates, may show up and ask you to set your own standards.","ko":"{year}년의 {ys} 기운은 나의 중심 기운에 {yrGod}(으)로 닿아요. 동업자든 경쟁자든 팀원이든 나와 비슷한 사람들이 나타나, 나만의 기준을 세우라고 할 수 있는 해예요."}],"card":"this_year"},"YR_TG_geopjae":{"tags":["yrgod:geopjae"],"v":[{"en":"In {year}, the year's element, {ys}, points you toward {yrGod}: a year of shared stakes, when teamwork and friendly competition both run high and shared work benefits from clear agreements.","ko":"{year}년에는 그해의 기운인 {ys}이(가) 당신을 {yrGod}(으)로 이끌어요. 함께 거는 일이 많은 해라 협력과 선의의 경쟁이 모두 커지고, 함께하는 일은 분명한 약속이 있을 때 편해요."},{"en":"{year} is led by {ys}, and for you that means {yrGod}: a year when collaboration and friendly contests both rise, and written or spoken agreements keep shared efforts smooth.","ko":"{year}년은 {ys}이(가) 이끄는 해이고, 당신에게는 {yrGod}을(를) 뜻해요. 협력과 즐거운 겨루기가 함께 커지는 해라서, 글이나 말로 한 분명한 약속이 함께하는 일을 매끄럽게 해 줘요."},{"en":"{ys}, the element of {year}, points you toward {yrGod}, a sign of shared stakes: you may enjoy both teamwork and a little competition, and clear terms keep group projects comfortable.","ko":"{year}년의 기운 {ys}은(는) 당신을 {yrGod}(으)로 이끌어요. 함께 거는 일이 많다는 표시라, 팀워크와 약간의 경쟁을 모두 즐길 수 있고 분명한 조건이 있으면 모둠 작업이 편해요."}],"card":"this_year"},"YR_TG_siksin":{"tags":["yrgod:siksin"],"v":[{"en":"In {year}, the year's element, {ys}, meets your core element as {yrGod}: a year that favors making things, cooking up ideas, and enjoying the process.","ko":"{year}년의 기운 {ys}은(는) 나의 중심 기운과 {yrGod}(으)로 만나요. 무언가를 만들고, 아이디어를 굴리고, 과정을 즐기기에 좋은 해예요."},{"en":"{year} carries {ys} energy, which reaches your core element as {yrGod}. It's a year that favors creating, brainstorming, and savoring the process.","ko":"{year}년에는 {ys} 기운이 오고, 나의 중심 기운에 {yrGod}(으)로 닿아요. 창작하고, 생각을 모으고, 과정을 음미하기에 좋은 해예요."},{"en":"Your core element meets {year}'s {ys} as {yrGod}, a mix that supports making things, playing with ideas, and enjoying the work itself.","ko":"나의 중심 기운은 {year}년의 {ys}을(를) {yrGod}(으)로 만나요. 무언가를 빚고, 생각을 가지고 놀고, 일 자체를 즐기는 데 힘이 되는 조합이에요."}],"card":"this_year"},"YR_TG_sanggwan":{"tags":["yrgod:sanggwan"],"v":[{"en":"In {year}, the year's element, {ys}, points you toward {yrGod}: a year for speaking up, changing formats, and trying a new way of expressing yourself.","ko":"{year}년에는 그해의 기운 {ys}이(가) 당신을 {yrGod} 쪽으로 이끌어요. 목소리를 내고, 방식을 바꾸고, 새로운 표현을 시도해 보기 좋은 해예요."},{"en":"{ys}, the element of {year}, points you toward {yrGod}: a year for speaking up, switching formats, and experimenting with fresh ways to express yourself.","ko":"{year}년의 기운인 {ys}은(는) 당신을 {yrGod}(으)로 향하게 해요. 목소리를 내고, 형식을 바꾸고, 새로운 표현 방식을 실험해 보라는 신호예요."},{"en":"{year} is led by {ys}, and for you that means {yrGod}: a good time to share your voice, shake up your format, and try expressing yourself differently.","ko":"{year}년은 {ys}이(가) 이끄는데, 당신에게 그것은 {yrGod}을(를) 뜻해요. 목소리를 나누고, 방식에 변화를 주고, 다르게 표현해 보기 좋은 때예요."}],"card":"this_year"},"YR_TG_pyeonjae":{"tags":["yrgod:pyeonjae"],"v":[{"en":"In {year}, the year's element, {ys}, meets your core element as {yrGod}: a year of opportunities, movement, and side paths.","ko":"{year}년에는 그해의 기운 {ys}이(가) 나의 중심 기운과 {yrGod}(으)로 만나요. 기회와 움직임, 곁길이 많은 해예요."},{"en":"{year} brings {ys} energy, which reaches your core element as {yrGod}: a year full of openings, motion, and detours.","ko":"{year}년에는 {ys} 기운이 찾아와 나의 중심 기운에 {yrGod}(으)로 닿아요. 열린 문과 움직임, 돌아가는 길이 가득한 해예요."},{"en":"Your core element meets {ys}, the element of {year}, as {yrGod}, so you may see chances, movement, and a few side roads.","ko":"나의 중심 기운은 {year}년의 기운 {ys}을(를) {yrGod}(으)로 만나요. 그래서 기회와 이동, 몇 갈래의 샛길이 보일 수 있어요."}],"card":"this_year"},"YR_TG_jeongjae":{"tags":["yrgod:jeongjae"],"v":[{"en":"In {year}, the year's element, {ys}, points you toward {yrGod}: a year for steady earning, budgets, and practical results.","ko":"{year}년에는 그해의 기운인 {ys}이(가) 당신을 {yrGod}(으)로 이끌어요. 꾸준한 수입, 예산, 실제 결과에 집중하는 해예요."},{"en":"{year}'s element, {ys}, reaches your core element as {yrGod}: a year for steady income, careful budgets, and results you can see.","ko":"{year}년의 기운 {ys}은(는) 나의 중심 기운에 {yrGod}(으)로 닿아요. 꾸준한 수입과 꼼꼼한 예산, 눈에 보이는 결과를 가리키는 해예요."},{"en":"{year} brings {ys}, which points you toward {yrGod}: a year to focus on steady earning, planning your money, and practical outcomes.","ko":"{year}년에는 {ys}이(가) 찾아와 당신을 {yrGod}(으)로 이끌어요. 꾸준히 벌고, 돈 계획을 세우고, 실속 있는 결과를 챙기는 해예요."}],"card":"this_year"},"YR_TG_pyeongwan":{"tags":["yrgod:pyeongwan"],"v":[{"en":"In {year}, the year's {ys} energy presses on your core element and calls on you to rise to challenges: a year that raises the stakes and asks you to step up.","ko":"{year}년에는 그해의 {ys} 기운이 나의 중심 기운을 누르며 도전에 맞서 보라고 불러요. 판이 커지고 한 걸음 나서기를 바라는 해예요."},{"en":"{year} brings {ys} energy, which presses on your core element and calls on you to rise to challenges: a year when the stakes rise and you're asked to step forward.","ko":"{year}년에는 {ys} 기운이 찾아와 나의 중심 기운을 누르고, 도전에 나서 보라고 해요. 걸린 것이 커지고 앞으로 나서 달라는 요청을 받는 해예요."},{"en":"Your core element meets {ys}, the element of {year}, in a way that points to rising to challenges: it widens your stage and invites you to step up.","ko":"나의 중심 기운은 {year}년의 기운인 {ys}을(를) 도전에 맞서라는 방식으로 만나요. 무대가 넓어지고 한 걸음 더 나서 보라고 부르는 조합이에요."}],"card":"this_year"},"YR_TG_jeonggwan":{"tags":["yrgod:jeonggwan"],"v":[{"en":"In {year}, the year's element, {ys}, meets your core element as {yrGod}: a year of roles, titles, rules, and recognition.","ko":"{year}년에는 그해의 기운 {ys}이(가) 나의 중심 기운과 {yrGod}(으)로 만나요. 역할과 직함, 규칙과 인정이 눈에 띄는 해예요."},{"en":"{year} brings {ys} energy, which reaches your core element as {yrGod}: a year touching on roles, titles, rules, and being recognized.","ko":"{year}년에는 {ys} 기운이 찾아와 나의 중심 기운에 {yrGod}(으)로 닿아요. 역할과 직함, 규칙, 인정받는 일과 이어진 해예요."},{"en":"The year's element, {ys}, points you toward {yrGod} in {year}, pointing to responsibilities, titles, rules, and recognition.","ko":"{year}년에는 그해의 기운 {ys}이(가) 당신을 {yrGod} 쪽으로 이끌어서, 책임과 직함, 규칙, 인정을 가리켜요."}],"card":"this_year"},"YR_TG_pyeonin":{"tags":["yrgod:pyeonin"],"v":[{"en":"In {year}, the year's {ys} energy meets your core element as a pull toward seeing things differently: a year for learning, research, and time to think.","ko":"{year}년에는 그해의 {ys} 기운이 나의 중심 기운을 만나, 세상을 다르게 바라보게 이끌어요. 배움과 연구, 생각할 시간의 해예요."}],"card":"this_year"},"YR_TG_jeongin":{"tags":["yrgod:jeongin"],"v":[{"en":"In {year}, the year's element, {ys}, meets your core element as {yrGod}: a year for study, mentors, paperwork, and being helped.","ko":"{year}년의 기운 {ys}은(는) 나의 중심 기운과 {yrGod}(으)로 만나요. 공부와 스승, 서류, 도움을 받는 일이 많은 해예요."}],"card":"this_year"},"YR_LAND_bigyeop_strong":{"tags":["yrcat:bigyeop","strength:strong"],"v":[{"en":"Because your chart already holds a lot of your own core energy, more of the same can crowd the room, so sharing the load may work better than racing for it.","ko":"사주에 이미 나의 중심 기운이 많아서, 같은 기운이 더해지면 자리가 붐빌 수 있어요. 앞다투기보다 짐을 나눠 드는 편이 더 잘 풀려요."}],"card":"this_year"},"YR_LAND_bigyeop_balanced":{"tags":["yrcat:bigyeop","strength:balanced"],"v":[{"en":"Since your chart sits in a balanced middle range, this extra boost to your core element can feel like a welcome lift in confidence.","ko":"사주가 한쪽으로 치우치지 않은 중간 범위라서, 나의 중심 기운에 더해지는 이 힘이 반가운 자신감으로 느껴질 수 있어요."}],"card":"this_year"},"YR_LAND_bigyeop_weak":{"tags":["yrcat:bigyeop","strength:weak"],"v":[{"en":"Because your chart leans on support, this year's boost of like-minded energy may feel like backup arriving: allies and confidence both.","ko":"사주가 곁의 도움에 기대는 쪽이라, 올해 늘어나는 같은 편 기운은 지원군이 도착한 것처럼 느껴질 수 있어요. 내 편과 자신감이 함께 오죠."}],"card":"this_year"},"YR_LAND_siksang_strong":{"tags":["yrcat:siksang","strength:strong"],"v":[{"en":"For a chart with plenty of energy behind it, expression is a natural outlet, so this year can turn stored energy into visible work.","ko":"뒤에서 받쳐 주는 힘이 넉넉한 사주에게 표현은 자연스러운 배출구라서, 올해는 쌓아 둔 힘을 눈에 보이는 결과로 바꿀 수 있어요."}],"card":"this_year"},"YR_LAND_siksang_balanced":{"tags":["yrcat:siksang","strength:balanced"],"v":[{"en":"With your chart in our middle range, this outward energy can open a creative stretch, as long as you pace it.","ko":"사주가 중간 구간(중화)이라 이 기운은 속도만 조절하면 창작의 시기를 열어 줄 수 있어요."}],"card":"this_year"},"YR_LAND_siksang_weak":{"tags":["yrcat:siksang","strength:weak"],"v":[{"en":"For a chart that leans on support, output can cost energy, so pick one channel for your ideas rather than five.","ko":"신약한 사주는 내보낼 때 힘이 들 수 있어요. 아이디어를 다섯 군데가 아니라 한 군데로 모으세요."},{"en":"With a chart that leans on support, expressing yourself can take effort, so funnel your ideas into one outlet instead of spreading them across many.","ko":"신약한 사주는 자신을 드러내는 데 힘이 들 수 있어요. 아이디어를 여러 곳에 흩지 말고 한 통로로 모아 보세요."}],"card":"this_year"},"YR_LAND_jaeseong_strong":{"tags":["yrcat:jaeseong","strength:strong"],"v":[{"en":"A chart with a strong core element tends to handle wealth-focused years well, so this can be a good year to build or grow something concrete.","ko":"나의 중심 기운이 강한 사주는 재물에 초점이 맞춰진 해를 잘 감당하는 편이라, 구체적인 무언가를 세우거나 키우기 좋은 해가 될 수 있어요."}],"card":"this_year"},"YR_LAND_jaeseong_balanced":{"tags":["yrcat:jaeseong","strength:balanced"],"v":[{"en":"With your chart in our middle range, this is a workable year for practical goals, taken one at a time.","ko":"사주가 중간 구간(중화)이라 현실적인 목표를 하나씩 이뤄 가기 무난한 해예요."}],"card":"this_year"},"YR_LAND_jaeseong_weak":{"tags":["yrcat:jaeseong","strength:weak"],"v":[{"en":"For a chart that leans on support, many opportunities at once can stretch you thin, so choose the ones you can actually carry.","ko":"신약한 사주는 기회가 한꺼번에 몰리면 힘이 흩어질 수 있어요. 실제로 감당할 수 있는 것만 고르세요."},{"en":"When your chart relies on support, a flood of chances can scatter your energy, so say yes only to those you can truly handle.","ko":"신약한 사주는 기회가 쏟아지면 기운이 흩어질 수 있어요. 정말 감당할 수 있는 것에만 응하세요."}],"card":"this_year"},"YR_LAND_gwanseong_strong":{"tags":["yrcat:gwanseong","strength:strong"],"v":[{"en":"A chart with plenty of its own strength can welcome a bit of structure, and this year's demands can give your energy a clear shape.","ko":"자기 힘이 넉넉한 사주는 적당한 틀을 반기는 편이라, 올해 주어지는 요구가 내 힘에 분명한 모양을 잡아 줄 수 있어요."}],"card":"this_year"},"YR_LAND_gwanseong_balanced":{"tags":["yrcat:gwanseong","strength:balanced"],"v":[{"en":"With your chart in our middle range, this year's structure can feel like a fair test rather than a weight.","ko":"사주가 중간 구간(중화)이라 올해의 틀은 무거운 짐보다 공정한 시험처럼 느껴질 수 있어요."}],"card":"this_year"},"YR_LAND_gwanseong_weak":{"tags":["yrcat:gwanseong","strength:weak"],"v":[{"en":"For a chart that leans on support, extra demands are best met with clear limits and help you ask for early.","ko":"신약한 사주는 늘어난 요구를 분명한 선과 일찍 청하는 도움으로 맞이하는 게 좋아요."}],"card":"this_year"},"YR_LAND_inseong_strong":{"tags":["yrcat:inseong","strength:strong"],"v":[{"en":"Your chart already runs strong, so extra support is best turned into learning you then share, rather than more comfort.","ko":"사주가 이미 힘이 센 편이라, 더해지는 도움은 편안함을 늘리기보다 배워서 나누는 쪽으로 쓰는 게 좋아요."}],"card":"this_year"},"YR_LAND_inseong_balanced":{"tags":["yrcat:inseong","strength:balanced"],"v":[{"en":"With your chart in our middle range, this is a good year to add a skill or a qualification.","ko":"사주가 중간 구간(중화)이라 기술이나 자격 하나를 더하기 좋은 해예요."}],"card":"this_year"},"YR_LAND_inseong_weak":{"tags":["yrcat:inseong","strength:weak"],"v":[{"en":"For a chart that leans on support, this is the kind of year that refills the well, so accept the help that comes.","ko":"신약한 사주에게는 우물을 다시 채우는 해예요. 들어오는 도움을 받아들이세요."}],"card":"this_year"},"YR_HAP_year":{"tags":["yrrel:hap:year"],"v":[{"en":"The year's animal, {yb}, pairs up with your birth-year animal, {nb}, so family roots and your wider community may draw closer or feel more cooperative.","ko":"올해의 동물 {yb}이(가) 태어난 해의 동물 {nb}와(과) 짝을 이뤄요. 집안의 뿌리와 넓은 인간관계가 가까워지거나 서로 더 잘 협력할 수 있어요."}],"card":"this_year"},"YR_CHUNG_year":{"tags":["yrrel:chung:year"],"v":[{"en":"The year's animal, {yb}, clashes with your birth-year animal, {nb}, so you may see movement around family roots and your wider community: a change that asks for flexibility more than worry.","ko":"올해의 동물 {yb}이(가) 태어난 해의 동물 {nb}와(과) 부딪쳐요. 집안의 뿌리와 넓은 인간관계 쪽에 움직임이 생길 수 있어요. 걱정보다 유연함이 필요한 변화예요."}],"card":"this_year"},"YR_HAP_month":{"tags":["yrrel:hap:month"],"v":[{"en":"The year's animal, {yb}, pairs up with your birth-month animal, {nb}, so work, colleagues, and daily routine may draw closer or feel more cooperative.","ko":"올해의 동물 {yb}이(가) 태어난 달의 동물 {nb}와(과) 짝을 이뤄요. 그래서 일과 동료, 일상의 흐름이 더 가까워지거나 서로 잘 맞을 수 있어요."}],"card":"this_year"},"YR_CHUNG_month":{"tags":["yrrel:chung:month"],"v":[{"en":"The year's animal, {yb}, clashes with your birth-month animal, {nb}, so you may see movement around work, colleagues, and daily routine: a change that asks for flexibility more than worry.","ko":"올해의 동물 {yb}이(가) 태어난 달의 동물 {nb}와(과) 부딪쳐요. 일과 동료, 일상의 흐름 쪽에 움직임이 생길 수 있어요. 걱정보다 유연함이 필요한 변화예요."}],"card":"this_year"},"YR_HAP_day":{"tags":["yrrel:hap:day"],"v":[{"en":"The year's animal, {yb}, pairs up with the animal of the day you were born, {nb}, so close partnership and home life may draw closer or feel more cooperative.","ko":"올해의 동물 {yb}이(가) 태어난 날의 동물 {nb}와(과) 짝을 이뤄요. 가까운 동반자 관계와 집안 생활이 더 가까워지거나 서로 더 잘 맞춰 갈 수 있어요."}],"card":"this_year"},"YR_CHUNG_day":{"tags":["yrrel:chung:day"],"v":[{"en":"The year's animal, {yb}, clashes with the animal of the day you were born, {nb}, so you may see movement around close partnership and home life: a change that asks for flexibility more than worry.","ko":"올해의 동물 {yb}이(가) 태어난 날의 동물 {nb}와(과) 부딪쳐요. 가까운 동반자 관계와 집안 생활 쪽에 움직임이 생길 수 있어요. 걱정보다 유연함이 필요한 변화예요."}],"card":"this_year"},"YR_HAP_hour":{"tags":["pillar:hour","yrrel:hap:hour"],"v":[{"en":"The year's animal, {yb}, pairs up with your birth-hour animal, {nb}, so long-term plans and personal projects may draw closer or feel more cooperative.","ko":"올해의 동물 {yb}이(가) 태어난 시각의 동물 {nb}와(과) 짝을 이뤄요. 그래서 먼 계획과 개인적인 일이 더 가까워지거나 서로 잘 맞을 수 있어요."}],"card":"this_year"},"YR_CHUNG_hour":{"tags":["pillar:hour","yrrel:chung:hour"],"v":[{"en":"The year's animal, {yb}, clashes with your birth-hour animal, {nb}, so you may see movement around long-term plans and personal projects: a change that asks for flexibility more than worry.","ko":"올해의 동물 {yb}이(가) 태어난 시각의 동물 {nb}와(과) 부딪쳐요. 먼 계획과 개인적인 일 쪽에 움직임이 생길 수 있어요. 걱정보다 유연함이 필요한 변화예요."}],"card":"this_year"},"YR_SAMHAP":{"tags":["yrrel:samhap"],"v":[{"en":"The year's animal also completes a traditional trio of animals with your chart ({trio}), gathering {samEl}, so things that seemed separate may start working together.","ko":"올해의 동물은 당신 사주와 함께 전통적인 세 동물 무리({trio})를 완성해 {samEl}을(를) 모아요. 따로 놀던 일들이 함께 굴러가기 시작할 수 있어요."}],"card":"this_year"},"YR_STEMHAP":{"tags":["yrrel:stemhap"],"v":[{"en":"The year's element, {ys}, also pairs up with your core element, so an offer, attraction, or partnership may feel unusually magnetic this year.","ko":"올해의 기운 {ys}은(는) 나의 중심 기운과도 짝을 이뤄요. 그래서 올해는 제안이나 끌림, 협력 관계가 유난히 강하게 당겨질 수 있어요."}],"card":"this_year"},"YR_REL_NONE":{"tags":["yrrel:none"],"v":[{"en":"{year}'s element and animal don't link, clash, or rub against your birth chart in any of the ways we check, so this year is read from its element and its place in the traditional growth cycle alone.","ko":"{year}년의 기운과 동물은 우리가 살피는 방식 중 어느 것으로도 당신의 사주와 이어지거나, 부딪치거나, 스치지 않아요. 그래서 이 해는 그해의 기운과 전통적인 성장 흐름 속 자리만으로 읽어요."}],"card":"this_year"},"YR_FILL":{"tags":["yrfill"],"v":[{"en":"The year brings {fillEl}, the element that shows up less in your chart, so {year} can feel like something missing is being refilled.","ko":"올해는 사주에 적게 나온 기운인 {fillEl}을(를) 가져와요. 그래서 {year}년은 모자랐던 무언가가 다시 채워지는 느낌이 들 수 있어요."},{"en":"{fillEl} is an element your chart doesn't hold much of, and this year brings it in, so {year} may feel like a missing piece slotting into place.","ko":"사주에 적었던 기운인 {fillEl}이(가) 올해 들어와요. 그래서 {year}년은 빠져 있던 조각이 맞춰지는 느낌일 수 있어요."},{"en":"This year delivers {fillEl}, an element your chart has less of, which can make {year} feel like a gap is finally being filled.","ko":"올해는 사주에 모자랐던 {fillEl} 기운을 데려와요. {year}년은 비어 있던 자리가 드디어 채워지는 듯한 해일 수 있어요."},{"en":"In {year}, the element {fillEl}, which is light in your chart, arrives to top things up, and you may notice a sense of completeness.","ko":"{year}년에는 사주에서 옅었던 {fillEl} 기운이 들어와 부족함을 보태 줘요. 한결 온전해지는 느낌이 들 수 있어요."}],"card":"this_year"},"YR_MORE":{"tags":["yrmore"],"v":[{"en":"Your chart already holds plenty of {moreEl}, and {year} adds more, so that year may feel intense at times; build in some cool-down time.","ko":"사주에 이미 {moreEl}이(가) 넉넉한데 {year}년에 더 들어와요. 가끔 벅차게 느껴질 수 있으니 식히는 시간을 미리 넣어 두세요."},{"en":"{year} brings still more {moreEl} to a chart that's already rich in it, so the year can feel intense now and then; plan some time to cool down.","ko":"{year}년에는 이미 {moreEl}이(가) 풍부한 사주에 {moreEl}이(가) 더 들어와요. 이따금 벅차게 느껴질 수 있으니 식힐 시간을 계획해 두세요."},{"en":"With plenty of {moreEl} in your chart already, the extra that arrives in {year} may feel like a lot at times, so schedule moments to unwind.","ko":"사주에 {moreEl}이(가) 이미 많은데 {year}년에 더 보태지니, 때로는 버겁게 느껴질 수 있어요. 긴장을 풀 순간을 일정에 넣어 두세요."},{"en":"Your chart is already generous with {moreEl}, and {year} adds to it; there may be days that feel overwhelming, so keep some downtime on the calendar.","ko":"당신의 사주는 {moreEl}이(가) 넉넉한 편인데 {year}년에 더 늘어나요. 벅찬 날도 있을 수 있으니 달력에 쉬는 시간을 남겨 두세요."},{"en":"Because {moreEl} is already abundant in your chart, {year} piling on more can feel heavy sometimes. Set aside a little time to cool off.","ko":"사주에 {moreEl}이(가) 이미 풍성해서 {year}년에 더 쌓이면 가끔 무겁게 느껴질 수 있어요. 열을 식힐 짧은 시간을 따로 떼어 두세요."},{"en":"Add the {moreEl} that {year} brings to the {moreEl} you already have, and the year may feel full to the brim; give yourself small breaks to settle.","ko":"{year}년이 가져오는 {moreEl}에 원래 있던 {moreEl}까지 더하면 한 해가 꽉 찬 느낌일 수 있어요. 마음이 가라앉도록 작은 쉼을 주세요."}],"card":"this_year"},"YR_STAGE_rising":{"tags":["yrstage:rising"],"v":[{"en":"Measured against your core element, the year's animal sits in an outward, rising phase of the traditional life-cycle reading, a sign of visibility and momentum.","ko":"나의 중심 기운에 비춰 보면, 올해의 동물은 전통의 생애 흐름 읽기에서 밖으로 드러나며 오르는 단계에 있어요. 눈에 띄고 탄력이 붙는 흐름이에요."}],"card":"this_year"},"YR_STAGE_forming":{"tags":["yrstage:forming"],"v":[{"en":"Measured against your core element, the year's animal sits in a forming phase of the traditional life-cycle reading: new things take shape but need patience before they show.","ko":"나의 중심 기운을 기준으로 보면, 올해의 동물은 전통적인 삶의 주기 풀이에서 새로 모양을 갖춰 가는 구간에 있어요. 새것이 자리를 잡지만 드러나기까지는 기다림이 필요해요."}],"card":"this_year"},"YR_STAGE_settling":{"tags":["yrstage:settling"],"v":[{"en":"Measured against your core element, the year's animal sits in a settling phase of the traditional life-cycle reading, more about ripening and review than launching.","ko":"나의 중심 기운을 기준으로 보면, 올해의 동물은 전통적인 삶의 순환 풀이에서 차분히 자리 잡는 구간에 있어요. 새로 시작하기보다 무르익히고 돌아보는 흐름이에요."}],"card":"this_year"},"YR_DY":{"tags":["dy:single"],"v":[{"en":"This year sits inside your {dyGz} decade (about age {dyA1} to {dyA2}), which leans toward {dyCat}, so {year}'s theme plays out against that backdrop.","ko":"올해는 {dyGz} 대운(대략 {dyA1}~{dyA2}세) 안에 있고, 이 대운은 {dyCat} 쪽으로 기울어 있어요. {year}년의 흐름은 그 바탕 위에서 펼쳐져요."}],"card":"this_year"},"YR_DY_PRE":{"tags":["dy:single"],"v":[{"en":"You haven't started your first 10-year cycle yet, so your birth month, {mp}, sets the backdrop for {year}.","ko":"아직 첫 10년 구간이 시작되기 전이라, {year}년의 바탕은 태어난 달 {mp}이(가) 잡아 줘요."}],"card":"this_year"},"YR_ACT_bigyeop_hap":{"tags":["yrcat:bigyeop","yrstate:hap"],"v":[{"en":"Pick one ally this year and plan something together, with a shared date on the calendar.","ko":"올해 함께할 사람 한 명을 정해 날짜까지 달력에 적고 무언가를 같이 계획해 보세요."},{"en":"Invite one friend or colleague to a shared goal this year, and put the first meeting on the calendar.","ko":"올해 친구나 동료 한 명에게 함께할 목표를 제안하고, 첫 모임 날짜를 달력에 적으세요."},{"en":"Find a study buddy or workout partner for this year and agree on a weekly time.","ko":"올해 함께 공부하거나 운동할 짝을 찾아 매주 만날 시간을 정해 보세요."}],"card":"this_year"},"YR_ACT_bigyeop_chung":{"tags":["yrcat:bigyeop","yrstate:chung"],"v":[{"en":"When a change comes this year, talk it through with one person you trust before deciding alone.","ko":"올해 변화가 오면 혼자 결정하기 전에 믿는 사람 한 명과 먼저 이야기해 보세요."},{"en":"If a change arrives this year, give yourself three nights before answering and jot down how you feel each morning.","ko":"올해 변화가 찾아오면 대답하기 전에 사흘 밤을 두고, 매일 아침 기분을 짧게 적어 보세요."},{"en":"When something shifts this year, ask someone who knows you well what they'd notice that you might miss.","ko":"올해 무언가 달라지면 당신을 잘 아는 사람에게, 내가 놓칠 수 있는 점이 무엇인지 물어보세요."}],"card":"this_year"},"YR_ACT_bigyeop_none":{"tags":["yrcat:bigyeop","yrstate:none"],"v":[{"en":"Choose one personal goal for the year and tell one friend, so someone is cheering you on.","ko":"올해의 개인 목표 하나를 정해 친구 한 명에게 말해 두세요. 응원해 줄 사람이 생겨요."}],"card":"this_year"},"YR_ACT_siksang_hap":{"tags":["yrcat:siksang","yrstate:hap"],"v":[{"en":"Say yes to one collaboration that lets you create, and set a finish date.","ko":"무언가를 만들 수 있는 협업 하나에 응하고, 끝낼 날짜를 정해 두세요."},{"en":"Pick one creative project you can share with someone else this year, and put a first draft on the calendar.","ko":"올해 누군가와 함께 나눌 수 있는 창작 프로젝트 하나를 골라 첫 초안 날짜를 달력에 적어 두세요."},{"en":"Show an unfinished idea to one trusted person this year and ask what they'd add.","ko":"올해 아직 덜 된 아이디어 하나를 믿는 사람에게 보여 주고 무엇을 더하고 싶은지 물어보세요."}],"card":"this_year"},"YR_ACT_siksang_chung":{"tags":["yrcat:siksang","yrstate:chung"],"v":[{"en":"Keep one notes page for ideas this year, and act on one per season rather than all at once.","ko":"올해 아이디어 노트 한 장을 두고, 한꺼번에가 아니라 계절마다 하나씩 실행해 보세요."},{"en":"This year, pick your single best idea each month and take one small step on it, such as a sketch or a draft.","ko":"올해는 매달 가장 마음에 드는 아이디어 하나를 골라 스케치나 초안 같은 작은 첫걸음을 떼 보세요."},{"en":"Set aside an hour a week this year to make something, and let the rest of the ideas wait on a list.","ko":"올해는 일주일에 한 시간을 따로 떼어 무언가를 만들고, 나머지 아이디어는 목록에 적어 기다리게 두세요."}],"card":"this_year"},"YR_ACT_siksang_none":{"tags":["yrcat:siksang","yrstate:none"],"v":[{"en":"Make one small thing each month this year, such as a recipe, a post, or a sketch, and keep them in one folder.","ko":"올해 매달 작은 것 하나씩 만들어 보세요. 요리법, 글, 스케치 같은 것들을 한 폴더에 모아 두세요."}],"card":"this_year"},"YR_ACT_jaeseong_hap":{"tags":["yrcat:jaeseong","yrstate:hap"],"v":[{"en":"Before agreeing to a joint plan this year, agree out loud on who does what.","ko":"올해 함께하는 계획에 동의하기 전에, 누가 무엇을 할지 소리 내어 정해 두세요."},{"en":"Write down each person's role and share before you sign on to any group plan this year.","ko":"올해 여럿이 하는 계획에 합류하기 전에, 사람마다 맡을 역할과 몫을 글로 적어 두세요."},{"en":"If someone invites you into a shared venture this year, ask for the split of work and money in plain words first.","ko":"올해 누군가 함께하는 일에 초대하면, 일과 돈을 어떻게 나눌지 쉬운 말로 먼저 물어보세요."}],"card":"this_year"},"YR_ACT_jaeseong_chung":{"tags":["yrcat:jaeseong","yrstate:chung"],"v":[{"en":"Keep one free afternoon each month this year, so changes in routine have room to land.","ko":"올해 매달 비어 있는 오후 하나를 남겨 두세요. 일상에 변화가 와도 자리를 잡을 여유가 생겨요."},{"en":"Before making any big money move this year, wait one night and write down your reasons.","ko":"올해 큰 돈 문제를 정하기 전에는 하룻밤 기다리고 이유를 적어 보세요."},{"en":"Each month, review your regular expenses and choose one to adjust, so changes feel planned rather than sudden.","ko":"매달 고정 지출을 훑어보고 하나를 골라 조정해 보세요. 변화가 갑작스럽지 않고 계획된 것처럼 느껴져요."}],"card":"this_year"},"YR_ACT_jaeseong_none":{"tags":["yrcat:jaeseong","yrstate:none"],"v":[{"en":"Pick one practical habit for the year, such as a fifteen-minute weekly planning slot, and keep it for three months.","ko":"올해 실용적인 습관 하나를 정하세요. 매주 15분 계획 시간 같은 것을 세 달만 지켜 보세요."}],"card":"this_year"},"YR_ACT_gwanseong_hap":{"tags":["yrcat:gwanseong","yrstate:hap"],"v":[{"en":"If a role or title is offered this year, ask for one clear thing that would help you succeed in it.","ko":"올해 역할이나 직함 제안이 오면, 잘해 내는 데 필요한 것 한 가지를 분명히 요청해 보세요."},{"en":"When a new role or title comes your way this year, write down what you'd want to learn in the first month and share it with whoever offers it.","ko":"올해 새 역할이나 직함이 오면, 첫 한 달 동안 배우고 싶은 것을 적어서 제안한 사람과 나눠 보세요."},{"en":"If you're offered a title this year, take a day to think, then ask what success would look like in the first three months.","ko":"올해 직함을 제안받으면 하루 동안 생각해 보고, 처음 석 달 동안 어떤 모습이 성공인지 물어보세요."}],"card":"this_year"},"YR_ACT_gwanseong_chung":{"tags":["yrcat:gwanseong","yrstate:chung"],"v":[{"en":"When plans shift this year, list what you must do versus what others expect, and drop one extra.","ko":"올해 계획이 흔들리면 꼭 해야 할 일과 남이 기대하는 일을 나눠 적고, 덤 하나는 내려놓으세요."},{"en":"When plans wobble this year, check your calendar and cancel or postpone one commitment you can do without.","ko":"올해 계획이 흔들리면 달력을 보고, 없어도 되는 약속 하나를 취소하거나 미뤄 보세요."},{"en":"If things get shaky this year, write down the single most important task for each day and start there.","ko":"올해 상황이 불안하면 하루마다 가장 중요한 일 한 가지를 적고, 거기서부터 시작해 보세요."}],"card":"this_year"},"YR_ACT_gwanseong_none":{"tags":["yrcat:gwanseong","yrstate:none"],"v":[{"en":"Choose one commitment this year to do especially well, and let one smaller one go.","ko":"올해 특히 잘 해내고 싶은 약속 하나를 고르고, 작은 약속 하나는 놓아주세요."}],"card":"this_year"},"YR_ACT_inseong_hap":{"tags":["yrcat:inseong","yrstate:hap"],"v":[{"en":"Find a teacher, course, or mentor this year and book the first session.","ko":"올해 선생님이나 강좌, 멘토를 찾아 첫 시간을 예약해 보세요."},{"en":"Pick one subject you've wanted to study and sign up for a class before the month ends.","ko":"배우고 싶었던 주제 하나를 골라 이번 달이 가기 전에 수업을 신청하세요."},{"en":"Ask someone you respect for thirty minutes of advice and put it on the calendar.","ko":"존경하는 사람에게 30분만 조언을 청하고, 그 시간을 달력에 넣어 두세요."}],"card":"this_year"},"YR_ACT_inseong_chung":{"tags":["yrcat:inseong","yrstate:chung"],"v":[{"en":"When things move quickly this year, protect one quiet hour each week for reading or reflection.","ko":"올해 일이 빠르게 돌아갈수록 매주 읽거나 돌아보는 조용한 한 시간을 지켜 주세요."},{"en":"When the pace picks up this year, set aside one evening a week to read, journal, or simply think.","ko":"올해 속도가 빨라지면 매주 하루 저녁은 책을 읽거나 일기를 쓰거나 가만히 생각하는 시간으로 남겨 두세요."},{"en":"Whenever things feel rushed this year, step away for a short walk without your phone.","ko":"올해 마음이 바쁘게 느껴질 때마다 휴대폰 없이 잠깐 걸으러 나가 보세요."}],"card":"this_year"},"YR_ACT_inseong_none":{"tags":["yrcat:inseong","yrstate:none"],"v":[{"en":"Pick one subject to study this year and give it fifteen minutes a week.","ko":"올해 공부할 주제 하나를 정해 매주 15분씩 들여 보세요."}],"card":"this_year"},"YR_SHIFT":{"tags":[],"v":[{"en":"From 2026 to 2027, the focus moves from {cat1} to {cat2}.","ko":"2026년에서 2027년으로 넘어가며 초점이 {cat1}에서 {cat2}(으)로 옮겨 가요."}],"card":"this_year"},"YR_SHIFT_SAME":{"tags":[],"v":[{"en":"2026 and 2027 share a theme, {cat1}, so what you start in 2026 can keep building in 2027.","ko":"2026년과 2027년은 {cat1}(이)라는 같은 주제를 나눠 가져요. 2026년에 시작한 일을 2027년에 계속 쌓아 갈 수 있어요."},{"en":"Both 2026 and 2027 carry the theme of {cat1}, which means a project you begin in 2026 may keep growing into 2027.","ko":"2026년과 2027년 모두 {cat1}(이)라는 주제를 품고 있어요. 2026년에 시작한 일이 2027년까지 이어져 자라날 수 있어요."},{"en":"the theme of {cat1} is the thread running through 2026 and 2027, so there's room to build on this year's efforts next year.","ko":"{cat1}(이)라는 주제가 2026년과 2027년을 잇는 실이에요. 올해 들인 노력 위에 내년에도 쌓아 갈 여지가 있어요."},{"en":"Think of 2026 and 2027 as two chapters on {cat1}: what you plant in the first can be tended in the second.","ko":"2026년과 2027년을 {cat1}에 관한 두 장으로 생각해 보세요. 첫 장에 심은 것을 둘째 장에서 가꿀 수 있어요."},{"en":"Because the theme of {cat1} stays in focus across 2026 and 2027, you don't have to finish everything this year.","ko":"{cat1}(이)라는 주제가 2026년과 2027년 내내 중심에 있어서, 올해 안에 모든 걸 끝내지 않아도 괜찮아요."},{"en":"With {cat1} setting the tone for two years in a row, what you begin in 2026 may carry real momentum into 2027.","ko":"{cat1}이(가) 2년 연달아 분위기를 정해서, 2026년에 시작한 일이 2027년으로 힘을 이어 갈 수 있어요."},{"en":"Your next two years, 2026 and 2027, lean on the same theme: {cat1}. Early steps now may pay off later.","ko":"2026년과 2027년, 앞으로 두 해는 {cat1}(이)라는 같은 주제에 기대어 있어요. 지금 내딛는 첫걸음이 나중에 빛을 볼 수 있어요."},{"en":"There's no hard reset between 2026 and 2027, since the theme of {cat1} appears in both, so you can pick up next year where you leave off.","ko":"{cat1}(이)라는 주제가 2026년과 2027년 둘 다에 나와서 확 끊기는 느낌이 적어요. 내년에는 올해 멈춘 자리에서 다시 이어 가면 돼요."},{"en":"Two years, one theme: {cat1} show up in 2026 and again in 2027, which can reward steady effort.","ko":"두 해, 하나의 주제예요. {cat1}이(가) 2026년에 나오고 2027년에 또 나와서, 꾸준한 노력이 보답받을 수 있어요."},{"en":"Since 2026 and 2027 both center on {cat1}, a slow start this year doesn't have to be a problem; there's another year to build.","ko":"2026년과 2027년 둘 다 {cat1}이(가) 중심이라서, 올해 느리게 시작해도 괜찮아요. 쌓아 갈 한 해가 더 있어요."},{"en":"Look at 2026 and 2027 together: the theme of {cat1} stays in the picture, so this year's lessons may be useful again next year.","ko":"2026년과 2027년을 함께 보세요. {cat1}(이)라는 주제가 계속 그림 안에 있어서, 올해 배운 것이 내년에도 쓸모 있을 수 있어요."},{"en":"The shared theme of {cat1} links 2026 to 2027, so you may find that a habit started now keeps paying off.","ko":"{cat1}(이)라는 공통 주제가 2026년과 2027년을 이어 줘서, 지금 시작한 습관이 계속 도움이 될 수 있어요."}],"card":"this_year"},"DY_INTRO":{"tags":["dy:single"],"v":[{"en":"Your 10-year luck cycles begin {startTxt} and move {dirWord} through the traditional sequence of sixty element-and-animal pairs, starting from {mp}, the pair for your birth month.","ko":"10년마다 바뀌는 당신의 운의 흐름은 {startTxt} 시작해, 태어난 달의 짝인 {mp}에서부터 기운과 동물을 짝지은 예순 개의 전통 순서를 따라 {dirWordKo}해요."}],"card":"luck"},"DY_INTRO_BOTH":{"tags":["dy:both"],"v":[{"en":"Because you chose \"Not sure,\" we show both directions. Forward cycles begin {startFTxt} and backward cycles {startBTxt}; the traditional method picks one based on whether you are male or female.","ko":"\"잘 모르겠음\"을 고르셔서 두 방향을 모두 보여 드려요. 앞으로 흐르는 10년 흐름은 {startFTxt}, 거꾸로 흐르는 10년 흐름은 {startBTxt} 시작해요. 전통 방식은 남자인지 여자인지에 따라 둘 중 하나를 골라요."},{"en":"You chose \"Not sure\", so both directions are shown. Forward cycles begin {startFTxt}, and backward cycles begin {startBTxt}; the traditional method chooses between them by whether you are male or female.","ko":"\"잘 모르겠음\"을 고르셔서 두 방향을 모두 보여 드려요. 순행은 {startFTxt}, 역행은 {startBTxt} 시작해요. 전통 방식은 남자/여자 구분(전통 용어: 건조·곤조)으로 둘 중 어느 쪽인지 정해요."},{"en":"The traditional method needs to know whether you are male or female before it can set the direction of your 10-year cycles. Since you chose \"Not sure\", we show both: forward cycles begin {startFTxt}, backward cycles {startBTxt}.","ko":"전통 방식은 남자/여자 구분(전통 용어: 건조·곤조)을 알아야 10년 대운의 방향을 정할 수 있어요. \"잘 모르겠음\"을 고르셨으니 둘 다 보여 드려요. 순행은 {startFTxt}, 역행은 {startBTxt} 시작해요."},{"en":"Since the direction is still open, here are both versions of your cycles: forward cycles begin {startFTxt}, and backward cycles begin {startBTxt}. Each follows its own path from there.","ko":"방향이 아직 정해지지 않아 두 가지 흐름을 모두 보여 드려요. 순행 대운은 {startFTxt}, 역행 대운은 {startBTxt} 시작하고, 그 뒤로는 각자 자기 길을 따라가요."},{"en":"We show two versions of your 10-year cycles because the direction is unsettled. In one, cycles begin {startFTxt}; in the other, {startBTxt}.","ko":"방향이 정해지지 않아 10년 대운을 두 가지로 보여 드려요. 한쪽은 {startFTxt}, 다른 쪽은 {startBTxt} 시작해요."}],"card":"luck"},"DY_NOW":{"tags":["dy:single"],"v":[{"en":"You're now {age}, in your {nowGz} cycle (age {nowA1} to {nowA2}), about {inYears} years in.","ko":"지금 당신은 {age}세로 {nowGz} 대운({nowA1}~{nowA2}세)에 들어선 지 약 {inYears}년째예요."}],"card":"luck"},"DY_NOW_PRE":{"tags":["dy:single"],"v":[{"en":"You're now {age}, and your first ten-year cycle starts at {start}; until then, your birth month, {mp}, sets the tone.","ko":"지금 당신은 {age}세이고, 첫 10년 흐름은 {start}세에 시작해요. 그때까지는 태어난 달 {mp}이(가) 흐름의 분위기를 잡아 줘요."}],"card":"luck"},"DY_FEEL_bigyeop":{"tags":["dycat:bigyeop"],"v":[{"en":"Lately you may feel more determined to decide things for yourself.","ko":"요즘은 스스로 결정하고 싶은 마음이 더 단단해졌을 수 있어요."},{"en":"Right now you may feel a stronger pull to stand on your own and decide things by your own measure.","ko":"요즘은 스스로 서고 내 기준으로 정하고 싶은 마음이 더 강해졌을 수 있어요."},{"en":"You may notice that you care more about doing things your own way these days.","ko":"요즘은 내 방식대로 하는 일이 더 중요하게 느껴질 수 있어요."}],"card":"luck"},"DY_FEEL_siksang":{"tags":["dycat:siksang"],"v":[{"en":"Lately you may feel you have more to say, make, or show.","ko":"요즘은 말하고, 만들고, 보여 줄 것이 더 많아졌다고 느낄 수 있어요."},{"en":"Right now you may feel more eager to put ideas out into the world, even before they are perfect.","ko":"요즘은 아이디어가 완벽하지 않아도 세상에 내놓고 싶은 마음이 더 커졌을 수 있어요."},{"en":"You may notice more creative energy than usual, and a wish to be heard.","ko":"요즘은 평소보다 창의적인 기운이 늘고, 내 이야기를 들려주고 싶은 마음이 들 수 있어요."}],"card":"luck"},"DY_FEEL_jaeseong":{"tags":["dycat:jaeseong"],"v":[{"en":"Lately you may notice practical goals and money taking more of your attention.","ko":"요즘은 현실적인 목표와 돈 문제가 관심을 더 많이 차지할 수 있어요."},{"en":"Right now you may find yourself weighing what things cost and what they return more than before.","ko":"요즘은 무엇이 얼마나 들고 얼마나 돌아오는지를 예전보다 더 따져 보게 될 수 있어요."},{"en":"You may notice a stronger wish for results you can actually see and count.","ko":"요즘은 눈으로 보고 셀 수 있는 결과를 바라는 마음이 더 커질 수 있어요."}],"card":"luck"},"DY_FEEL_gwanseong":{"tags":["dycat:gwanseong"],"v":[{"en":"Lately you may feel the weight, and the pride, of more responsibility.","ko":"요즘은 늘어난 책임의 무게와 그만큼의 자부심을 함께 느낄 수 있어요."},{"en":"Right now you may feel expectations, from others or from yourself, pressing a bit harder than before.","ko":"요즘은 남이나 나 자신에게서 오는 기대가 예전보다 조금 더 무겁게 느껴질 수 있어요."},{"en":"You may notice a stronger wish to do things properly and be seen as dependable.","ko":"요즘은 제대로 해내고 믿음직하게 보이고 싶은 마음이 더 강해질 수 있어요."}],"card":"luck"},"DY_FEEL_inseong":{"tags":["dycat:inseong"],"v":[{"en":"Lately you may feel drawn to learning, reflection, or finding a mentor.","ko":"요즘은 배우고, 돌아보고, 스승을 찾고 싶은 마음이 들 수 있어요."},{"en":"Right now you may feel the urge to slow down, read, and understand things more deeply.","ko":"요즘은 속도를 늦추고 읽고 더 깊이 이해하고 싶은 마음이 들 수 있어요."},{"en":"You may notice that quiet time and good advice feel more valuable than they used to.","ko":"요즘은 조용한 시간과 좋은 조언이 예전보다 더 값지게 느껴질 수 있어요."}],"card":"luck"},"DY_MEAN_bigyeop":{"tags":["dycat:bigyeop"],"v":[{"en":"This decade's element, {nowGan}, brings out {nowGod} in you, so the next ten years lean toward {nowCat}. Decades like this can build independence and bring friends and equals into your story.","ko":"이번 10년의 기운 {nowGan}은(는) 당신 안의 {nowGod}을(를) 끌어내서, 앞으로 10년은 {nowCatKo} 쪽으로 기울어요. 이런 10년은 독립심을 키우고 친구와 대등한 동료들을 이야기 속으로 불러들일 수 있어요."},{"en":"In this 10-year stretch, {nowGan} points you toward {nowGod}, tilting the decade toward {nowCat}. Times like this can ask you to trust your own judgment and find companions who respect it.","ko":"이 10년 동안 {nowGan}은(는) 당신을 {nowGod} 쪽으로 이끌어, 이 시기를 {nowCatKo} 쪽으로 기울게 해요. 이런 때에는 내 판단을 믿고, 그것을 존중해 주는 동료를 찾게 되기도 해요."}],"card":"luck"},"DY_MEAN_siksang":{"tags":["dycat:siksang"],"v":[{"en":"This decade of your life brings {nowGan} energy, which shows up for you as {nowGod}, so these ten years lean toward {nowCat}. Decades like this can favor creative work, teaching, and self-expression.","ko":"지금 인생의 10년 구간에는 {nowGan} 기운이 들어와 당신에게 {nowGod}(으)로 나타나요. 그래서 이 10년은 {nowCatKo} 쪽으로 기울어요. 이런 10년은 창작과 가르침, 자기표현에 힘을 실어 줄 수 있어요."},{"en":"The element of your current ten-year stretch is {nowGan}, and in your chart it works as {nowGod}, so this decade leans toward {nowCat}. Times like this can reward making, sharing, and trying things in public.","ko":"지금 10년 구간의 기운인 {nowGan}은(는) 당신의 사주에서 {nowGod}(으)로 작용해요. 그래서 이 시기는 {nowCatKo} 쪽으로 기울어요. 이런 때는 만들고 나누고 사람들 앞에서 시도해 볼 때 보답이 있을 수 있어요."}],"card":"luck"},"DY_MEAN_jaeseong":{"tags":["dycat:jaeseong"],"v":[{"en":"The element leading your current ten-year cycle is {nowGan}, which shows up for you as {nowGod}, so this decade leans toward {nowCat}. Decades like this often center on building wealth and managing real-world results.","ko":"{nowGan}이(가) 지금의 10년 흐름을 이끌고, 당신에게는 {nowGod}(으)로 나타나서 이 10년은 {nowCatKo} 쪽으로 기울어요. 이런 10년은 재산을 쌓고 현실의 결과를 다루는 일이 중심이 되는 경우가 많아요."},{"en":"Your current ten-year cycle is led by {nowGan}, and for you that means {nowGod}, tilting this decade toward {nowCat}. Stretches like this can put practical results, planning, and resources in the foreground.","ko":"지금의 10년 흐름은 {nowGan}이(가) 이끌고, 당신에게는 {nowGod}을(를) 뜻해서 이 10년을 {nowCatKo} 쪽으로 기울게 해요. 이런 시기에는 실제 결과와 계획, 가진 자원이 앞에 나올 수 있어요."}],"card":"luck"},"DY_MEAN_gwanseong":{"tags":["dycat:gwanseong"],"v":[{"en":"Your current ten-year cycle carries {nowGan}, which carries the theme of {nowGod} for you, so this decade leans toward {nowCat}. Decades like this can bring roles, rules, and recognition, along with their demands.","ko":"지금의 10년 흐름에는 {nowGan}이(가) 담겨 있고, 이것이 당신에게 {nowGod}을(를) 가져와서 이 10년은 {nowCatKo} 쪽으로 기울어요. 이런 10년은 역할과 규칙, 인정을 가져오고, 그에 따른 요구도 함께 올 수 있어요."},{"en":"The {nowGan} energy of your current ten-year cycle stands for {nowGod} in your chart, tilting this decade toward {nowCat}. Stretches like this can come with new titles, standards, and the chance to be trusted with more.","ko":"지금 10년 흐름의 {nowGan} 기운은 당신의 사주에서 {nowGod}을(를) 뜻해서, 이 10년을 {nowCatKo} 쪽으로 기울게 해요. 이런 시기에는 새 직함과 기준, 더 많은 것을 믿고 맡겨 받을 기회가 함께 올 수 있어요."}],"card":"luck"},"DY_MEAN_inseong":{"tags":["dycat:inseong"],"v":[{"en":"This decade's element, {nowGan}, points you toward {nowGod}, so these ten years lean toward {nowCat}. Traditionally, decades like this can favor study, qualifications, and help from mentors.","ko":"이번 10년의 기운 {nowGan}은(는) 당신을 {nowGod} 쪽으로 이끌어서, 이 10년은 {nowCatKo} 쪽으로 기울어요. 전통적으로 이런 10년은 공부와 자격, 이끌어 주는 어른의 도움에 힘을 실어 줄 수 있어요."},{"en":"Your current decade is marked by {nowGan}, which shows up for you as {nowGod} and tilts these years toward {nowCat}. Stretches like this can favor deepening skills, earning credentials, and learning from people with more experience.","ko":"지금의 10년은 {nowGan}이(가) 이끄는데, 당신에게는 {nowGod}(으)로 나타나 이 시기를 {nowCatKo} 쪽으로 기울게 해요. 이런 때는 실력을 깊게 하고 자격을 쌓고 경험 많은 사람에게 배우는 일에 유리할 수 있어요."}],"card":"luck"},"DY_STAGE_rising":{"tags":["dystage:rising"],"v":[{"en":"Its animal, {nowZhi}, sits in {nowStage} for your core element in the traditional life-cycle reading, so this decade's work may be visible.","ko":"이 시기의 동물 {nowZhi}은(는) 전통적인 생애 흐름으로 보면 나의 중심 기운에게 {nowStageKo}에 놓여 있어요. 그래서 이 10년에 하는 일은 겉으로 잘 드러날 수 있어요."},{"en":"Its animal, {nowZhi}, sits in {nowStage} for your core element, so what you do in this decade may be noticed by others.","ko":"이 시기의 동물 {nowZhi}은(는) 나의 중심 기운 기준으로 {nowStageKo}에 자리해요. 그래서 이 10년 동안 하는 일이 남들 눈에 띌 수 있어요."}],"card":"luck"},"DY_STAGE_forming":{"tags":["dystage:forming"],"v":[{"en":"Its animal, {nowZhi}, sits in {nowStage} for your core element in the traditional life-cycle reading, so much of this decade's growth happens below the surface first.","ko":"이 10년의 동물 {nowZhi}은(는) 전통의 생애 흐름 읽기에서 나의 중심 기운을 {nowStageKo}에 두어서, 이 시기의 성장은 먼저 물밑에서 이뤄지는 경우가 많아요."},{"en":"Its animal, {nowZhi}, sits in {nowStage} for your core element, so this decade may feel like quiet preparation before results show.","ko":"이 10년의 동물 {nowZhi}에서 나의 중심 기운은 {nowStageKo}에 있어서, 이 시기는 결과가 드러나기 전의 조용한 준비처럼 느껴질 수 있어요."}],"card":"luck"},"DY_STAGE_settling":{"tags":["dystage:settling"],"v":[{"en":"Its animal, {nowZhi}, sits in {nowStage} for your core element in the traditional life-cycle reading, so this decade rewards depth, review, and finishing well.","ko":"그 시기의 동물 {nowZhi}은(는) 전통적인 삶의 주기 풀이에서 나의 중심 기운을 기준으로 {nowStageKo}에 놓여 있어요. 그래서 이 10년은 깊이와 돌아보기, 잘 마무리하기에 보답해요."},{"en":"Its animal, {nowZhi}, sits in {nowStage} for your core element, so this decade suits tidying up, passing things on, and finishing what matters.","ko":"그 시기의 동물 {nowZhi}은(는) 나의 중심 기운을 기준으로 {nowStageKo}에 있어서, 이 10년은 정리하고, 물려주고, 중요한 일을 끝맺기에 어울려요."}],"card":"luck"},"DY_BEST":{"tags":["decade:best"],"v":[{"en":"Most active decade (our score): {bestList}. This cycle brings more of the elements that balance your chart, so effort may meet less friction.","ko":"힘이 가장 큰 10년(자체 채점): {bestList}. 이 대운은 사주의 균형을 잡아 주는 기운을 더 많이 가져와서, 노력이 덜 부딪히며 나아가는 편이에요."},{"en":"Most active decade (our score): {bestList}. This cycle brings more of the energy that evens out your chart, so effort may meet less friction.","ko":"힘이 가장 큰 10년(자체 채점): {bestList}. 이 대운은 사주를 고르게 해 주는 기운을 더 가져와서, 노력이 덜 막히는 편이에요."}],"card":"luck"},"DY_GROW":{"tags":["decade:grow"],"v":[{"en":"Growing decade (our score): {growList}. It's a good stretch for growing new skills, the kind you keep using for years afterward.","ko":"성장하는 10년(자체 채점): {growList}. 새로운 기술을 키우기 좋은 시기이고, 그렇게 기른 힘은 이후 오래 쓰여요."},{"en":"Growing decade (our score): {growList}. A good stretch to build skills and habits that keep paying off for years.","ko":"성장하는 10년(자체 채점): {growList}. 오래 쓸 기술과 습관을 쌓기 좋은 시기예요."}],"card":"luck"},"DY_POS_inbest":{"tags":["decade:best","pos:inbest"],"v":[{"en":"You're inside your most active decade by our score, and it may be a good time to start the things you've been setting aside.","ko":"지금이 우리 채점으로 힘이 가장 큰 10년이에요. 미뤄 두던 일을 시작하기 좋은 때일 수 있어요."},{"en":"You're standing in your most active decade by our score, so plans you have been holding back may find less friction now.","ko":"지금 우리 채점으로 힘이 가장 큰 10년 안에 서 있어요. 미뤄 둔 계획이 지금은 덜 부딪힐 수 있어요."},{"en":"This is your most active decade by our score, and it may be a natural time to move one long-delayed plan from \"someday\" to a date on the calendar.","ko":"지금은 우리 채점으로 힘이 가장 큰 10년이에요. 오래 미룬 계획 하나를 \"언젠가\"에서 달력 위의 날짜로 옮기기 좋은 때일 수 있어요."},{"en":"By our score you're in your most active decade, so it may be a fair time to pick one plan you have postponed and give it a first date.","ko":"우리 채점으로 지금은 힘이 가장 큰 10년이에요. 미뤄 둔 계획 하나를 골라 첫 날짜를 잡아 보기에 알맞은 때일 수 있어요."},{"en":"Your current decade is the most active one on our scoring, and that may make this a good stretch to try something you have only talked about.","ko":"지금 10년은 우리 채점에서 힘이 가장 큰 시기예요. 말로만 해 오던 일을 해 보기 좋은 시기일 수 있어요."}],"card":"luck"},"DY_POS_ingrow":{"tags":["decade:grow","pos:ingrow"],"v":[{"en":"You're inside your growing decade, a good stretch for growing new skills that pay off in the next cycle.","ko":"지금은 성장하는 10년 안에 있어요. 다음 대운에서 쓰일 새로운 기술을 키우기 좋은 시기예요."},{"en":"You're inside a growing decade, which may reward patient practice; what you build now can pay off in later cycles.","ko":"지금은 성장하는 10년 안에 있어요. 차분한 연습이 보답받기 쉬운 시기라, 지금 쌓는 것이 이후 대운에서 열매가 될 수 있어요."},{"en":"This decade is marked as a growing one, a good season for learning by doing and for laying groundwork that stays useful.","ko":"이 10년은 성장하는 10년으로 표시돼요. 해 보면서 배우고, 오래 쓸 기반을 놓기 좋은 때예요."},{"en":"You're in a decade marked as growing, a good time to practice slowly and let skills settle in before the next cycle arrives.","ko":"지금은 성장하는 시기로 표시된 10년 안에 있어요. 천천히 연습하며 다음 대운이 오기 전에 실력이 자리 잡게 하기 좋은 때예요."},{"en":"This is a growing decade by our score, so gentle, regular practice now can become a strength in the cycles that follow.","ko":"우리 채점으로 성장하는 10년이에요. 지금 차분히 꾸준히 연습해 두면 이어지는 대운에서 힘이 될 수 있어요."}],"card":"luck"},"DY_POS_ahead":{"tags":["decade:best","pos:ahead"],"v":[{"en":"Your next most active decade begins at about age {nextBest}, so the groundwork you lay now has somewhere to go.","ko":"다음으로 힘이 큰 10년은 대략 {nextBest}세에 시작해요. 지금 다지는 기반이 쓰일 곳이 있어요."},{"en":"A stretch that scores especially high on our measure starts around age {nextBest}, so the steady work you do now is preparation for it.","ko":"우리 기준으로 점수가 특히 높은 구간이 대략 {nextBest}세부터 시작돼요. 지금 하는 꾸준한 일이 그 준비가 돼요."},{"en":"Your next most active decade starts near age {nextBest}; until then, small steady steps are a fine way to get ready.","ko":"다음으로 힘이 큰 10년은 {nextBest}세 무렵 시작돼요. 그때까지는 작고 꾸준한 걸음이 좋은 준비예요."}],"card":"luck"},"DY_POS_past":{"tags":["decade:best","pos:past"],"v":[{"en":"Your most active decade came earlier, at ages {bestList}; what you built then is still a resource you can draw on.","ko":"힘이 가장 컸던 10년은 {bestList}로 이미 지나왔어요. 그때 쌓은 것은 지금도 꺼내 쓸 수 있는 자산이에요."},{"en":"Your most active decade ran at ages {bestList}. That stretch is behind you, and what you learned in it's still yours to use.","ko":"힘이 가장 컸던 10년은 {bestList}였어요. 이미 지나온 시기지만, 그때 배운 것은 지금도 쓸 수 있어요."},{"en":"The decade that scored highest on our measure was ages {bestList}; you can still borrow its lessons whenever things feel uncertain.","ko":"우리 기준으로 점수가 가장 높았던 10년은 {bestList}였어요. 마음이 흔들릴 때 그 시기의 배움을 다시 꺼내 쓸 수 있어요."}],"card":"luck"},"DY_ACT_bigyeop":{"tags":["dycat:bigyeop"],"v":[{"en":"Name one decision for this decade that you want to own fully, and start on it this month.","ko":"이번 대운 동안 온전히 내 것으로 삼고 싶은 결정 하나를 정하고, 이번 달에 시작해 보세요."},{"en":"Find one peer who is working toward something similar and agree to check in monthly.","ko":"비슷한 목표를 향해 가는 동료 한 명을 찾아 매달 서로 소식을 나누기로 약속해 보세요."},{"en":"Write down one thing you want to do independently this decade, and choose its first small step.","ko":"이번 대운에 혼자 힘으로 해 보고 싶은 일 하나를 적고, 그 첫 작은 걸음을 정해 보세요."}],"card":"luck"},"DY_ACT_siksang":{"tags":["dycat:siksang"],"v":[{"en":"Set up a simple way to share your work regularly, such as a folder, a page, or a monthly show-and-tell.","ko":"내 작업을 꾸준히 나눌 간단한 방법을 만들어 보세요. 폴더, 페이지, 월 1회 발표 같은 것이요."},{"en":"Choose one skill you could teach, and offer a short session to one person.","ko":"가르칠 수 있는 기술 하나를 골라 한 사람에게 짧은 시간 가르쳐 주세요."},{"en":"Pick one thing you made this year and show it to someone whose opinion you trust.","ko":"올해 만든 것 하나를 골라, 의견을 믿을 수 있는 사람에게 보여 주세요."},{"en":"Pick one idea you keep returning to and give it thirty minutes this week.","ko":"자꾸 떠오르는 아이디어 하나를 골라 이번 주에 30분을 줘 보세요."}],"card":"luck"},"DY_ACT_jaeseong":{"tags":["dycat:jaeseong"],"v":[{"en":"Start a one-page plan of what you want to build by the end of this cycle.","ko":"이번 대운이 끝날 때까지 쌓고 싶은 것을 한 장짜리 계획으로 써 보세요."},{"en":"Review where your time turns into results, and move one hour a week toward the best of it.","ko":"내 시간이 어디서 결과로 바뀌는지 살펴보고, 매주 한 시간을 가장 좋은 쪽으로 옮겨 보세요."},{"en":"Pick one practical goal for this decade and tell one person who will ask you about it.","ko":"이번 대운의 현실적인 목표 하나를 정해, 그 일을 물어봐 줄 사람 한 명에게 말해 두세요."},{"en":"Write down your three biggest recurring expenses or time costs, and decide which one deserves a second look.","ko":"반복해서 드는 큰 지출이나 시간 비용 세 가지를 적고, 다시 살펴볼 만한 하나를 골라 보세요."}],"card":"luck"},"DY_ACT_gwanseong":{"tags":["dycat:gwanseong"],"v":[{"en":"List your current roles and mark the one you'd most like to grow into.","ko":"지금 맡은 역할을 적고, 가장 키워 가고 싶은 하나에 표시해 보세요."},{"en":"Ask someone you respect how they handled the responsibilities you now carry.","ko":"존경하는 사람에게 지금 내가 지고 있는 책임을 그들은 어떻게 감당했는지 물어보세요."},{"en":"Choose one responsibility you would like to hand on within this decade, and start teaching it.","ko":"이번 대운 안에 넘겨주고 싶은 책임 하나를 골라, 가르치기 시작해 보세요."},{"en":"Choose one commitment you carry and decide whether to deepen it, share it, or finish it.","ko":"지고 있는 약속 하나를 골라, 더 깊이 할지 나눌지 마무리할지 정해 보세요."}],"card":"luck"},"DY_ACT_inseong":{"tags":["dycat:inseong"],"v":[{"en":"Choose one long course of learning that fits this decade, and take the first step.","ko":"이번 대운에 맞는 긴 배움 하나를 골라 첫걸음을 떼어 보세요."},{"en":"Keep a short learning journal, one line a day, for the next month.","ko":"다음 한 달 동안 하루 한 줄짜리 배움 일지를 써 보세요."},{"en":"Ask someone further along your path which book or course helped them most, and start it.","ko":"나보다 앞서 같은 길을 간 사람에게 가장 도움이 된 책이나 강좌를 물어보고 시작해 보세요."},{"en":"Set aside one fixed hour each week for learning something just for yourself.","ko":"매주 정해진 한 시간을 나만을 위한 배움에 따로 떼어 두세요."}],"card":"luck"},"DY_ACT_pre":{"tags":["dy:single"],"v":[{"en":"Before your first cycle, the most useful step is simple: notice what you enjoy practicing without being asked, and make room for it.","ko":"첫 대운 전에는 간단한 한 걸음이 가장 좋아요. 시키지 않아도 즐겨 연습하는 것을 알아차리고, 그 일에 자리를 내어 주세요."}],"card":"luck"},"DY_ACT_both":{"tags":["dy:both"],"v":[{"en":"Read both timelines and notice which one's rhythm matches what you have actually lived; that may be the more useful one to plan with.","ko":"두 흐름표를 읽어 보고, 어느 쪽 리듬이 실제로 살아온 모습과 맞는지 살펴보세요. 그쪽이 계획 세우기에 더 쓸모 있을 수도 있어요."},{"en":"Look at both timelines side by side and mark the decade where your real life changed most; see which direction lines up with it.","ko":"두 흐름표를 나란히 놓고, 실제로 삶이 가장 크게 바뀐 10년에 표시해 본 뒤 어느 방향과 맞는지 살펴보세요."},{"en":"Pick one past turning point and check which timeline places it near a cycle change; keep that one in mind as you plan.","ko":"지나온 전환점 하나를 골라 어느 흐름표에서 대운이 바뀌는 때와 가까운지 확인하고, 계획을 세울 때 그쪽을 참고해 보세요."},{"en":"Mark on both timelines the decade that feels closest to your real story, and ask a trusted person whether it rings true for them too.","ko":"두 흐름표에서 내 실제 이야기와 가장 가까운 10년에 표시해 보고, 믿는 사람에게도 맞게 느껴지는지 물어보세요."},{"en":"Write one sentence about each timeline's current decade, then notice which sentence sounds more like you.","ko":"각 흐름표의 지금 10년을 한 문장씩 적어 보고, 어느 쪽이 더 나 같은지 살펴보세요."},{"en":"Keep both timelines for now, and note which past decade matches each one; it doesn't need to be settled today.","ko":"지금은 두 흐름표를 모두 두고, 지나온 10년이 각각과 어떻게 맞는지 적어 보세요. 오늘 정하지 않아도 괜찮아요."}],"card":"luck"},"DY_FEEL_both":{"tags":["dy:both"],"v":[{"en":"You may feel that your life has had clear chapters, even if you couldn't say exactly when each one began.","ko":"각 시기가 정확히 언제 시작됐는지는 몰라도, 삶에 뚜렷한 장(章)들이 있었다고 느낄 수 있어요."},{"en":"Your life may have had clear chapters that you could name afterward, even if the exact start of each is blurry.","ko":"각 장이 정확히 언제 시작됐는지는 흐릿해도, 지나고 나서 이름을 붙일 수 있는 뚜렷한 시기가 있었다고 느낄 수 있어요."},{"en":"You may sense that your life moved in distinct stretches, even if you couldn't say which year each one began.","ko":"몇 년도에 시작했는지는 말하기 어려워도, 삶이 뚜렷한 구간들로 움직여 왔다고 느낄 수 있어요."},{"en":"You may feel that some years closed one chapter and opened another, even if you couldn't date them exactly.","ko":"정확히 언제인지는 몰라도, 어떤 해에 한 장이 닫히고 다른 장이 열렸다고 느낀 적이 있을 수 있어요."},{"en":"Looking back, you may see clear turns in your life, even when you're unsure which year each one began.","ko":"돌아보면 각각이 몇 년도에 시작됐는지는 확실하지 않아도 삶에 뚜렷한 굽이가 있었다고 느낄 수 있어요."},{"en":"You may sense that your life has come in phases, each with its own mood, even if the dates blur.","ko":"날짜는 흐릿해도 삶이 저마다 다른 분위기의 시기들로 이어져 왔다고 느낄 수 있어요."}],"card":"luck"},"ST_FEEL_early_smooth":{"tags":["stage:early","fit:early:smooth"],"v":[{"en":"In your early years, doors may open fairly readily, even when it doesn't feel that way at the time.","ko":"어린 시절과 젊은 시절에는 그때는 몰라도 문이 비교적 잘 열릴 수 있어요."},{"en":"Looking back, your early years may have offered more open doors than you realized at the time.","ko":"돌아보면 어린 시절과 젊은 시절에는 그때 알아차린 것보다 열린 문이 더 많았을 수 있어요."},{"en":"Early on, things may have fallen into place more gently than it felt in the moment.","ko":"초반에는 그때 느낀 것보다 일이 더 부드럽게 풀렸을 수 있어요."},{"en":"Your early years may hold more open doors than they seem to at first.","ko":"초반에는 겉으로 보이는 것보다 열려 있는 문이 더 많을 수 있어요."},{"en":"Early on, things may be easier than they feel in the moment.","ko":"초반에는 그 순간 느끼는 것보다 일이 더 수월할 수 있어요."}],"card":"early"},"ST_FEEL_early_stretch":{"tags":["stage:early","fit:early:stretch"],"v":[{"en":"Your early years may bring responsibility or hard effort, and that can build skills sooner.","ko":"젊은 시절에 책임이나 힘든 노력이 찾아올 수 있고, 그만큼 실력이 더 일찍 쌓이기도 해요."},{"en":"Responsibility or hard effort may arrive early in life, and that can grow your skills sooner.","ko":"젊은 시절에 책임이나 애써야 할 일이 일찍 올 수 있고, 덕분에 실력이 더 빨리 자랄 수 있어요."},{"en":"You may be asked to step up while you're still young, and that early effort can turn into real skill.","ko":"아직 젊을 때 앞장서야 하는 일이 생길 수 있고, 그 노력이 진짜 실력으로 이어질 수 있어요."},{"en":"Early on, life may hand you duties or challenges, which can build your abilities ahead of schedule.","ko":"초반에 맡을 일이나 도전이 찾아올 수 있고, 그것이 능력을 예정보다 빨리 키워 줄 수 있어요."},{"en":"Your younger years could include early responsibility, and the effort you put in may pay off as skill.","ko":"젊은 시절에 일찍 책임을 맡게 될 수 있고, 쏟은 노력이 실력으로 돌아올 수 있어요."}],"card":"early"},"ST_FEEL_early_mixed":{"tags":["stage:early","fit:early:mixed"],"v":[{"en":"Your early years may hold a mix of easy stretches and stretches for growing new skills.","ko":"젊은 시절에는 수월한 때와 새로운 기술을 키우는 때가 섞여 있을 수 있어요."},{"en":"Your early years can include both smooth stretches and times for building new skills.","ko":"젊은 시절에는 순탄한 구간과 새 기술을 쌓는 구간이 함께 들어 있을 수 있어요."},{"en":"Youth looks mixed in your chart, with some easy seasons and some that ask you to learn.","ko":"사주에서 젊은 시절은 여러 빛깔이에요. 편안한 계절도 있고 배우기를 청하는 계절도 있어요."},{"en":"Some of your early years may flow easily, while others are better for growing new abilities.","ko":"초년의 어떤 때는 수월하게 흐르고, 어떤 때는 새로운 능력을 키우기에 더 좋을 수 있어요."},{"en":"In your early years, easy periods and skill-building periods may take turns.","ko":"초년에는 수월한 때와 실력을 쌓는 때가 번갈아 찾아올 수 있어요."},{"en":"Your younger days may blend gentle patches with chances to build new skills.","ko":"젊은 날에는 편안한 시기와 새 기술을 쌓을 기회가 어우러져 있을 수 있어요."}],"card":"early"},"ST_FEEL_middle_smooth":{"tags":["stage:middle","fit:middle:smooth"],"v":[{"en":"Your middle years look like a stretch where effort and results line up more readily.","ko":"중년은 노력과 결과가 비교적 잘 맞물리는 시기로 보여요."},{"en":"The middle years may feel like a time when your work and its rewards fit together without much friction.","ko":"중년은 일과 그 보람이 큰 마찰 없이 맞아떨어지는 시기처럼 느껴질 수 있어요."},{"en":"You may find your middle years flowing, with effort paying off at a pace that makes sense.","ko":"중년이 순하게 흘러가고, 노력이 납득할 만한 속도로 열매를 맺는다고 느낄 수 있어요."},{"en":"Midlife looks like a chapter where doing the work and seeing the results go hand in hand.","ko":"중년은 일을 해내는 것과 결과를 보는 것이 나란히 가는 장으로 보여요."}],"card":"middle"},"ST_FEEL_middle_stretch":{"tags":["stage:middle","fit:middle:stretch"],"v":[{"en":"Your middle years look like a time of steady building, the kind of effort that lasts.","ko":"중년은 꾸준히 쌓아 가는 시기로 보여요. 오래 남는 종류의 노력이죠."},{"en":"The middle years may be about laying one brick at a time, building something that stays.","ko":"중년은 벽돌을 한 장씩 쌓듯, 오래 남을 무언가를 지어 가는 시기일 수 있어요."},{"en":"You may find midlife is a season of patient construction, with work that holds up over time.","ko":"중년은 인내심 있게 지어 올리는 계절이고, 시간이 지나도 버티는 일을 하게 될 수 있어요."}],"card":"middle"},"ST_FEEL_middle_mixed":{"tags":["stage:middle","fit:middle:mixed"],"v":[{"en":"Your middle years look varied: some decades carry you, and others are good stretches for growing new skills.","ko":"중년은 다채로워 보여요. 어떤 10년은 당신을 실어 나르고, 어떤 10년은 새로운 기술을 키우기 좋은 시기예요."},{"en":"The middle years can feel like a patchwork: certain decades carry you along, while others invite you to build new skills.","ko":"중년은 조각보처럼 느껴질 수 있어요. 어떤 10년은 당신을 앞으로 밀어 주고, 어떤 10년은 새 기술을 쌓아 보라고 권해요."},{"en":"Your middle years seem to have two moods, some decades with a tailwind and some better suited to learning new things.","ko":"중년에는 두 가지 분위기가 있는 것 같아요. 순풍이 부는 10년도 있고, 새로운 것을 배우기에 더 어울리는 10년도 있어요."},{"en":"Midlife can bring variety; a few decades may move you forward easily, and others are good times to grow new abilities.","ko":"중년에는 여러 변화가 찾아올 수 있어요. 수월하게 나아가는 10년도 있고, 새로운 능력을 키우기 좋은 10년도 있어요."},{"en":"Midlife looks mixed in your chart, with supportive decades alongside ones that are good for practicing new skills.","ko":"사주에서 중년은 여러 빛깔이에요. 힘이 되어 주는 10년과 새 기술을 연습하기 좋은 10년이 나란히 있어요."},{"en":"Some decades in your middle years may lift you up, and others make room for learning something new.","ko":"중년의 어떤 10년은 당신을 끌어올려 줄 수 있고, 어떤 10년은 새로운 것을 배울 여유를 내어 줘요."},{"en":"There's a mix in your middle years: easy-flowing decades sit beside decades well suited to building skills.","ko":"중년에는 여러 모습이 섞여 있어요. 술술 풀리는 10년 옆에 실력을 쌓기에 잘 맞는 10년이 놓여 있어요."}],"card":"middle"},"ST_FEEL_later_smooth":{"tags":["stage:later","fit:later:smooth"],"v":[{"en":"Your later years may settle into a steadier rhythm.","ko":"말년에는 한결 차분한 리듬으로 자리 잡을 수 있어요."},{"en":"Later life may be a season when things settle into an easy, comfortable pace.","ko":"말년은 일상이 편안하고 여유로운 속도로 자리 잡는 계절이 될 수 있어요."},{"en":"In your later years, daily life can find a calm and comfortable rhythm.","ko":"말년에는 하루하루가 차분하고 편안한 리듬을 찾을 수 있어요."},{"en":"The later chapters of your life may ease into a steady, comfortable flow.","ko":"인생의 뒷장은 안정되고 편안한 흐름으로 천천히 풀려 갈 수 있어요."}],"card":"later"},"ST_FEEL_later_stretch":{"tags":["stage:later","fit:later:stretch"],"v":[{"en":"Your later years may have room for plenty of activity, with new interests at your own pace.","ko":"말년에는 활발하게 움직일 자리가 넉넉할 수 있어요. 새로운 관심사도 내 속도대로 펼쳐 보세요."},{"en":"You may find your later years lively rather than quiet, with space to explore new interests at your pace.","ko":"말년이 고요하기보다 생기 있게 느껴질 수 있고, 내 걸음에 맞춰 새로운 관심사를 찾아볼 여유도 있어요."},{"en":"Later life may be busy in a good way, leaving you room to follow fresh curiosities at your own speed.","ko":"말년은 좋은 의미로 바쁠 수 있어요. 내 속도대로 새로운 호기심을 따라갈 자리가 있어요."},{"en":"Your later years may be more active than restful, with new interests opening up at a speed that suits you.","ko":"말년은 쉬는 시간보다 움직이는 시간이 더 많을 수 있어요. 새로운 관심사가 나에게 맞는 속도로 열리기도 해요."}],"card":"later"},"ST_FEEL_later_mixed":{"tags":["stage:later","fit:later:mixed"],"v":[{"en":"Your later years may blend rest and renewed projects.","ko":"말년에는 쉼과 새로 시작하는 일이 어우러질 수 있어요."},{"en":"Rest and fresh projects may share space in your later years.","ko":"말년에는 쉼과 새 일이 한자리를 나눠 쓸 수 있어요."},{"en":"In your later years, calm stretches and new undertakings may sit side by side.","ko":"말년에는 차분한 시간과 새로 시작하는 일이 나란히 놓일 수 있어요."},{"en":"You may find your later years balanced between slowing down and starting something new.","ko":"말년이 천천히 쉬는 일과 새로 시작하는 일 사이에서 균형을 이룰 수 있어요."},{"en":"A mix of quiet time and new pursuits may mark your later years.","ko":"조용한 시간과 새로운 도전이 섞인 모습이 말년을 채울 수 있어요."},{"en":"Later life may feel like a gentle back-and-forth between rest and a fresh project.","ko":"말년은 쉼과 새 프로젝트 사이를 부드럽게 오가는 시기로 느껴질 수 있어요."},{"en":"Your later years may be part restful, part busy with new work.","ko":"말년은 반쯤은 느긋하고, 반쯤은 새로운 일로 바쁠 수 있어요."}],"card":"later"},"ST_RANGE":{"tags":[],"v":[{"en":"These three life stages and their ages are K Saju's own split. Which part of your chart speaks for each stage follows tradition (birth month for youth, the animal of your birth day for midlife, birth hour for later life), but our age ranges differ from the traditional ones. Based on your 10-year cycles, this stage covers about ages {r1} to {r2} (rounded to the nearest year): {cycList}.","ko":"이 세 시기의 나눔과 나이는 K사주가 직접 정한 것이에요. 사주의 어느 부분이 어느 시기를 말하는지는 전통을 따랐어요(젊은 시절은 태어난 달, 중년은 태어난 날의 동물, 말년은 태어난 시각). 다만 나이 구간은 전통과 달라요. 10년 흐름을 바탕으로, 이 시기는 대략 {r1}~{r2}세(가까운 해로 반올림)예요. {cycList}."}],"card":"early_middle_later"},"ST_RANGE_OPEN":{"tags":[],"v":[{"en":"These three life stages and their ages are K Saju's own split. Which part of your chart speaks for which stage follows tradition (your birth month for youth, the animal of your birth day for midlife, your birth hour for later life), but the traditional age ranges differ from ours. Based on your 10-year cycles, this stage begins at about age {r1} (rounded to the nearest year): {cycList}.","ko":"인생을 세 시기로 나누는 방식과 나이는 K사주가 직접 정한 것이에요. 사주의 어느 부분이 어느 시기를 말하는지는 전통을 따랐지만(젊은 시절은 태어난 달, 중년은 태어난 날의 동물, 말년은 태어난 시각), 전통의 나이 구간은 우리와 달라요. 당신의 10년 단위 흐름을 바탕으로, 이 시기는 대략 {r1}세(반올림)부터 시작해요: {cycList}."}],"card":"early_middle_later"},"ST_RANGE_BOTH":{"tags":["dy:both"],"v":[{"en":"These three life stages and their ages are K Saju's own split. Which part of your chart speaks for each stage follows tradition (birth month for youth, the animal of your birth day for midlife, birth hour for later life), but our age ranges differ from the traditional ones. Without knowing which way your ten-year cycles run, we can't pin down when they change, so we split at ages 30 and 60. This stage covers ages {r1} to {r2}.","ko":"세 시기와 그 나이는 K사주가 직접 나눈 것이에요. 어느 부분이 어느 시기를 말하는지는 전통을 따랐지만(태어난 달은 젊은 시절, 태어난 날의 동물은 중년, 태어난 시각은 말년), 나이 구간은 전통과 달라요. 10년 흐름이 어느 쪽으로 도는지 모르면 바뀌는 때를 정할 수 없어서, 만 30세와 60세를 기준으로 나눴어요. 이 시기는 만 {r1}~{r2}세예요."}],"card":"early_middle_later"},"ST_RANGE_BOTH_OPEN":{"tags":["dy:both"],"v":[{"en":"These three life stages and their ages are K Saju's own split. Which part of your chart speaks for which stage follows tradition (birth month for youth, the animal of your birth day for midlife, birth hour for later life), but traditional age ranges differ from ours. Without knowing which way your 10-year cycles run, we can't place when they change, so we split at ages 30 and 60. This stage begins at age {r1}.","ko":"이 세 시기의 나눔과 나이는 K사주가 직접 정한 것이에요. 사주의 어느 부분이 어느 시기를 말하는지는 전통을 따랐어요(태어난 달은 젊은 시절, 태어난 날의 동물은 중년, 태어난 시간은 말년). 하지만 전통의 나이 구간은 우리와 달라요. 10년 흐름이 어느 방향으로 도는지 모르면 언제 바뀌는지 정할 수 없어서, 30세와 60세를 기준으로 나눴어요. 이 시기는 {r1}세부터 시작돼요."}],"card":"early_middle_later"},"ST_CYC_early_bigyeop":{"tags":["stage:early"],"v":[{"en":"Your young years may be shaped by peers, such as friends, siblings, and classmates, and by learning to stand your ground.","ko":"젊은 시절은 친구, 형제, 동급생 같은 또래와 내 자리를 지키는 법을 배우는 일로 빚어질 수 있어요."},{"en":"Your early years may revolve around people your own age, whether friends, siblings, or classmates, and around figuring out where you stand.","ko":"젊은 시절은 친구나 형제, 동급생 같은 또래 주변을 맴돌고, 내 자리가 어디인지 찾아가는 시간일 수 있어요."},{"en":"Friends, siblings, and classmates play a big part in your young years, and so does learning to hold your own.","ko":"젊은 시절에는 친구, 형제, 동급생이 큰 몫을 하고, 나 자신을 지키는 법을 배우는 일도 함께해요."}],"card":"early"},"ST_CYC_early_siksang":{"tags":["stage:early"],"v":[{"en":"Your young years lean toward expression: talents, hobbies, and a voice that wants to be heard.","ko":"젊은 시절은 표현 쪽으로 기울어요. 재능과 취미, 들려지고 싶은 목소리요."},{"en":"Self-expression can take center stage in your early years, with talents, hobbies, and a voice looking for an audience.","ko":"어린 시절과 젊은 시절에는 자기표현이 중심에 놓일 수 있어요. 재능과 취미, 들어 줄 사람을 찾는 목소리요."},{"en":"In your young years, creativity wants room: you may find yourself drawn to making things, trying hobbies, and speaking up.","ko":"젊은 시절에는 창의력이 자리를 원해요. 무언가 만들고, 취미를 해 보고, 목소리를 내는 데 끌릴 수 있어요."}],"card":"early"},"ST_CYC_early_jaeseong":{"tags":["stage:early"],"v":[{"en":"Your young years turn practical early: part-time work, managing money, or real-world results.","ko":"젊은 시절은 일찍부터 현실적이에요. 아르바이트, 돈 관리, 실제 결과 같은 것들이요."},{"en":"Practical matters come early in life, such as first jobs, handling money, and seeing real results.","ko":"젊은 시절에 일찌감치 현실적인 일들이 찾아와요. 첫 일자리, 돈을 다루는 일, 눈에 보이는 성과 같은 것들이요."},{"en":"Your younger years lean toward the down-to-earth: earning, budgeting, and getting tangible outcomes.","ko":"어린 시절과 젊은 날은 발이 땅에 닿아 있어요. 돈을 벌고, 살림을 꾸리고, 손에 잡히는 결과를 얻는 일이 중심이에요."}],"card":"early"},"ST_CYC_early_gwanseong":{"tags":["stage:early"],"v":[{"en":"Your young years may bring structure early: rules, expectations, and roles you grow into.","ko":"젊은 시절은 일찍부터 틀을 가져올 수 있어요. 규칙과 기대, 자라며 맞춰 가는 역할들이요."},{"en":"Your early years may come with rules, expectations, and roles to grow into, giving life some shape from the start.","ko":"젊은 시절에는 규칙과 기대, 자라며 맞춰 갈 역할이 따라와서 처음부터 삶에 틀이 잡힐 수 있어요."},{"en":"Structure shows up early for you, through rules, expectations, and roles you slowly grow into.","ko":"틀은 일찍부터 찾아와요. 규칙과 기대, 천천히 자라며 맞춰 가는 역할을 통해서요."}],"card":"early"},"ST_CYC_early_inseong":{"tags":["stage:early"],"v":[{"en":"Your young years lean toward learning: school, mentors, and people who look after you.","ko":"젊은 시절은 배움 쪽으로 기울어요. 학교와 스승, 당신을 돌봐 주는 사람들이요."},{"en":"Early life points toward study, with teachers, mentors, and caretakers shaping your path.","ko":"이른 시절은 공부 쪽을 향하고, 선생님과 멘토, 돌봐 주는 사람들이 길을 만들어 줘요."},{"en":"Learning takes the lead in your young years, supported by school, guides, and people who look out for you.","ko":"젊은 시절에는 배움이 앞에 서고, 학교와 길잡이, 챙겨 주는 사람들이 받쳐 줘요."}],"card":"early"},"ST_CYC_middle_bigyeop":{"tags":["stage:middle"],"v":[{"en":"In the middle years independence grows: your own venture, your own way, or a team of equals.","ko":"중년에는 독립심이 자라요. 나만의 일, 나만의 방식, 혹은 대등한 사람들의 팀이요."},{"en":"Your middle years can bring a stronger pull toward independence, such as running your own show or working alongside equals.","ko":"중년에는 독립을 향한 마음이 더 커질 수 있어요. 내 일을 꾸리거나 대등한 사람들과 함께 일하는 식으로요."}],"card":"middle"},"ST_CYC_middle_siksang":{"tags":["stage:middle"],"v":[{"en":"In the middle years output leads: work that shows your skill, teaching, or making things people use.","ko":"중년에는 결과물이 앞장서요. 실력을 보여 주는 일, 가르치는 일, 사람들이 쓰는 것을 만드는 일이요."},{"en":"Midlife puts output first: careers built on showcasing skill, teaching others, or creating things people use.","ko":"중년에는 만들어 내는 힘이 먼저예요. 실력을 드러내는 일, 남을 가르치는 일, 사람들이 쓰는 것을 창작하는 일이 어울려요."},{"en":"Your middle years lean toward expression, whether that means work that displays your talent, instructing, or making useful things.","ko":"중년은 표현하는 쪽으로 기울어요. 재능을 보여 주는 일이든, 알려 주는 일이든, 쓸모 있는 것을 만드는 일이든요."}],"card":"middle"},"ST_CYC_middle_jaeseong":{"tags":["stage:middle"],"v":[{"en":"In the middle years building wealth takes center stage: earnings, property, and managing real results.","ko":"중년에는 재산 쌓기가 중심에 서요. 수입과 자산, 실제 결과를 관리하는 일이요."},{"en":"Money-building comes to the fore during the middle years, with income, property, and the management of tangible results.","ko":"중년에는 돈을 모으는 일이 앞으로 나오고, 수입과 재산, 눈에 보이는 결과를 다루는 일이 이어져요."},{"en":"The middle years put wealth at center stage, meaning earning, assets, and keeping track of real outcomes.","ko":"중년에는 재물이 무대 한가운데에 서요. 버는 일, 자산, 실제 성과를 챙기는 일이 그 내용이에요."}],"card":"middle"},"ST_CYC_middle_gwanseong":{"tags":["stage:middle"],"v":[{"en":"In the middle years roles and responsibility grow: titles, leadership, and being counted on.","ko":"중년에는 역할과 책임이 커져요. 직함과 이끄는 자리, 믿고 맡겨지는 일이요."},{"en":"Your middle years may bring bigger roles and more responsibility, from titles to leading others to being the person people rely on.","ko":"중년에는 더 큰 역할과 책임이 올 수 있어요. 직함이 생기고, 사람들을 이끌고, 모두가 의지하는 사람이 되는 일이요."},{"en":"Responsibility rises in the middle years: you may be given a title, a team to guide, or work others trust you with.","ko":"중년에는 책임이 커져요. 직함이나 이끌 팀, 남들이 믿고 맡기는 일이 주어질 수 있어요."},{"en":"The middle years can put you in charge of more: leadership, recognition, and people counting on you.","ko":"중년에는 맡는 일이 늘어날 수 있어요. 이끄는 자리, 인정, 그리고 당신을 믿고 기대는 사람들이요."}],"card":"middle"},"ST_CYC_middle_inseong":{"tags":["stage:middle"],"v":[{"en":"In the middle years knowledge and reputation grow: qualifications, expertise, and a network that looks out for you.","ko":"중년에는 지식과 평판이 자라요. 자격과 전문성, 당신을 챙겨 주는 인맥이요."},{"en":"Middle age brings growth in learning and reputation, through credentials, expertise, and a circle of people who support you.","ko":"중년에는 배움과 평판이 자라요. 자격, 전문 분야, 그리고 당신을 받쳐 주는 사람들의 모임이 그 바탕이에요."},{"en":"Your middle years build up knowledge and standing, with qualifications, specialized skill, and a network that has your back.","ko":"중년에는 지식과 위상이 쌓여요. 자격증, 깊이 있는 기술, 당신 편이 되어 주는 인맥과 함께요."}],"card":"middle"},"ST_CYC_later_bigyeop":{"tags":["stage:later"],"v":[{"en":"In later years friendships and community may matter most: people who stand beside you.","ko":"말년에는 우정과 공동체가 가장 중요해질 수 있어요. 곁에 서 주는 사람들이요."},{"en":"Later in life, close friends and community may become your anchor: people who stand by you.","ko":"말년에는 가까운 친구와 공동체가 닻이 되어 줄 수 있어요. 곁을 지켜 주는 사람들이요."},{"en":"Friendship and belonging may carry the most weight in your later years, through the people who walk beside you.","ko":"말년에는 우정과 소속감이 가장 큰 무게를 가질 수 있어요. 나란히 걸어 주는 사람들을 통해서요."}],"card":"later"},"ST_CYC_later_siksang":{"tags":["stage:later"],"v":[{"en":"In later years creative and generous energy stays strong: hobbies, sharing skills, and enjoying the fruits.","ko":"말년에도 창의적이고 너그러운 기운이 이어져요. 취미, 재주 나누기, 거둔 열매를 즐기는 일이요."},{"en":"Your later years can stay inventive and giving, with room for hobbies, passing on what you know, and savoring what you've gathered.","ko":"말년에도 창의적이고 베푸는 기운이 이어질 수 있어요. 취미, 아는 것 전하기, 모아 온 것을 누리는 일이요."},{"en":"Creativity and generosity keep shining in your later years: think hobbies, teaching others, and enjoying the harvest.","ko":"말년에도 창의성과 너그러움이 계속 빛나요. 취미 생활, 남을 가르치기, 수확을 누리는 일을 떠올려 보세요."}],"card":"later"},"ST_CYC_later_jaeseong":{"tags":["stage:later"],"v":[{"en":"In later years practical matters stay active: managing what you've built and passing it on well.","ko":"말년에도 현실적인 일이 계속 활발해요. 쌓아 온 것을 관리하고 잘 물려주는 일이요."},{"en":"Practical matters may keep you busy in later years, from looking after what you've built to handing it on with care.","ko":"말년에는 현실적인 일로 바쁠 수 있어요. 쌓아 온 것을 돌보는 일부터 정성껏 물려주는 일까지요."},{"en":"Your later years stay lively with real-world matters: caring for what you've gathered and passing it down well.","ko":"말년은 현실의 일들로 활기가 이어져요. 모아 온 것을 가꾸고 잘 넘겨주는 일들이요."}],"card":"later"},"ST_CYC_later_gwanseong":{"tags":["stage:later"],"v":[{"en":"In later years you may still hold roles of respect: advising, guiding, and keeping standards.","ko":"말년에도 존중받는 역할을 맡을 수 있어요. 조언하고, 이끌고, 기준을 지키는 일이요."},{"en":"You may still be someone people look up to in later years, advising, leading, and upholding standards.","ko":"말년에도 사람들이 우러러보는 사람일 수 있어요. 조언하고, 앞장서고, 기준을 지키는 모습으로요."},{"en":"Later life can keep you in respected roles where you give advice, set direction, and maintain good standards.","ko":"말년에는 조언을 건네고 방향을 잡아 주며 좋은 기준을 지키는, 존중받는 자리에 머물 수 있어요."}],"card":"later"},"ST_CYC_later_inseong":{"tags":["stage:later"],"v":[{"en":"In later years, reflection, learning, and receiving care from others may play a part.","ko":"나이 든 뒤에는 돌아보기와 배움, 다른 사람의 보살핌을 받는 일이 한몫할 수 있어요."},{"en":"Reflecting, studying, and being looked after by others may stand out in your later years.","ko":"되돌아보고, 공부하고, 다른 사람의 돌봄을 받는 일이 나중 시절에 눈에 띌 수 있어요."},{"en":"Your later years may bring time for reflection, learning, and care from the people around you.","ko":"말년에는 사색하고 배우며 주변 사람의 돌봄을 누리는 시간이 찾아올 수 있어요."}],"card":"later"},"ST_FIT_smooth":{"tags":[],"v":[{"en":"By the same measure used in your Life Timeline, the cycles in your {stageWord} bring a good share of the elements that balance your chart.","ko":"인생 흐름 칸과 같은 기준으로 보면 {stageWordKo}의 대운들은 사주의 균형을 잡아 주는 기운을 넉넉히 가져와요."},{"en":"Measured the same way as your Life Timeline, the cycles of your {stageWord} bring plenty of the elements that balance your chart.","ko":"인생 흐름 칸과 같은 방식으로 재 보면, {stageWordKo}의 10년 흐름들에는 사주의 균형을 맞추는 기운이 넉넉히 들어 있어요."},{"en":"The cycles of your {stageWord} carry a generous share of balancing elements, going by the Life Timeline's yardstick.","ko":"인생 흐름 칸의 잣대로 보면, {stageWordKo}의 10년 흐름은 균형을 잡는 기운을 후하게 품고 있어요."},{"en":"On the same basis as the Life Timeline, the {stageWord} supply a good amount of what steadies your chart.","ko":"인생 흐름 칸과 같은 기준으로 보면 {stageWordKo}에는 사주를 안정시키는 기운이 충분히 와요."},{"en":"The cycles of your {stageWord} bring a fair amount of the elements that help bring your chart into balance, by the Life Timeline's measure.","ko":"인생 흐름 칸의 기준으로 {stageWordKo}의 대운은 사주를 균형으로 이끄는 기운을 적잖이 가져와요."},{"en":"In the {stageWord}, your cycles deliver a good portion of the elements that balance your chart, judged as in the Life Timeline.","ko":"{stageWordKo}에는 대운이 사주의 균형을 맞춰 주는 기운을 넉넉히 전해 줘요. 인생 흐름 칸과 같은 판단 방식이에요."},{"en":"By the Life Timeline's standard, the cycles of your {stageWord} add a good helping of balancing elements.","ko":"인생 흐름 칸의 기준으로 보면 {stageWordKo}의 10년 흐름은 균형을 잡는 기운을 듬뿍 보태 줘요."},{"en":"Judged like the Life Timeline, the {stageWord} bring in a good share of the elements your chart needs for balance.","ko":"인생 흐름 칸처럼 판단하면 {stageWordKo}에는 사주가 균형을 이루는 데 필요한 기운이 넉넉히 들어와요."},{"en":"Here, in the {stageWord}, the cycles provide a solid share of the balancing elements, the same measure used in your Life Timeline.","ko":"{stageWordKo}의 대운은 균형을 잡는 기운을 든든하게 채워 줘요. 인생 흐름 칸에서 쓴 것과 같은 기준이에요."}],"card":"early_middle_later"},"ST_FIT_stretch":{"tags":[],"v":[{"en":"By the same measure used in your Life Timeline, the cycles in your {stageWord} bring somewhat fewer of the elements that balance your chart, which makes them a good stretch for growing new skills at an unhurried pace.","ko":"인생 흐름 칸과 같은 기준으로 보면 {stageWordKo}의 대운들은 균형을 잡아 주는 기운을 조금 덜 가져와요. 그래서 서두르지 않고 새로운 기술을 키우기 좋은 시기예요."},{"en":"Using the same yardstick as your Life Timeline, the cycles in your {stageWord} supply a little less of what balances your chart, so this is a nice stretch to build new skills without hurrying.","ko":"인생 흐름 칸과 같은 잣대로 보면 {stageWordKo}의 대운들은 사주의 균형을 맞추는 기운을 조금 적게 실어 와요. 서두르지 않고 새 기술을 쌓아 가기에 알맞은 때예요."},{"en":"The cycles of your {stageWord}, measured the way your Life Timeline does it, bring somewhat less of the elements that steady your chart; it's a fitting time to grow new abilities slowly.","ko":"인생 흐름 칸이 재는 방식대로 보면 {stageWordKo}의 대운들은 사주를 안정시키는 기운이 약간 적어요. 새로운 능력을 천천히 키우기에 어울리는 시기예요."},{"en":"The cycles of your {stageWord} carry a bit less of the balancing elements by the Life Timeline's measure, which suits learning something new at a gentle pace.","ko":"인생 흐름 칸의 기준으로는 {stageWordKo}의 10년 흐름에 균형을 잡아 주는 기운이 조금 덜 들어 있어요. 느긋한 걸음으로 새로운 것을 배우기에 잘 맞아요."},{"en":"Compared on the same basis as the Life Timeline, the {stageWord} bring slightly fewer of the elements your chart leans on for balance, making this a good season for patient skill-building.","ko":"인생 흐름 칸과 같은 기준으로 견주면 {stageWordKo}에는 사주가 균형을 맞추려고 기대는 기운이 살짝 적게 와요. 차분히 실력을 쌓기 좋은 계절이에요."},{"en":"Here's how the {stageWord} look by the Life Timeline's measure: their cycles add a little less balancing energy, so it may be a good time to practice new skills calmly.","ko":"인생 흐름 칸의 기준으로 {stageWordKo}를 보면, 대운이 더해 주는 균형 기운이 조금 적어요. 그래서 새 기술을 마음 편히 연습하기 좋은 때일 수 있어요."},{"en":"In the {stageWord}, the cycles offer somewhat fewer of the balancing elements, going by the Life Timeline's yardstick, and that makes room for slow, steady skill growth.","ko":"인생 흐름 칸의 잣대로 보면 {stageWordKo}의 대운은 균형을 맞추는 기운을 약간 적게 내놓아요. 그 덕분에 느리지만 꾸준하게 실력을 키울 여유가 생겨요."},{"en":"By the Life Timeline's standard, the cycles of your {stageWord} supply somewhat fewer balancing elements, which can be a good setting for picking up new skills without rushing.","ko":"인생 흐름 칸의 기준으로 보면 {stageWordKo}의 10년 흐름에는 균형 기운이 조금 적게 들어 있어요. 서두르지 않고 새 기술을 익히기에 좋은 환경이 될 수 있어요."},{"en":"Judged the same way as the Life Timeline, the cycles of your {stageWord} hold a little less of what balances your chart, so unhurried practice of new skills fits well.","ko":"인생 흐름 칸과 같은 방식으로 판단하면 {stageWordKo}의 10년 흐름은 사주의 균형을 잡는 기운을 조금 덜 품고 있어요. 그래서 서두르지 않고 새 기술을 연습하는 쪽이 잘 맞아요."}],"card":"early_middle_later"},"ST_FIT_mixed":{"tags":[],"v":[{"en":"By the same measure used in your Life Timeline, the cycles in your {stageWord} are mixed, with smoother decades and decades for growing new skills side by side.","ko":"인생 흐름 칸과 같은 기준으로 보면 {stageWordKo}의 대운들은 섞여 있어서, 수월한 10년과 새로운 기술을 키우는 10년이 나란히 있어요."},{"en":"Using the same yardstick as your Life Timeline, your {stageWord} have a blend of cycles: some decades feel smoother, while others are for building new skills.","ko":"인생 흐름 칸과 같은 잣대로 보면 {stageWordKo}의 대운은 고루 섞여 있어요. 수월하게 느껴지는 10년도, 새 기술을 쌓는 10년도 있어요."},{"en":"Your {stageWord} hold a mix of cycles, judged the same way as in your Life Timeline: easier stretches sit next to stretches that ask you to learn.","ko":"인생 흐름 칸과 같은 방식으로 보면 {stageWordKo}에는 여러 대운이 섞여 있어요. 편안한 구간 옆에 배움을 요구하는 구간이 함께 놓여 있어요."},{"en":"Measured as your Life Timeline does, the cycles of your {stageWord} aren't all one kind; calmer decades and skill-building decades take turns.","ko":"인생 흐름 칸이 재는 방식으로 보면 {stageWordKo}의 대운은 한 가지로만 되어 있지 않아요. 잔잔한 10년과 기술을 키우는 10년이 번갈아 와요."},{"en":"For your {stageWord}, the Life Timeline's yardstick shows a mixed picture, with some smoother decades and some decades that grow new abilities.","ko":"{stageWordKo}에 대해 인생 흐름 칸의 잣대로 보면 그림이 다채로워요. 비교적 순한 10년도 있고, 새 능력을 키우는 10년도 있어요."},{"en":"There's variety in the cycles of your {stageWord} by the same Life Timeline standard: a few easier decades and a few that stretch you into new skills.","ko":"같은 인생 흐름 기준으로 {stageWordKo}의 대운에는 변화가 있어요. 편안한 10년이 몇 번, 새 기술로 나를 넓혀 주는 10년이 몇 번 섞여 있어요."},{"en":"Judged by the Life Timeline's measure, your {stageWord} don't lean one way. They mix smoother decades with decades of learning something new.","ko":"인생 흐름 칸의 기준으로 보면 {stageWordKo}은(는) 한쪽으로 기울지 않아요. 수월한 10년과 새로운 걸 익히는 10년이 섞여 있어요."},{"en":"In the Life Timeline's terms, the cycles across your {stageWord} come in different flavors, so easy decades and growth decades appear side by side.","ko":"인생 흐름 칸의 기준으로 {stageWordKo}의 대운은 결이 서로 달라요. 수월한 10년과 성장하는 10년이 나란히 이어져요."},{"en":"Counting cycles the way your Life Timeline does, your {stageWord} offer a balance: some decades flow, others teach new skills.","ko":"인생 흐름 칸처럼 대운을 헤아려 보면 {stageWordKo}에는 균형이 있어요. 술술 흐르는 10년도, 새 기술을 가르쳐 주는 10년도 있어요."},{"en":"Read by the Life Timeline standard, your {stageWord} look like a patchwork: gentler decades mixed in with decades of skill-building.","ko":"인생 흐름 기준으로 {stageWordKo}은(는) 조각보처럼 읽혀요. 부드러운 10년 사이사이에 기술을 쌓는 10년이 끼어 있어요."},{"en":"On the same scale as the Life Timeline, your {stageWord} include both smoother cycles and cycles built for learning.","ko":"인생 흐름 칸과 같은 눈금으로 보면 {stageWordKo}에는 순탄한 대운과 배움에 맞춰진 대운이 모두 들어 있어요."}],"card":"early_middle_later"},"ST_PAL_early":{"tags":[],"v":[{"en":"Korean tradition reads your birth month for youth and upbringing. The element of that month carries the theme of {palGod}, which colors these years with {palCat}.","ko":"전통에서는 태어난 달로 젊은 시절과 자라 온 환경을 읽어요. 태어난 달의 기운은 {palGod}의 주제를 담고 있어서, 이 시기를 {palCatKo}의 빛깔로 물들여요."},{"en":"Tradition looks to the birth month for youth and upbringing, and in yours the element points to {palGod}, giving these years a shade of {palCat}.","ko":"전통은 젊은 시절과 성장 환경을 태어난 달에서 찾아요. 당신의 경우 그 기운이 {palGod}을(를) 가리켜서, 이 시기에 {palCatKo}의 색이 한 겹 더해져요."},{"en":"Your formative years are read through your birth month, and that month's element carries the theme of {palGod}, so that time can take on a tint of {palCat}.","ko":"성장기는 태어난 달을 통해 읽고, 그 달의 기운에는 {palGod}의 주제가 담겨 있어요. 그래서 그 시절이 {palCatKo}의 빛을 띨 수 있어요."},{"en":"The element of your birth month, the part of your chart tradition reads for youth and the setting you grew up in, points to {palGod}, bringing a note of {palCat} to those years.","ko":"태어난 달의 기운은 전통적으로 젊은 시절과 자란 환경을 읽는 자리인데, 당신은 {palGod}을(를) 가리켜요. 그 시기에 {palCatKo}의 분위기를 살짝 더해 줘요."},{"en":"Traditional commentaries read youth and upbringing from the birth month; the element of yours carries the theme of {palGod}, which can lend these years a flavor of {palCat}.","ko":"전통 해설서는 태어난 달에서 젊은 시절과 자란 환경을 읽어요. 당신의 달 기운은 {palGod}의 주제를 지녀서, 이 시기에 {palCatKo}의 맛이 날 수 있어요."},{"en":"Look at the element of your birth month, the traditional window onto your youth and the home you grew up in: it carries the theme of {palGod}, which adds {palCat} to this season of life.","ko":"젊은 시절과 자란 집을 들여다보는 전통의 창, 태어난 달의 기운을 살펴보세요. 거기 담긴 {palGod}의 주제가 이 시기에 {palCatKo}을(를) 보태 줘요."},{"en":"In your chart, the element of your birth month carries the theme of {palGod}. Since that month is read for upbringing, the early years may take on a tone of {palCat}.","ko":"당신의 사주에서 태어난 달의 기운은 {palGod}의 주제를 담고 있어요. 그 달은 자라 온 환경을 읽는 곳이라, 어린 시절이 {palCatKo}의 색조를 띨 수 있어요."},{"en":"Your growing-up years are linked with your birth month, and its element carries the theme of {palGod}, which can bring {palCat} into that stretch.","ko":"자라는 시기는 태어난 달과 이어져 있고, {palGod}을(를) 가리키는 그 달의 기운은 이 시기에 {palCatKo}을(를) 불러오는 것으로 읽어요."},{"en":"Your birth month's element carries the theme of {palGod}. Tradition connects this month with youth, so it casts a light of {palCat} over your early chapters.","ko":"태어난 달의 기운에는 {palGod}의 주제가 담겨 있어요. 전통은 이 달을 젊은 시절과 이어 보기에, 인생의 앞부분에 {palCatKo}의 빛을 비춰 줘요."},{"en":"Tradition ties youth to the birth month, and its element in your chart, with {palGod}, is read as shading those years with {palCat}.","ko":"전통은 젊은 시절을 태어난 달과 묶어 보는데, 당신의 사주에서 그 달은 {palGod}의 주제를 지녀요. 그래서 그 시기를 {palCatKo}의 색으로 물들여요."},{"en":"When your formative years are read through your birth month, its element points to {palGod}, a sign these years carry the feel of {palCat}.","ko":"성장기를 태어난 달로 읽으면, 그 달의 기운이 {palGod}을(를) 가리켜요. 이 시기에 {palCatKo}의 느낌이 깃들어 있다는 신호예요."},{"en":"Your youth and the setting you grew up in are traditionally read from your birth month, whose element carries the theme of {palGod}; that gives the period a hue of {palCat}.","ko":"젊은 시절과 자란 환경은 전통적으로 태어난 달에서 읽는데, 그 달의 기운이 {palGod}의 주제를 담고 있어요. 그래서 이 시기가 {palCatKo}의 색감을 띠어요."}],"card":"early"},"ST_PAL_middle":{"tags":[],"v":[{"en":"The animal of the day you were born, which tradition reads for the middle years and close partnership, is linked with {palGod}, bringing a thread of {palCat} into these years.","ko":"태어난 날의 동물은 전통적으로 중년과 가까운 동반자 관계를 읽는 자리인데, {palGod}와(과) 이어져 있어서 이 시기에 {palCatKo}의 실타래를 더해요."},{"en":"Traditionally, the animal of your birth day speaks for the middle years and close partnership, and yours is tied to {palGod}, which adds a strand of {palCat} to this stretch of life.","ko":"전통적으로 태어난 날의 동물은 중년과 가까운 동반자 관계를 말해 줘요. 당신의 동물은 {palGod}와(과) 묶여 있어서, 인생의 이 구간에 {palCatKo}의 결이 한 가닥 더해져요."},{"en":"The animal of the day you were born carries the theme of {palGod}. Because tradition reads that spot for the middle years and close partnership, a touch of {palCat} may color this period.","ko":"태어난 날의 동물에는 {palGod}의 주제가 담겨 있어요. 전통에서 그 자리를 중년과 가까운 동반자 관계로 읽기 때문에, 이 시기에 {palCatKo}의 기운이 살짝 물들 수 있어요."},{"en":"Look at the animal of your birth day, the place tradition reads for midlife and partnership: it points to {palGod}, a hint of {palCat} running through these years.","ko":"중년과 동반자 관계를 읽는 자리인 태어난 날의 동물을 보세요. {palGod}을(를) 가리키고 있어서, 이 시기 내내 {palCatKo}의 느낌이 은은하게 흘러요."},{"en":"Midlife and close partnership are traditionally read from the animal of your birth day, and yours carries the theme of {palGod}, so a thread of {palCat} may run through these years.","ko":"전통에서는 중년과 가까운 동반자 관계를 태어난 날의 동물로 읽어요. 당신의 동물에는 {palGod}의 주제가 담겨 있어서, 이 시기에 {palCatKo}의 실이 이어질 수 있어요."},{"en":"Your birth-day animal is linked with {palGod}. Since tradition reads it for the middle years and close bonds, this suggests a flavor of {palCat} during that time.","ko":"태어난 날의 동물이 {palGod}와(과) 이어져 있어요. 전통에서 그 동물로 중년과 가까운 인연을 읽으니, 이 시기에 {palCatKo}의 맛이 난다고 볼 수 있어요."},{"en":"Through the animal of your birth day, which tradition ties to the middle years and the people closest to you, a theme of {palGod} brings a shade of {palCat} into this chapter.","ko":"전통에서 중년과 가장 가까운 사람들과 이어 보는 태어난 날의 동물을 통해, {palGod}의 주제가 이 시기에 {palCatKo}의 빛깔을 한 겹 더해 줘요."},{"en":"The middle years and close partnership are tied to your birth-day animal in tradition. In your chart, that animal is marked by {palGod}, which can bring {palCat} into the picture.","ko":"전통에서는 중년과 가까운 동반자 관계를 태어난 날의 동물과 이어서 봐요. 당신의 사주에서 그 동물에는 {palGod}의 표시가 있어서, {palCatKo}이(가) 그림 안에 들어올 수 있어요."},{"en":"There's a theme of {palGod} in the animal of your birth day, the spot tradition reads for the middle years and close partnership, and it lends these years a tone of {palCat}.","ko":"중년과 가까운 동반자 관계를 읽는 자리, 태어난 날의 동물에 {palGod}의 주제가 있어요. 그래서 이 시기에는 {palCatKo}의 분위기가 감돌아요."},{"en":"Tradition reads your birth-day animal for the middle of life and for close partnership; yours leans toward {palGod}, so a sense of {palCat} may become part of how these years feel.","ko":"전통에서는 태어난 날의 동물로 인생의 중반과 가까운 동반자 관계를 읽어요. 당신의 동물은 {palGod} 쪽으로 기울어 있어서, 이 시기의 느낌에 {palCatKo}이(가) 섞일 수 있어요."},{"en":"For the middle years, tradition turns to the animal of the day you were born, and yours points to {palGod}. That adds a layer of {palCat} to this part of your life.","ko":"중년을 볼 때 전통은 태어난 날의 동물을 살피는데, 당신의 동물은 {palGod}을(를) 가리켜요. 인생의 이 구간에 {palCatKo}의 층이 하나 더해져요."},{"en":"A note of {palCat} enters your middle years through a theme of {palGod}, found in your birth-day animal, the spot tradition reads for close partnership.","ko":"{palCatKo}의 기운이 중년에 들어오는데, 그 통로는 태어난 날의 동물에 담긴 {palGod}의 주제예요. 이 동물은 전통에서 가까운 동반자 관계를 읽는 자리예요."}],"card":"middle"},"ST_PAL_later":{"tags":["pillar:hour"],"v":[{"en":"Your birth hour, which tradition reads for later life and long-term projects, carries the theme of {palGod}, adding a note of {palCat} to these years.","ko":"전통에서 말년과 오래가는 일을 읽는 태어난 시각에는 {palGod}의 주제가 담겨 있어서, 이 시기에 {palCatKo}의 색을 더해요."},{"en":"Tradition looks to the hour you were born for later life and long-term projects, and yours points to {palGod}, which brings a shade of {palCat} to these years.","ko":"전통은 말년과 오래 이어 갈 일을 태어난 시각에서 찾는데, 당신의 시각은 {palGod}을(를) 가리켜요. 이 시기에 {palCatKo}의 빛깔이 한 겹 더해져요."},{"en":"A theme of {palGod} shows up in your birth hour, the part of your chart linked with later life and lasting work, so a tint of {palCat} may color this stage.","ko":"말년과 오래 남는 일에 이어진 자리, 태어난 시각에 {palGod}의 주제가 나타나요. 그래서 이 시기가 {palCatKo}의 기운으로 물들 수 있어요."},{"en":"Look at your birth hour, read for later life and long-term projects: it carries the theme of {palGod}, adding a hint of {palCat} to these years.","ko":"말년과 오래가는 일을 읽는 태어난 시각을 보면 {palGod}의 주제가 담겨 있어요. 이 시기에 {palCatKo}의 느낌이 은은하게 더해져요."},{"en":"Later life and lasting work are read from the hour you were born, and yours carries the theme of {palGod}, so a thread of {palCat} may run through this chapter.","ko":"말년과 오래 남는 일은 태어난 시각으로 읽는데, 당신의 시각에는 {palGod}의 주제가 있어요. 그래서 이 시기에 {palCatKo}이(가) 실처럼 이어질 수 있어요."},{"en":"The hour you were born carries the theme of {palGod}. Since that hour speaks for your later years and long-term projects, it lends a flavor of {palCat} to that time.","ko":"태어난 시각에는 {palGod}의 주제가 담겨 있어요. 그 시각은 말년과 오래가는 일을 말해 주는 곳이라, 그 시기에 {palCatKo}의 맛을 더해요."},{"en":"Through your birth hour, which tradition ties to later life and projects that last, a theme of {palGod} brings a touch of {palCat} into your later years.","ko":"전통이 말년과 오래가는 일에 이어 보는 태어난 시각을 통해, {palGod}의 주제가 말년에 {palCatKo}의 색을 살짝 가져와요."},{"en":"Your birth hour is where tradition looks for later life and long-term projects. In your chart it points to {palGod}, which can add {palCat} to this stage.","ko":"태어난 시각은 전통이 말년과 오래가는 일을 찾아보는 곳이에요. 당신의 사주에서는 {palGod}을(를) 가리켜서, 이 시기에 {palCatKo}이(가) 더해질 수 있어요."},{"en":"There's a theme of {palGod} in your birth hour, the spot tradition reads for later life and lasting work, giving these years a tone of {palCat}.","ko":"전통이 말년과 오래 남는 일을 읽는 자리, 태어난 시각에 {palGod}의 주제가 있어요. 그래서 이 시기에는 {palCatKo}의 분위기가 감돌아요."},{"en":"Your birth hour, the part of your chart tradition reads for long-term projects, carries a thread of {palCat} into your later years.","ko":"태어난 시각은 말년으로 {palCatKo}의 실 한 가닥을 이어 줘요. 전통에서 오래가는 일을 읽는 자리예요."}],"card":"later"},"ST_LATE_PARTIAL":{"tags":["notice:time-unknown"],"v":[{"en":"This section is read from your 10-year cycles. If you learn your birth time later, one more piece fills in.","ko":"이 칸은 10년 대운으로 읽었어요. 나중에 태어난 시간을 알게 되면 조각 하나가 더 채워져요."},{"en":"This part comes from your 10-year cycles, and learning your birth time later could add one more piece.","ko":"이 부분은 10년 대운에서 나왔어요. 나중에 태어난 시간을 알게 되면 조각이 하나 더 보태질 수 있어요."},{"en":"We read this section through your 10-year cycles; once your birth time is known, another piece can be added.","ko":"이 칸은 10년 대운으로 읽었어요. 태어난 시간을 알게 되면 또 다른 조각을 더할 수 있어요."}],"card":"early_middle_later"},"ST_LATE_PARTIAL_BOTH":{"tags":["notice:time-unknown"],"v":[{"en":"This section is read from your 10-year cycles in both directions. If you learn your birth time later, one more piece fills in.","ko":"이 칸은 두 방향의 10년 대운으로 읽었어요. 나중에 태어난 시간을 알게 되면 조각 하나가 더 채워져요."}],"card":"early_middle_later"},"ST_NATAL_early":{"tags":[],"v":[{"en":"Your birth year and birth month, {yp} and {mp}, frame these years: the year for family roots, the month for the setting you grew up in.","ko":"태어난 해 {yp}와(과) 태어난 달 {mp}이(가) 이 시기의 틀을 잡아요. 태어난 해는 집안의 뿌리를, 태어난 달은 자라난 환경을 보여 줘요."}],"card":"early"},"ST_NATAL_middle":{"tags":[],"v":[{"en":"The day you were born, {dp}, frames these years: its element is your core element, and its animal is the life you build closest to home.","ko":"태어난 날 {dp}이(가) 이 시기의 틀을 잡아요. 그날의 기운은 나의 중심 기운이고, 그날의 동물은 가장 가까이에서 일궈 가는 삶이에요."}],"card":"middle"},"ST_ACT_early_past":{"tags":["stage:early"],"v":[{"en":"Name one strength you built before {c1} that you still use today.","ko":"{c1}세 이전에 길러서 지금도 쓰고 있는 힘 하나를 떠올려 보세요."},{"en":"Think of one person from your early years who helped you, and write them a short thank-you; you can decide later whether to send it, and to whom.","ko":"젊은 시절 도움을 준 사람 한 명을 떠올려 짧은 감사 인사를 써 보세요. 보낼지, 누구에게 보낼지는 나중에 정해도 돼요."},{"en":"Recall a skill you picked up before age {c1} and use it once this week on purpose.","ko":"{c1}세 이전에 익힌 기술 하나를 떠올리고, 이번 주에 일부러 한 번 써 보세요."},{"en":"Write down one habit from before {c1} that still serves you, and say thanks to it.","ko":"{c1}세 이전부터 지금까지 도움이 되는 습관 하나를 적고, 고마운 마음을 전해 보세요."},{"en":"Look at an old photo from your early years and jot down one quality you see in it that's still yours.","ko":"젊은 시절 사진 한 장을 보고, 지금도 내 안에 남아 있는 모습 하나를 적어 보세요."},{"en":"Ask a family member or old friend what they remember you being good at when you were young.","ko":"가족이나 오랜 친구에게 어렸을 때 내가 뭘 잘했는지 기억나는지 물어보세요."},{"en":"Pick one lesson from your early years and pass it on to someone younger.","ko":"젊은 시절에 얻은 교훈 하나를 골라 더 어린 사람에게 들려주세요."},{"en":"Spend twenty minutes this weekend on something you loved doing before {c1}.","ko":"이번 주말에 {c1}세 이전에 좋아하던 일을 20분만 해 보세요."},{"en":"List three things you learned before {c1} that you're glad to still know.","ko":"{c1}세 이전에 배워서 지금도 알고 있어 다행인 것 세 가지를 적어 보세요."},{"en":"Revisit one song or dish from your early years and enjoy it slowly.","ko":"젊은 시절의 노래나 음식 하나를 다시 꺼내 천천히 즐겨 보세요."}],"card":"early"},"ST_ACT_early_now":{"tags":["stage:early"],"v":[{"en":"Pick one skill you'd like to have by {c1}, and spend twenty minutes on it this week.","ko":"{c1}세까지 갖추고 싶은 기술 하나를 골라 이번 주에 20분을 써 보세요."},{"en":"Ask one older person you respect what they wish they'd done before {c1}.","ko":"존경하는 연장자 한 분께 {c1}세 전에 해 두었으면 좋았을 일이 무엇인지 여쭤보세요."}],"card":"early"},"ST_ACT_middle_past":{"tags":["stage:middle"],"v":[{"en":"List two things your middle years taught you, and one you would like to pass on.","ko":"중년이 가르쳐 준 두 가지와 물려주고 싶은 한 가지를 적어 보세요."},{"en":"Look back on one decision from your middle years that still serves you, and name why it worked.","ko":"중년에 내린 결정 중 지금도 도움이 되는 것 하나를 떠올리고, 왜 잘 풀렸는지 적어 보세요."},{"en":"Write a thank-you note to someone who supported you during your middle years.","ko":"중년에 힘이 되어 준 사람에게 감사 편지를 한 장 써 보세요."},{"en":"Choose one photo or object from your middle years and tell a friend the story behind it.","ko":"중년 시절의 사진이나 물건 하나를 골라 친구에게 그 뒷이야기를 들려주세요."},{"en":"Pick one habit you built in your middle years and decide whether to keep it, tweak it, or retire it.","ko":"중년에 만든 습관 하나를 골라 계속할지, 고칠지, 내려놓을지 정해 보세요."}],"card":"middle"},"ST_ACT_middle_now":{"tags":["stage:middle"],"v":[{"en":"Choose one area, such as work, home, or daily habits, to invest in steadily this year.","ko":"일, 집, 생활 습관 가운데 한 영역을 골라 올해 꾸준히 공을 들여 보세요."},{"en":"Block one hour a month to review where you are and where you're heading.","ko":"한 달에 한 시간, 지금 어디에 있고 어디로 가는지 돌아보는 시간을 비워 두세요."},{"en":"Choose one relationship or project that matters to you and give it an unhurried hour this month.","ko":"나에게 중요한 관계나 일 하나를 골라 이번 달 서두르지 않는 한 시간을 내어 주세요."},{"en":"Pick one small thing you've been putting off and finish it before the month ends.","ko":"미뤄 둔 작은 일 하나를 골라 이번 달이 가기 전에 끝내 보세요."},{"en":"Ask someone you trust how your life looks from the outside, and listen without defending yourself.","ko":"믿는 사람에게 내 삶이 바깥에서 어떻게 보이는지 물어보고, 변명 없이 들어 보세요."},{"en":"Jot down three things that are working in your life right now, and keep the note where you'll see it.","ko":"지금 내 삶에서 잘 돌아가는 것 세 가지를 적어 눈에 띄는 곳에 붙여 두세요."}],"card":"middle"},"ST_ACT_middle_ahead":{"tags":["stage:middle"],"v":[{"en":"Start a small habit now that your middle-years self will thank you for, such as stretching a little or learning a little.","ko":"중년의 내가 고마워할 작은 습관을 지금 시작해 보세요. 조금씩 몸을 풀거나 조금씩 배우는 것처럼요."},{"en":"Picture yourself at {c1} and name one thing you hope you'll have built by then.","ko":"{c1}세의 나를 그려 보고, 그때까지 쌓아 두었기를 바라는 것 하나를 떠올려 보세요."},{"en":"Imagine your life at {c1} and decide on one small thing to start today that your future self would appreciate.","ko":"{c1}세의 내 모습을 상상하고, 미래의 내가 고마워할 작은 일 하나를 오늘 시작해 보세요."}],"card":"middle"},"ST_ACT_later_now":{"tags":["stage:later"],"v":[{"en":"Choose one thing you want to keep doing for the joy of it, and put it on your weekly calendar.","ko":"즐거워서 계속하고 싶은 일 하나를 골라 매주 달력에 넣어 두세요."},{"en":"Share one skill or story with someone younger this month.","ko":"이번 달, 더 젊은 누군가에게 재주나 이야기 하나를 나눠 주세요."},{"en":"Take a class, join a club, or try a workshop this season, just to see what feels fun.","ko":"이번 계절에 수업을 듣거나 모임에 들어가거나 체험 강좌를 해 보며 무엇이 즐거운지 살펴보세요."},{"en":"Call an old friend this month and set a date to meet.","ko":"이번 달, 오랜 친구에게 전화해서 만날 날짜를 잡아 보세요."},{"en":"Write down one lesson you've learned so far, and share it with someone you trust.","ko":"지금까지 배운 교훈 하나를 적어서, 믿는 사람과 나눠 보세요."}],"card":"later"},"ST_ACT_later_ahead":{"tags":["stage:later"],"v":[{"en":"Picture your life at {c2}: who is around you and what you do in a morning. Write three lines about it.","ko":"{c2}세의 삶을 그려 보세요. 곁에 누가 있고, 아침에 무엇을 하는지요. 세 줄로 적어 보세요."},{"en":"Start one friendship or hobby now that you would enjoy keeping for decades.","ko":"수십 년 이어 가고 싶은 우정이나 취미 하나를 지금 시작해 보세요."},{"en":"Think about your life at {c2} and jot down one place you'd like to be living.","ko":"{c2}세의 삶을 떠올리고, 그때 살고 싶은 곳 한 군데를 적어 보세요."},{"en":"Pick one skill you'd enjoy still practicing at {c2} and book a first lesson this month.","ko":"{c2}세에도 즐겁게 하고 싶은 기술 하나를 골라 이번 달에 첫 수업을 예약해 보세요."},{"en":"Ask someone who's already past {c2} what they're glad they started earlier, and note their answer.","ko":"{c2}세를 이미 지난 분께 일찍 시작해서 다행이었던 일이 뭔지 묻고, 대답을 적어 두세요."},{"en":"Set a yearly reminder to review your plans for {c2}, and keep it small enough to actually do.","ko":"{c2}세를 위한 계획을 돌아보는 알림을 매년 하나 맞춰 두세요. 실제로 할 수 있게 작게요."},{"en":"Choose a weekly outing you'd like to still enjoy at {c2}, and put the first one on the calendar.","ko":"{c2}세에도 즐기고 싶은 주간 나들이 하나를 정하고, 첫 번째 날짜를 달력에 적어 두세요."},{"en":"Write a short letter to yourself at {c2}, and say what you hope you kept doing.","ko":"{c2}세의 나에게 짧은 편지를 써 보세요. 그때까지 계속 해 왔기를 바라는 일을 적어 주세요."}],"card":"later"},"LV_FEEL_bigyeop":{"tags":["dbcat:bigyeop"],"v":[{"en":"In love, you may want a partner who feels like an equal and a friend first.","ko":"사랑에서 당신은 대등하고, 무엇보다 친구 같은 상대를 원할 수 있어요."},{"en":"You may feel most at ease with someone who lets you keep your own space and pace.","ko":"내 공간과 속도를 지켜 주는 사람 곁에서 가장 편안할 수 있어요."},{"en":"Love may feel best when your partner is also your friend and treats you as an equal.","ko":"연인이 친구이기도 하고 나를 대등하게 대해 줄 때 사랑이 가장 편안하게 느껴질 수 있어요."}],"card":"love"},"LV_FEEL_siksang":{"tags":["dbcat:siksang"],"v":[{"en":"In love, you may show care by doing, making, and playing more than by planning.","ko":"사랑에서 당신은 계획보다 해 주고, 만들어 주고, 함께 노는 것으로 마음을 보여 줄 수 있어요."},{"en":"You may feel closest to someone when you can laugh and talk freely.","ko":"마음껏 웃고 이야기할 수 있을 때 상대와 가장 가깝게 느낄 수 있어요."},{"en":"In love, you may express affection through playful, hands-on gestures more than careful planning.","ko":"사랑에서 당신은 치밀한 계획보다 장난기 어린 손길과 직접 해 주는 몸짓으로 애정을 표현할 수 있어요."}],"card":"love"},"LV_FEEL_jaeseong":{"tags":["dbcat:jaeseong"],"v":[{"en":"In love, you often show care in practical ways and appreciate someone who does the same.","ko":"사랑에서 당신은 실질적인 방식으로 마음을 보여 주는 편이고, 똑같이 챙겨 주는 사람을 고맙게 여겨요."},{"en":"You may feel secure when a relationship has a clear, workable rhythm.","ko":"관계에 분명하고 굴러가는 리듬이 있을 때 안심할 수 있어요."},{"en":"Showing love through useful, concrete acts tends to come naturally, and you may value a partner who does likewise.","ko":"쓸모 있고 구체적인 행동으로 사랑을 보여 주는 게 자연스러운 편이고, 똑같이 해 주는 상대를 소중히 여길 수 있어요."}],"card":"love"},"LV_FEEL_gwanseong":{"tags":["dbcat:gwanseong"],"v":[{"en":"In love, you may take commitment seriously and hope for the same in return.","ko":"사랑에서 당신은 약속을 무겁게 여기고, 상대에게도 같은 마음을 바랄 수 있어요."},{"en":"You may feel closest to someone you can respect as well as enjoy.","ko":"함께 즐거울 뿐 아니라 존경할 수 있는 사람과 가장 가깝게 느낄 수 있어요."},{"en":"In romance, you may value a partner who follows through on what they say.","ko":"연애에서는 말한 대로 행동으로 옮기는 사람을 소중히 여길 수 있어요."}],"card":"love"},"LV_FEEL_inseong":{"tags":["dbcat:inseong"],"v":[{"en":"In love, you may look for someone who makes you feel understood and looked after.","ko":"사랑에서 당신은 이해받고 돌봄받는 느낌을 주는 사람을 찾을 수 있어요."},{"en":"You may feel most at home with someone calm and thoughtful.","ko":"차분하고 사려 깊은 사람 곁에서 가장 편안할 수 있어요."},{"en":"A partner who understands you and looks after you may be what you want most in love.","ko":"나를 이해해 주고 보살펴 주는 짝이 사랑에서 가장 바라는 모습일 수 있어요."}],"card":"love"},"LV_MEAN_bigyeop":{"tags":["dbcat:bigyeop"],"v":[{"en":"The animal of the day you were born, {db}, is traditionally read as the place of close partnership, the same way for everyone. Yours carries the theme of {dbGod}: partnership as a friendship between equals.","ko":"태어난 날의 동물 {db}은(는) 전통적으로 가까운 동반자의 자리로 읽어요. 누구에게나 같은 방식이에요. 당신의 경우 {dbGod}을(를) 가져와서, 대등한 친구 같은 동반자 관계를 가리켜요."}],"card":"love"},"LV_MEAN_siksang":{"tags":["dbcat:siksang"],"v":[{"en":"The animal of the day you were born, {db}, marks the spot for close partnership in your chart (read the same way for everyone). It's linked with {dbGod}, pointing to affection shown through warmth, humor, and shared fun.","ko":"태어난 날의 동물 {db}은(는) 사주에서 가까운 동반자 자리를 나타내요(누구에게나 같은 방식으로 읽어요). 여기에는 {dbGod}이(가) 이어져 있어서, 따뜻함과 유머, 함께 노는 즐거움으로 드러나는 애정을 가리켜요."}],"card":"love"},"LV_MEAN_jaeseong":{"tags":["dbcat:jaeseong"],"v":[{"en":"The animal of the day you were born, {db}, sits in the spot tradition reads for close partnership (read the same way for everyone). Here it carries the theme of {dbGod}: care shown through reliability and practical help.","ko":"태어난 날의 동물 {db}은(는) 전통적으로 가까운 동반자를 읽는 자리에 있어요(누구에게나 같은 방식으로 읽어요). 여기서는 {dbGod}을(를) 뜻하고, 믿음직함과 실질적인 도움으로 드러나는 돌봄을 가리켜요."}],"card":"love"},"LV_MEAN_gwanseong":{"tags":["dbcat:gwanseong"],"v":[{"en":"The animal of the day you were born, {db}, marks the spot for close partnership, read the same way for everyone. Yours carries a theme of {dbGod}: loyalty, clear commitments, and mutual respect.","ko":"태어난 날의 동물 {db}은(는) 가까운 동반자를 보는 자리로, 누구에게나 같은 방식으로 읽어요. 당신의 경우 {dbGod}(이)라는 주제를 품고 있어서, 의리와 분명한 약속, 서로에 대한 존중을 가리켜요."}],"card":"love"},"LV_MEAN_inseong":{"tags":["dbcat:inseong"],"v":[{"en":"The animal of the day you were born, {db}, sits in the spot every chart uses for close partnership, and it carries the theme of {dbGod}: emotional safety and feeling understood.","ko":"태어난 날의 동물 {db}은(는) 모든 사주가 가까운 동반자를 보는 자리에 있고, {dbGod}의 주제를 담고 있어요. 마음의 안전과 이해받는 느낌을 가리켜요."}],"card":"love"},"LV_STAGE_rising":{"tags":["dbstage:rising"],"v":[{"en":"In the traditional life-cycle reading this animal sits in an outward phase, so your close relationships may be lively and visible.","ko":"전통적인 삶의 주기 풀이에서 이 동물은 밖으로 뻗어 나가는 구간에 있어서, 가까운 관계가 활기차고 겉으로도 잘 드러날 수 있어요."}],"card":"love"},"LV_STAGE_forming":{"tags":["dbstage:forming"],"v":[{"en":"In the traditional life-cycle reading this animal sits in a forming phase, so your bonds may deepen slowly and keep renewing.","ko":"전통적인 삶의 순환 풀이에서 이 동물은 새로 자라나는 구간에 있어서, 인연이 천천히 깊어지고 계속 새로워질 수 있어요."}],"card":"love"},"LV_STAGE_settling":{"tags":["dbstage:settling"],"v":[{"en":"In the traditional life-cycle reading this animal sits in a settling phase, so you may prefer quiet, steady closeness over constant excitement.","ko":"전통적인 생애 흐름으로 보면 이 동물은 자리를 잡아 가는 구간에 있어요. 그래서 늘 설레는 관계보다 조용하고 꾸준한 가까움을 더 좋아할 수 있어요."}],"card":"love"},"LV_REL_hap":{"tags":["lvrel:hap"],"v":[{"en":"The animal of the day you were born pairs up with the animal of your birth {relP} ({relPair}), a traditional sign that close ties come together readily.","ko":"태어난 날의 동물이 {relPKo}의 동물과 짝을 이뤄요({relPair}). 전통적으로 가까운 인연이 쉽게 모인다는 표시예요."}],"card":"love"},"LV_REL_hap_hour":{"tags":["lvrel:hap","pillar:hour"],"v":[{"en":"The animal of the day you were born pairs well with the animal of the hour you were born ({relPair}), a traditional sign that close ties come together readily.","ko":"태어난 날의 동물이 태어난 시간의 동물과 잘 어울려요({relPair}). 전통적으로 가까운 인연이 쉽게 모인다는 표시예요."}],"card":"love"},"LV_REL_chung":{"tags":["lvrel:chung"],"v":[{"en":"The animal of the day you were born clashes with the animal of your birth {relP} ({relPair}), which can show up as needing some space and movement inside closeness; a little distance can be natural, not a warning sign.","ko":"태어난 날의 동물이 {relPKo}의 동물과 부딪쳐요({relPair}). 가까운 관계 안에서도 약간의 공간과 움직임이 필요한 모습으로 나타날 수 있어요. 조금의 거리는 경고 신호가 아니라 자연스러운 거예요."}],"card":"love"},"LV_REL_chung_hour":{"tags":["lvrel:chung","pillar:hour"],"v":[{"en":"The animal of the day you were born clashes with the animal of your birth hour ({relPair}), which can show up as needing some space and movement inside closeness; a little distance can be natural, not a warning sign.","ko":"태어난 날의 동물이 태어난 시각의 동물과 부딪쳐요({relPair}). 가까운 관계 안에서도 약간의 공간과 움직임이 필요한 모습으로 나타날 수 있어요. 조금의 거리는 경고가 아니라 자연스러운 것이에요."}],"card":"love"},"LV_EXPR_none":{"tags":["expr:none"],"v":[{"en":"Your chart has no signs of self-expression at all, even counting the ones tucked beneath the surface, so feelings may stay inside longer than you intend.","ko":"숨어 있는 층까지 살펴봐도 사주에 자기 표현의 표시가 하나도 없어서, 마음이 생각보다 오래 안에 머물 수 있어요."}],"card":"love"},"LV_EXPR_some":{"tags":["expr:some"],"v":[{"en":"Your chart has a moderate amount of expression, hidden layers included, so you share feelings readily once you feel safe.","ko":"사주에 표현의 기운이 숨은 층까지 합쳐 적당히 있어서, 안전하다고 느끼면 마음을 잘 나눌 수 있어요."},{"en":"Expression shows up in a medium amount in your chart, so opening up can come naturally once you trust someone.","ko":"사주에 표현의 기운이 중간쯤 있어서, 누군가를 믿게 되면 마음을 여는 일이 자연스럽게 찾아와요."},{"en":"Counting the quieter layers too, your chart shows a middle amount of expression, which can make it easy to talk about feelings when you feel secure.","ko":"조용히 숨은 층까지 세어 보면 표현의 기운이 중간 정도로 보여요. 마음이 놓일 때는 감정을 말하기가 편할 수 있어요."},{"en":"With expression present in a balanced amount, you can share what's on your mind once the setting feels safe.","ko":"표현의 기운이 알맞은 양으로 있어서, 분위기가 안전하게 느껴지면 속마음을 나눌 수 있어요."},{"en":"Your chart carries a fair share of expression, so you may find the words for your feelings when you're with someone you trust.","ko":"사주에 표현의 기운이 적당한 몫으로 있어요. 믿는 사람과 함께 있을 때 감정을 담을 말을 찾을 수 있어요."},{"en":"Expression sits at a moderate level in your chart, so you're neither guarded nor overflowing, and a partner's warmth helps you open up.","ko":"표현의 기운이 사주에 알맞은 수준으로 있어서, 꽁꽁 닫히지도 넘치지도 않아요. 상대의 따뜻함이 마음을 여는 데 힘이 돼요."},{"en":"There's enough expression in your chart to let feelings flow, especially once you know you won't be judged.","ko":"사주에 감정을 흘려보낼 만큼의 표현 기운이 있어요. 평가받지 않는다는 걸 알게 되면 특히 더 그래요."},{"en":"Hidden layers counted, expression sits at a comfortable middle level for you, which can make sharing feelings easy in safe company.","ko":"숨은 층까지 세면 표현의 기운이 편안한 중간쯤에 놓여 있어요. 편한 사람들 곁에서는 감정 나누기가 수월할 수 있어요."},{"en":"Since your chart holds a comfortable middle amount of expression, you can speak openly about what you feel once trust is in place.","ko":"사주에 표현의 기운이 편안한 중간 정도로 담겨 있어서, 믿음이 생기면 느끼는 것을 터놓고 말할 수 있어요."}],"card":"love"},"LV_EXPR_many":{"tags":["expr:many"],"v":[{"en":"Your chart has plenty of self-expression in it, even in its quieter layers, so feelings may come out quickly, warm words and sharp words alike.","ko":"사주에 자기표현의 기운이 넉넉해요. 조용한 층에도요. 그래서 마음이 빨리 밖으로 나올 수 있어요. 따뜻한 말도, 날 선 말도요."},{"en":"Self-expression runs strong in your chart, so your feelings may rush out fast, in tender words and sharp ones alike.","ko":"사주에 자기표현의 기운이 강하게 흘러서, 감정이 빠르게 쏟아질 수 있어요. 다정한 말로도, 날카로운 말로도요."},{"en":"Your chart leans heavily toward speaking up, so you may say what you feel quickly, whether it comes out kind or blunt.","ko":"사주가 말로 드러내는 쪽으로 많이 기울어 있어서, 느낀 것을 재빨리 말하게 될 수 있어요. 상냥하게 나오든 직설적으로 나오든요."},{"en":"Counting its hidden layers too, your chart is rich in self-expression, which can make your emotions spill into words fast, gentle or edgy.","ko":"숨은 층까지 세면 자기표현이 가득한 사주라서, 감정이 말이 되어 빨리 흘러나올 수 있어요. 부드럽게든 거칠게든요."}],"card":"love"},"LV_CONN_none":{"tags":["conn:none"],"v":[{"en":"Your chart holds few of the characters we link to attraction and commitment, which can mean relationships grow out of friendship or timing rather than a rush.","ko":"사주에 끌림과 약속에 연결해 보는 글자가 적어서, 관계가 급하게보다 우정이나 때를 따라 자랄 수 있어요."}],"card":"love"},"LV_CONN_some":{"tags":["conn:some"],"v":[{"en":"Your chart holds a moderate number of the characters we link to attraction and commitment: steady interest rather than drama.","ko":"사주에 끌림과 약속에 연결해 보는 글자가 적당히 있어요. 요란함보다 꾸준한 관심이에요."}],"card":"love"},"LV_CONN_many":{"tags":["conn:many"],"v":[{"en":"Your chart holds many of the characters we link to attraction and commitment, so relationships may be a big part of your story; choosing depth over number helps.","ko":"사주에 끌림과 약속에 연결해 보는 글자가 많아서, 관계가 인생 이야기의 큰 부분을 차지할 수 있어요. 여럿보다 깊이를 고르는 게 도움이 돼요."}],"card":"love"},"LV_ACT_none":{"tags":["expr:none"],"v":[{"en":"This week, tell someone close one feeling in plain words, even just \"I liked today with you.\"","ko":"이번 주, 가까운 사람에게 마음 하나를 쉬운 말로 전해 보세요. \"오늘 너랑 있어서 좋았어\" 한마디라도요."},{"en":"Jot a short message you'd normally only think; you can decide later whether to send it, and to whom.","ko":"평소 생각만 하던 짧은 말을 적어 보세요. 보낼지, 누구에게 보낼지는 나중에 정해도 돼요."}],"card":"love"},"LV_ACT_some":{"tags":["expr:some"],"v":[{"en":"This week, ask someone close one question about their day and listen to the whole answer.","ko":"이번 주, 가까운 사람에게 하루에 대해 한 가지를 묻고 대답을 끝까지 들어 보세요."},{"en":"Plan one small shared moment this week, such as a walk, a meal, or a call, with no agenda.","ko":"이번 주, 목적 없이 함께하는 작은 시간 하나를 계획해 보세요. 산책, 식사, 통화 같은 것이요."},{"en":"Send a short message this week to someone close, just to say you were thinking of them.","ko":"이번 주, 가까운 사람에게 짧은 메시지를 보내 당신을 떠올렸다고 전해 보세요."},{"en":"Put your phone away during one meal with someone you care about this week.","ko":"이번 주, 아끼는 사람과 함께하는 식사 한 번만큼은 휴대폰을 치워 두세요."},{"en":"This week, tell someone close one thing you appreciated about them recently.","ko":"이번 주, 가까운 사람에게 요즘 고마웠던 점 한 가지를 말해 보세요."},{"en":"Share a small, ordinary story from your day with someone close, and ask for theirs.","ko":"오늘 있었던 사소한 이야기를 가까운 사람에게 들려주고, 그 사람의 이야기도 물어보세요."},{"en":"Offer to do one small chore for someone close this week, without being asked.","ko":"이번 주, 부탁받지 않아도 가까운 사람의 작은 집안일 하나를 먼저 도와주겠다고 해 보세요."},{"en":"Pick a song, photo, or place that reminds you of someone close and share it with them.","ko":"가까운 사람이 떠오르는 노래나 사진, 장소 하나를 골라 그 사람에게 보여 주세요."},{"en":"Invite someone close to try something new with you this week, even something as small as a new coffee spot.","ko":"이번 주, 가까운 사람에게 새로운 것을 함께 해 보자고 청해 보세요. 새 커피집 같은 작은 일이어도 좋아요."}],"card":"love"},"LV_ACT_many":{"tags":["expr:many"],"v":[{"en":"This week, when a strong reaction rises, wait one breath and start with \"I feel\" instead of \"You always.\"","ko":"이번 주, 강한 반응이 올라오면 한 번 숨을 고르고 \"너는 늘\"이 아니라 \"나는 ~하게 느껴\"로 시작해 보세요."},{"en":"Before a hard talk this week, write down the one thing you most want the other person to hear.","ko":"이번 주 어려운 대화 전에, 상대가 꼭 들어 줬으면 하는 한 가지를 먼저 적어 보세요."},{"en":"This week, when you feel a sharp reply coming, take a sip of water first and then say what you need in one calm sentence.","ko":"이번 주, 날 선 대답이 올라오면 먼저 물을 한 모금 마시고, 필요한 말을 차분한 한 문장으로 해 보세요."},{"en":"Before reacting to something that stings this week, pause and ask the other person what they meant.","ko":"이번 주, 마음에 걸리는 말을 들으면 바로 반응하기 전에 멈추고 상대에게 무슨 뜻이었는지 물어보세요."}],"card":"love"},"WK_FEEL_bigyeop":{"tags":["monthcat:bigyeop"],"v":[{"en":"At work, you may feel most yourself when no one is hovering.","ko":"일할 때 누가 옆에서 지켜보지 않을 때 가장 나다울 수 있어요."},{"en":"You may prefer to own a task from start to finish.","ko":"일을 처음부터 끝까지 내가 맡는 쪽을 더 좋아할 수 있어요."}],"card":"work_money"},"WK_FEEL_siksang":{"tags":["monthcat:siksang"],"v":[{"en":"At work, you may feel most alive when you can create or explain something.","ko":"일할 때 무언가를 만들거나 설명할 수 있을 때 가장 살아 있다고 느낄 수 있어요."},{"en":"You may get restless in roles that don't let you use your ideas.","ko":"아이디어를 쓸 수 없는 자리에서는 좀이 쑤실 수 있어요."},{"en":"You may light up in work that lets you invent, teach, or show people something.","ko":"발명하고, 가르치고, 무언가를 보여 주는 일에서 생기가 돌 수 있어요."}],"card":"work_money"},"WK_FEEL_jaeseong":{"tags":["monthcat:jaeseong"],"v":[{"en":"At work, you may feel good when results are clear and countable.","ko":"일할 때 결과가 분명하고 셀 수 있을 때 기분이 좋을 수 있어요."},{"en":"You may enjoy juggling practical tasks and seeing things move.","ko":"현실적인 일 여러 개를 굴리며 일이 진척되는 걸 보는 게 즐거울 수 있어요."},{"en":"Seeing concrete progress on practical tasks may give you a lift at work.","ko":"현실적인 일에서 눈에 보이는 진전을 확인하면 일하는 중에 힘이 날 수 있어요."}],"card":"work_money"},"WK_FEEL_gwanseong":{"tags":["monthcat:gwanseong"],"v":[{"en":"At work, you may feel steadier with a clear role and clear expectations.","ko":"일할 때 역할과 기대가 분명하면 더 안정감을 느낄 수 있어요."},{"en":"You may be the one people trust with responsibility, sometimes more than you want.","ko":"사람들이 책임을 맡기는 쪽이 당신일 수 있어요. 가끔은 원하는 것보다 더 많이요."},{"en":"Clear expectations at work may help you settle in and do your best.","ko":"일터에서 기대가 분명하면 자리 잡고 실력을 내기 한결 쉬울 수 있어요."}],"card":"work_money"},"WK_FEEL_inseong":{"tags":["monthcat:inseong"],"v":[{"en":"At work, you may feel best when you're learning or helping others understand.","ko":"일할 때 배우거나 남이 이해하도록 도울 때 가장 좋을 수 있어요."},{"en":"You may prefer thinking a problem through before acting.","ko":"움직이기 전에 문제를 끝까지 생각해 보는 쪽을 좋아할 수 있어요."},{"en":"You may enjoy work most when you get to learn, or to help others grasp an idea.","ko":"배우거나 다른 사람이 어떤 생각을 이해하도록 도울 때 일이 가장 즐거울 수 있어요."}],"card":"work_money"},"WK_MEAN_bigyeop":{"tags":["monthcat:bigyeop"],"v":[{"en":"Your birth-month animal, traditionally read for career and social life, points to {monthGod}: you may do well with autonomy, partnerships of equals, or a venture of your own.","ko":"전통적으로 일과 사회생활을 읽는 태어난 달의 동물이 {monthGod}을(를) 가리켜요. 스스로 정하는 자유, 대등한 동업, 혹은 나만의 일에서 잘할 수 있어요."}],"card":"work_money"},"WK_MEAN_siksang":{"tags":["monthcat:siksang"],"v":[{"en":"Your birth-month animal, traditionally read for career and social life, carries a theme of {monthGod}: you may do well in roles that create, teach, perform, or improve things.","ko":"전통적으로 일과 사회생활을 읽는 태어난 달의 동물에 {monthGod}의 주제가 담겨 있어요. 만들고, 가르치고, 보여 주고, 개선하는 역할에서 잘할 수 있어요."},{"en":"A theme of {monthGod} shows in the animal of your birth month, the spot traditionally read for career and social life, so creative, teaching, performing, or improving roles may suit you.","ko":"전통적으로 일과 사회생활을 보는 자리인 태어난 달의 동물에 {monthGod}의 주제가 드러나요. 그래서 창작, 가르침, 무대, 다듬는 일 같은 역할이 어울릴 수 있어요."},{"en":"With {monthGod} marked in the animal of your birth month, the traditional place to look for work and public life, you could shine where you make, explain, present, or refine things.","ko":"일과 사회생활을 살피는 전통적인 자리인 태어난 달의 동물에 {monthGod}의 표시가 있어서, 만들고 설명하고 보여 주고 다듬는 자리에서 빛날 수 있어요."}],"card":"work_money"},"WK_MEAN_jaeseong":{"tags":["monthcat:jaeseong"],"v":[{"en":"Your birth-month animal, traditionally read for career and social life, points to {monthGod}: you may do well in roles with tangible results, such as sales, operations, or managing budgets and resources.","ko":"전통적으로 직업과 사회생활을 읽는 태어난 달의 동물은 {monthGod}을(를) 가리켜요. 영업, 운영, 예산과 자원 관리처럼 눈에 보이는 결과가 있는 역할에서 잘할 수 있어요."},{"en":"Tradition reads your birth-month animal for career and social life, and yours carries the theme of {monthGod}, so roles with visible results, like sales, operations, or running budgets, may suit you well.","ko":"전통에서는 태어난 달의 동물로 직업과 사회생활을 읽는데, 당신의 것에는 {monthGod}의 주제가 담겨 있어요. 그래서 영업이나 운영, 예산 꾸리기처럼 결과가 눈에 보이는 역할이 잘 맞을 수 있어요."},{"en":"The animal of your birth month speaks for work and social life, and yours leans toward {monthGod}: work with hands-on outcomes, such as sales, operations, or looking after resources, may be where you do well.","ko":"태어난 달의 동물은 일과 사회생활을 말해 주는데, 당신의 것은 {monthGod} 쪽으로 기울어요. 영업, 운영, 자원 돌보기처럼 손에 잡히는 결과가 있는 일에서 힘을 낼 수 있어요."}],"card":"work_money"},"WK_MEAN_gwanseong":{"tags":["monthcat:gwanseong"],"v":[{"en":"Your birth-month animal, the traditional place to read career and social life, carries the theme of {monthGod}: you may do well in structured roles, such as organizations, public service, or leadership tracks.","ko":"전통적으로 직업과 사회생활을 읽는 자리인 태어난 달의 동물이 {monthGod}(이)라는 주제를 품고 있어요. 조직, 공공 일, 리더 과정처럼 틀이 있는 역할에서 잘할 수 있어요."},{"en":"Tradition reads career and social life from your birth-month animal, and yours carries the theme of {monthGod}, so organized settings such as institutions, public service, or management tracks may suit you.","ko":"전통에서는 태어난 달의 동물로 직업과 사회생활을 읽는데, 당신의 경우 {monthGod}을(를) 가져와요. 그래서 기관, 공공 일, 관리자 경로처럼 체계가 있는 환경이 어울릴 수 있어요."},{"en":"With {monthGod} in your birth-month animal, the traditional seat of work and public life, you could do well where roles are clearly defined, like large organizations or leadership paths.","ko":"일과 사회생활의 전통적인 자리인 태어난 달의 동물에 {monthGod}이(가) 있어서, 큰 조직이나 리더 경로처럼 역할이 분명한 곳에서 잘해 낼 수 있어요."}],"card":"work_money"},"WK_MEAN_inseong":{"tags":["monthcat:inseong"],"v":[{"en":"The animal of your birth month, which tradition reads for career and social life, is linked with {monthGod}: you may do well in roles built on knowledge, such as research, education, advising, or care work.","ko":"전통적으로 일과 사회생활을 읽는 태어난 달의 동물은 {monthGod}와(과) 이어져 있어요. 연구, 교육, 상담, 돌봄처럼 지식에 바탕을 둔 역할에서 잘할 수 있어요."},{"en":"Tradition reads your birth-month animal for career and social life, and yours carries a theme of {monthGod}; roles built on knowledge, like research, teaching, advising, or caregiving, may suit you well.","ko":"전통은 태어난 달의 동물로 일과 사회생활을 읽는데, 당신의 동물에는 {monthGod}의 주제가 담겨 있어요. 연구, 가르침, 상담, 돌봄처럼 지식에 바탕을 둔 역할이 잘 맞을 수 있어요."},{"en":"Your birth-month animal points to {monthGod}, and since tradition reads it for work and social standing, you could shine in knowledge-based roles such as research, education, counseling, or care.","ko":"태어난 달의 동물이 {monthGod}을(를) 가리켜요. 전통적으로 일과 사회적 자리를 읽는 곳이라서, 연구, 교육, 상담, 돌봄 같은 지식 중심 역할에서 빛날 수 있어요."}],"card":"work_money"},"MN_W_none":{"tags":["wealth:none"],"v":[{"en":"Your chart shows no money signs, even counting hidden elements. That can mean results come through skill and role rather than chasing them, so build the channel first.","ko":"숨은 기운까지 봐도 사주에 재물 표시가 없어요. 결과를 쫓아가기보다 실력과 역할을 통해 들어오는 편일 수 있으니, 먼저 통로를 만들어 두세요."}],"card":"work_money"},"MN_W_jeong":{"tags":["wealth:some"],"v":[{"en":"The money side of your chart, hidden elements included, leans toward the steady-earner style: regular income, steady routines, and careful planning tend to suit you.","ko":"숨은 기운까지 포함해 사주의 돈 쪽 기운은 꾸준히 버는 스타일로 기울어 있어요. 규칙적인 수입, 꾸준한 생활 습관, 꼼꼼한 계획이 잘 맞는 편이에요."},{"en":"Counting hidden elements too, your chart's money signs point to the steady-paycheck type, so reliable pay, dependable habits, and thoughtful budgeting may fit you well.","ko":"숨은 기운까지 세어 보면 사주의 돈 표시는 꼬박꼬박 받는 수입 쪽을 가리켜요. 믿을 만한 벌이, 안정된 습관, 신중한 예산 짜기가 잘 어울릴 수 있어요."},{"en":"Among the money signs in your chart (hidden ones counted), the steady-income kind stands out, which favors regular earnings, orderly routines, and careful planning.","ko":"사주의 돈 표시 가운데(숨은 것까지 포함) 꾸준한 수입 쪽이 두드러져요. 규칙적인 벌이, 질서 있는 생활, 차근차근한 계획과 잘 맞아요."},{"en":"A steady approach to money may suit you, hidden elements included: consistent earnings, tidy routines, and plans made with care.","ko":"숨은 기운까지 보면, 돈을 대할 때 꾸준한 방식이 잘 맞을 수 있어요. 한결같은 벌이, 정돈된 습관, 정성껏 세운 계획이 어울려요."},{"en":"Looking at your chart's money signs, hidden ones too, the lean is toward steady income, a style that rewards patience, regular habits, and careful planning.","ko":"숨은 것까지 사주의 돈 표시를 살펴보면 꾸준한 수입 쪽으로 기울어요. 인내와 규칙적인 습관, 꼼꼼한 계획이 보답받는 스타일이에요."},{"en":"With your chart's money signs tilting toward steady income (hidden elements included), a paycheck-style rhythm and careful planning may feel natural.","ko":"사주의 돈 표시가 꾸준한 수입 쪽으로 기울어 있어서(숨은 기운 포함), 월급처럼 규칙적인 리듬과 꼼꼼한 계획이 자연스럽게 느껴질 수 있어요."}],"card":"work_money"},"MN_W_pyeon":{"tags":["wealth:some"],"v":[{"en":"Your money signs (hidden ones included) lean toward the opportunity-chasing side: varied income, deals, and new openings can suit you, along with steady routines to hold on to gains.","ko":"돈과 관련된 표시(숨은 것 포함)가 기회를 쫓는 쪽으로 기울어 있어요. 다양한 수입, 거래, 새로운 기회가 잘 맞을 수 있고, 얻은 것을 지키는 꾸준한 습관이 함께 있으면 좋아요."},{"en":"Chasing opportunities is the direction your money signs, hidden ones included, point toward. Mixed income, deals, and fresh openings may fit, with steady routines to hold on to what you gain.","ko":"숨은 것까지 포함해 돈의 표시가 가리키는 방향은 기회 쫓기예요. 여러 갈래의 수입과 거래, 새로 열리는 문이 맞을 수 있고, 얻은 것을 붙들어 주는 꾸준한 습관이 함께하면 좋아요."},{"en":"With the hidden layer counted, the money signs in your chart tilt toward the go-getter side, which can favor several sources of income, negotiating, and opportunities, plus regular habits that protect your gains.","ko":"숨은 층까지 세면 사주의 돈 표시가 적극적으로 뛰어드는 쪽으로 쏠려 있어요. 수입원을 여러 개 두고, 협상하고, 기회를 잡는 데 유리할 수 있고, 성과를 지켜 주는 규칙적인 습관이 더해지면 좋아요."},{"en":"A go-getter streak shows in your money signs (hidden ones included), so variety in earnings, trades, and openings may suit you, and a steady routine can keep the gains from slipping away.","ko":"돈의 표시(숨은 것 포함)에 적극적인 기질이 보여서, 다양한 벌이와 거래, 열린 기회가 어울릴 수 있어요. 꾸준한 습관은 얻은 것이 빠져나가지 않게 도와줘요."},{"en":"Among your money signs, hidden ones included, the opportunity-seeking kind stands out. That can mean you fit with varied income, dealmaking, and chances that come along, supported by consistent routines.","ko":"숨은 것까지 포함한 돈의 표시 가운데 기회를 찾아 나서는 쪽이 두드러져요. 다채로운 수입, 거래 성사, 찾아오는 기회와 잘 맞을 수 있고, 한결같은 습관이 받쳐 주면 좋아요."},{"en":"Opportunities, deals, and varied ways of earning may suit you, since your money signs (hidden ones counted) lean toward the go-getter side. Steady routines can help you keep what you earn.","ko":"기회, 거래, 다양한 돈벌이 방식이 어울릴 수 있어요. 돈의 표시(숨은 것 포함)가 적극적인 쪽으로 기울어 있거든요. 꾸준한 습관이 번 것을 지키는 데 도움이 돼요."}],"card":"work_money"},"MN_W_mixed":{"tags":["wealth:some"],"v":[{"en":"Your money signs, hidden ones included, are split between the steady-paycheck kind and the go-getter kind, so a stable base plus one side stream may suit you.","ko":"숨은 것까지 포함한 돈의 표시가 꾸준한 월급 쪽과 적극적으로 뛰어드는 쪽으로 나뉘어 있어요. 안정적인 바탕에 곁가지 수입 하나가 잘 맞을 수 있어요."}],"card":"work_money"},"MN_W_many":{"tags":["wealth:many"],"v":[{"en":"With plenty of money signs, practical matters take up real space in your life, and clear systems help.","ko":"사주에 돈 표시가 넉넉해서 현실적인 일이 삶에서 큰 자리를 차지해요. 분명한 체계가 도움이 돼요."},{"en":"Your chart is rich in money signs, so practical concerns loom large in your life, and well-defined systems keep them manageable.","ko":"사주에 돈 표시가 풍부해서 현실적인 걱정거리가 삶에서 크게 느껴질 수 있어요. 잘 짜인 체계가 그 부담을 다룰 만하게 해 줘요."},{"en":"A generous number of money signs means money and daily logistics may occupy a lot of your attention; clear structure helps.","ko":"돈 표시가 넉넉하면 돈과 생활 실무에 신경 쓸 일이 많아질 수 있어요. 분명한 짜임새가 도움이 돼요."}],"card":"work_money"},"MN_O_none":{"tags":["officer:none"],"v":[{"en":"Your chart shows no signs of outside rules and structure, even in its hidden layers, so you may do better setting your own rules than following someone else's.","ko":"숨은 층까지 봐도 사주에 바깥 규칙과 틀의 표시가 없어서, 남의 규칙을 따르기보다 내 규칙을 세울 때 더 잘할 수 있어요."}],"card":"work_money"},"MN_O_jeong":{"tags":["officer:some"],"v":[{"en":"Your chart leans toward order and proper roles: formal positions, clear ladders, and fair rules can suit you.","ko":"사주가 질서와 제 역할 쪽으로 기울어 있어요. 정식 자리, 분명한 승진 사다리, 공정한 규칙이 잘 맞을 수 있어요."},{"en":"Formal roles, a clear ladder up, and fair rules can suit you well, since your chart points toward steady responsibility.","ko":"정식 역할과 또렷한 승진 단계, 공정한 규칙이 잘 어울릴 수 있어요. 사주가 꾸준한 책임 쪽을 가리키거든요."},{"en":"The structure side of your chart tilts toward doing things properly, so structured positions, defined paths forward, and even-handed rules may fit.","ko":"사주에서 틀을 보는 부분이 일을 제대로 하는 쪽으로 기울어 있어서, 짜임새 있는 자리와 정해진 앞길, 치우침 없는 규칙이 맞을 수 있어요."},{"en":"Your chart's sense of structure leans toward playing by the book. Official titles, clear steps up, and rules applied fairly may feel like a good match.","ko":"사주의 틀 감각이 원칙대로 하는 쪽으로 쏠려 있어요. 공식 직함, 분명한 단계, 공평하게 적용되는 규칙이 잘 맞게 느껴질 수 있어요."},{"en":"With your chart tilting toward order and responsibility, you may do well where roles are formal, advancement is clear, and the rules are fair.","ko":"사주가 질서와 책임 쪽으로 기운 만큼, 역할이 분명하고 올라가는 길이 보이며 규칙이 공정한 곳에서 잘 해낼 수 있어요."},{"en":"A strong sense of proper order stands out in your chart, which suits settings with real roles, visible promotion paths, and fair play.","ko":"사주에서 바른 질서를 중시하는 마음이 두드러져요. 제대로 된 역할과 눈에 보이는 승진 경로, 공정한 운영이 있는 환경에 어울려요."},{"en":"A lean toward responsibility in your chart points to workplaces with clear titles, a defined route upward, and rules that treat everyone alike.","ko":"사주가 책임 쪽으로 기운 것은 직함이 분명하고 올라가는 길이 정해져 있으며 모두에게 같은 규칙이 적용되는 일터를 가리킬 수 있어요."}],"card":"work_money"},"MN_O_pyeon":{"tags":["officer:some"],"v":[{"en":"Your chart leans toward an intense, high-demand kind of structure: challenging, fast-moving roles tend to bring out your best.","ko":"당신의 사주는 강하고 요구가 큰 틀 쪽으로 기울어 있어요. 도전적이고 빠르게 돌아가는 자리에서 가장 좋은 모습이 나오는 편이에요."},{"en":"The structure in your chart leans toward the bold, demanding kind, so you may do your best work in challenging, fast-moving roles.","ko":"사주 속 틀이 대담하고 까다로운 쪽으로 기울어 있어서, 도전적이고 빠르게 움직이는 역할에서 가장 잘할 수 있어요."},{"en":"A strong, driven energy stands out in your chart, which can mean you shine where the pace is quick and the challenge is real.","ko":"사주에서 강하고 힘차게 밀고 나가는 기운이 눈에 띄어요. 속도가 빠르고 도전이 진짜인 곳에서 빛날 수 있다는 뜻이에요."},{"en":"With your chart tilting toward intense, testing energy, roles that stretch you and move quickly may bring out your strengths.","ko":"사주가 세고 시험하는 기운 쪽으로 기울어 있으니, 당신을 한 뼘 자라게 하고 빠르게 움직이는 역할이 강점을 끌어낼 수 있어요."},{"en":"Fast-moving, demanding roles may suit you, since your chart leans toward bold, high-intensity energy.","ko":"사주가 대담하고 세기가 큰 기운 쪽으로 기울어 있어서, 빠르게 움직이고 요구가 큰 역할이 잘 맞을 수 있어요."},{"en":"You may find your edge in tough situations, as your chart points toward a driven, challenge-ready energy.","ko":"사주가 힘차고 도전을 반기는 기운을 가리키니, 어려운 상황에서 당신만의 강점을 찾을 수 있어요."}],"card":"work_money"},"MN_O_mixed":{"tags":["officer:some"],"v":[{"en":"Your chart blends calm, orderly structure with a sharper, high-intensity drive, so you can handle both steady routines and sudden demands.","ko":"사주에 차분하고 질서 있는 짜임새와 더 날카롭고 강렬한 추진력이 섞여 있어서, 꾸준한 일상과 갑작스러운 요구를 모두 감당할 수 있어요."}],"card":"work_money"},"MN_CARRY":{"tags":["strength:weak","carry"],"v":[{"en":"Because your chart leans on support while holding many money and authority signs, the key isn't carrying it all alone: delegate, partner, or pace yourself.","ko":"사주가 곁의 도움에 기대는 쪽인데 재물과 책임의 표시가 많아서, 핵심은 혼자 다 지지 않는 거예요. 맡기고, 함께하고, 속도를 조절하세요."},{"en":"Your chart leans on support while holding a lot of money and authority signs, so you don't have to shoulder everything yourself: share the load, team up, and set a pace you can keep.","ko":"사주가 곁의 도움에 기대는 쪽이면서 재물과 책임의 표시를 많이 지니고 있어서, 모든 걸 혼자 짊어질 필요가 없어요. 짐을 나누고, 팀을 이루고, 오래 지킬 수 있는 속도를 정해 보세요."},{"en":"With many money and authority signs but a chart that does best with backup, the lesson is to hand off some tasks, bring in partners, and slow the tempo when needed.","ko":"재물과 책임의 표시는 많은데 사주는 뒷받침이 있을 때 힘을 내는 쪽이라서, 일부를 맡기고 함께할 사람을 들이고 필요하면 속도를 늦추는 게 좋아요."},{"en":"Plenty of money and authority signs plus a support-seeking chart suggests that sharing responsibility, whether by delegating, partnering, or pacing, works better than going solo.","ko":"재물과 책임의 표시가 넉넉한데 사주는 도움을 찾는 쪽이에요. 맡기든, 함께하든, 속도를 조절하든 책임을 나누는 편이 혼자 가는 것보다 잘 맞을 수 있어요."}],"card":"work_money"},"MN_OUTLET":{"tags":["strength:strong","wealth:none","officer:none"],"v":[{"en":"With plenty of energy backing you and no money or authority signs, your drive needs an outlet: a concrete goal, or a structure you choose for yourself.","ko":"뒤를 받쳐 주는 기운은 넉넉한데 재물과 틀의 표시가 없어서, 그 힘을 쏟을 곳이 필요해요. 구체적인 목표나 스스로 고른 틀이요."}],"card":"work_money"},"MN_S_none":{"tags":["expr:none"],"v":[{"en":"Expression symbols are scarce, so showing your work may take deliberate effort; let a portfolio or a record speak for you.","ko":"결과물을 내는 글자(식상)가 드물어서, 내 일을 보여 주는 데 일부러 힘을 써야 할 수 있어요. 작업 모음이나 기록이 대신 말하게 하세요."}],"card":"work_money"},"MN_S_many":{"tags":["expr:many"],"v":[{"en":"Expression symbols are plentiful: your ideas are a real asset at work, and finishing matters as much as starting.","ko":"결과물을 내는 글자(식상)가 넉넉해요. 아이디어가 일에서 큰 자산이고, 시작만큼 마무리가 중요해요."}],"card":"work_money"},"MN_ACT_none":{"tags":[],"v":[{"en":"This month, list one skill you'd like to be known for, and one small way to show it.","ko":"이번 달, 알려지고 싶은 기술 하나와 그것을 보여 줄 작은 방법 하나를 적어 보세요."},{"en":"This month, ask one person in your field what they value most in a colleague, and listen closely.","ko":"이번 달, 같은 분야 사람에게 동료에게서 가장 중요하게 보는 점이 무엇인지 묻고 잘 들어 보세요."}],"card":"work_money"},"MN_ACT_jeong":{"tags":[],"v":[{"en":"This month, pick one weekly task and map out its steps so it runs smoothly even on a busy day.","ko":"이번 달, 매주 하는 일 하나를 골라 바쁜 날에도 잘 굴러가도록 순서를 정리해 보세요."},{"en":"This month, keep one steady work routine for four weeks and notice what it frees up.","ko":"이번 달, 일의 루틴 하나를 4주 동안 지키고 무엇이 여유로워지는지 살펴보세요."},{"en":"Over the next few weeks, set up a simple monthly bill calendar and check it every Friday.","ko":"앞으로 몇 주 동안 간단한 월별 청구서 일정표를 만들고 매주 금요일에 확인해 보세요."},{"en":"Pick one recurring task at work and write a three-line checklist for it.","ko":"일에서 반복되는 작업 하나를 골라 세 줄짜리 체크리스트를 써 보세요."},{"en":"Try blocking the same 30 minutes each morning for your most important task, and see how it settles your day.","ko":"매일 아침 같은 30분을 가장 중요한 일에 비워 두고, 하루가 얼마나 안정되는지 살펴보세요."},{"en":"Spend one evening reviewing your weekly expenses and trimming one habit that doesn't serve you.","ko":"하루 저녁을 정해 한 주의 지출을 돌아보고, 도움이 안 되는 습관 하나를 줄여 보세요."}],"card":"work_money"},"MN_ACT_pyeon":{"tags":[],"v":[{"en":"This month, choose one opportunity to pursue and set the date you'll decide whether to continue.","ko":"이번 달, 쫓아갈 기회 하나를 고르고, 계속할지 정할 날짜를 정해 두세요."},{"en":"This month, say yes to one new contact or project and give it a clear time limit.","ko":"이번 달, 새로운 인연이나 일 하나에 응하되 분명한 기한을 정해 두세요."},{"en":"Write down your top three opportunities, then circle the one that deserves your next hour.","ko":"가장 끌리는 기회 세 가지를 적고, 다음 한 시간을 쓸 만한 하나에 동그라미를 치세요."},{"en":"Send one message to a contact you've been meaning to reach, and ask a single clear question.","ko":"연락하려고 마음먹었던 사람에게 메시지 하나를 보내고, 분명한 질문 한 가지를 물어보세요."},{"en":"Set aside a fixed block of weekly time for a side project, and review how it went after a month.","ko":"부업이나 사이드 프로젝트에 매주 정해진 시간을 떼어 두고, 한 달 뒤에 어땠는지 돌아보세요."},{"en":"Before you accept a new deal, wait one night and write down what you'd gain and what you'd give up.","ko":"새 거래를 받아들이기 전에 하룻밤 기다리고, 얻는 것과 내주는 것을 적어 보세요."}],"card":"work_money"},"MN_ACT_mixed":{"tags":[],"v":[{"en":"This month, split your week into steady work and one side project, and protect time for each.","ko":"이번 달, 한 주를 꾸준한 일과 곁가지 일 하나로 나누고 각각의 시간을 지켜 주세요."},{"en":"This month, decide how many hours your side project gets each week, and keep to it.","ko":"이번 달, 곁가지 일에 매주 몇 시간을 쓸지 정하고 지켜 보세요."}],"card":"work_money"},"WT_strong_FEEL":{"tags":["strength:strong"],"v":[{"en":"You may sometimes push ahead before others are ready.","ko":"다른 사람들이 준비되기 전에 먼저 밀고 나갈 때가 있을 수 있어요."},{"en":"You could charge ahead while others are still getting ready.","ko":"다른 사람들이 아직 준비하는 중인데 먼저 달려 나갈 수 있어요."},{"en":"At times you may move faster than the people around you can follow.","ko":"때로는 주변 사람들이 따라오기 힘들 만큼 빨리 움직일 수 있어요."}],"card":"caution"},"WT_strong_MEAN":{"tags":["strength:strong"],"v":[{"en":"A strong core element brings real drive; the one thing to watch is moving faster than the people around you.","ko":"나의 중심 기운이 강하면 분명한 추진력이 생겨요. 살필 점은 하나, 주변 사람들보다 너무 빨리 달리는 거예요."},{"en":"When your core element is well supported, you have steady drive; the thing to keep an eye on is getting too far ahead of the people beside you.","ko":"나의 중심 기운이 든든하게 받쳐지면 꾸준한 추진력이 있어요. 눈여겨볼 점은 곁에 있는 사람들보다 너무 멀리 앞서 나가는 거예요."},{"en":"A chart with a strong core has real momentum, and the one thing to check is whether others can keep your pace.","ko":"중심이 강한 사주에는 진짜 힘이 실려 있어요. 하나만 확인해 보세요. 다른 사람들이 내 속도를 따라올 수 있는지요."}],"card":"caution"},"WT_strong_COPE":{"tags":["strength:strong"],"v":[{"en":"Before a big decision, ask one person, \"What am I missing?\" and wait for the full answer.","ko":"큰 결정 전에 한 사람에게 \"내가 놓친 게 뭘까?\"라고 묻고, 대답을 끝까지 기다려 보세요."},{"en":"When a message stirs you up, wait ten minutes, then reply in two sentences.","ko":"마음이 들끓는 메시지는 10분 기다렸다가 두 문장으로 답해 보세요."},{"en":"In your next meeting, let someone else speak first and write down what they say before you respond.","ko":"다음 회의에서는 다른 사람이 먼저 말하게 하고, 그 말을 받아 적은 뒤에 대답하세요."}],"card":"caution"},"WT_weak_FEEL":{"tags":["strength:weak"],"v":[{"en":"You may say yes to more than you have energy for.","ko":"기운이 허락하는 것보다 더 많이 \"네\"라고 답할 수 있어요."},{"en":"You might take on more than your energy can comfortably hold.","ko":"기운이 편히 감당할 수 있는 것보다 더 많이 떠안을 수 있어요."},{"en":"It may be tempting to agree to things before checking how much energy you've got.","ko":"기운이 얼마나 남았는지 확인하기 전에 먼저 수락하고 싶어질 수 있어요."},{"en":"Saying \"sure\" may come faster than your energy allows.","ko":"기운이 따라 주는 속도보다 \"좋아요\"라는 대답이 먼저 나올 수 있어요."},{"en":"Your plate could fill up faster than your stamina does.","ko":"체력이 차오르는 것보다 할 일이 더 빨리 쌓일 수 있어요."},{"en":"You may find yourself agreeing to favors that leave you running on fumes.","ko":"부탁을 들어주다가 기운이 바닥나 있는 나를 발견할 수 있어요."}],"card":"caution"},"WT_weak_MEAN":{"tags":["strength:weak"],"v":[{"en":"Your chart tends to work best with help from others, so a very full calendar may leave you tired.","ko":"당신의 사주는 주변의 도움을 받을 때 가장 잘 돌아가는 편이라, 일정이 너무 빽빽하면 지칠 수 있어요."},{"en":"When a chart leans on outside support, energy can drain faster than it returns, so taking on too much may show up as fatigue before it shows up as a setback.","ko":"도움을 받아야 균형이 잡히는 신약한 사주는 기운이 돌아오는 속도보다 빠지는 속도가 빠를 수 있어요. 일을 너무 많이 떠안으면 좌절보다 피곤함이 먼저 올 수 있어요."},{"en":"Charts like yours spend energy more quickly than they restore it, which means overcommitting may feel like tiredness first, not failure.","ko":"당신 같은 사주는 기운을 되찾는 것보다 쓰는 속도가 빨라서, 약속을 과하게 하면 실패가 아니라 피로로 먼저 느껴질 수 있어요."},{"en":"Since your chart relies on support, its energy can run down faster than it refills; packing the schedule may lead to exhaustion rather than missed goals.","ko":"신약한 사주라 기운이 차오르는 것보다 빨리 줄어들 수 있어요. 일정을 빽빽하게 채우면 목표를 놓치기보다 먼저 지칠 수 있어요."},{"en":"Think of your energy as a cup that empties faster than it fills: saying yes to everything may leave you tired long before it leaves you stuck.","ko":"기운을 채워지는 것보다 빨리 비는 컵이라고 생각해 보세요. 자꾸 승낙하다 보면 막히기 훨씬 전에 먼저 지칠 수 있어요."},{"en":"Your chart may like to recharge with help from others, so a full calendar can feel tiring.","ko":"주변의 도움으로 힘을 채우는 편일 수 있어서, 일정이 꽉 차면 피곤하게 느껴질 수 있어요."}],"card":"caution"},"WT_weak_COPE":{"tags":["strength:weak"],"v":[{"en":"Keep one evening a week with nothing scheduled, and protect it like an appointment.","ko":"일주일에 하루 저녁은 아무 일정도 넣지 말고, 약속처럼 지켜 주세요."},{"en":"Say no to one request this week, and use that time to rest or do something slow.","ko":"이번 주에 부탁 하나는 정중히 거절하고, 그 시간에 쉬거나 느긋한 일을 해 보세요."},{"en":"Before you start your day, pick the single most important task and do that one first.","ko":"하루를 시작하기 전에 가장 중요한 일 하나를 고르고, 그것부터 하세요."},{"en":"Put a ten-minute pause between two commitments today and step outside for some air.","ko":"오늘 일정 두 개 사이에 10분 쉼표를 넣고 바깥 공기를 쐬러 나가 보세요."},{"en":"Ask a friend or coworker to take one small task off your plate this week.","ko":"이번 주에 친구나 동료에게 작은 일 하나를 맡아 달라고 부탁해 보세요."},{"en":"Go to bed at the same time tonight and tomorrow, and see how the mornings feel.","ko":"오늘 밤과 내일 밤 같은 시간에 잠자리에 들고, 아침이 어떤지 살펴보세요."}],"card":"caution"},"WT_ex_wood_FEEL":{"tags":["el:wood:excess"],"v":[{"en":"You may start more things than you can grow at once.","ko":"한 번에 키울 수 있는 것보다 더 많은 일을 시작할 수 있어요."},{"en":"Fresh ideas may tempt you to plant more seeds than you have time to tend.","ko":"새로운 아이디어에 끌려 돌볼 시간보다 더 많은 씨앗을 심게 될 수 있어요."}],"card":"caution"},"WT_ex_wood_MEAN":{"tags":["el:wood:excess"],"v":[{"en":"With Wood abundant in your chart ({exN} of the {total} visible characters), growth energy can scatter in many directions.","ko":"사주에 나무 기운이 많아서(보이는 {total}자 중 {exN}자), 자라려는 힘이 여러 방향으로 흩어질 수 있어요."}],"card":"caution"},"WT_ex_wood_COPE":{"tags":["el:wood:excess"],"v":[{"en":"Each season, choose one project to prune and one to water.","ko":"계절마다 가지치기할 일 하나와 물 줄 일 하나를 고르세요."},{"en":"At the turn of each season, decide which project to trim back and which to nurture.","ko":"계절이 바뀔 때마다 줄일 일 하나와 키울 일 하나를 정해 보세요."}],"card":"caution"},"WT_ex_fire_FEEL":{"tags":["el:fire:excess"],"v":[{"en":"You may burn bright and then need a long rest.","ko":"환하게 타오른 뒤 오래 쉬어야 할 때가 있을 수 있어요."},{"en":"Your energy may flare brightly, then call for a long pause afterward.","ko":"에너지가 환하게 타오른 뒤 오래 멈춰 쉬어야 할 수 있어요."}],"card":"caution"},"WT_ex_fire_MEAN":{"tags":["el:fire:excess"],"v":[{"en":"With Fire abundant in your chart ({exN} of the {total} visible characters), enthusiasm runs high and can outpace your rest.","ko":"사주에 불 기운이 많아서(보이는 {total}자 중 {exN}자), 열정이 앞서 쉬는 속도를 앞지를 수 있어요."},{"en":"Fire fills {exN} of the {total} visible characters in your chart, so your drive may run ahead of your need to rest.","ko":"보이는 {total}자 중 {exN}자가 불 기운이라서, 추진력이 쉬어야 할 시간보다 앞서 달릴 수 있어요."}],"card":"caution"},"WT_ex_fire_COPE":{"tags":["el:fire:excess"],"v":[{"en":"After a big day, plan a quiet evening before you plan the next big thing.","ko":"큰일을 치른 날 뒤에는 다음 큰일보다 조용한 저녁을 먼저 계획하세요."},{"en":"Following a demanding day, put a calm evening on the calendar first, then think about what's next.","ko":"힘든 하루를 보낸 뒤에는 차분한 저녁을 먼저 일정에 넣고, 그다음 일을 생각하세요."}],"card":"caution"},"WT_ex_earth_FEEL":{"tags":["el:earth:excess"],"v":[{"en":"You may hold on to worries, habits, or duties longer than they serve you.","ko":"걱정이나 습관, 의무를 쓸모 있는 기간보다 오래 붙들고 있을 수 있어요."},{"en":"Worries, routines, or obligations may stay with you past the point where they help.","ko":"걱정이나 일과, 의무가 도움이 되는 시점을 지나서도 곁에 남아 있을 수 있어요."},{"en":"It may be hard to let go of a concern or a duty, even once it has done its job.","ko":"걱정거리나 맡은 일이 제 할 일을 마친 뒤에도 놓아 주기 어려울 수 있어요."},{"en":"You could keep carrying old habits or responsibilities longer than you need to.","ko":"오래된 습관이나 책임을 필요한 시간보다 더 길게 짊어지고 갈 수 있어요."}],"card":"caution"},"WT_ex_earth_MEAN":{"tags":["el:earth:excess"],"v":[{"en":"With Earth abundant in your chart ({exN} of the {total} visible characters), steadiness can sometimes feel heavy.","ko":"사주에 흙 기운이 많아서(보이는 {total}자 중 {exN}자), 든든함이 때로는 무겁게 느껴질 수 있어요."},{"en":"Earth is plentiful in your chart, {exN} of the {total} visible characters, so a steady feeling can sometimes turn heavy.","ko":"사주에 흙 기운이 넉넉해서(보이는 {total}자 중 {exN}자), 안정감이 가끔은 무거워질 수 있어요."},{"en":"Since {exN} of the {total} visible characters in your chart are Earth, solid reliability may occasionally weigh on you.","ko":"보이는 {total}자 중 {exN}자가 흙 기운이라서, 듬직함이 이따금 짐처럼 느껴질 수 있어요."},{"en":"Earth fills {exN} of your {total} visible characters, and that groundedness may feel a little weighty at times.","ko":"보이는 {total}자 중 {exN}자를 흙 기운이 채우고 있어서, 그 차분히 자리 잡은 느낌이 때때로 조금 묵직할 수 있어요."}],"card":"caution"},"WT_ex_earth_COPE":{"tags":["el:earth:excess"],"v":[{"en":"Once a week, finish or let go of one thing you've been carrying.","ko":"일주일에 한 번, 지고 다니던 것 하나를 끝내거나 내려놓으세요."},{"en":"Write down what you're carrying right now, then circle one thing to drop this week.","ko":"지금 지고 있는 것들을 적어 보고, 이번 주에 내려놓을 것 하나에 동그라미를 치세요."},{"en":"Every week, hand one responsibility to someone else or set it down for now.","ko":"매주 책임 하나를 다른 사람에게 넘기거나 잠시 내려놓으세요."},{"en":"Take ten minutes each week to clear one pile, physical or mental, off your plate.","ko":"매주 10분을 내어 눈앞에 쌓인 물건이든 마음속 일이든 한 더미를 치워 보세요."}],"card":"caution"},"WT_ex_metal_FEEL":{"tags":["el:metal:excess"],"v":[{"en":"You may hold high standards for yourself and others, sometimes higher than the situation needs.","ko":"자신과 남에게 높은 기준을 두고, 때로는 상황이 요구하는 것보다 높을 수 있어요."},{"en":"You may set a high bar for yourself and others, sometimes a bit higher than the moment calls for.","ko":"자신과 남에게 기준을 높게 두고, 때로는 그 순간에 필요한 것보다 조금 더 높게 잡을 수 있어요."}],"card":"caution"},"WT_ex_metal_MEAN":{"tags":["el:metal:excess"],"v":[{"en":"With Metal abundant in your chart ({exN} of the {total} visible characters), clear standards can come across as sharp.","ko":"사주에 쇠 기운이 많아서(보이는 {total}자 중 {exN}자), 분명한 기준이 날카롭게 느껴질 수 있어요."}],"card":"caution"},"WT_ex_metal_COPE":{"tags":["el:metal:excess"],"v":[{"en":"When you notice a critique forming, name one thing that's working first.","ko":"지적이 떠오르면 잘되고 있는 점 하나를 먼저 말해 보세요."},{"en":"Before you give feedback, begin with one thing that's going well.","ko":"의견을 건네기 전에, 잘 되고 있는 점 하나로 말문을 열어 보세요."}],"card":"caution"},"WT_ex_water_FEEL":{"tags":["el:water:excess"],"v":[{"en":"You may think a situation through so many ways that acting gets delayed.","ko":"상황을 여러 갈래로 생각하다가 행동이 늦어질 수 있어요."},{"en":"Weighing every angle of a situation could keep you from taking the first step.","ko":"상황의 모든 면을 따져 보다가 첫걸음을 떼지 못할 수 있어요."}],"card":"caution"},"WT_ex_water_MEAN":{"tags":["el:water:excess"],"v":[{"en":"With Water abundant in your chart ({exN} of the {total} visible characters), deep thought can drift.","ko":"사주에 물 기운이 많아서(보이는 {total}자 중 {exN}자), 깊은 생각이 떠다니게 될 수 있어요."}],"card":"caution"},"WT_ex_water_COPE":{"tags":["el:water:excess"],"v":[{"en":"When you're stuck, pick the next step that takes ten minutes and do only that.","ko":"막히면 10분이면 끝나는 다음 단계 하나만 골라 그것만 하세요."},{"en":"Tell one trusted person what's blocking you, then ask for a single suggestion.","ko":"믿는 사람에게 무엇이 막고 있는지 털어놓고, 제안 하나만 청해 보세요."}],"card":"caution"},"WT_clash_FEEL":{"tags":["natal:chung"],"v":[{"en":"You may notice that some parts of your life pull in different directions.","ko":"삶의 몇몇 부분이 서로 다른 방향으로 당긴다고 느낄 수 있어요."}],"card":"caution"},"WT_clash_MEAN":{"tags":["natal:chung"],"v":[{"en":"Your chart has a clash between {cb1} and {cb2} (from your {cp1} and {cp2} of birth); this points to movement and change between those areas of life, not a warning sign.","ko":"사주에서 {cb1}와(과) {cb2}이(가) 부딪치는 자리가 있어요({cp1Ko}·{cp2Ko} 쪽). 이것은 삶의 그 영역들 사이의 움직임과 변화를 가리키지, 경고가 아니에요."}],"card":"caution"},"WT_clash_COPE":{"tags":["natal:chung"],"v":[{"en":"When two demands collide, write both down and decide which one gets this week.","ko":"두 요구가 부딪히면 둘 다 적고, 이번 주에는 어느 쪽에 줄지 정하세요."}],"card":"caution"},"WT_clash_hour_FEEL":{"tags":["natal:chung","pillar:hour"],"v":[{"en":"You may notice that some parts of your life pull in different directions.","ko":"삶의 몇몇 부분이 서로 다른 방향으로 당긴다고 느낄 수 있어요."}],"card":"caution"},"WT_clash_hour_MEAN":{"tags":["natal:chung","pillar:hour"],"v":[{"en":"Your chart has a clash between {cb1} and {cb2} (the animals of your birth {cp1} and birth hour); in this tradition that means movement and change between those areas, not a warning sign.","ko":"사주에서 {cb1}와(과) {cb2}이(가) 부딪쳐요({cp1Ko}의 동물과 태어난 시각의 동물). 이 전통에서는 그 영역들 사이의 움직임과 변화를 뜻할 뿐, 경고가 아니에요."}],"card":"caution"},"WT_clash_hour_COPE":{"tags":["natal:chung","pillar:hour"],"v":[{"en":"When two demands collide, write both down and decide which one gets this week.","ko":"두 요구가 부딪히면 둘 다 적고, 이번 주에는 어느 쪽에 줄지 정하세요."}],"card":"caution"},"WT_miss_inseong_FEEL":{"tags":["cat:inseong:none"],"v":[{"en":"You may find it hard to rest or accept help.","ko":"쉬거나 도움을 받는 게 어려울 수 있어요."}],"card":"caution"},"WT_miss_inseong_MEAN":{"tags":["cat:inseong:none"],"v":[{"en":"Your chart shows no learning-and-support signs, even counting hidden elements, so rest and self-care may need to be chosen on purpose.","ko":"숨은 기운까지 세어 봐도 사주에 배움과 도움의 표시가 없어서, 쉼과 자기 돌봄을 일부러 챙겨야 할 수 있어요."}],"card":"caution"},"WT_miss_inseong_COPE":{"tags":["cat:inseong:none"],"v":[{"en":"Ask for one small favor this week and let someone help without paying it back right away.","ko":"이번 주 작은 부탁 하나를 하고, 바로 갚으려 하지 말고 도움을 받아 보세요."}],"card":"caution"},"WT_miss_siksang_FEEL":{"tags":["cat:siksang:none"],"v":[{"en":"You may keep feelings or ideas inside longer than you mean to.","ko":"마음이나 생각을 뜻한 것보다 오래 안에 담아 둘 수 있어요."}],"card":"caution"},"WT_miss_siksang_MEAN":{"tags":["cat:siksang:none"],"v":[{"en":"As noted in Love & Relationships, expression has no built-in outlet in your chart, so it helps to create one on purpose.","ko":"사랑과 관계 칸에서 본 것처럼 사주에 표현의 통로가 따로 없어서, 일부러 하나 만들어 두면 도움이 돼요."}],"card":"caution"},"WT_miss_siksang_COPE":{"tags":["cat:siksang:none"],"v":[{"en":"Share one idea or feeling out loud this week, even if it isn't polished.","ko":"이번 주, 다듬어지지 않았더라도 생각이나 마음 하나를 소리 내어 나눠 보세요."}],"card":"caution"},"WT_miss_bigyeop_FEEL":{"tags":["cat:bigyeop:none"],"v":[{"en":"You may give way to others more than you need to.","ko":"필요 이상으로 남에게 양보할 수 있어요."}],"card":"caution"},"WT_miss_bigyeop_MEAN":{"tags":["cat:bigyeop:none"],"v":[{"en":"With no peer symbols, your own position needs conscious backing.","ko":"나와 동료의 글자(비겁)가 없어서, 내 입장을 일부러 챙겨야 해요."}],"card":"caution"},"WT_miss_bigyeop_COPE":{"tags":["cat:bigyeop:none"],"v":[{"en":"Once this week, state your preference first before hearing others'.","ko":"이번 주 한 번은 남의 의견을 듣기 전에 내 선호를 먼저 말해 보세요."}],"card":"caution"},"WT_miss_jaeseong_FEEL":{"tags":["cat:jaeseong:none"],"v":[{"en":"You may find practical money details easy to postpone.","ko":"돈에 관한 세세한 일을 자꾸 미루기 쉬울 수 있어요."}],"card":"caution"},"WT_miss_jaeseong_MEAN":{"tags":["cat:jaeseong:none"],"v":[{"en":"With no wealth symbols, money needs a simple system rather than attention on demand.","ko":"재물의 글자(재성)가 없어서, 돈은 그때그때의 관심보다 간단한 체계가 필요해요."}],"card":"caution"},"WT_miss_jaeseong_COPE":{"tags":["cat:jaeseong:none"],"v":[{"en":"Put a fifteen-minute planning check on your calendar every two weeks.","ko":"2주마다 15분짜리 계획 점검 시간을 달력에 넣어 두세요."}],"card":"caution"},"WT_miss_gwanseong_FEEL":{"tags":["cat:gwanseong:none"],"v":[{"en":"You may feel a little restless around schedules and rules, even useful ones.","ko":"쓸모 있는 일정과 규칙에도 조금 답답함이 들 수 있어요."}],"card":"caution"},"WT_miss_gwanseong_MEAN":{"tags":["cat:gwanseong:none"],"v":[{"en":"With no authority symbols, outside rules can feel foreign, and a self-made structure works better.","ko":"책임과 틀의 글자(관성)가 없어서, 바깥 규칙은 낯설게 느껴지고 스스로 만든 틀이 더 잘 맞을 수 있어요."}],"card":"caution"},"WT_miss_gwanseong_COPE":{"tags":["cat:gwanseong:none"],"v":[{"en":"Set one personal rule for the week, and keep it just for yourself.","ko":"이번 주 나만의 규칙 하나를 정하고, 나를 위해 지켜 보세요."}],"card":"caution"},"WT_over_bigyeop_FEEL":{"tags":["cat:bigyeop:many"],"v":[{"en":"You may compete even when you didn't mean to.","ko":"의도하지 않았는데도 경쟁하게 될 수 있어요."}],"card":"caution"},"WT_over_bigyeop_MEAN":{"tags":["cat:bigyeop:many"],"v":[{"en":"With many signs of friends and equals in your chart (hidden ones included), sharing work and results goes best with clear agreements.","ko":"사주에 친구와 대등한 동료를 뜻하는 표시가 많아서(숨은 것 포함), 일과 결과를 나눌 때 분명한 약속이 있으면 가장 좋아요."}],"card":"caution"},"WT_over_bigyeop_COPE":{"tags":["cat:bigyeop:many"],"v":[{"en":"In your next joint plan, write down who does what.","ko":"다음 공동 계획에서 누가 무엇을 할지 적어 두세요."}],"card":"caution"},"WT_over_siksang_FEEL":{"tags":["cat:siksang:many"],"v":[{"en":"You may talk yourself into too many directions.","ko":"말하다 보면 너무 많은 방향으로 뻗어 나갈 수 있어요."}],"card":"caution"},"WT_over_siksang_MEAN":{"tags":["cat:siksang:many"],"v":[{"en":"With many expression symbols, words and ideas flow fast and can spill over.","ko":"식상의 글자가 많아서, 말과 생각이 빠르게 흘러넘칠 수 있어요."}],"card":"caution"},"WT_over_siksang_COPE":{"tags":["cat:siksang:many"],"v":[{"en":"Before sending a sharp message, save it as a draft for an hour.","ko":"날 선 메시지는 보내기 전에 한 시간 임시 저장해 두세요."}],"card":"caution"},"WT_over_jaeseong_FEEL":{"tags":["cat:jaeseong:many"],"v":[{"en":"You may feel pulled by too many practical demands.","ko":"현실적인 요구 여러 개에 끌려다닌다고 느낄 수 있어요."}],"card":"caution"},"WT_over_jaeseong_MEAN":{"tags":["cat:jaeseong:many"],"v":[{"en":"With many wealth symbols, chasing every opportunity can wear you out.","ko":"재성의 글자가 많아서, 모든 기회를 쫓다 보면 지칠 수 있어요."}],"card":"caution"},"WT_over_jaeseong_COPE":{"tags":["cat:jaeseong:many"],"v":[{"en":"Say no to one opportunity this month that you only half want.","ko":"이번 달, 반쯤만 원하는 기회 하나에는 \"아니요\"라고 답하세요."}],"card":"caution"},"WT_over_gwanseong_FEEL":{"tags":["cat:gwanseong:many"],"v":[{"en":"You may feel watched or measured, even when no one is judging.","ko":"아무도 평가하지 않을 때에도 지켜보이고 평가받는다고 느낄 수 있어요."}],"card":"caution"},"WT_over_gwanseong_MEAN":{"tags":["cat:gwanseong:many"],"v":[{"en":"With many authority symbols, pressure from roles can pile up.","ko":"관성의 글자가 많아서, 역할에서 오는 압박이 쌓일 수 있어요."}],"card":"caution"},"WT_over_gwanseong_COPE":{"tags":["cat:gwanseong:many"],"v":[{"en":"List your obligations and mark one you can hand over or shrink.","ko":"해야 할 일을 적고, 넘기거나 줄일 수 있는 하나에 표시하세요."}],"card":"caution"},"WT_over_inseong_FEEL":{"tags":["cat:inseong:many"],"v":[{"en":"You may think, prepare, and plan longer than needed before starting.","ko":"시작하기 전에 필요 이상으로 생각하고 준비하고 계획할 수 있어요."}],"card":"caution"},"WT_over_inseong_MEAN":{"tags":["cat:inseong:many"],"v":[{"en":"With a lot of learning-and-support energy in your chart (hidden layers included), preparation can quietly replace action.","ko":"사주에 배움과 도움의 기운이 많아서(숨은 층 포함), 준비가 슬그머니 행동을 대신할 수 있어요."}],"card":"caution"},"WT_over_inseong_COPE":{"tags":["cat:inseong:many"],"v":[{"en":"Start one thing this week at eighty percent ready.","ko":"이번 주, 80퍼센트만 준비된 상태에서 하나를 시작해 보세요."}],"card":"caution"},"WT_general_FEEL":{"tags":["watch:general"],"v":[{"en":"You may notice ordinary tiredness from routine more than any single pattern.","ko":"어떤 한 가지 패턴보다 일상의 반복에서 오는 평범한 피로를 더 느낄 수 있어요."},{"en":"The everyday grind of repeating routines may wear on you more than any one particular pattern does.","ko":"특정한 한 가지 패턴보다 매일 되풀이되는 일과가 더 지치게 할 수 있어요."},{"en":"What you feel most may be plain tiredness from daily repetition, rather than something specific.","ko":"가장 크게 느끼는 건 특별한 무언가보다 날마다 반복되는 데서 오는 평범한 피곤함일 수 있어요."},{"en":"Ordinary routine tiredness may weigh on you more than any single pattern in your chart.","ko":"사주의 어느 한 패턴보다 평범한 일상 속 피로가 더 무겁게 다가올 수 있어요."}],"card":"caution"},"WT_general_MEAN":{"tags":["watch:general"],"v":[{"en":"Your chart doesn't flag a strong imbalance here, so the everyday things, such as sleep rhythm, meals, and breaks, matter most.","ko":"사주에서 뚜렷한 치우침이 보이지 않아서, 잠의 리듬·식사·쉬는 시간 같은 일상적인 것이 가장 중요해요."},{"en":"Nothing in your chart stands out as a strong imbalance, so simple daily rhythms such as when you sleep, eat, and rest are what count most.","ko":"사주에서 눈에 띄게 치우친 곳이 없어서, 언제 자고 먹고 쉬는지 같은 간단한 하루 리듬이 가장 중요해요."},{"en":"Because your chart shows no pronounced lean in one direction, regular sleep, regular meals, and real breaks are the things worth protecting.","ko":"사주가 한쪽으로 크게 기울어 있지 않아서, 규칙적인 잠과 식사, 제대로 된 휴식이 지킬 만한 것들이에요."},{"en":"There's no single point of strain in your chart, so everyday basics like a steady bedtime, unhurried meals, and short pauses matter most.","ko":"사주에 한 군데 부담이 몰린 곳이 없어서, 일정한 취침 시간과 여유로운 식사, 짧은 쉼 같은 기본기가 가장 중요해요."}],"card":"caution"},"WT_general_COPE":{"tags":["watch:general"],"v":[{"en":"Pick one daily rhythm, such as a fixed bedtime, and hold it for two weeks.","ko":"정해진 잠자리 시간처럼 하루 리듬 하나를 골라 2주간 지켜 보세요."},{"en":"Choose one small evening ritual, like turning off screens at a set time, and keep it for two weeks.","ko":"정해진 시각에 화면을 끄는 것처럼 작은 저녁 습관 하나를 골라 2주 동안 지켜 보세요."},{"en":"Take a ten-minute walk at the same time each day for the next two weeks.","ko":"앞으로 2주 동안 매일 같은 시간에 10분씩 걸어 보세요."},{"en":"Pick one regular mealtime and keep it steady for two weeks.","ko":"식사 시간 하나를 정하고 2주 동안 꾸준히 지켜 보세요."}],"card":"caution"},"BL_FEEL_wood":{"tags":["bal:add:wood"],"v":[{"en":"Wood helps you start things and keep them growing.","ko":"나무 기운은 일을 시작하고 계속 키워 가게 도와줘요."},{"en":"Starting something new and nurturing it along can feel natural with Wood on your side.","ko":"나무 기운이 곁에 있으면 새로 시작하고 가꿔 가는 일이 자연스럽게 느껴질 수 있어요."},{"en":"Wood may lend you a sense of fresh beginnings and steady growth.","ko":"나무 기운은 새로운 시작과 꾸준한 자람의 느낌을 보태 줄 수 있어요."},{"en":"Growth feels closer when Wood is around, from the first shoot to the slow tending.","ko":"나무 기운이 있으면 첫 싹부터 천천히 돌보는 과정까지, 자라는 일이 한결 가깝게 느껴져요."},{"en":"There's a Wood energy that may encourage you to plant seeds and watch them grow.","ko":"나무의 기운은 씨앗을 심고 자라는 모습을 지켜보도록 북돋아 줄 수 있어요."}],"card":"habits_candidate"},"BL_MEAN_wood":{"tags":["bal:add:wood"],"v":[{"en":"Wood is the element of beginnings and growth. Traditionally it's linked with the east, spring, and the color green.","ko":"나무는 시작과 성장의 기운이에요. 전통적으로 동쪽, 봄, 초록색과 짝지어져요."},{"en":"In the traditional system, Wood represents new starts and growth, and it's associated with the east, spring, and green.","ko":"전통 체계에서 나무는 새로운 시작과 성장을 나타내요. 동쪽, 봄, 초록색과 연결돼요."},{"en":"Wood carries the feeling of sprouting and reaching upward; spring, the east, and the color green belong to it by tradition.","ko":"나무는 싹이 트고 위로 뻗는 느낌을 담고 있어요. 전통적으로 봄과 동쪽, 초록색이 나무에 속해요."},{"en":"Think of Wood as the springtime element: beginnings, growth, the direction east, and the color green.","ko":"나무는 봄철 같은 기운이라고 생각해 보세요. 시작과 성장, 동쪽이라는 방향, 초록색이 함께해요."},{"en":"Beginnings and growth are what Wood stands for, and old texts pair it with the east, the spring season, and green.","ko":"시작과 성장이 나무가 상징하는 것이에요. 옛 글에서는 동쪽과 봄, 초록색을 나무와 짝지어요."}],"card":"habits_candidate"},"BL_ACT_wood":{"tags":["bal:add:wood"],"v":[{"en":"Put a green plant or something green where you work, and begin each day with one five-minute task.","ko":"일하는 곳에 초록 식물이나 초록색 물건을 두고, 하루를 5분짜리 일 하나로 시작해 보세요."},{"en":"Take a morning walk among trees once this week, and use it to plan one first step.","ko":"이번 주 한 번은 나무 사이로 아침 산책을 하며 첫걸음 하나를 계획해 보세요."},{"en":"Stretch for five minutes by a window each morning, then write down one thing you want to start.","ko":"매일 아침 창가에서 5분 동안 몸을 쭉 펴고, 시작하고 싶은 일 하나를 적어 보세요."},{"en":"Start something small this week, like seeds on a windowsill or a new notebook page, and give it a little attention each day.","ko":"이번 주에 창가의 씨앗이나 새 공책 한 장처럼 작은 것을 시작하고, 매일 조금씩 마음을 써 보세요."},{"en":"Spend a lunch break outdoors near greenery, and note one idea you'd like to try.","ko":"점심시간에 초록이 있는 바깥에서 쉬며, 해 보고 싶은 아이디어 하나를 적어 보세요."}],"card":"habits_candidate"},"BL_FEEL_fire":{"tags":["bal:add:fire"],"v":[{"en":"Fire helps you show the warmth you already feel.","ko":"불 기운은 이미 느끼는 따뜻함을 밖으로 보여 주게 도와줘요."},{"en":"Fire gives the warmth inside you a way to show.","ko":"불 기운은 마음속 따뜻함이 겉으로 드러날 길을 열어 줘요."},{"en":"With Fire, the warmth you already feel can reach others.","ko":"불 기운이 더해지면 이미 품고 있던 온기가 다른 사람에게 닿을 수 있어요."}],"card":"habits_candidate"},"BL_MEAN_fire":{"tags":["bal:add:fire"],"v":[{"en":"Fire is the element of warmth and expression. Traditionally it's linked with the south, summer, and the color red.","ko":"불은 따뜻함과 표현의 기운이에요. 전통적으로 남쪽, 여름, 붉은색과 짝지어져요."},{"en":"Fire stands for warmth and self-expression, and tradition ties it to the south, summer, and the color red.","ko":"불은 따뜻함과 자기 표현을 뜻하고, 전통에서는 남쪽과 여름, 붉은색에 이어져요."},{"en":"In tradition, Fire carries warmth and expression, and it's paired with the south, the summer season, and red.","ko":"전통에서 불은 따뜻함과 표현을 품고 있고, 남쪽과 여름철, 빨강과 짝을 이뤄요."}],"card":"habits_candidate"},"BL_ACT_fire":{"tags":["bal:add:fire"],"v":[{"en":"Add warm light or a touch of red to your space, and share one piece of good news with someone this week.","ko":"공간에 따뜻한 조명이나 붉은색을 조금 더하고, 이번 주 누군가에게 좋은 소식 하나를 나눠 보세요."},{"en":"Spend some time in the sun this week, and call a friend just to catch up.","ko":"이번 주 햇볕 아래서 시간을 보내고, 안부만 묻는 전화를 친구에게 걸어 보세요."}],"card":"habits_candidate"},"BL_FEEL_earth":{"tags":["bal:add:earth"],"v":[{"en":"Earth helps you feel settled when routines keep shifting.","ko":"흙 기운은 일상이 자꾸 바뀔 때 마음을 붙들어 줘요."},{"en":"Earth can give you something steady to hold onto when daily life keeps changing.","ko":"흙 기운은 일상이 계속 달라질 때 붙잡을 수 있는 든든함을 줄 수 있어요."}],"card":"habits_candidate"},"BL_MEAN_earth":{"tags":["bal:add:earth"],"v":[{"en":"Earth is the element of stability and nourishment. Traditionally it's linked with the center, the turn of the seasons and the color yellow.","ko":"흙은 안정과 기름짐의 기운이에요. 전통적으로 가운데, 계절이 바뀌는 때, 노란색과 짝지어져요."},{"en":"Earth stands for steadiness and nourishment. Traditionally it's paired with the center, the shifts between seasons, and the color yellow.","ko":"흙은 든든함과 북돋움의 기운이에요. 전통적으로 가운데, 계절이 넘어가는 때, 노란색과 짝을 이뤄요."}],"card":"habits_candidate"},"BL_ACT_earth":{"tags":["bal:add:earth"],"v":[{"en":"Keep one fixed daily anchor, such as the same wake-up time or a meal at the same hour, for a week.","ko":"일주일 동안 같은 기상 시간이나 같은 시간의 식사처럼 하루의 닻 하나를 지켜 보세요."},{"en":"Cook one simple meal from scratch this week and eat it without screens.","ko":"이번 주 간단한 한 끼를 직접 만들어 화면 없이 먹어 보세요."}],"card":"habits_candidate"},"BL_FEEL_metal":{"tags":["bal:add:metal"],"v":[{"en":"Metal helps you make clear decisions and hold your boundaries.","ko":"쇠 기운은 분명하게 결정하고 선을 지키게 도와줘요."},{"en":"Metal can sharpen your sense of what to choose and where your limits are.","ko":"쇠 기운은 무엇을 고를지, 어디까지가 내 한계인지 감각을 또렷하게 해 줄 수 있어요."},{"en":"With Metal around, saying a clear yes or no may feel easier.","ko":"쇠 기운이 곁에 있으면 분명하게 \"좋아요\"나 \"아니요\"라고 말하기가 더 쉬워질 수 있어요."}],"card":"habits_candidate"},"BL_MEAN_metal":{"tags":["bal:add:metal"],"v":[{"en":"Metal is the element of clarity and structure. Traditionally it's linked with the west, autumn, and the color white.","ko":"쇠는 분명함과 틀의 기운이에요. 전통적으로 서쪽, 가을, 흰색과 짝지어져요."},{"en":"Metal stands for clarity and structure in Saju. Tradition pairs it with the west, the autumn season, and the color white.","ko":"사주에서 쇠는 분명함과 틀을 뜻해요. 전통적으로 서쪽, 가을철, 흰색과 짝을 이뤄요."},{"en":"In traditional Saju, Metal carries the qualities of clarity and structure, and it's paired with autumn, the west, and white.","ko":"전통 사주에서 쇠는 분명함과 틀의 성질을 지니고, 가을과 서쪽, 흰색과 짝지어져요."}],"card":"habits_candidate"},"BL_ACT_metal":{"tags":["bal:add:metal"],"v":[{"en":"Clear one drawer or one desktop folder this week, and keep only what you use.","ko":"이번 주 서랍 하나나 컴퓨터 폴더 하나를 정리하고, 쓰는 것만 남겨 보세요."},{"en":"Make one decision you've been postponing, and write down why you chose it.","ko":"미뤄 온 결정 하나를 내리고, 왜 그렇게 골랐는지 적어 보세요."},{"en":"Tonight, write down your three priorities for tomorrow in order, and start with the first one.","ko":"오늘 밤 내일의 우선순위 세 가지를 순서대로 적고, 첫 번째부터 시작해 보세요."}],"card":"habits_candidate"},"BL_FEEL_water":{"tags":["bal:add:water"],"v":[{"en":"Water helps you slow down and reflect.","ko":"물 기운은 속도를 늦추고 돌아보게 도와줘요."},{"en":"Water eases your pace and invites a look inward.","ko":"물 기운은 걸음을 누그러뜨리고 안쪽을 들여다보게 이끌어요."},{"en":"A little Water can give you room to slow down and think things over.","ko":"물 기운이 조금 더해지면 천천히 쉬며 생각을 정리할 여유가 생겨요."}],"card":"habits_candidate"},"BL_MEAN_water":{"tags":["bal:add:water"],"v":[{"en":"Water is the element of rest and reflection. Traditionally it's linked with the north, winter, and the colors black and deep blue.","ko":"물은 쉼과 돌아봄의 기운이에요. 전통적으로 북쪽, 겨울, 검은색과 짙은 파랑과 짝지어져요."},{"en":"Water represents rest and reflection, and tradition pairs it with the north, winter, and the colors black and deep blue.","ko":"물은 쉼과 돌아봄을 나타내고, 전통에서는 북쪽과 겨울, 검정과 짙은 파랑이 짝이에요."},{"en":"Traditionally, Water is the energy of quiet and looking inward, connected to the north, the winter season, and black and deep blue.","ko":"전통적으로 물은 고요함과 안을 들여다보는 기운이고, 북쪽과 겨울철, 검정과 짙은 파랑에 이어져요."}],"card":"habits_candidate"},"BL_ACT_water":{"tags":["bal:add:water"],"v":[{"en":"Keep a glass of water on your desk, and take a quiet ten-minute pause each evening.","ko":"책상에 물 한 잔을 두고, 저녁마다 조용히 10분 쉬어 보세요."},{"en":"Spend a few minutes near water, such as a river, a fountain, or a long bath, and let your thoughts settle.","ko":"강이나 분수, 느긋한 목욕처럼 물 가까이에서 몇 분 보내며 생각을 가라앉혀 보세요."}],"card":"habits_candidate"},"BL_PICK_lack":{"tags":[],"v":[{"en":"{balEl} appears {balN} times among the {total} visible characters, and it's one of the elements that balance your chart, so a little more of it may steady you.","ko":"{balEl}은(는) 보이는 {total}자 중 {balN}자이고, 사주의 균형을 잡아 주는 기운 가운데 하나예요. 그래서 조금 더하면 마음이 안정되는 편이에요."}],"card":"habits_candidate"},"BL_PICK_two":{"tags":[],"v":[{"en":"{balEl} and {balEl2} both help balance your chart ({balEl}: {balN}, {balEl2}: {balN2}, out of {total} characters); we start with {balEl}.","ko":"{balEl}와(과) {balEl2} 둘 다 사주의 균형을 잡아 줘요(전체 {total}개 글자 가운데 {balEl} {balN}개, {balEl2} {balN2}개). 먼저 {balEl}부터 볼게요."}],"card":"habits_candidate"},"BL_SEASON_summer":{"tags":["season:summer","bal:season:water"],"v":[{"en":"You were born in the summer months. One common reading, called season balancing, cools a summer chart with Water, so unhurried, cool evenings may help you reset.","ko":"여름 달에 태어났어요. 계절 균형 맞추기(조후)라는 흔한 해석 하나는 여름 사주를 물로 식혀요. 그래서 서두르지 않는 서늘한 저녁이 재충전에 도움이 될 수 있어요."},{"en":"Your birth falls in the summer months. A familiar reading called season balancing cools a summer chart with Water, so slow, cool evenings may be a nice way to recharge.","ko":"여름 달에 태어났어요. 계절 균형 맞추기(조후)라는 널리 알려진 해석은 여름 사주를 물로 식혀요. 느긋하고 서늘한 저녁이 재충전에 좋은 방법일 수 있어요."},{"en":"Born in summer, you fall under a traditional idea known as season balancing, which pairs hot-season charts with Water; calm, cool evenings could help you reset.","ko":"여름에 태어난 당신에게는 계절 균형 맞추기(조후)라는 전통적인 생각이 적용돼요. 더운 계절의 사주에 물을 짝지어 주는데, 차분하고 서늘한 저녁이 재충전에 도움이 될 수 있어요."}],"card":"habits_candidate"},"BL_SEASON_summer_has":{"tags":["season:summer"],"v":[{"en":"You were born in the summer months. One common reading, called season balancing, cools a summer chart with Water, and your chart already carries plenty of it.","ko":"여름 달에 태어났어요. 계절 균형 맞추기(조후)라는 흔한 해석은 여름 사주를 물로 식히는데, 당신 사주에는 이미 물이 넉넉해요."}],"card":"habits_candidate"},"BL_SEASON_winter":{"tags":["season:winter","bal:season:fire"],"v":[{"en":"You were born in the winter months. One common reading, called season balancing, warms a winter chart with Fire, so warm light, sunshine, and good company may help you thaw.","ko":"겨울 달에 태어났어요. 계절 균형 맞추기(조후)라는 흔한 해석 하나는 겨울 사주를 불로 데워요. 그래서 따뜻한 빛과 햇살, 좋은 사람들이 마음을 녹여 줄 수 있어요."},{"en":"You were born in a winter month, and one traditional approach to season balancing brings in Fire to warm a chilly chart, so cozy light, sunny spots, and warm company may help you feel thawed.","ko":"겨울 달에 태어났어요. 계절 균형 맞추기(조후)의 전통적인 접근 하나는 차가운 사주에 불을 더해 데워요. 그래서 포근한 빛과 햇볕 드는 곳, 따뜻한 사람들이 마음을 풀어 줄 수 있어요."}],"card":"habits_candidate"},"BL_SEASON_winter_has":{"tags":["season:winter"],"v":[{"en":"You were born in the winter months. One common reading, called season balancing, warms a winter chart with Fire, and your chart already carries plenty of it.","ko":"겨울 달에 태어났어요. 계절 균형 맞추기(조후)라는 흔한 해석은 겨울 사주를 불로 데우는데, 당신 사주에는 이미 불이 넉넉해요."}],"card":"habits_candidate"},"BL_SEASON_spring":{"tags":["season:spring"],"v":[{"en":"For spring births we don't add a season-balancing suggestion, so the element count above leads.","ko":"봄 출생은 계절 균형 맞추기(조후) 제안을 따로 더하지 않고, 위의 오행 개수를 따라요."},{"en":"Spring births don't get a separate season-balancing tip here; the element count above takes the lead.","ko":"봄에 태어난 분께는 계절 균형 맞추기(조후) 제안을 따로 드리지 않고, 위의 오행 개수가 중심이 돼요."},{"en":"We skip the season-balancing suggestion for a spring birth and let the element count above guide you.","ko":"봄 출생에는 계절 균형 맞추기(조후) 제안을 건너뛰고, 위의 오행 개수를 길잡이로 삼아요."},{"en":"Since you were born in spring, no extra season-balancing advice is added, and the element tally above leads the way.","ko":"봄에 태어났기 때문에 계절 균형 맞추기(조후) 조언은 더하지 않고, 위의 오행 집계가 방향을 이끌어요."}],"card":"habits_candidate"},"BL_SEASON_autumn":{"tags":["season:autumn"],"v":[{"en":"For autumn births we don't add a season-balancing suggestion, so the element count above leads.","ko":"가을 출생은 계절 균형 맞추기(조후) 제안을 따로 더하지 않고, 위의 오행 개수를 따라요."},{"en":"Since you were born in autumn, we skip the season-balancing tip and let the element count above guide you.","ko":"가을에 태어났기 때문에 계절 균형 맞추기(조후) 팁은 넣지 않고, 위의 오행 개수가 안내하도록 해요."},{"en":"No extra season-balancing advice is added for autumn births, so the element count above takes the lead.","ko":"가을 출생에는 계절 균형(조후) 조언을 따로 더하지 않아서, 위의 오행 개수가 중심이 돼요."},{"en":"Autumn births get no separate season-balancing suggestion here; the element count above is what we follow.","ko":"여기서 가을 출생은 계절 균형(조후) 제안을 따로 받지 않고, 위의 오행 개수를 기준으로 삼아요."}],"card":"habits_candidate"},"DISCLAIMER":{"tags":[],"v":[{"en":"For entertainment purposes only. Not medical, legal, financial or psychological advice.","ko":"재미로 보는 풀이입니다. 의료·법률·재정·심리 상담을 대신하지 않습니다."}],"card":"common"},"TIME_UNKNOWN_NOTE":{"tags":["notice:time-unknown"],"v":[{"en":"Your big picture is here even without the hour. If you learn it later, one more piece fills in.","ko":"시간을 몰라도 큰 그림은 여기 있어요. 나중에 알게 되면 조각 하나가 더 채워져요."}],"card":"common"},"GL_DM":{"tags":["glossary"],"v":[{"en":"Your core element is the element of the day you were born, the part of your chart that stands for you.","ko":"나의 중심 기운은 태어난 날의 기운으로, 사주에서 \"나\"를 나타내는 부분이에요."}],"card":"common"},"GL_CHARS":{"tags":["glossary"],"v":[{"en":"Your chart is made of eight visible signs, four elements and four animals; the element counts in this reading use only those eight visible signs.","ko":"사주는 눈에 보이는 여덟 개의 표시, 곧 기운 넷과 동물 넷으로 이루어져요. 이 풀이에서 다섯 기운의 개수는 그 보이는 여덟 개만 센 거예요."}],"card":"common"},"GL_IPCHUN":{"tags":["glossary"],"v":[{"en":"The Start of Spring, around February 4, is where each traditional year begins.","ko":"2월 4일 무렵의 입춘이 전통 달력에서 한 해가 시작되는 날이에요."}],"card":"common"},"GL_STAGE":{"tags":["glossary"],"v":[{"en":"This is a traditional twelve-step scale of how strong your core element (the element of the day you were born) is beside each animal in your chart, from fresh growth to rest and renewal; it describes strength, not events.","ko":"태어난 날의 기운인 나의 중심 기운이 사주 속 각 동물 곁에서 얼마나 힘이 있는지를, 새로 자라남부터 쉼과 새로 시작함까지 열두 단계로 나눈 전통 척도예요. 힘의 정도를 말할 뿐, 사건을 뜻하지 않아요."}],"card":"common"},"GL_SYMBOLS":{"tags":["glossary"],"v":[{"en":"We sort the ten relationship types into five families: self and equals, expression, wealth, authority, and learning and support. When we count them, we also include the elements hidden inside each animal in your chart.","ko":"열 가지 관계는 다섯 무리로 나눠 봐요. 나와 동료, 표현, 재물, 책임과 틀, 배움과 도움이에요. 개수를 셀 때는 사주 속 각 동물 안에 숨은 기운도 함께 넣어요."}],"card":"common"},"GL_CYCLES":{"tags":["glossary"],"v":[{"en":"Your 10-year cycles are the decade-long luck periods that begin a few years after birth.","ko":"10년 대운(大運)은 태어나고 몇 해 뒤부터 10년씩 바뀌는 운의 흐름이에요."}],"card":"common"},"OV_SPECIAL":{"tags":["special"],"v":[{"en":"Your chart shows a pattern that Saju teachers read in different ways, sometimes called a special pattern. That doesn't mean anything is wrong with your chart; it just means the strength notes here are one view among several.","ko":"당신의 사주는 사주 선생님들 사이에서도 해석이 갈리기도 하는 모양(특별한 격이라고도 해요)이에요. 사주에 이상이 있다는 뜻은 아니고, 이 풀이의 강약 이야기는 여러 관점 중 하나로 읽어 주세요."},{"en":"Saju teachers read a pattern like yours in different ways, and it's sometimes called a special pattern. Nothing is wrong with your chart; treat the strength notes here as one view among several.","ko":"당신과 같은 모양은 사주 선생님마다 다르게 읽기도 하고, 특별한 격이라고도 해요. 사주에 이상이 있다는 뜻은 아니니, 이 풀이의 강약 이야기는 여러 관점 중 하나로 읽어 주세요."},{"en":"Your chart has a pattern that can be read in more than one way, sometimes called a special pattern. It isn't a flaw, and it simply means the strength notes here are one view among several.","ko":"당신의 사주에는 한 가지 이상으로 읽을 수 있는 모양(특별한 격이라고도 해요)이 있어요. 결함이 아니라, 이 풀이의 강약 이야기가 여러 관점 중 하나라는 뜻이에요."}],"card":"overview"},"YR_R_fuyin":{"tags":["yrrel"],"v":[{"en":"{year}'s element and animal, {yearGz}, exactly match those of {pWhole}, a pattern called a repeat year. One common reading is that themes around {area} come back for a second look.","ko":"{year}년의 기운과 동물 {yearGz}이(가) {pWhole}의 것과 똑같아요. 이를 '되풀이되는 해'라고 불러요. 흔한 풀이 하나는 {area}에 관한 주제가 한 번 더 돌아와 살펴볼 기회를 준다는 거예요."}],"card":"this_year"},"YR_R_chung":{"tags":["yrrel"],"v":[{"en":"{year}'s animal, the {yb}, clashes with {pAnimal}, the {nb}. In this tradition a clash means movement, so {area} may see some change.","ko":"{year}년의 동물 {yb}이(가) {pAnimal}인 {nb}와(과) 부딪쳐요. 이 전통에서 부딪침은 움직임을 뜻해서, {area} 쪽에 변화가 생길 수 있어요."}],"card":"this_year"},"YR_R_hap":{"tags":["yrrel"],"v":[{"en":"{year}'s animal, {yb}, pairs up with {pAnimal}, {nb}, so {area} may draw closer or become more cooperative.","ko":"{year}년의 동물 {yb}이(가) {pAnimal}인 {nb}와(과) 짝을 이뤄요. 그래서 {area}이(가) 가까워지거나 더 잘 협력하게 될 수 있어요."}],"card":"this_year"},"YR_R_samhap":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, completes a traditional trio of animals ({trio}) with your chart, gathering {samEl} energy, so separate efforts may start pulling in one direction.","ko":"{year}년의 동물 {yb}이(가) 당신의 사주와 함께 전통적인 세 동물 무리({trio})를 완성해 {samEl} 기운을 모아요. 따로 하던 노력들이 한 방향으로 모이기 시작할 수 있어요."}],"card":"this_year"},"YR_R_banhap":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, joins {pAnimal} ({pair}) to make two of a three-animal team, a lighter form of the full group that leans toward {samEl}.","ko":"올해의 동물 {yb}이(가) {pAnimal}와(과) 손잡아({pair}) 세 동물 모둠 중 둘을 이뤄요. 온전한 모둠의 가벼운 형태로, {samEl} 쪽으로 기울어요."}],"card":"this_year"},"YR_R_fanghe":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, completes a seasonal group ({trio}) with your chart, gathering a strong wave of {samEl} energy for the year.","ko":"올해의 동물 {yb}이(가) 당신의 사주와 함께 계절 묶음({trio})을 완성해서, 그해에 {samEl} 기운이 크게 모여요."}],"card":"this_year"},"YR_R_sanxing":{"tags":["yrrel"],"v":[{"en":"{year} is a year for tidying rules, paperwork, and agreements: its animal, {yb}, forms a tense trio with {trio2} in your chart, so careful follow-through helps.","ko":"{year}년은 규칙·서류·약속을 정리하기 좋은 해예요. 그해의 동물 {yb}이(가) 당신 사주의 {trio2}와(과) 팽팽한 세 동물 묶음을 이뤄서, 꼼꼼한 마무리가 도움이 돼요."}],"card":"this_year"},"YR_R_xing":{"tags":["yrrel"],"v":[{"en":"This year's {yb} rubs a little against {pAnimal}, the {nb}, which makes {year} a good year to keep agreements clear and to be patient with small frictions.","ko":"올해의 {yb}은(는) {pAnimal}, 곧 {nb}와(과) 살짝 부딪쳐요. 그래서 {year}년은 약속을 분명히 하고 작은 마찰에 너그러워지기 좋은 해예요."}],"card":"this_year"},"YR_R_zixing":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, matches {pAnimal}, which makes {year} a year to notice when one worry keeps coming back and to set it down.","ko":"올해의 동물 {yb}이(가) {pAnimal}와(과) 같아요. 그래서 {year}년은 같은 걱정이 되풀이될 때 알아차리고 내려놓기 좋은 해예요."}],"card":"this_year"},"YR_R_ganhe":{"tags":["yrrel"],"v":[{"en":"{year}'s element, {ys}, pairs up with {pElem}, {ns}, so an offer, attraction, or partnership connected with {area} may feel unusually magnetic.","ko":"{year}년의 기운 {ys}이(가) {pElem}인 {ns}와(과) 짝을 이뤄요. 그래서 {area}와(과) 관련된 제안이나 끌림, 협력이 유난히 강하게 당겨질 수 있어요."}],"card":"this_year"},"YR_R_ganchong":{"tags":["yrrel"],"v":[{"en":"{year}'s element, {ys}, clashes with {pElem}, {ns}, which can show up as a push to rethink {area}.","ko":"{year}년의 기운 {ys}이(가) {pElem}, 곧 {ns}와(과) 맞부딪쳐요. {area}을(를) 다시 생각해 보게 되는 계기로 나타날 수 있어요."},{"en":"In {year}, the year's {ys} runs into {pElem}, {ns}, and that friction can nudge you to look at {area} with fresh eyes.","ko":"{year}년에는 그해의 {ys}이(가) {pElem}, 곧 {ns}와(과) 마주쳐요. 그 마찰이 {area}을(를) 새로운 눈으로 보게 이끌 수 있어요."},{"en":"The {ys} energy of {year} pushes against {pElem}, {ns}, which may prompt a second look at {area}.","ko":"{year}년의 {ys} 기운이 {pElem}, 곧 {ns}을(를) 밀어내서 {area}을(를) 한 번 더 돌아보게 될 수 있어요."},{"en":"In {year}, {pElem}, {ns}, meets a clashing {ys}, so {area} can be where you feel a pull to adjust.","ko":"{year}년에는 {pElem}, 곧 {ns}이(가) 부딪치는 기운 {ys}을(를) 만나요. 그래서 {area}에서 조정하고 싶은 마음이 들 수 있어요."},{"en":"An element clash arrives in {year} between {ys} and {pElem}, {ns}; it's a traditional sign that {area} could use a fresh look.","ko":"{year}년에는 {ys}와(과) {pElem}, 곧 {ns} 사이에 기운의 부딪침이 와요. 전통적으로 {area}을(를) 새롭게 살펴보라는 신호로 읽어요."},{"en":"When {year}'s {ys} collides with {pElem}, {ns}, you may feel ready to shake up {area}.","ko":"{year}년의 {ys}이(가) {pElem}, 곧 {ns}와(과) 부딪치면, {area}을(를) 다루는 방식을 바꿔 보고 싶어질 수 있어요."},{"en":"You may notice some friction around {area} in {year}: the year's {ys} opposes {pElem}, {ns}, and that can open the door to a change of plan.","ko":"{year}년에는 {area} 쪽에서 마찰이 느껴질 수 있어요. 올해의 {ys}이(가) {pElem}, 곧 {ns}와(과) 맞서면서 계획을 바꿀 문이 열리기도 해요."}],"card":"this_year"},"YR_STAGE":{"tags":["yrstage"],"v":[{"en":"On the traditional growth cycle, {year}'s animal, the {yb}, puts your core element at {stg}.","ko":"전통적인 성장의 순환으로 보면, {year}년의 동물인 {yb}은(는) 나의 중심 기운을 {stg}에 놓아요."},{"en":"Read through the old cycle of growth and rest, {year}'s {yb} sets your core element at {stg}.","ko":"자라고 쉬는 오래된 순환으로 읽으면, {year}년의 {yb}에서 나의 중심 기운은 {stg}에 자리해요."},{"en":"{year} brings the {yb}, and on the traditional growth cycle that places your core element at {stg}.","ko":"{year}년에는 {yb}이(가) 찾아오고, 전통적인 성장의 순환에서 이때 나의 중심 기운은 {stg}에 있어요."},{"en":"Look at {year} through the cycle of growth and rest: with the {yb} in charge, your core element lands on {stg}.","ko":"{year}년을 자라고 쉬는 순환으로 바라보면, {yb}이(가) 한 해를 맡는 동안 나의 중심 기운은 {stg}에 닿아요."},{"en":"Your core element sits at {stg} on the traditional growth cycle when it meets the {yb}, the animal of {year}.","ko":"나의 중심 기운이 {year}년의 동물 {yb}을(를) 만나면, 전통적인 성장의 순환에서 {stg}에 앉아요."},{"en":"The traditional growth cycle marks {year}'s animal, the {yb}, as the point where your core element reaches {stg}.","ko":"전통적인 성장의 순환은 {year}년의 동물 {yb}을(를) 나의 중심 기운이 {stg}에 이르는 자리로 표시해요."},{"en":"Where does your core element stand in {year}? With the {yb} as the year's animal, the growth cycle puts it at {stg}.","ko":"{year}년에 나의 중심 기운은 어디쯤 서 있을까요? 그해의 동물 {yb}을(를) 보면, 성장의 순환은 {stg}을(를) 가리켜요."},{"en":"Set against the {yb} of {year}, your core element is at {stg} in the traditional growth cycle.","ko":"{year}년의 {yb}에 견주어 보면, 전통적인 성장의 순환에서 나의 중심 기운은 {stg}에 있어요."},{"en":"In the growth-cycle reading, the {yb} is the animal for {year}, and your core element is placed at {stg} there.","ko":"성장의 순환 풀이에서는 {yb}이(가) {year}년의 동물이에요. 거기서 나의 중심 기운은 {stg}에 놓여요."},{"en":"Counting around the growth cycle, {year}'s {yb} lands your core element on {stg}.","ko":"성장의 순환을 따라 세어 가면, {year}년의 {yb}에서 나의 중심 기운은 {stg}에 내려앉아요."},{"en":"With the {yb} as the animal of {year}, the growth cycle sets your core element at {stg}.","ko":"{yb}을(를) {year}년의 동물로 두면, 성장의 순환은 나의 중심 기운을 {stg}에 세워요."},{"en":"The growth cycle puts your core element at {stg} when {year}'s animal, the {yb}, comes into view.","ko":"{year}년의 동물 {yb}이(가) 눈앞에 오면, 성장의 순환은 나의 중심 기운을 {stg}에 두어요."}],"card":"this_year"},"DY_STAGE":{"tags":["dystage"],"v":[{"en":"In the traditional life-cycle reading, this decade's animal, {nowZhi}, puts your core element at {stg}{stgNote}.","ko":"전통의 생애 흐름 읽기에서, 이 10년의 동물 {nowZhi}은(는) 당신의 중심 기운을 {stg}에 놓아요{stgNote}."}],"card":"luck"},"DY_EVEN":{"tags":["decade:even"],"v":[{"en":"Your current and coming 10-year cycles come out even on our measure, so we don't single out a most active or growing decade.","ko":"우리 기준으로 보면 지금과 앞으로의 10년 대운이 고르게 나와서, 힘이 가장 큰 10년이나 성장하는 10년을 따로 고르지 않아요."},{"en":"On our measure, your current and coming 10-year cycles are about level, so no decade is marked as most active or growing.","ko":"우리 기준으로는 지금과 앞으로의 10년 대운이 거의 같은 수준이라, 힘이 가장 큰 10년이나 성장하는 10년으로 따로 표시하지 않아요."}],"card":"luck"},"LV_W_none":{"tags":["lvw:none"],"v":[{"en":"Wealth symbols, which we read here as what draws you and how you give and share, don't appear in your chart, so attraction may grow slowly, through shared time rather than a sudden spark.","ko":"재성(財星)은 여기서 \"무엇에 끌리는지, 어떻게 주고 나누는지\"로 읽는데, 사주에 보이지 않아요. 그래서 끌림이 갑작스러운 불꽃보다 함께한 시간을 통해 천천히 자랄 수 있어요."}],"card":"love"},"LV_W_some":{"tags":["lvw:some"],"v":[{"en":"Your chart holds some wealth signs (counting the ones beneath the surface), which we read here as what draws you and how you give and share: care may come out as generosity and practical help.","ko":"사주에 재물 표시가 어느 정도 있어요(겉에 드러나지 않은 것까지 세면요). 여기서는 무엇에 끌리는지, 어떻게 주고 나누는지로 읽어요. 마음이 너그러움과 실질적인 도움으로 나올 수 있어요."},{"en":"Some wealth signs show up in your chart, hidden ones included. Here we read them as what attracts you and how you give and share, so your care can take the form of generosity and hands-on help.","ko":"숨은 것까지 합치면 사주에 재물 표시가 조금 보여요. 여기서는 끌리는 것과 주고 나누는 방식으로 읽어요. 그래서 챙기는 마음이 너그러움과 손에 잡히는 도움의 모습이 되기도 해요."},{"en":"There's a moderate amount of wealth in your chart, counting the signs below the surface. We take it to describe what pulls you in and the way you give and share: warmth that may come through as open-handedness and practical support.","ko":"겉 아래 숨은 표시까지 세면 사주에 재물 기운이 적당히 있어요. 이것을 무엇에 마음이 끌리고 어떻게 주고 나누는지로 풀어요. 따뜻함이 후한 인심과 현실적인 도움으로 전해질 수 있어요."},{"en":"Wealth signs, including some tucked beneath the surface, appear in your chart in a modest amount. Read here as what you're drawn to and how you share, they may show affection as generosity and useful help.","ko":"속에 숨은 것까지 포함하면 사주에 재물 표시가 알맞게 있어요. 여기서는 끌리는 대상과 나누는 방식으로 읽는데, 애정이 너그러움과 쓸모 있는 도움으로 드러날 수 있어요."},{"en":"With a fair share of wealth signs (hidden ones counted), your chart points to what attracts you and how you offer yourself to others. Your caring may be expressed through generous gestures and real, practical help.","ko":"재물 표시(숨은 것 포함)가 알맞게 자리해서, 무엇에 끌리는지와 다른 사람에게 어떻게 마음을 내어 주는지를 보여 줘요. 당신의 챙김은 넉넉한 몸짓과 실제로 도움이 되는 일로 나올 수 있어요."},{"en":"Counting the hidden layer, wealth shows up in your chart to a moderate degree. In this reading it speaks to what you're drawn to and how you give and share, with care that may arrive as generosity and down-to-earth help.","ko":"숨은 층까지 세어 보면 사주에 재물 기운이 중간쯤 들어 있어요. 이 풀이에서는 끌리는 것과 주고 나누는 모습을 말해 주고, 챙기는 마음이 너그러움과 현실적인 도움으로 다가올 수 있어요."},{"en":"Your chart carries a moderate presence of wealth signs, counting the hidden ones too. We read that as a picture of what draws you and how you give, and it suggests love that may be shown through generosity and practical help.","ko":"숨은 것까지 더하면 사주에 재물 표시가 무난하게 있어요. 이것을 무엇이 마음을 끌고 어떻게 베푸는지를 그린 그림으로 읽어요. 사랑이 넉넉함과 실용적인 도움으로 표현될 수 있어요."},{"en":"Including the hidden layer, your chart has some wealth signs. Here they describe what attracts you and the way you give and share, so your care may take shape as generous acts and practical support.","ko":"숨은 층을 넣으면 사주에 재물 표시가 얼마간 있어요. 여기서는 마음이 끌리는 것과 주고 나누는 방식을 말해 주고, 그래서 챙김이 후한 행동과 실질적인 뒷받침으로 나타날 수 있어요."},{"en":"A middle amount of wealth signs (hidden ones counted) sits in your chart. We use it to read what you're drawn to and how you give and share, which may show up as generosity and help you can actually use.","ko":"재물 표시(숨은 것 포함)가 중간 정도로 사주에 놓여 있어요. 끌리는 것과 주고 나누는 방식을 읽는 데 쓰는데, 너그러움과 실제로 쓸 수 있는 도움으로 드러날 수 있어요."}],"card":"love"},"LV_W_many":{"tags":["lvw:many"],"v":[{"en":"Your chart holds plenty of wealth symbols, hidden ones included, which we read here as what draws you and how you give and share, so your interests may run in many directions; choosing depth helps.","ko":"사주에 재물의 기운이 숨은 것까지 합쳐 넉넉해요. 여기서는 \"무엇에 끌리는지, 어떻게 주고 나누는지\"로 읽어요. 관심이 여러 방향으로 뻗을 수 있으니 깊이를 고르는 게 도움이 돼요."},{"en":"Wealth symbols are plentiful in your chart. Here they stand for what attracts you and how you give, so your interests can spread several ways, and picking one to go deep on can help.","ko":"사주에 재물의 기운이 풍부해요. 여기서는 끌리는 것과 내가 주는 방식을 뜻해서, 관심이 여러 갈래로 퍼질 수 있어요. 하나를 골라 깊이 파 보면 도움이 돼요."},{"en":"There's no shortage of wealth symbols in your chart. They point to what pulls you in and how you share, which means your attention may scatter, and choosing depth can steady it.","ko":"사주에 재물의 기운이 모자라지 않아요. 끌어당기는 것과 나누는 방식을 가리키니 주의가 흩어질 수 있어요. 깊이를 정하면 중심이 잡혀요."},{"en":"Many wealth symbols appear in your chart, counting the hidden ones. They reflect what you're drawn to and how you share what you have, so your interests often fan out; going deep on one helps.","ko":"숨은 것까지 세면 사주에 재물의 기운이 많이 보여요. 끌리는 대상과 가진 것을 나누는 방식을 비춰 줘서, 관심이 자주 사방으로 펼쳐져요. 하나를 깊이 파 보면 도움이 돼요."}],"card":"love"},"LV_A_none":{"tags":["lva:none"],"v":[{"en":"Nothing in your chart reads as outside rules or structure, so you may prefer a relationship that builds its own rules rather than following a script.","ko":"관성(官星)은 여기서 \"약속과 틀\"로 읽는데, 사주에 보이지 않아요. 정해진 대본을 따르기보다 둘만의 규칙을 만들어 가는 관계를 더 좋아할 수 있어요."}],"card":"love"},"LV_A_jeong":{"tags":["lva:some"],"v":[{"en":"The part of your chart we read as commitment and structure leans to its steady, rule-keeping side, so clear, well-defined commitments may feel right.","ko":"이 풀이에서 약속과 틀로 읽는 부분이 꾸준하고 규칙을 지키는 쪽으로 기울어 있어요. 그래서 분명하고 또렷한 약속이 잘 맞을 수 있어요."},{"en":"Commitment and structure show up in your chart in their calm, by-the-book form, so steady promises with clear terms tend to feel like a good fit.","ko":"사주에서 약속과 틀이 차분하고 원칙대로인 모습으로 나타나요. 그래서 조건이 분명한 꾸준한 약속이 잘 어울린다고 느끼는 편이에요."},{"en":"In this reading, the commitment-and-structure side of your chart favors order and reliability, and a relationship built on clear, dependable promises may feel right.","ko":"이 풀이에서 사주의 약속과 틀 쪽은 질서와 믿음직함을 좋아해요. 분명하고 믿을 만한 약속 위에 세운 관계가 편안하게 느껴질 수 있어요."}],"card":"love"},"LV_A_pyeon":{"tags":["lva:some"],"v":[{"en":"The part of your chart that stands for commitment and structure leans toward intensity: challenge can feel attractive, and clear agreements help a bond last.","ko":"사주에서 약속과 틀을 뜻하는 부분이 강렬함 쪽으로 기울어 있어요. 도전이 매력적으로 느껴질 수 있고, 분명한 약속이 관계를 오래가게 해 줘요."},{"en":"When it comes to commitment and structure, your chart tilts toward intensity: you may be drawn to a challenge, and clear agreements can help a bond last.","ko":"약속과 틀에 관해서는 사주가 강렬함 쪽으로 기울어요. 도전에 마음이 가기도 하고, 또렷한 약속은 관계가 오래가도록 도와줄 수 있어요."}],"card":"love"},"LV_A_mixed":{"tags":["lva:some"],"v":[{"en":"Your chart holds both a steady, by-the-rules energy and a more intense, demanding one, so steadiness and intensity may each appeal at different times; saying which one you need today helps both of you.","ko":"사주에 차분하고 규칙을 지키는 기운과 더 강렬하고 까다로운 기운이 함께 있어서, 때로는 안정이, 때로는 강렬함이 끌릴 수 있어요. 오늘은 어느 쪽이 필요한지 말해 주면 두 사람 모두에게 도움이 돼요."},{"en":"Your chart carries calm structure alongside a sharper, more driven streak, so you may be drawn to quiet reliability one season and a stronger spark in another; telling your partner which you need helps.","ko":"사주에 차분한 짜임새와 더 날카롭고 추진력 있는 기질이 나란히 있어요. 어느 때는 조용한 믿음직함에, 어느 때는 더 강한 불꽃에 끌릴 수 있으니, 지금 필요한 쪽을 상대에게 말해 주면 좋아요."},{"en":"Your chart mixes a steady, rule-keeping side with a bolder, high-intensity side, which can leave you torn between comfort and excitement; a quick check-in about what you want right now keeps things clear.","ko":"사주에 꾸준히 규칙을 지키는 면과 더 대담하고 강렬한 면이 섞여 있어서, 편안함과 설렘 사이에서 마음이 오갈 수 있어요. 지금 원하는 게 무엇인지 짧게 나눠 보면 서로 헷갈리지 않아요."},{"en":"A calm, dependable streak and an intense, driven streak sit together in your chart, so a steady partner and an intense one may each feel appealing depending on the day. Naming your mood out loud makes love easier for both of you.","ko":"차분하고 믿음직한 기질과 강렬하고 밀어붙이는 기질이 사주에 함께 있어서, 날에 따라 안정적인 사람도, 강렬한 사람도 매력적으로 느껴질 수 있어요. 지금 기분을 소리 내어 말하면 사랑이 두 사람 모두에게 한결 쉬워져요."},{"en":"Because your chart holds both a reliable side and a daring, high-energy side, what attracts you can shift between dependable and bold. Sharing which mood you're in helps your partner meet you there.","ko":"사주에 믿음직한 면과 대담하고 힘이 넘치는 면이 모두 있어서, 끌리는 모습이 든든함과 과감함 사이를 오갈 수 있어요. 어떤 기분인지 나누면 상대가 그 마음에 맞춰 다가올 수 있어요."},{"en":"With orderly calm and fiery intensity paired in your chart, you may crave stability at times and a bit of thrill at others. A simple \"tonight I need this\" goes a long way.","ko":"질서 있는 차분함과 불같은 강렬함이 사주에 짝지어 있어서, 어떤 때는 안정을, 어떤 때는 약간의 짜릿함을 바랄 수 있어요. \"오늘은 이게 필요해\"라는 한마디가 큰 힘이 돼요."},{"en":"Your chart makes room for both gentle order and strong intensity, so your taste in love can swing between the two. Telling your partner where you are today keeps you in step.","ko":"사주에 부드러운 질서와 강한 열기가 모두 자리하고 있어서, 사랑에서의 취향이 둘 사이를 오갈 수 있어요. 오늘 내 마음이 어디쯤인지 말해 주면 발걸음이 맞아요."},{"en":"A blend of steady order and bold intensity in your chart may pull you toward calm on some days and excitement on others. Say which one you're craving, and your partner doesn't have to guess.","ko":"꾸준한 질서와 대담한 강렬함이 사주에 섞여 있어서, 어떤 날은 차분함이, 어떤 날은 설렘이 당길 수 있어요. 바라는 쪽을 말해 주면 상대가 짐작하지 않아도 돼요."}],"card":"love"},"LV_STAGE":{"tags":["dbstage"],"v":[{"en":"Read against the animal of the day you were born, your core element sits at {stg}. Take it as a mood for how you approach closeness, not a prediction.","ko":"태어난 날의 동물에 비춰 보면 당신의 중심 기운은 {stg}에 있어요. 가까워지는 방식의 분위기로 읽어 주세요. 예측이 아니에요."},{"en":"Korean tradition places your core element at {stg} when measured from your birth-day animal. Take it as a mood for how you get close, not a forecast.","ko":"전통에서는 태어난 날의 동물을 기준으로 당신의 중심 기운을 {stg}에 놓아요. 가까워지는 방식의 분위기로만 받아들이세요. 앞날을 맞히는 말은 아니에요."},{"en":"Measured from your birth-day animal, your core element lands at {stg}. Think of it as a flavor of how you open up to others, not a prediction.","ko":"태어난 날의 동물에서 재어 보면 당신의 중심 기운은 {stg}에 닿아요. 사람들에게 마음을 여는 결 정도로 생각해 주세요. 예측은 아니에요."},{"en":"Starting from the animal of the day you were born, the old life-cycle reading puts your core element at {stg}. It's a gentle hint about how you come close to people, not a forecast of what will happen.","ko":"태어난 날의 동물에서 출발하면, 옛 생애 흐름 읽기는 당신의 중심 기운을 {stg}에 두어요. 사람에게 다가가는 모습을 살짝 비추는 힌트일 뿐, 앞으로 일어날 일을 말하는 건 아니에요."},{"en":"In the traditional life-cycle reading, based on your birth-day animal, your core element sits at {stg}. Treat this as a mood around closeness rather than a prediction.","ko":"태어난 날의 동물을 바탕으로 한 전통의 생애 흐름 읽기에서, 당신의 중심 기운은 {stg}에 있어요. 가까움을 둘러싼 분위기로 받아들이고, 예측으로는 보지 마세요."},{"en":"Based on the animal of the day you were born, your core element is at {stg}. This colors how you approach closeness; it doesn't predict anything.","ko":"태어난 날의 동물을 기준으로 당신의 중심 기운은 {stg}에 있어요. 가까워지는 방식에 색을 입힐 뿐, 무언가를 예측하지는 않아요."},{"en":"Here's a small lens on love: read from your birth-day animal, your core element sits at {stg}. Use it as a mood for closeness, not a prediction.","ko":"사랑을 보는 작은 렌즈 하나예요. 태어난 날의 동물에서 읽으면 당신의 중심 기운은 {stg}에 있어요. 가까움의 분위기로만 쓰시고 예측으로는 쓰지 마세요."},{"en":"When the life-cycle reading starts from the animal of your birth day, your core element holds {stg}. It describes a mood in how you get close, nothing more fixed than that.","ko":"생애 흐름 읽기를 태어난 날의 동물에서 시작하면, 당신의 중심 기운은 {stg} 단계에 머물러요. 가까워질 때의 분위기를 말해 줄 뿐, 그보다 단단히 정해진 건 없어요."},{"en":"Your birth-day animal places your core element at {stg} in the traditional life cycle. See it as a tone for how you approach closeness, not as a forecast.","ko":"태어난 날의 동물은 전통의 생애 흐름에서 당신의 중심 기운을 {stg}에 놓아요. 가까워지는 방식의 색조로 보시고, 앞날을 맞히는 말로는 보지 마세요."}],"card":"love"},"BL_FEEL_generic":{"tags":[],"v":[{"en":"You may notice that some kinds of days leave you more settled than others.","ko":"어떤 날은 유난히 마음이 차분히 가라앉는다고 느낄 수 있어요."}],"card":"habits_candidate"},"BL_PICK_none":{"tags":[],"v":[{"en":"{balEl} doesn't appear among the {total} visible characters, and it's one of the elements that balance your chart, so a little more of it may steady you.","ko":"{balEl}은(는) 보이는 {total}자 가운데 하나도 없고, 사주의 균형을 잡아 주는 기운 가운데 하나예요. 그래서 조금 더하면 마음이 안정되는 편이에요."},{"en":"None of the {total} visible characters in your chart is {balEl}, which is one of the elements that balance it, so adding a little may feel steadying.","ko":"사주에 보이는 {total}자 중에 {balEl}은(는) 하나도 없어요. 균형을 잡아 주는 기운 가운데 하나라서, 조금 더하면 마음이 차분해질 수 있어요."},{"en":"Of the {total} visible characters, not one is {balEl}, an element that helps balance your chart, so bringing in a little more may settle you.","ko":"보이는 {total}자 가운데 {balEl}은(는) 하나도 없어요. 사주의 균형을 돕는 기운이라 조금 보태면 안정감이 생길 수 있어요."},{"en":"{balEl} is missing from your {total} visible characters, and it's one of the elements that balance your chart, so a bit more of it may feel grounding.","ko":"{balEl}은(는) 보이는 {total}자 어디에도 없는데, 사주의 균형을 잡는 기운 중 하나예요. 조금 더하면 든든하게 느껴질 수 있어요."},{"en":"Your {total} visible characters hold no {balEl}, yet it's one of the balancing elements for your chart, so a small addition may bring some calm.","ko":"보이는 {total}자에는 {balEl}이(가) 없지만, 사주의 균형에 도움이 되는 기운이에요. 조금만 더해도 마음이 편안해질 수 있어요."},{"en":"Count the {total} visible characters in your chart and you won't find {balEl}, an element that helps balance things, so a little extra may feel steadying.","ko":"사주에 보이는 {total}자를 세어 봐도 {balEl}은(는) 찾을 수 없어요. 균형을 돕는 기운이라, 조금 더하면 마음이 안정될 수 있어요."},{"en":"Among the {total} visible characters, {balEl} doesn't show up, and since it helps balance your chart, adding a bit of it may bring some ease.","ko":"보이는 {total}자 중에는 {balEl}이(가) 나타나지 않아요. 사주의 균형을 돕는 기운이니, 조금 더하면 한결 편해질 수 있어요."}],"card":"habits_candidate"},"GL_CHARS_6":{"tags":["glossary"],"v":[{"en":"Without a birth time, your chart shows six signs, an element and an animal for each of your birth year, month, and day; the element counts in this reading use only those six.","ko":"태어난 시간이 없으면 사주에는 여섯 가지 표시가 보여요. 태어난 해, 달, 날마다 기운 하나와 동물 하나씩이에요. 이 풀이에서 기운의 개수는 그 여섯 가지만 센 거예요."}],"card":"common"},"OV_DECADE_later":{"tags":["dy:single"],"v":[{"en":"By our own scoring, your most active decade comes later in life.","ko":"우리 자체 채점으로 보면, 힘이 가장 큰 10년은 인생 후반에 와요."}],"card":"overview"},"YR_R_chung_B":{"tags":["yrrel"],"v":[{"en":"A clash between the year's {yb} and {pAnimal}, the {nb}, points to some reshuffling in {area}.","ko":"올해의 {yb}와(과) {pAnimal}, 곧 {nb} 사이의 부딪침은 {area} 쪽이 조금 새로 짜일 수 있음을 가리켜요."}],"card":"this_year"},"YR_R_hap_B":{"tags":["yrrel"],"v":[{"en":"{yb} also pairs up with {pAnimal}, the {nb}, a sign of cooperation around {area}.","ko":"{yb}은(는) {pAnimal}인 {nb}와(과)도 짝을 이뤄서, {area} 쪽에 협력의 신호가 돼요."}],"card":"this_year"},"YR_R_ganhe_B":{"tags":["yrrel"],"v":[{"en":"The year's element, {ys}, also pairs up with {pElem}, {ns}, so offers tied to {area} may catch your attention.","ko":"그해의 기운 {ys}은(는) {pElem}인 {ns}와(과)도 짝을 이뤄, {area}와(과) 이어진 제안이 눈길을 끌 수 있어요."}],"card":"this_year"},"YR_R_ganchong_B":{"tags":["yrrel"],"v":[{"en":"This year's element, {ys}, clashes with {pElem}, {ns}, a nudge to rethink {area}.","ko":"올해의 기운 {ys}이(가) {pElem}, 곧 {ns}와(과) 부딪쳐서, {area}을(를) 다시 생각해 보라고 살짝 등을 떠밀어요."}],"card":"this_year"},"YR_STAGE_B":{"tags":["yrstage"],"v":[{"en":"For {year}, you're in {stg}.","ko":"{year}년, 당신은 {stg} 자리에 서 있어요."},{"en":"In {year}, you're at {stg}.","ko":"{year}년에는 {stg}에 있어요."},{"en":"{year} sits at {stg}.","ko":"{year}년은 {stg}에 자리해요."},{"en":"{year} reads as {stg}.","ko":"{year}년은 {stg}(으)로 읽혀요."},{"en":"Your place in {year}'s cycle: {stg}.","ko":"{year}년의 흐름 속 당신의 자리는 {stg}(이)에요."},{"en":"In {year}, the cycle marks {stg}.","ko":"{year}년에 순환은 {stg}을(를) 가리켜요."},{"en":"On the cycle, {year} sits at {stg}.","ko":"순환으로 보면 {year}년은 {stg}에 앉아 있어요."},{"en":"Reading {year}, the cycle points to {stg}.","ko":"{year}년을 읽어 보면, 흐름은 {stg}을(를) 짚어요."},{"en":"Looking at {year}, the cycle points to {stg}.","ko":"{year}년을 보면 순환은 {stg}을(를) 가리켜요."},{"en":"The growth cycle places {year} at {stg}.","ko":"성장의 흐름에서 {year}년은 {stg}에 놓여요."},{"en":"Here, {year} corresponds to {stg}.","ko":"여기서 {year}년은 {stg}에 해당해요."},{"en":"Across the cycle, {year} shows {stg}.","ko":"순환을 따라가면 {year}년은 {stg}을(를) 보여 줘요."}],"card":"this_year"},"YR_DY_B":{"tags":["dy:single"],"v":[{"en":"{year} still falls inside your {dyGz} decade.","ko":"{year}년도 여전히 {dyGz} 대운 안에 있어요."}],"card":"this_year"},"DY_SCORING_NOTE":{"tags":["scoring-note"],"v":[{"en":"Most active and Growing decades are marked by our own scoring, not a traditional rule (see How We Calculate); only cycles from now through the next thirty years are marked. A decade without a mark isn't a bad decade.","ko":"'힘이 큰 시기'와 '성장하는 시기' 표시는 전통 규칙이 아닌 우리 자체 채점이에요(How We Calculate 참고). 지금부터 30년 안의 대운에만 표시해요. 표시가 없는 10년이 나쁜 시기라는 뜻은 아니에요."},{"en":"The Most active and Growing marks come from our own scoring, not from a traditional rule (see How We Calculate), and they cover only the cycles from now through the next thirty years. No mark doesn't mean a bad decade.","ko":"'힘이 큰 시기'와 '성장하는 시기' 표시는 전통 규칙이 아니라 우리 자체 채점에서 나온 것이고(How We Calculate 참고), 지금부터 30년 안의 대운에만 붙어요. 표시가 없다고 나쁜 10년인 것은 아니에요."},{"en":"Marks like Most active and Growing are our own scoring, not a traditional rule (see How We Calculate). Only cycles from now through the next thirty years get one, and a decade with no mark isn't a bad decade.","ko":"'힘이 큰 시기', '성장하는 시기' 같은 표시는 전통 규칙이 아닌 우리 자체 채점이에요(How We Calculate 참고). 지금부터 30년 안의 대운에만 붙고, 표시가 없는 10년이 나쁜 시기라는 뜻은 아니에요."},{"en":"Our own scoring, not a traditional rule, decides the Most active and Growing marks (see How We Calculate), and only the cycles from now through the next thirty years can get one. A decade without a mark isn't a bad one.","ko":"'힘이 큰 시기'와 '성장하는 시기' 표시는 전통 규칙이 아니라 우리 자체 채점으로 정해요(How We Calculate 참고). 지금부터 30년 안의 대운만 표시 대상이고, 표시가 없는 10년이 나쁜 10년은 아니에요."},{"en":"Note: Most active and Growing are labels from our own scoring (see How We Calculate), not from a traditional rule, and they appear only within the next thirty years. Unmarked decades aren't bad decades.","ko":"참고로 '힘이 큰 시기'와 '성장하는 시기'는 전통 규칙이 아닌 우리 자체 채점의 이름표예요(How We Calculate 참고). 앞으로 30년 안에만 붙고, 표시 없는 10년이 나쁜 10년은 아니에요."},{"en":"Most active and Growing are our own scoring labels, not traditional rules (see How We Calculate), and only the next thirty years carry them. If a decade has no label, that doesn't make it a bad decade.","ko":"'힘이 큰 시기'와 '성장하는 시기'는 전통 규칙이 아닌 우리 자체 채점 이름표예요(How We Calculate 참고). 앞으로 30년만 대상이고, 이름표가 없다고 나쁜 10년인 것은 아니에요."}],"card":"luck"},"DY_BEST_LATER":{"tags":["decade:best"],"v":[{"en":"Most active decade: none within the next thirty years, so this timeline doesn't mark one.","ko":"힘이 가장 큰 10년: 앞으로 30년 안에는 없어서 이 흐름표에는 따로 표시하지 않아요."}],"card":"luck"},"BL_SPECIAL":{"tags":["special"],"v":[{"en":"For a chart with a pattern like yours, Saju teachers read this part in different ways.","ko":"당신과 같은 모양의 사주는 사주 선생님들도 이 부분을 다르게 읽기도 해요."},{"en":"Charts shaped like yours can be read in more than one way, and Saju teachers don't all agree on this part.","ko":"당신 같은 모양의 사주는 읽는 법이 한 가지가 아니고, 이 부분은 사주 선생님마다 의견이 갈리기도 해요."},{"en":"With a chart pattern like yours, different Saju teachers may read this section differently.","ko":"당신과 같은 사주 모양은 선생님에 따라 이 부분을 다르게 읽을 수 있어요."}],"card":"habits_candidate"},"BL_SEASON_summer_diff":{"tags":["season:summer"],"v":[{"en":"You were born in the summer months. One common reading, called season balancing, would add Water to cool a summer chart; your strength balance points elsewhere, so we list it as a separate view rather than mixing the two.","ko":"여름 달에 태어났어요. 계절 균형 맞추기(조후)라는 흔한 해석은 여름 사주에 물을 더해 식히지만, 당신 사주의 강약 균형은 다른 쪽을 가리켜서 두 가지를 섞지 않고 따로 적어 둘게요."}],"card":"habits_candidate"},"BL_SEASON_winter_diff":{"tags":["season:winter"],"v":[{"en":"You were born in the winter months. One common reading, called season balancing, would add Fire to warm a winter chart; your strength balance points elsewhere, so we list it as a separate view rather than mixing the two.","ko":"겨울 달에 태어났어요. 계절 균형 맞추기(조후)라는 흔한 해석은 겨울 사주에 불을 더해 데우지만, 당신 사주의 강약 균형은 다른 쪽을 가리켜서 두 가지를 섞지 않고 따로 적어 둘게요."}],"card":"habits_candidate"},"BL_PICK_two_none":{"tags":[],"v":[{"en":"Neither {balEl} nor {balEl2} appears among the {total} visible characters, and both help balance your chart; we start with {balEl}.","ko":"{balEl}과(와) {balEl2} 둘 다 보이는 {total}자 가운데 없고, 둘 다 사주의 균형을 잡아 줘요. 먼저 {balEl}부터 볼게요."}],"card":"habits_candidate"},"DY_BEST_PL":{"tags":["decade:best"],"v":[{"en":"Most active decades (our score): {bestList}. These cycles bring more of the elements that balance your chart, so effort may meet less friction.","ko":"힘이 가장 큰 10년(자체 채점): {bestList}. 이 대운들은 사주의 균형을 잡아 주는 기운을 더 많이 가져와서, 노력이 덜 부딪히며 나아가는 편이에요."}],"card":"luck"},"OV_DECADE_best_PL":{"tags":["dy:single"],"v":[{"en":"By our own scoring, the most active decades among your current and coming cycles are {bestList}.","ko":"우리 자체 채점으로, 지금과 앞으로의 대운 가운데 힘이 가장 큰 10년은 {bestList}(이)에요."}],"card":"overview"},"OV_SEASON_cusp_辰":{"tags":["season:cusp:辰"],"card":"overview","v":[{"en":"You were born in the last month of spring on the traditional seasonal calendar, the stretch that leads into summer. Tradition says Earth carries one season into the next, most strongly in that month's final days, so your birth season blends growth settling in with warmth on its way.","ko":"당신은 전통 계절 달력으로 봄의 마지막 달, 여름으로 이어지는 때에 태어났어요. 전통에서는 흙이 한 계절을 다음 계절로 넘겨준다고 보고, 그 힘이 그 달의 마지막 며칠에 가장 강하다고 해요. 그래서 당신이 태어난 계절에는 자리 잡는 성장과 다가오는 따뜻함이 섞여 있어요."}]},"OV_SEASON_cusp_未":{"tags":["season:cusp:未"],"card":"overview","v":[{"en":"You were born in the final month of summer on the traditional seasonal calendar, the stretch that leads into autumn. Traditionally, Earth carries one season into the next, most strongly in a month's last days, so your birth season blends summer's full warmth with the first signs of harvest.","ko":"당신은 전통 계절 달력으로 여름의 마지막 달, 가을로 이어지는 때에 태어났어요. 전통적으로 흙의 기운이 한 계절을 다음 계절로 넘겨준다고 보고, 그 힘은 달의 마지막 며칠에 가장 강해요. 그래서 당신이 태어난 계절에는 무르익은 한여름의 따뜻함과 수확의 첫 기미가 섞여 있어요."}]},"OV_SEASON_cusp_戌":{"tags":["season:cusp:戌"],"card":"overview","v":[{"en":"You were born in the final month of autumn on the traditional seasonal calendar, the stretch that leads into winter. In the traditional view, Earth carries one season over into the next, most strongly in the last days of such a month, so your birth season blends the harvest being gathered in with the first quiet of winter.","ko":"당신은 계절 흐름을 따르는 전통 달력으로 가을의 마지막 달, 겨울로 이어지는 때에 태어났어요. 전통에서는 흙 기운이 한 계절을 다음 계절로 넘겨준다고 보고, 그런 달의 끝 무렵에 가장 강하다고 여겨요. 그래서 당신이 태어난 계절에는 거두어들이는 수확과 겨울의 첫 고요가 섞여 있어요."}]},"OV_SEASON_cusp_丑":{"tags":["season:cusp:丑"],"card":"overview","v":[{"en":"You were born in the last month of winter by the traditional seasonal calendar, the stretch that leads into spring. Traditionally, Earth carries one season over into the next, most strongly in the final days of such a month, so your birth season blends deep rest and the first stirrings under the ground.","ko":"당신은 전통 계절 달력으로 겨울의 마지막 달, 봄으로 이어지는 때에 태어났어요. 전통에서는 흙의 기운이 한 계절을 다음 계절로 넘겨준다고 보고, 그런 달의 마지막 며칠에 그 힘이 가장 세다고 해요. 그래서 당신이 태어난 계절에는 깊은 쉼과 땅 밑에서 막 시작되는 움직임이 함께 섞여 있어요."}]},"HB_NOTICE":{"tags":[],"card":"habits","v":[{"en":"These are everyday routines for your reference, not a substitute for medical care. If you are worried about your body, please talk to a doctor. Linking the five elements to daily habits is traditional symbolism, not a statement about the condition of your body.","ko":"이 내용은 생활 습관 참고용이에요. 진단이나 치료를 대신하지 않아요. 몸이 걱정되면 의사와 상의해 주세요. 오행과 생활 습관을 잇는 것은 전통의 상징 풀이이고, 건강 상태를 말하는 것이 아니에요."},{"en":"Please treat this as a reference for daily routines. It is not a substitute for medical care, so if your body worries you, talk to a doctor. Connecting the five elements with daily habits is traditional symbolism; it says nothing about the condition of your body.","ko":"이 내용은 생활 습관 참고용이에요. 진단이나 치료를 대신하지 않아요. 몸이 걱정되면 의사와 상의해 주세요. 오행과 생활 습관을 잇는 것은 전통의 상징 풀이이고, 건강 상태를 말하는 것이 아니에요."},{"en":"Everything here is a reference for everyday routines and does not replace medical care. For any worry about your body, please talk to a doctor. Tying the five elements to daily habits is traditional symbolism, not a statement about the condition of your body.","ko":"이 내용은 생활 습관 참고용이에요. 진단이나 치료를 대신하지 않아요. 몸이 걱정되면 의사와 상의해 주세요. 오행과 생활 습관을 잇는 것은 전통의 상징 풀이이고, 건강 상태를 말하는 것이 아니에요."}]},"HB_FEEL_wood":{"tags":["hb:wood"],"card":"habits","v":[{"en":"You may feel steadier on days that begin with a little movement instead of a rush.","ko":"서두르는 대신 몸을 조금 움직이며 시작한 날에 더 차분해질 수 있어요."},{"en":"A day that feels stuck may loosen once you get up and start something small.","ko":"막힌 듯한 하루가 작은 일 하나를 시작하면 풀릴 수 있어요."},{"en":"You may notice your mood lift when you step outside before the day gets going.","ko":"하루가 본격적으로 시작되기 전에 밖으로 나서면 기분이 올라가는 걸 느낄 수 있어요."},{"en":"You may feel more like yourself when you give the morning a little stretch before the screens come on.","ko":"화면을 켜기 전에 아침에 가볍게 기지개를 켜면 더 나다운 기분이 들 수 있어요."},{"en":"Planting, watering, or just looking at a green plant may give your mood a gentle lift.","ko":"식물을 심거나 물을 주거나 그저 바라보기만 해도 기분이 살짝 올라갈 수 있어요."}]},"HB_MEAN_wood":{"tags":["hb:wood"],"card":"habits","v":[{"en":"Wood is the element of beginnings and growth, so habits that start your day gently and keep you stretching toward something may suit this chart.","ko":"나무는 시작과 성장의 기운이라서, 하루를 부드럽게 열고 무언가를 향해 계속 뻗어 가게 하는 습관이 이 사주에 어울릴 수 있어요."},{"en":"Traditionally, Wood stands for spring-like energy, so routines that restart you each morning may feel natural for you.","ko":"전통적으로 나무는 봄 같은 기운을 뜻해서, 매일 아침 다시 시작하게 해 주는 습관이 자연스럽게 느껴질 수 있어요."},{"en":"Wood is linked with growth and reaching upward, which fits habits that keep a little forward motion in every day.","ko":"나무는 성장과 위로 뻗는 모습과 이어져서, 매일 조금씩 앞으로 나아가는 느낌을 주는 습관과 잘 맞을 수 있어요."},{"en":"Because Wood is tied to spring, sprouting, and steady growth, habits that give each day a fresh start may feel supportive for you.","ko":"나무는 봄과 싹틈, 꾸준한 성장과 이어져 있어서, 하루마다 새 출발 느낌을 주는 습관이 든든하게 느껴질 수 있어요."},{"en":"Traditionally, Wood energy is about new shoots and upward growth, so routines that keep you gently moving forward may be a good match.","ko":"전통적으로 나무 기운은 새싹과 위로 자라는 성장을 뜻해서, 부드럽게 앞으로 나아가게 하는 습관이 잘 맞을 수 있어요."}]},"HB_ACT_wood":{"tags":["hb:wood"],"card":"habits","v":[{"en":"Open a window or step outside for five minutes when you wake up, before you pick up your phone.","ko":"일어나면 휴대폰을 집기 전에 창문을 열거나 5분 동안 밖에 나가 보세요."},{"en":"Add a short stretch to the same moment every day, such as right after you brush your teeth.","ko":"양치 직후처럼 매일 같은 순간에 짧은 스트레칭을 붙여 보세요."},{"en":"Plan tomorrow's first small step tonight, so the morning has a gentle place to begin.","ko":"내일의 첫 작은 걸음을 오늘 밤 정해 두어, 아침이 부드럽게 시작될 자리를 마련해 보세요."},{"en":"Take a ten-minute walk somewhere green this week and notice what you see.","ko":"이번 주에 초록이 있는 곳에서 10분 걸으며 눈에 들어오는 것을 살펴보세요."},{"en":"Spend a few minutes tending a plant, or just looking at one, before your day gets busy.","ko":"하루가 바빠지기 전에 몇 분 동안 화분을 돌보거나 가만히 바라보세요."}]},"HB_FEEL_fire":{"tags":["hb:fire"],"card":"habits","v":[{"en":"You may notice your mood lift after time with people you enjoy.","ko":"좋아하는 사람들과 시간을 보내고 나면 기분이 올라가는 걸 느낄 수 있어요."},{"en":"A day with no warm moment in it may feel flat to you.","ko":"따뜻한 순간이 하나도 없는 하루는 밋밋하게 느껴질 수 있어요."},{"en":"You may find that a little light and company can change the feel of a whole afternoon.","ko":"약간의 밝음과 함께하는 사람이 오후 전체의 분위기를 바꿔 놓는 걸 느낄 수 있어요."}]},"HB_MEAN_fire":{"tags":["hb:fire"],"card":"habits","v":[{"en":"Fire is the element of warmth and expression, so habits that bring light and company into your day may suit this chart.","ko":"불은 따뜻함과 표현의 기운이라서, 하루에 밝음과 사람을 들여오는 습관이 이 사주에 어울릴 수 있어요."},{"en":"Traditionally, Fire stands for warmth and connection, so routines built around sharing may feel good to you.","ko":"전통에서 불은 따뜻함과 이어짐을 뜻해서, 나누는 일을 중심으로 한 습관이 좋게 느껴질 수 있어요."},{"en":"Fire is linked with brightness and joy, which fits habits that put a little celebration into ordinary days.","ko":"불은 밝음과 즐거움과 이어져서, 평범한 날에 작은 기쁨을 넣어 주는 습관과 잘 맞을 수 있어요."}]},"HB_ACT_fire":{"tags":["hb:fire"],"card":"habits","v":[{"en":"Send one friendly message to someone before lunch.","ko":"점심 전에 누군가에게 다정한 메시지를 하나 보내 보세요."},{"en":"Keep one evening this week for a meal or a call with someone you like.","ko":"이번 주 하루 저녁은 좋아하는 사람과의 식사나 통화를 위해 비워 두세요."},{"en":"Put a lamp or a bright window where you start your day.","ko":"하루를 시작하는 자리에 조명이나 밝은 창을 두어 보세요."},{"en":"Do one small thing today just because it makes you smile.","ko":"오늘 그냥 웃음이 나는 일 하나를 해 보세요."}]},"HB_FEEL_earth":{"tags":["hb:earth"],"card":"habits","v":[{"en":"You may feel best when your days have a steady beat.","ko":"하루에 꾸준한 박자가 있을 때 가장 편안할 수 있어요."},{"en":"A scattered schedule may leave you feeling unsettled.","ko":"들쭉날쭉한 일정은 마음을 어수선하게 만들 수 있어요."},{"en":"You may notice that regular times for meals and rest make everything else easier.","ko":"식사와 쉬는 시간이 일정하면 나머지가 다 수월해지는 걸 느낄 수 있어요."}]},"HB_MEAN_earth":{"tags":["hb:earth"],"card":"habits","v":[{"en":"Earth is the element of steadiness, so regular times for eating, resting, and starting may suit this chart.","ko":"흙은 안정의 기운이라서, 먹고 쉬고 시작하는 시간이 일정한 습관이 이 사주에 어울릴 수 있어요."},{"en":"Traditionally, Earth stands for the ground under your feet, so routines you can repeat may become your anchor.","ko":"전통에서 흙은 발 딛는 땅을 뜻해요. 그래서 되풀이하기 쉬운 습관이 든든한 닻이 될 수 있어요."},{"en":"Earth is linked with patience and reliability, which fits habits that are simple enough to keep for a long time.","ko":"흙은 인내와 믿음직스러움과 이어져서, 오래 이어 갈 수 있을 만큼 단순한 습관과 잘 맞을 수 있어요."}]},"HB_ACT_earth":{"tags":["hb:earth"],"card":"habits","v":[{"en":"Pick a regular time for one meal this week and keep it.","ko":"이번 주에 한 끼니의 시간을 정해 꾸준히 지켜 보세요."},{"en":"Choose a bedtime window for the next seven days and stay inside it.","ko":"앞으로 7일 동안 잠드는 시간대를 정하고 그 안에서 지내 보세요."},{"en":"Tidy one small spot at the same time each day, such as your desk after dinner.","ko":"저녁 식사 후 책상처럼, 매일 같은 시간에 작은 자리 하나를 정리해 보세요."},{"en":"Write down one routine you already keep and give it a small reward this week.","ko":"이미 지키고 있는 습관 하나를 적어 보고, 이번 주에 작은 보상을 주세요."}]},"HB_FEEL_metal":{"tags":["hb:metal"],"card":"habits","v":[{"en":"You may feel lighter after you clear something out.","ko":"무언가를 치우고 나면 마음이 더 가벼워지는 걸 느낄 수 있어요."},{"en":"Clutter, in your space or in your head, may weigh on you more than you notice.","ko":"공간이든 머릿속이든 어수선함이 알아차리는 것보다 더 무겁게 느껴질 수 있어요."},{"en":"You may enjoy the feeling of finishing one thing cleanly before starting the next.","ko":"다음 일을 시작하기 전에 하나를 깔끔하게 끝내는 느낌을 좋아할 수 있어요."}]},"HB_MEAN_metal":{"tags":["hb:metal"],"card":"habits","v":[{"en":"Metal is the element of clarity and clean edges, so habits of sorting, finishing, and letting go may suit this chart.","ko":"쇠는 분명함과 깔끔한 경계의 기운이라서, 정리하고 마무리하고 내려놓는 습관이 이 사주에 어울릴 수 있어요."},{"en":"Traditionally, Metal stands for focus and refinement, so routines with a clear start and a clear end may help.","ko":"전통적으로 쇠는 집중과 다듬음을 뜻해서, 시작과 끝이 분명한 습관이 도움이 될 수 있어요."},{"en":"Metal is linked with order and precision, which fits habits that keep your space and schedule tidy.","ko":"쇠는 질서와 정확함과 이어져서, 공간과 일정을 단정하게 유지하는 습관과 잘 맞을 수 있어요."}]},"HB_ACT_metal":{"tags":["hb:metal"],"card":"habits","v":[{"en":"Clear out one drawer, shelf, or screen this week.","ko":"이번 주에 서랍, 선반, 화면 중 하나를 비워 보세요."},{"en":"End your day by writing down three things you finished.","ko":"하루를 마무리하며 끝낸 일 세 가지를 적어 보세요."},{"en":"Take five slow breaths before something you have been dreading.","ko":"미루고 싶던 일 앞에서 천천히 다섯 번 숨을 쉬어 보세요."},{"en":"Set a clear stopping time for one activity today and stick to it.","ko":"오늘 한 가지 활동의 끝나는 시간을 분명히 정하고 지켜 보세요."}]},"HB_FEEL_water":{"tags":["hb:water"],"card":"habits","v":[{"en":"You may need more quiet in your day than you let yourself have.","ko":"스스로 허락하는 것보다 더 많은 고요가 하루에 필요할 수 있어요."},{"en":"Rest may be the first thing you cut when life gets busy.","ko":"바빠지면 가장 먼저 줄이는 것이 쉼일 수 있어요."},{"en":"You may feel more like yourself after a stretch of unhurried time alone.","ko":"서두르지 않는 혼자만의 시간을 보내고 나면 더 나다워지는 걸 느낄 수 있어요."}]},"HB_MEAN_water":{"tags":["hb:water"],"card":"habits","v":[{"en":"Water is the element of rest and flow, so habits that protect quiet time and a steady sleep rhythm may suit this chart.","ko":"물은 쉼과 흐름의 기운이라서, 고요한 시간과 일정한 잠의 리듬을 지키는 습관이 이 사주에 어울릴 수 있어요."},{"en":"Traditionally, Water stands for depth and stillness, so routines with room to unwind may help.","ko":"전통적으로 물은 깊이와 고요를 뜻해서, 긴장을 풀 여유가 있는 습관이 도움이 될 수 있어요."},{"en":"Water is linked with calm and reflection, which fits habits that give your mind somewhere quiet to land.","ko":"물은 평온과 되돌아봄과 이어져서, 마음이 조용히 내려앉을 곳을 마련해 주는 습관과 잘 맞을 수 있어요."}]},"HB_ACT_water":{"tags":["hb:water"],"card":"habits","v":[{"en":"Keep the last ten minutes before bed screen-free for the next week.","ko":"앞으로 일주일 동안 잠들기 전 10분은 화면 없이 보내 보세요."},{"en":"Spend ten quiet minutes in one corner each evening, without your phone.","ko":"매일 저녁 한 모퉁이에서 휴대폰 없이 10분을 조용히 보내 보세요."},{"en":"Take a slow walk after a busy day, with no goal except to unwind.","ko":"바쁜 하루를 보낸 뒤에는 긴장을 풀겠다는 것 말고는 목표 없이 천천히 걸어 보세요."},{"en":"Jot down one thing on your mind before bed, then set the notebook aside.","ko":"자기 전에 마음에 걸리는 것 하나를 적고, 공책은 옆으로 치워 두세요."}]},"HB_STR_strong":{"tags":[],"card":"habits","v":[{"en":"With plenty of energy in your chart, you may move fast on busy days, so a short afternoon pause can keep your pace comfortable.","ko":"기운이 넉넉한 사주라 바쁜 날에는 빠르게 움직이기 쉬워요. 오후에 짧게 쉬어 가면 속도를 편안하게 지킬 수 있어요."},{"en":"Because your chart runs strong, habits that let you burn off energy, like a brisk walk, may suit you well.","ko":"사주의 힘이 센 편이라서, 힘차게 걷기처럼 기운을 시원하게 써 버리는 습관이 잘 맞을 수 있어요."},{"en":"A strong chart like yours tends to do well with a routine that has some slack in it, so you can rest before you get tired.","ko":"당신처럼 힘이 센 사주는 여유가 조금 있는 일과와 잘 맞는 편이라, 지치기 전에 쉴 수 있어요."}]},"HB_STR_weak":{"tags":[],"card":"habits","v":[{"en":"Because your chart leans on support, shared routines may carry you further than willpower alone: a walking friend, a regular call, a class you attend together.","ko":"곁의 도움에 기대는 사주라서, 의지만 쓰기보다 함께하는 습관이 더 멀리 데려다줄 수 있어요. 같이 걷는 친구, 정기적인 통화, 함께 듣는 수업 같은 것이요."},{"en":"Since your chart leans on support, it may help to attach a new habit to something you already do, so you are not starting from nothing.","ko":"곁의 도움에 기대는 사주라서, 새 습관을 이미 하고 있는 일에 붙이면 맨땅에서 시작하지 않아도 돼서 도움이 될 수 있어요."},{"en":"Your chart leans on support, so a gentle, repeatable routine may suit you better than a demanding plan.","ko":"곁의 도움에 기대는 사주라서, 힘든 계획보다 부드럽고 반복할 수 있는 습관이 더 잘 맞을 수 있어요."},{"en":"Because your chart leans on support, you may find it easier to stick with a habit when someone shares it, such as a workout buddy or a study group.","ko":"곁의 도움에 기대는 사주라서, 습관을 누군가와 함께할 때 이어 가기 더 쉬울 수 있어요. 운동 친구나 스터디 모임 같은 거요."},{"en":"With a chart that leans on support, a small habit tied to a visible reminder, like a note on the mirror, may help more than relying on willpower.","ko":"곁의 도움에 기대는 사주라서, 의지에 맡기기보다 거울에 붙인 쪽지처럼 눈에 보이는 알림에 작은 습관을 묶어 두는 편이 더 도움이 될 수 있어요."},{"en":"Your chart leans on support, so starting with a tiny version of a habit and building up slowly may work better than a big overhaul.","ko":"곁의 도움에 기대는 사주라서, 습관을 아주 작게 시작해 천천히 늘려 가는 쪽이 크게 뜯어고치는 것보다 잘 맞을 수 있어요."}]},"HB_STR_balanced":{"tags":[],"card":"habits","v":[{"en":"With a balanced chart you have room to adjust, so try a habit for two weeks and keep only what fits.","ko":"고른 사주라 조정할 여지가 있어요. 습관 하나를 2주 동안 해 보고 맞는 것만 남겨 보세요."},{"en":"Your chart sits in our middle range, so there is no single routine you need; it may be enough to notice what leaves you feeling good and do a bit more of it.","ko":"우리 체계의 중간 구간이라 꼭 필요한 한 가지 습관이 따로 있지는 않아요. 무엇을 하고 나면 기분이 좋은지 알아채고 조금 더 해 보면 충분할 수 있어요."},{"en":"A balanced chart can try many routines, so choose one for how it feels rather than how it looks.","ko":"고른 사주는 여러 습관을 시도해 볼 수 있으니, 보기에 좋은 것보다 해 보았을 때 느낌이 좋은 것을 골라 보세요."},{"en":"A balanced chart gives you flexibility, so test one routine for a couple of weeks and hold on to whatever feels right.","ko":"고른 사주는 유연함이 있어요. 습관 하나를 두어 주 해 보고 잘 맞는다 싶은 것만 붙들어 보세요."},{"en":"No single habit is required for a chart in the middle range; you can follow what lifts your mood and gently build on it.","ko":"중간 구간의 사주에는 꼭 해야 하는 습관이 하나로 정해져 있지 않아요. 기분이 좋아지는 일을 따라가며 조금씩 늘려 가면 돼요."}]},"HB_SEASON_spring":{"tags":["hbseason:spring"],"card":"habits","v":[{"en":"You were born in spring, which Saju reads as a season of fresh starts, so a little morning light or fresh air may fit your rhythm.","ko":"봄 달에 태어났어요. 사주에서 봄은 새 출발의 계절로 읽으니, 아침 햇빛이나 바깥 공기를 잠깐 쐬는 일이 리듬에 맞을 수 있어요."},{"en":"A spring birth month is read as a season of beginnings, so habits that restart you gently each morning may feel natural.","ko":"봄에 태어난 달은 시작의 계절로 읽어서, 매일 아침 부드럽게 다시 시작하게 하는 습관이 자연스럽게 느껴질 수 있어요."},{"en":"Spring is read as the season when things begin to grow, so a small daily habit that you can watch grow may feel rewarding.","ko":"봄은 무언가 자라기 시작하는 계절로 읽어서, 자라는 모습을 지켜볼 수 있는 작은 일상 습관이 보람 있게 느껴질 수 있어요."}]},"HB_SEASON_summer":{"tags":["hbseason:summer"],"card":"habits","v":[{"en":"You were born in summer, which Saju reads as a season of full energy, so a slow, cool wind-down in the evening may suit you.","ko":"여름 달에 태어났어요. 여름은 기운이 가득한 계절로 읽으니, 저녁에 서늘하게 천천히 마무리하는 시간이 잘 맞을 수 있어요."},{"en":"Because summer is read as a season of full energy, a short pause in the middle of the day may keep your pace comfortable.","ko":"여름은 기운이 가득한 계절로 읽어서, 하루 중간의 짧은 쉼이 속도를 편안하게 지켜 줄 수 있어요."},{"en":"A summer birth month is read as bright and busy, so shade, quiet, and an early end to the day may feel especially good.","ko":"여름에 태어난 달은 밝고 분주한 시기로 읽어서, 그늘과 고요, 일찍 마무리하는 하루가 특히 좋게 느껴질 수 있어요."}]},"HB_SEASON_autumn":{"tags":["hbseason:autumn"],"card":"habits","v":[{"en":"You were born in autumn, which Saju reads as a season of bringing things in, so sorting, finishing, and tidying may feel satisfying.","ko":"가을 달에 태어났어요. 가을은 거두어들이는 계절로 읽으니, 정리하고 마무리하고 치우는 일이 후련하게 느껴질 수 있어요."},{"en":"Autumn is read as a season of harvest and letting go, so a weekly clean-out of your space or your schedule may suit you.","ko":"가을은 수확과 내려놓음의 계절로 읽어서, 매주 공간이나 일정을 한 번 비우는 습관이 잘 맞을 수 있어요."},{"en":"A birth month in autumn is read as clear and crisp, so habits with a clean beginning and end may feel good.","ko":"가을에 태어난 달은 맑고 선선한 시기로 읽어서, 시작과 끝이 깔끔한 습관이 좋게 느껴질 수 있어요."}]},"HB_SEASON_winter":{"tags":["hbseason:winter"],"card":"habits","v":[{"en":"You were born in winter, which Saju reads as a season of rest and reserve, so earlier nights and quiet evenings may suit you.","ko":"겨울 달에 태어났어요. 겨울은 쉼과 비축의 계절로 읽으니, 이른 밤과 고요한 저녁이 잘 맞을 수 있어요."},{"en":"Winter is read as a season for storing energy, so protecting your sleep rhythm may be worth a little extra care.","ko":"겨울은 기운을 갈무리하는 계절로 읽어서, 잠의 리듬을 지키는 데 조금 더 마음을 써 볼 만해요."},{"en":"A winter birth month is read as deep and still, so warm, slow routines may feel especially comforting.","ko":"겨울에 태어난 달은 깊고 고요한 시기로 읽어서, 따뜻하고 느린 습관이 특히 편안하게 느껴질 수 있어요."}]},"HB_SEASON_cusp":{"tags":["hbseason:cusp"],"card":"habits","v":[{"en":"You were born in the last month of a season, when Earth energy links one season to the next, so a habit that stays the same while the weather shifts, such as a steady wake-up time, may be your anchor.","ko":"계절의 마지막 달(환절기)에 태어났어요. 흙의 기운이 계절을 이어 주는 달이라서, 날씨가 바뀌어도 그대로인 습관, 예를 들어 일정한 기상 시간이 닻이 될 수 있어요."},{"en":"Your birth month is the last month of a season, the one where Earth energy joins it to the next, so steady meal and sleep times through the change may help you feel grounded.","ko":"태어난 달은 계절의 마지막 달(환절기)이에요. 흙의 기운이 다음 계절로 이어 주는 때라서, 바뀌는 동안 식사와 잠드는 시간을 일정하게 지키면 중심이 잡히는 데 도움이 될 수 있어요."},{"en":"Because you were born in the month that carries one season into the next, where Earth energy does the linking, a simple routine you can keep through the change may feel reassuring.","ko":"한 계절을 다음 계절로 넘겨주는 달, 흙의 기운이 계절을 이어 주는 때에 태어나서, 계절이 바뀌는 동안 지킬 수 있는 단순한 습관이 안심이 될 수 있어요."},{"en":"Traditionally, the last month of each season is an Earth month that links the seasons, and you were born in one, so a regular bedtime that does not change with the weather may comfort you.","ko":"전통적으로 각 계절의 마지막 달은 계절을 이어 주는 흙의 달이에요. 그런 달에 태어났으니, 날씨가 바뀌어도 그대로인 일정한 잠드는 시간이 마음을 편하게 해 줄 수 있어요."},{"en":"You were born in an Earth month, when one season hands over to the next, so a small daily ritual that stays put through the shift may steady you.","ko":"계절이 다음 계절에 자리를 넘겨주는 흙의 달(환절기)에 태어났어요. 계절이 바뀌는 동안에도 변함없는 작은 일과가 중심을 잡아 줄 수 있어요."}]},"WKM_FEEL_bigyeop":{"tags":["monthcat:bigyeop"],"card":"work","v":[{"en":"You may like figuring things out your own way, and feel proud when you do something on your own.","ko":"내 방식대로 알아내는 걸 좋아하고, 혼자 해냈을 때 뿌듯할 수 있어요."},{"en":"You may enjoy projects where you get to keep your own part and your own pace.","ko":"내 몫과 내 속도를 지킬 수 있는 활동을 즐길 수 있어요."}]},"WKM_MEAN_bigyeop":{"tags":["monthcat:bigyeop"],"card":"work","v":[{"en":"Your chart leans toward independence and friends who feel like equals, so group projects where everyone has a real part may suit you.","ko":"당신의 사주는 독립심과 대등한 친구 쪽으로 기울어서, 모두가 제 몫을 맡는 모둠 활동이 잘 맞을 수 있어요."}]},"WKM_ACT_bigyeop":{"tags":["monthcat:bigyeop"],"card":"work","v":[{"en":"Ask to take one part of the next group project and make it yours.","ko":"다음 모둠 활동에서 한 부분을 맡아 내 것으로 만들어 보세요."},{"en":"Tell a friend which part of a project you would like to own.","ko":"친구에게 활동에서 내가 맡고 싶은 부분을 말해 보세요."}]},"LVM_FEEL_bigyeop":{"tags":["dbcat:bigyeop"],"card":"love","v":[{"en":"You may feel closest to friends who treat you as an equal.","ko":"나를 대등하게 대해 주는 친구와 가장 가깝게 느낄 수 있어요."},{"en":"You may like having your own space, even with people you love.","ko":"좋아하는 사람 곁에서도 나만의 공간이 있는 걸 좋아할 수 있어요."}]},"LVM_MEAN_bigyeop":{"tags":["dbcat:bigyeop"],"card":"love","v":[{"en":"Your chart leans toward independence and equal footing with others, so friends and siblings who share things evenly may feel best to you.","ko":"당신의 사주는 독립심과 서로 대등한 관계 쪽으로 기울어서, 서로 고르게 나누는 친구나 형제자매가 편안하게 느껴질 수 있어요."}]},"LVM_ACT_bigyeop":{"tags":["dbcat:bigyeop"],"card":"love","v":[{"en":"Tell a friend one thing you appreciate about them.","ko":"친구에게 고마운 점 하나를 말해 보세요."},{"en":"Ask a friend or sibling what they would like to do together this weekend.","ko":"친구나 형제자매에게 이번 주말에 함께 하고 싶은 일을 물어보세요."}]},"WKM_FEEL_siksang":{"tags":["monthcat:siksang"],"card":"work","v":[{"en":"You may have ideas you want to show someone: a drawing, a story, a song, a plan.","ko":"그림, 이야기, 노래, 계획처럼 누군가에게 보여 주고 싶은 생각이 있을 수 있어요."},{"en":"You may feel most alive when you are making something.","ko":"무언가를 만들고 있을 때 가장 생기가 날 수 있어요."}]},"WKM_MEAN_siksang":{"tags":["monthcat:siksang"],"card":"work","v":[{"en":"Your chart leans toward expression and making things, so clubs and classes where you can create may suit you.","ko":"당신의 사주는 표현과 만들어 내기 쪽으로 기울어서, 직접 만들 수 있는 동아리나 수업이 잘 맞을 수 있어요."}]},"WKM_ACT_siksang":{"tags":["monthcat:siksang"],"card":"work","v":[{"en":"Show one thing you made to one person this week.","ko":"이번 주에 만든 것 하나를 한 사람에게 보여 주세요."},{"en":"Spend twenty minutes this week on something you like to make, with no goal.","ko":"이번 주에 만드는 걸 좋아하는 일에 목표 없이 20분을 써 보세요."}]},"LVM_FEEL_siksang":{"tags":["dbcat:siksang"],"card":"love","v":[{"en":"You may open up most when you are making or playing something together.","ko":"함께 무언가를 만들거나 놀 때 마음이 가장 열릴 수 있어요."},{"en":"You may show you care through jokes, drawings, or little surprises.","ko":"농담이나 그림, 작은 깜짝 선물로 마음을 표현할 수 있어요."}]},"LVM_MEAN_siksang":{"tags":["dbcat:siksang"],"card":"love","v":[{"en":"Your chart leans toward expression, so doing things together, like games, crafts, or stories, can build closeness.","ko":"당신의 사주는 표현 쪽으로 기울어서, 게임이나 만들기, 이야기처럼 함께하는 활동이 가까워지는 길이 될 수 있어요."}]},"LVM_ACT_siksang":{"tags":["dbcat:siksang"],"card":"love","v":[{"en":"Invite a friend or family member to make something with you.","ko":"친구나 가족 한 명을 초대해 함께 무언가를 만들어 보세요."},{"en":"Draw or write a short note for someone you like.","ko":"좋아하는 사람에게 짧은 그림이나 쪽지를 써 보세요."}]},"WKM_FEEL_jaeseong":{"tags":["monthcat:jaeseong"],"card":"work","v":[{"en":"You may enjoy seeing a clear result from your effort, like a finished model or a good score.","ko":"완성한 모형이나 좋은 점수처럼 노력의 결과가 분명히 보이는 걸 좋아할 수 있어요."},{"en":"You may like knowing exactly what you did and what it led to.","ko":"내가 무엇을 했고 어떤 결과가 나왔는지 정확히 아는 걸 좋아할 수 있어요."}]},"WKM_MEAN_jaeseong":{"tags":["monthcat:jaeseong"],"card":"work","v":[{"en":"Your chart leans toward practical results, so goals you can measure in small steps may suit you.","ko":"당신의 사주는 현실적인 결과 쪽으로 기울어서, 작은 단계로 확인할 수 있는 목표가 잘 맞을 수 있어요."}]},"WKM_ACT_jaeseong":{"tags":["monthcat:jaeseong"],"card":"work","v":[{"en":"Pick one small goal and put a check mark on each day you practice it.","ko":"작은 목표 하나를 골라 연습한 날마다 체크 표시를 해 보세요."},{"en":"Write down one thing you finished this week and how it felt.","ko":"이번 주에 끝낸 일 하나와 그때 느낌을 적어 보세요."}]},"LVM_FEEL_jaeseong":{"tags":["dbcat:jaeseong"],"card":"love","v":[{"en":"You may show you care by being practical and helpful.","ko":"실용적으로 도와주는 모습으로 마음을 보여 줄 수 있어요."},{"en":"You may notice what people around you need before they say it.","ko":"주변 사람이 말하기 전에 필요한 것을 알아챌 수 있어요."}]},"LVM_MEAN_jaeseong":{"tags":["dbcat:jaeseong"],"card":"love","v":[{"en":"Your chart leans toward practical care, so helping with small things may be how you show love to family and friends.","ko":"당신의 사주는 현실적인 보살핌 쪽으로 기울어서, 작은 일을 도와주는 것이 가족과 친구에게 마음을 보여 주는 방법일 수 있어요."}]},"LVM_ACT_jaeseong":{"tags":["dbcat:jaeseong"],"card":"love","v":[{"en":"Do one small helpful thing for a family member without being asked.","ko":"부탁받지 않아도 가족에게 도움이 되는 작은 일 하나를 해 보세요."},{"en":"Ask a friend if there is anything small you can do for them.","ko":"친구에게 내가 해 줄 수 있는 작은 일이 있는지 물어보세요."}]},"WKM_FEEL_gwanseong":{"tags":["monthcat:gwanseong"],"card":"work","v":[{"en":"You may feel proud when someone trusts you with a task, like being class helper.","ko":"학급 도우미처럼 누군가 일을 맡겨 주면 뿌듯할 수 있어요."},{"en":"You may like knowing the rules and doing things properly.","ko":"규칙을 알고 제대로 해내는 걸 좋아할 수 있어요."}]},"WKM_MEAN_gwanseong":{"tags":["monthcat:gwanseong"],"card":"work","v":[{"en":"Your chart leans toward responsibility and structure, so roles with clear rules may suit you.","ko":"당신의 사주는 책임과 틀 쪽으로 기울어서, 규칙이 분명한 역할이 잘 맞을 수 있어요."}]},"WKM_ACT_gwanseong":{"tags":["monthcat:gwanseong"],"card":"work","v":[{"en":"Choose one thing to take care of every day, like a plant or a small chore.","ko":"식물이나 작은 집안일처럼 매일 돌볼 것 하나를 골라 보세요."},{"en":"Ask a teacher if there is a small helper role you could try.","ko":"선생님께 해 볼 수 있는 작은 도우미 역할이 있는지 여쭤보세요."}]},"LVM_FEEL_gwanseong":{"tags":["dbcat:gwanseong"],"card":"love","v":[{"en":"You may care a lot about being fair and keeping promises with friends.","ko":"친구 사이에서 공정함과 약속 지키기를 많이 중요하게 여길 수 있어요."},{"en":"You may feel upset when a rule is broken between friends.","ko":"친구 사이에서 규칙이 깨지면 속상할 수 있어요."}]},"LVM_MEAN_gwanseong":{"tags":["dbcat:gwanseong"],"card":"love","v":[{"en":"Your chart leans toward responsibility, so being someone friends can rely on may matter to you.","ko":"당신의 사주는 책임 쪽으로 기울어서, 친구들이 믿고 기댈 수 있는 사람이 되는 것이 중요할 수 있어요."}]},"LVM_ACT_gwanseong":{"tags":["dbcat:gwanseong"],"card":"love","v":[{"en":"Keep one promise to a friend this week, even a small one.","ko":"이번 주에 친구와의 약속 하나를 지켜 보세요. 작은 약속이어도 좋아요."},{"en":"Tell someone in your family one thing they can count on you for.","ko":"가족에게 내가 믿고 맡길 수 있는 일 하나를 말해 보세요."}]},"WKM_FEEL_inseong":{"tags":["monthcat:inseong"],"card":"work","v":[{"en":"You may get curious and keep asking why.","ko":"궁금해서 계속 왜 그런지 묻게 될 수 있어요."},{"en":"You may feel calm when you are reading or learning something new.","ko":"책을 읽거나 새로운 것을 배울 때 마음이 차분해질 수 있어요."}]},"WKM_MEAN_inseong":{"tags":["monthcat:inseong"],"card":"work","v":[{"en":"Your chart leans toward learning and nurture, so teachers, books, and patient helpers may matter to you.","ko":"당신의 사주는 배움과 보살핌 쪽으로 기울어서, 선생님과 책, 차분히 도와주는 사람이 중요할 수 있어요."}]},"WKM_ACT_inseong":{"tags":["monthcat:inseong"],"card":"work","v":[{"en":"Write down one question you are curious about, then ask a teacher or look it up with a parent.","ko":"궁금한 질문 하나를 적고, 선생님께 여쭤보거나 부모님과 함께 찾아보세요."},{"en":"Borrow one book about something you want to know more about.","ko":"더 알고 싶은 주제의 책을 한 권 빌려 보세요."}]},"LVM_FEEL_inseong":{"tags":["dbcat:inseong"],"card":"love","v":[{"en":"You may feel safest with people who listen.","ko":"내 말을 들어 주는 사람 곁에서 가장 안심될 수 있어요."},{"en":"You may enjoy quiet time with someone who takes you seriously.","ko":"나를 진지하게 대해 주는 사람과의 조용한 시간을 좋아할 수 있어요."}]},"LVM_MEAN_inseong":{"tags":["dbcat:inseong"],"card":"love","v":[{"en":"Your chart leans toward learning and nurture, so patient friends, relatives, and teachers may matter a lot.","ko":"당신의 사주는 배움과 보살핌 쪽으로 기울어서, 차분한 친구와 친척, 선생님이 크게 중요할 수 있어요."}]},"LVM_ACT_inseong":{"tags":["dbcat:inseong"],"card":"love","v":[{"en":"Thank one person who has listened to you.","ko":"내 이야기를 들어 준 사람 한 명에게 고맙다고 말해 보세요."},{"en":"Ask a family member to tell you a story from when they were your age.","ko":"가족에게 내 나이 때의 이야기를 들려 달라고 부탁해 보세요."}]},"YR_FEEL_jaeseong@minor":{"tags":["yrcat:jaeseong"],"card":"this_year","v":[{"en":"You may feel more alert to practical chances and small trades with friends in {year}.","ko":"{year}년에는 현실적인 기회와 친구들과의 작은 교환에 더 예민해질 수 있어요."},{"en":"{year} may make you keenly aware of what's working and what's paying off.","ko":"{year}년에는 무엇이 잘 굴러가고 무엇이 결실을 내는지 또렷이 보일 수 있어요."}]},"YR_TG_jeongjae@minor":{"tags":["yrgod:jeongjae"],"card":"this_year","v":[{"en":"In {year}, the year's element, {ys}, points you toward {yrGod}: a year for steady effort, step-by-step goals, and practical results.","ko":"{year}년에는 그해의 기운 {ys}이(가) 당신을 {yrGod} 쪽으로 이끌어요. 꾸준한 노력, 한 걸음씩 나아가는 목표, 실제 결과에 집중하기 좋은 해예요."}]},"YR_LAND_jaeseong_strong@minor":{"tags":["yrcat:jaeseong","strength:strong"],"card":"this_year","v":[{"en":"A chart with plenty of its own core energy can handle practical, hands-on years well, so this could be a good year to build or grow something concrete.","ko":"자기 중심 기운이 넉넉한 사주는 직접 손으로 해 보는 해를 잘 감당하는 편이에요. 그래서 눈에 보이는 무언가를 만들거나 키워 보기 좋은 해가 될 수 있어요."}]},"YR_ACT_gwanseong_hap@minor":{"tags":["yrcat:gwanseong","yrstate:hap"],"card":"this_year","v":[{"en":"If a new role is offered this year, such as class helper or team captain, ask for one clear thing that would help you do it well.","ko":"올해 학급 도우미나 팀 대표 같은 새 역할 제안이 오면, 잘해 내는 데 필요한 것 한 가지를 분명히 요청해 보세요."}]},"YR_TG_jeonggwan@minor":{"tags":["yrgod:jeonggwan"],"card":"this_year","v":[{"en":"In {year}, the year's element, {ys}, points you toward {yrGod}: a year of roles, rules, and recognition.","ko":"{year}년에는 그해의 기운인 {ys}이(가) 당신을 {yrGod}(으)로 이끌어요. 역할과 규칙, 인정받는 일이 눈에 띄는 해예요."}]},"YR_LAND_inseong_balanced@minor":{"tags":["yrcat:inseong","strength:balanced"],"card":"this_year","v":[{"en":"With your chart in our middle range, this may be a good year to add a skill or a new interest.","ko":"사주가 중간 구간(중화)이라 기술이나 새 관심사 하나를 더하기 좋은 해일 수 있어요."}]},"ST_CYC_early_jaeseong@minor":{"tags":["stage:early"],"card":"early","v":[{"en":"Your young years may turn practical early: chores, saving up, or seeing real results.","ko":"젊은 시절은 일찍부터 현실적일 수 있어요. 집안일, 모으기, 실제 결과 같은 것들이요."}]},"ST_CYC_middle_bigyeop@minor":{"tags":["stage:middle"],"card":"middle","v":[{"en":"In the middle years independence may grow: your own project, your own way, or a team of equals.","ko":"중년에는 독립심이 자랄 수 있어요. 나만의 프로젝트, 나만의 방식, 혹은 대등한 사람들의 팀이요."}]},"ST_CYC_middle_gwanseong@minor":{"tags":["stage:middle"],"card":"middle","v":[{"en":"In the middle years roles and responsibility may grow: leadership, and being counted on.","ko":"중년에는 역할과 책임이 커질 수 있어요. 이끄는 자리, 믿고 맡겨지는 일이요."}]},"ST_CYC_middle_inseong@minor":{"tags":["stage:middle"],"card":"middle","v":[{"en":"In the middle years knowledge and reputation may grow: expertise, and a circle of people who look out for you.","ko":"중년에는 지식과 평판이 자랄 수 있어요. 전문성, 당신을 챙겨 주는 사람들의 모임이요."}]},"ST_CYC_middle_jaeseong@minor":{"tags":["stage:middle"],"card":"middle","v":[{"en":"In the middle years practical matters may take center stage: planning, saving, and managing real results.","ko":"중년에는 현실적인 일이 중심에 설 수 있어요. 계획하고, 모으고, 실제 결과를 챙기는 일이요."}]},"YR_R_ganhe@minor":{"tags":["yrrel"],"card":"this_year","v":[{"en":"{year}'s element, {ys}, pairs up with {pElem}, {ns}, so an invitation, a new friendship, or a team-up connected with {area} may feel especially hard to resist.","ko":"{year}년의 기운 {ys}이(가) {pElem}, 곧 {ns}와(과) 짝을 이뤄요. 그래서 {area}와(과) 관련된 초대나 새 친구, 함께하는 일을 특히 뿌리치기 어려울 수 있어요."}]},"YR_R_ganhe_B@minor":{"tags":["yrrel"],"card":"this_year","v":[{"en":"This year's element, {ys}, also pairs with {pElem}, {ns}, so invitations to play or learn with others may catch your attention.","ko":"올해의 기운 {ys}은(는) {pElem}, 곧 {ns}와(과)도 짝을 이뤄요. 그래서 다른 사람과 함께 놀거나 배워 보자는 초대가 눈길을 끌 수 있어요."}]},"YR_TG_bigyeon@minor":{"tags":["yrgod:bigyeon"],"card":"this_year","v":[{"en":"In {year}, the year's element, {ys}, meets your core element as {yrGod}: a year that may bring people who are like you, such as classmates, competitors, and teammates, and asks you to stand on your own terms.","ko":"{year}년에는 그해의 기운 {ys}이(가) 나의 중심 기운과 {yrGod}(으)로 만나요. 반 친구, 경쟁자, 팀원처럼 나와 닮은 사람들이 곁에 올 수 있고, 내 기준으로 서 보라고 하는 해예요."}]},"ST_PAL_middle@minor":{"tags":[],"card":"middle","v":[{"en":"The animal of the day you were born, which tradition reads for the middle years and close relationships, points to {palGod}, adding a thread of {palCat} to these years.","ko":"태어난 날의 동물은 전통적으로 중년과 가까운 관계를 읽는 자리인데, {palGod}을(를) 가리켜서 이 시기에 {palCatKo}의 실 한 가닥을 더해요."}]},"YR_ACT_jaeseong_chung@minor":{"tags":["yrcat:jaeseong","yrstate:chung"],"card":"this_year","v":[{"en":"Keep one free afternoon each month this year, so changes in routine have room to land.","ko":"올해 매달 비어 있는 오후 하나를 남겨 두세요. 일상에 변화가 와도 자리를 잡을 여유가 생겨요."},{"en":"Each month, look over your regular routine and choose one thing to adjust, so changes feel planned rather than sudden.","ko":"매달 일상 루틴을 훑어보고 하나를 골라 조정해 보세요. 변화가 갑작스럽지 않고 계획된 것처럼 느껴져요."}]},"YR_ACT_jaeseong_hap@minor":{"tags":["yrcat:jaeseong","yrstate:hap"],"card":"this_year","v":[{"en":"Before agreeing to a joint plan this year, agree out loud on who does what.","ko":"올해 함께하는 계획에 동의하기 전에, 누가 무엇을 할지 소리 내어 정해 두세요."},{"en":"Write down each person's role before you sign on to any group plan this year.","ko":"올해 여럿이 하는 계획에 합류하기 전에, 사람마다 맡을 역할을 글로 적어 두세요."}]},"YR_FEEL_gwanseong@minor":{"tags":["yrcat:gwanseong"],"card":"this_year","v":[{"en":"You may feel more is expected of you in {year}, at school or at home.","ko":"{year}년에는 학교나 집에서 나에게 거는 기대가 커졌다고 느낄 수 있어요."},{"en":"{year} may be a year of trying new things at your own pace.","ko":"{year}년은 내 속도대로 새로운 것을 해 보는 해가 될 수 있어요."},{"en":"Expectations from school or family could feel heavier in {year}.","ko":"{year}년에는 학교나 가족이 건네는 기대가 한층 무겁게 느껴질 수 있어요."}]},"YR_ACT_bigyeop_hap@minor":{"tags":["yrcat:bigyeop","yrstate:hap"],"card":"this_year","v":[{"en":"Pick one buddy this year and plan something together, with a shared date on the calendar.","ko":"올해 함께할 짝 한 명을 정해 날짜까지 달력에 적고 무언가를 같이 계획해 보세요."},{"en":"Invite one friend or classmate to a shared goal this year, and put the first meeting on the calendar.","ko":"올해 친구나 반 친구 한 명에게 함께할 목표를 제안하고, 첫 모임 날짜를 달력에 적으세요."},{"en":"Find a study buddy for this year and agree on a weekly time.","ko":"올해 함께 공부할 짝을 찾아 매주 만날 시간을 정해 보세요."}]},"WT_ex_earth_FEEL@minor":{"tags":["el:earth:excess"],"card":"caution","v":[{"en":"You may think about things for a long time before you let them go.","ko":"어떤 일을 마음에서 놓기 전에 오래오래 생각할 수 있어요."},{"en":"A worry or a chore may stay on your mind even after it is done.","ko":"걱정이나 맡은 일이 끝난 뒤에도 마음에 남아 있을 수 있어요."},{"en":"It may be hard to let go of a worry, even once it is no longer needed.","ko":"걱정거리가 더는 필요하지 않게 된 뒤에도 놓아 주기 어려울 수 있어요."},{"en":"You might hold on to an old worry longer than you need to.","ko":"오래된 걱정을 필요한 시간보다 더 길게 붙들고 있을 수 있어요."}]},"WT_over_jaeseong_MEAN@minor":{"tags":["cat:jaeseong:many"],"card":"caution","v":[{"en":"With many practical-results symbols, chasing every opportunity can wear you out.","ko":"현실적인 결과를 뜻하는 글자(재성)가 많아서, 모든 기회를 쫓다 보면 지칠 수 있어요."}]},"WT_miss_jaeseong_FEEL@minor":{"tags":["cat:jaeseong:none"],"card":"caution","v":[{"en":"You may find practical details, like keeping track of your things, easy to postpone.","ko":"자기 물건을 챙기는 것 같은 현실적인 세세한 일을 자꾸 미루기 쉬울 수 있어요."}]},"WT_miss_jaeseong_MEAN@minor":{"tags":["cat:jaeseong:none"],"card":"caution","v":[{"en":"Your chart does not show practical-results symbols, so small practical tasks may go better with a simple system, like a checklist, than with remembering on the spot.","ko":"현실적인 결과를 뜻하는 글자(재성)가 사주에 보이지 않아서, 현실적인 작은 일은 그때그때 기억하는 것보다 체크리스트 같은 간단한 방법이 더 잘 맞을 수 있어요."}]},"WT_miss_jaeseong_COPE@minor":{"tags":["cat:jaeseong:none"],"card":"caution","v":[{"en":"Put a fifteen-minute tidy-up check on your calendar every two weeks.","ko":"2주마다 15분짜리 정리 점검 시간을 달력에 넣어 두세요."}]},"ST_LATE_MINOR":{"tags":[],"card":"later","v":[{"en":"You're still at the very start. This part is about what may be waiting far down the road, so you can skip it for now.","ko":"아직 한참 먼 이야기예요. 지금은 건너뛰어도 괜찮아요."}]},"HB_NOTICE@minor":{"tags":[],"card":"habits","v":[{"en":"These are everyday routines for you to try, not a substitute for medical care. If you are worried about your body, tell a parent or talk to a doctor. Linking the five elements to daily habits is an old tradition of symbols, not a statement about your body.","ko":"이 내용은 생활 습관 참고용이에요. 병원에서 받는 도움을 대신하지 않아요. 몸이 걱정되면 부모님이나 보호자께 말씀드리거나 의사와 상의해 주세요. 오행과 생활 습관을 잇는 것은 옛 전통의 상징 풀이이고, 내 몸 상태를 말하는 것이 아니에요."},{"en":"Think of this as a list of everyday routines to try. It does not replace medical care, so if anything about your body worries you, tell a parent or talk to a doctor. Connecting the five elements with habits is a traditional way of using symbols; it says nothing about your body.","ko":"이 내용은 생활 습관 참고용이에요. 병원에서 받는 도움을 대신하지 않아요. 몸이 걱정되면 부모님이나 보호자께 말씀드리거나 의사와 상의해 주세요. 오행과 생활 습관을 잇는 것은 옛 전통의 상징 풀이이고, 내 몸 상태를 말하는 것이 아니에요."}]},"YR_R_fuyin@minor":{"tags":["yrrel"],"v":[{"en":"{year}'s element and animal, {yearGz}, match those of {pWhole}, a pattern called a repeat year, so it can be a nice year to come back to a favorite hobby.","ko":"{year}년의 기운과 동물인 {yearGz}이(가) {pWhole}의 것과 같아요. 이런 해를 되풀이되는 해라고 불러요. 그래서 좋아하는 취미로 다시 돌아가기 좋은 해가 될 수 있어요."},{"en":"In {year}, the year's sign, {yearGz}, is the same as that of {pWhole}, so you may enjoy returning to things you already love.","ko":"{year}년의 표시 {yearGz}은(는) {pWhole}의 표시와 같아요. 그래서 이미 좋아하는 것들로 돌아가는 일이 즐거울 수 있어요."}],"card":"this_year"},"YR_R_chung@minor":{"tags":["yrrel"],"v":[{"en":"{year}'s animal, the {yb}, meets {pAnimal}, the {nb}, so your own daily rhythm may feel a little different from usual.","ko":"{year}년의 동물 {yb}이(가) {pAnimal}, 곧 {nb}을(를) 만나서, 평소 하루의 리듬이 조금 다르게 느껴질 수 있어요."},{"en":"In {year}, the {yb} sits across from {pAnimal}, the {nb}, so it can be a good year to try a new routine and see what you like.","ko":"{year}년에는 {yb}이(가) {pAnimal}, 곧 {nb}와(과) 마주 보고 있어서, 새로운 습관을 시도하며 내가 좋아하는 걸 찾아보기 좋은 해예요."},{"en":"The {yb} of {year} faces {pAnimal}, the {nb}, so small changes in your week can be a chance to learn something new.","ko":"{year}년의 {yb}이(가) {pAnimal}, 곧 {nb}을(를) 마주해요. 한 주 동안의 작은 변화가 새로운 걸 배울 기회가 되기도 해요."}],"card":"this_year"},"YR_R_chung_B@minor":{"tags":["yrrel"],"v":[{"en":"The year's {yb} also meets {pAnimal}, the {nb}, so a few of your usual routines may shift a little.","ko":"올해의 {yb}은(는) {pAnimal}인 {nb}와(과)도 마주쳐서, 늘 하던 일과 몇 가지가 조금 바뀔 수 있어요."},{"en":"The {yb} also faces {pAnimal}, the {nb}, a gentle hint to stay flexible when plans change.","ko":"{yb}은(는) {pAnimal}인 {nb}와(과)도 마주 보고 있어요. 계획이 바뀔 때 유연하게 움직여 보라는 부드러운 귀띔이에요."}],"card":"this_year"},"YR_R_hap@minor":{"tags":["yrrel"],"v":[{"en":"{year}'s animal, the {yb}, pairs up with {pAnimal}, the {nb}, so teamwork with friends may feel easy.","ko":"{year}년의 동물 {yb}이(가) {pAnimal}, 곧 {nb}와(과) 짝을 이뤄서, 친구들과 함께하는 일이 수월하게 느껴질 수 있어요."},{"en":"In {year}, the {yb} lines up with {pAnimal}, so it can be a good year to notice what makes your days feel easy.","ko":"{year}년에는 {yb}이(가) {pAnimal}와(과) 나란히 맞춰져서, 하루하루를 편하게 만드는 게 무엇인지 알아보기 좋은 해예요."}],"card":"this_year"},"YR_R_hap_B@minor":{"tags":["yrrel"],"v":[{"en":"The {yb} also pairs up with {pAnimal}, the {nb}, a friendly sign for group projects and games.","ko":"{yb}은(는) {pAnimal}, 곧 {nb}와(과)도 짝을 이뤄요. 모둠 활동과 놀이에 다정한 신호예요."},{"en":"The year's {yb} also gets along with {pAnimal}, so doing things with others may feel a bit smoother.","ko":"올해의 {yb}은(는) {pAnimal}와(과)도 사이가 좋아서, 다른 사람과 함께하는 일이 조금 더 매끄럽게 느껴질 수 있어요."}],"card":"this_year"},"YR_R_samhap@minor":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, completes a traditional trio of animals ({trio}) with your chart, so your different interests may start to fit together.","ko":"올해의 동물 {yb}이(가) 당신의 사주와 함께 전통적인 세 동물 묶음({trio})을 완성해요. 그래서 여러 관심사가 하나로 맞춰지기 시작할 수 있어요."},{"en":"In {year}, the {yb} rounds out a trio of animals ({trio}) in your chart, leaning toward {samEl}, so it can be a fun year to combine things you enjoy.","ko":"{year}년에는 {yb}이(가) 사주 속 세 동물 묶음({trio})을 채워 주고, {samEl} 쪽으로 기울어요. 좋아하는 것들을 엮어 보기 재미있는 해가 될 수 있어요."}],"card":"this_year"},"YR_R_banhap@minor":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, joins {pAnimal} ({pair}) to make two of a three-animal team, so friendly help may show up when you need it.","ko":"올해의 동물 {yb}이(가) {pAnimal}와(과) 만나 세 동물 모둠 가운데 둘을 이뤄요({pair}). 그래서 필요할 때 다정한 도움이 찾아올 수 있어요."},{"en":"In {year}, the {yb} teams up with {pAnimal} ({pair}), two parts of a three-animal group that leans toward {samEl}, which can make it a good year to share ideas with friends.","ko":"{year}년에는 {yb}이(가) {pAnimal}와(과) 짝을 이뤄요({pair}). {samEl} 쪽으로 기우는 세 동물 모둠의 두 자리라서, 친구들과 생각을 나누기 좋은 해일 수 있어요."}],"card":"this_year"},"YR_R_fanghe@minor":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, completes a seasonal group ({trio}) with your chart, bringing a big wave of {samEl}, so you may have lots of energy for things you love.","ko":"올해의 동물 {yb}이(가) 당신의 사주와 함께 계절 무리({trio})를 완성해서 {samEl}의 큰 물결을 가져와요. 좋아하는 일에 쏟을 힘이 넘칠 수 있어요."},{"en":"In {year}, the {yb} rounds out a seasonal group of animals ({trio}) in your chart, so it can be a great year to dive into a favorite hobby.","ko":"{year}년에는 {yb}이(가) 사주 속 동물들의 계절 무리({trio})를 채워 줘서, 좋아하는 취미에 푹 빠져 보기 좋은 해일 수 있어요."}],"card":"this_year"},"YR_R_sanxing@minor":{"tags":["yrrel"],"v":[{"en":"{year}'s animal, the {yb}, meets {trio2} in your chart, so it can be a good year to keep your things tidy and finish what you start.","ko":"{year}년의 동물 {yb}이(가) 사주 속 {trio2}을(를) 만나요. 물건을 깔끔하게 정리하고 시작한 일을 끝맺기 좋은 해예요."},{"en":"In {year}, the {yb} lines up with {trio2} in your chart, a gentle reminder to read instructions carefully and take your time.","ko":"{year}년에는 {yb}이(가) 사주 속 {trio2}와(과) 나란히 서요. 설명을 꼼꼼히 읽고 천천히 해 보라는 부드러운 알림이에요."}],"card":"this_year"},"YR_R_xing@minor":{"tags":["yrrel"],"v":[{"en":"This year's {yb} rubs a little against {pAnimal}, the {nb}, so {year} can be a good year to practice patience with small bumps.","ko":"올해의 {yb}이(가) {pAnimal}인 {nb}와(과) 살짝 부딪쳐요. 그래서 {year}년은 작은 덜컹거림에 참을성을 연습하기 좋은 해가 될 수 있어요."},{"en":"In {year}, the {yb} meets {pAnimal}, the {nb}, so being kind when little things go wrong can help your days feel easier.","ko":"{year}년에는 {yb}이(가) {pAnimal}인 {nb}와(과) 만나요. 작은 일이 어긋날 때 너그럽게 대하면 하루하루가 한결 편해질 수 있어요."}],"card":"this_year"},"YR_R_zixing@minor":{"tags":["yrrel"],"v":[{"en":"The year's animal, {yb}, matches {pAnimal}, so {year} can be a year to notice when one worry keeps coming back and to talk it over with someone you trust.","ko":"올해의 동물 {yb}은(는) {pAnimal}와(과) 같아요. 그래서 {year}년은 같은 걱정이 자꾸 돌아올 때 알아차리고, 믿는 사람과 이야기 나누기 좋은 해일 수 있어요."},{"en":"In {year}, the {yb} is the same animal as {pAnimal}, which makes it a nice year to get to know yourself a little better.","ko":"{year}년의 {yb}은(는) {pAnimal}와(과) 같은 동물이라, 나를 조금 더 알아 가기 좋은 해예요."}],"card":"this_year"},"YR_R_ganchong@minor":{"tags":["yrrel"],"v":[{"en":"{year}'s element, {ys}, pushes against {pElem}, {ns}, so you may feel like trying a new way of doing things.","ko":"{year}년의 기운 {ys}이(가) {pElem}, 곧 {ns}와(과) 맞부딪쳐서, 새로운 방식으로 해 보고 싶은 마음이 들 수 있어요."},{"en":"In {year}, the year's {ys} meets {pElem}, {ns}, which can be a fun push to look at things with fresh eyes.","ko":"{year}년에는 그해의 {ys}이(가) {pElem}, 곧 {ns}와(과) 만나요. 새로운 눈으로 바라보게 해 주는 즐거운 자극이 될 수 있어요."}],"card":"this_year"},"YR_R_ganchong_B@minor":{"tags":["yrrel"],"v":[{"en":"This year's element, {ys}, also pushes against {pElem}, {ns}, a small nudge to try something new.","ko":"올해의 기운 {ys}은(는) {pElem}, 곧 {ns}을(를) 살짝 밀기도 해요. 새로운 걸 해 보라는 작은 신호예요."},{"en":"The year's {ys} also meets {pElem}, {ns}, so changing up your routine may feel refreshing.","ko":"올해의 {ys}은(는) {pElem}, 곧 {ns}와(과)도 만나서, 하루 습관을 바꿔 보면 상쾌하게 느껴질 수 있어요."}],"card":"this_year"},"OV_ACT_strong@minor":{"tags":["strength:strong"],"v":[{"en":"This month, pick one thing you like doing and spend a little time on it each day.","ko":"이번 달에는 좋아하는 일 하나를 골라 날마다 조금씩 시간을 내 보세요."},{"en":"This month, help someone with something small, and notice how it feels.","ko":"이번 달에는 누군가의 작은 일을 도와주고, 그때 마음이 어떤지 느껴 보세요."}],"card":"overview"},"DY_FEEL_gwanseong@minor":{"tags":["dycat:gwanseong"],"v":[{"en":"Right now you may be growing fast and learning a lot of new things.","ko":"지금은 빠르게 자라면서 새로운 것을 많이 배우는 때일 수 있어요."},{"en":"You may want to do things the right way and feel proud when you do.","ko":"무엇이든 바르게 해내고 싶어 하고, 해냈을 때 뿌듯함을 느낄 수 있어요."}],"card":"luck"},"DY_ACT_gwanseong@minor":{"tags":["dycat:gwanseong"],"v":[{"en":"Ask someone you look up to what they enjoyed most when they were your age.","ko":"존경하는 어른께 내 나이 때 무엇이 가장 즐거우셨는지 여쭤보세요."},{"en":"Write down one thing you are getting better at, and one thing you would like to learn next.","ko":"요즘 점점 잘하게 되는 것 한 가지와, 다음에 배워 보고 싶은 것 한 가지를 적어 보세요."}],"card":"luck"},"WHO_FEEL_辛@minor":{"tags":["dm:辛"],"v":[{"en":"You may like doing things carefully and well.","ko":"일을 꼼꼼하고 정성껏 하는 걸 좋아할 수 있어요."},{"en":"You may notice tiny details that other people miss.","ko":"다른 사람이 놓치는 작은 부분을 알아챌 수 있어요."}],"card":"personality"},"WT_strong_COPE@minor":{"tags":["strength:strong"],"v":[{"en":"When something upsets you, take three slow breaths and tell a grown-up you trust.","ko":"속상한 일이 생기면 천천히 세 번 숨을 쉬고, 믿을 수 있는 어른에게 이야기해 보세요."},{"en":"When you feel upset, count to ten before you answer, then say how you feel in a few words.","ko":"속이 상할 때는 대답하기 전에 열까지 세어 보고, 그다음 내 기분을 몇 마디로 말해 보세요."}],"card":"caution"},"HB_FEEL_water@minor":{"tags":["hb:water"],"v":[{"en":"You may feel best with some quiet time in your day.","ko":"하루에 조용한 시간이 조금 있을 때 가장 편안할 수 있어요."},{"en":"A calm, cozy moment on your own can help you feel like yourself again.","ko":"혼자 보내는 차분하고 포근한 순간이 다시 나다운 기분을 찾게 도와줄 수 있어요."}],"card":"habits"},"DY_FEEL_both@young":{"tags":["dy:both"],"v":[{"en":"As you grow, your life may come in phases, each with its own mood.","ko":"자라면서 삶은 여러 시기로 나뉘어 찾아올 수 있고, 시기마다 저마다의 분위기가 있어요."},{"en":"Your story is just getting started, and each new phase can bring something to enjoy.","ko":"이야기는 이제 막 시작됐어요. 새로운 시기마다 즐길 거리가 생길 수 있어요."}],"card":"luck"},"YR_ACT_inseong_hap@young":{"tags":["yrcat:inseong","yrstate:hap"],"v":[{"en":"With a parent or teacher, find one new thing to try or learn this year.","ko":"엄마 아빠나 선생님과 함께, 올해 해 보거나 배워 볼 새로운 것 하나를 찾아봐요."},{"en":"Ask a grown-up to help you pick one new book or activity to explore this year.","ko":"어른께 부탁해서 올해 살펴볼 새 책이나 활동 하나를 함께 골라 봐요."}],"card":"this_year"},"DY_ACT_jaeseong@young":{"tags":["dycat:jaeseong"],"v":[{"en":"Pick one thing you enjoy practicing and spend ten minutes on it each day.","ko":"즐겁게 연습할 거리 하나를 골라 날마다 10분씩 해 보세요."},{"en":"Help with one small chore at home each week and notice how good it feels to finish it.","ko":"일주일에 한 번 집안일 하나를 돕고, 끝까지 해냈을 때 얼마나 기분 좋은지 느껴 보세요."}],"card":"luck"},"DY_ACT_siksang@young":{"tags":["dycat:siksang"],"v":[{"en":"Ask a parent or teacher to help you pick one skill to practice this week.","ko":"부모님이나 선생님께 이번 주에 연습할 것 하나를 함께 골라 달라고 해 보세요."},{"en":"Make or draw one small thing this week and show it to someone you love.","ko":"이번 주에 작은 것 하나를 만들거나 그려서 아끼는 사람에게 보여 주세요."}],"card":"luck"},"ST_ACT_early_now@young":{"tags":["stage:early"],"v":[{"en":"Ask a parent or teacher to help you pick one skill to practice this week.","ko":"부모님이나 선생님께 이번 주에 연습할 기술 한 가지를 같이 골라 달라고 해 보세요."},{"en":"Pick one thing you enjoy practicing and spend ten minutes on it each day.","ko":"연습하면 즐거운 것 하나를 골라서 매일 10분씩 해 보세요."}],"card":"early"},"ST_ACT_later_ahead@young":{"tags":["stage:later"],"v":[{"en":"Ask a parent or teacher to help you pick one skill to practice this week.","ko":"부모님이나 선생님께 이번 주에 연습할 솜씨 하나를 함께 골라 달라고 해 봐요."},{"en":"Think of one thing you would love to learn when you are older, and tell someone about it.","ko":"커서 꼭 배우고 싶은 것 하나를 떠올리고, 누군가에게 이야기해 봐요."}],"card":"later"},"MN_ACT_none@young":{"tags":[],"v":[{"en":"Pick one thing you enjoy practicing and spend ten minutes on it each day.","ko":"좋아하는 연습거리 하나를 정해서 매일 10분씩 해 보세요."},{"en":"Keep a small jar of notes about things you are proud of, and add one each week.","ko":"자랑스러운 일을 적은 쪽지를 작은 병에 모아 보세요. 일주일에 하나씩 넣어요."}],"card":"work_money"},"DY_FEEL_jaeseong@young":{"tags":["dycat:jaeseong"],"v":[{"en":"As you grow, practical things like finishing what you start may matter more.","ko":"커 가면서, 시작한 것을 끝까지 해내는 일이 더 소중해질 수 있어요."},{"en":"You may enjoy seeing a small project through from start to finish.","ko":"작은 만들기를 처음부터 끝까지 해내는 걸 즐길 수 있어요."}],"card":"luck"},"YR_ACT_inseong_none@young":{"tags":["yrcat:inseong","yrstate:none"],"v":[{"en":"Pick one new thing to explore with a grown-up this year, and try it for a few minutes a week.","ko":"올해 공부할 주제 하나를 정해 매주 15분씩 들여 보세요."},{"en":"Choose one picture book or topic you like and look at it together with a grown-up.","ko":"올해 공부할 주제 하나를 정해 매주 15분씩 들여 보세요."}],"card":"this_year"},"YR_ACT_gwanseong_chung@young":{"tags":["yrcat:gwanseong","yrstate:chung"],"v":[{"en":"If things feel shaky, ask a grown-up to help you pick one small thing to do first.","ko":"올해 계획이 흔들리면 꼭 해야 할 일과 남이 기대하는 일을 나눠 적고, 덤 하나는 내려놓으세요."},{"en":"When a day feels busy, start with one small, easy thing.","ko":"올해 계획이 흔들리면 꼭 해야 할 일과 남이 기대하는 일을 나눠 적고, 덤 하나는 내려놓으세요."}],"card":"this_year"},"WHO_ACT_bigyeop@young":{"tags":["topcat:bigyeop"],"v":[{"en":"This week, show something you're proud of to someone you trust.","ko":"이번 주, 평소 혼자 하던 일에 한 사람을 초대해 보세요."},{"en":"Try one thing on your own this week, then share it with someone you love.","ko":"이번 주, 평소 혼자 하던 일에 한 사람을 초대해 보세요."}],"card":"personality"},"OV_ACT_balanced@young":{"tags":["strength:balanced"],"v":[{"en":"This month, talk with a grown-up about two things you'd like to try, and pick one together.","ko":"이번 달, 10년 뒤 어디에 있고 싶은지 한 문장으로 적어 눈에 보이는 곳에 두세요."},{"en":"Pick one game or activity you enjoy and do it a little each day.","ko":"이번 달, 10년 뒤 어디에 있고 싶은지 한 문장으로 적어 눈에 보이는 곳에 두세요."}],"card":"overview"},"ST_ACT_middle_ahead@young":{"tags":["stage:middle"],"v":[{"en":"Think of one thing you would love to learn when you are older, and tell someone about it.","ko":"중년의 내가 고마워할 작은 습관을 지금 시작해 보세요. 조금씩 몸을 풀거나 조금씩 배우는 것처럼요."},{"en":"Draw or tell a grown-up about something you dream of doing one day.","ko":"중년의 내가 고마워할 작은 습관을 지금 시작해 보세요. 조금씩 몸을 풀거나 조금씩 배우는 것처럼요."}],"card":"middle"},"BL_ACT_fire@young":{"tags":["bal:add:fire"],"v":[{"en":"Spend a little time outside in the sun with someone you like.","ko":"공간에 따뜻한 조명이나 붉은색을 조금 더하고, 이번 주 누군가에게 좋은 소식 하나를 나눠 보세요."},{"en":"Play outside for a little while on a sunny day.","ko":"공간에 따뜻한 조명이나 붉은색을 조금 더하고, 이번 주 누군가에게 좋은 소식 하나를 나눠 보세요."}],"card":"habits_candidate"},"OV_FEEL_庚@young":{"tags":["dm:庚"],"v":[{"en":"As you grow, hard moments may turn into some of your clearest lessons.","ko":"가장 뚜렷하게 성장한 때는 힘든 순간 바로 뒤였을지도 몰라요."},{"en":"You may grow stronger each time you try something hard.","ko":"가장 뚜렷하게 성장한 때는 힘든 순간 바로 뒤였을지도 몰라요."}],"card":"overview"},"DY_ACT_jaeseong@minor":{"tags":["dycat:jaeseong"],"v":[{"en":"Pick one thing you'd like to get better at, and practice it for ten minutes a few times this week.","ko":"이번 대운이 끝날 때까지 쌓고 싶은 것을 한 장짜리 계획으로 써 보세요."},{"en":"Notice which after-school activity makes you proudest, and give it a little more time.","ko":"이번 대운이 끝날 때까지 쌓고 싶은 것을 한 장짜리 계획으로 써 보세요."}],"card":"luck"},"ST_ACT_early_now@minor":{"tags":["stage:early"],"v":[{"en":"Pick one skill you'd like to get better at, and practice it for ten minutes a few times this week.","ko":"{c1}세까지 갖추고 싶은 기술 하나를 골라 이번 주에 20분을 써 보세요."},{"en":"Ask a teacher or coach which small habit would help you most this month.","ko":"{c1}세까지 갖추고 싶은 기술 하나를 골라 이번 주에 20분을 써 보세요."}],"card":"early"},"OV_FEEL_壬@minor":{"tags":["dm:壬"],"v":[{"en":"Your life story is just getting started, and it can go in many directions.","ko":"생각했던 것보다 인생의 굽이가 많았을지도 몰라요. 방향 전환과 새로운 장들이요."},{"en":"You may enjoy trying new paths and seeing where each one leads.","ko":"생각했던 것보다 인생의 굽이가 많았을지도 몰라요. 방향 전환과 새로운 장들이요."}],"card":"overview"},"OV_FEEL_己@minor":{"tags":["dm:己"],"v":[{"en":"You may enjoy watching something you started slowly grow.","ko":"심어 둔 무언가가 마침내 싹을 틔운 해가 가장 좋은 해였다고 느낄지도 몰라요."},{"en":"Small things you care for, like a plant or a project, may grow well with your patience.","ko":"심어 둔 무언가가 마침내 싹을 틔운 해가 가장 좋은 해였다고 느낄지도 몰라요."}],"card":"overview"},"WT_weak_COPE@minor":{"tags":["strength:weak"],"v":[{"en":"When a day feels busy, take three slow breaths before the next thing.","ko":"일주일에 하루 저녁은 아무 일정도 넣지 말고, 약속처럼 지켜 주세요."},{"en":"Ask a grown-up to help you with one thing this week.","ko":"일주일에 하루 저녁은 아무 일정도 넣지 말고, 약속처럼 지켜 주세요."}],"card":"caution"}},"meta":{"name":"K Saju deep reading sentence fragments","version":"fragments_en_ko_v2 (2026-10-02 night 1, +variants; eval patch applied)","source":"sentence_bank_v4 (2026-09-30, patched 2026-10-01) -> English side hanja-free; Korean side unchanged","notes":["Each bundle = tags + v[] variants; each variant = {en, ko} pair. {slot} placeholders are filled by deep_reading_engine.js.","Korean strings may contain hanja and josa markers such as (이)가, (으)로; the engine fills the right particle.","English strings contain no hanja. Slot values with hanja are converted by deep_reading_engine.js (stems -> nickname, branches -> animal, pillars -> \"Yang Wood Tiger\").","card = the card that uses the bundle. Day-1 cards: overview, personality, luck. Others are ready in the data but shown as Coming soon on the page."],"counts":{"bundles":486,"pairs":1223,"addedPairs":69}}};
